    @State var showShortcutSheet = false  // Cmd long-press shortcut overlay
    @State var shortcutSheetFocusedCommandID: String? = nil  // Up/Down nav inside shortcut sheet
    @State var shortcutSheetSearchQuery = ""
    @State var shortcutSheetSourcePID: pid_t = 0
    @State var shortcutSheetAppName = "App"
    @State var cmdHoldTask: Task<Void, Never>? = nil
    @State var cmdHoldMonitor: Any? = nil
    @State var cmdHoldGlobalMonitor: Any? = nil
    @State var cmdTapArmed = false
    @State var cmdChordUsed = false
    @State var cmdHoldTriggered = false
    // AI chat mode
