    func currentRegularRunningApps() -> [NSRunningApplication] {
        var seen = Set<String>()
        return NSWorkspace.shared.runningApplications.filter { app in
            guard app.activationPolicy == .regular,
                app.bundleIdentifier != Bundle.main.bundleIdentifier,
                !app.isTerminated
            else { return false }

            let key =
                app.bundleIdentifier
                ?? app.bundleURL?.standardizedFileURL.path
                ?? (app.localizedName ?? "").lowercased()
            guard !key.isEmpty else { return false }
            return seen.insert(key).inserted
        }
    }

    struct DockPillItem: Identifiable {
        let id: String
        let index: Int
        let icon: NSImage?
        let label: String
        let subtitle: String?
        let hoverKey: String
        let action: () -> Void
        let destructiveAction: (() -> Void)?
        let removeAction: (() -> Void)?
    }

    func buildAppCascadeItems(
        pinnedApps: [PinnedApp],
        runningApps: [NSRunningApplication],
        pinnedCount: Int
    ) -> [DockPillItem] {
        var items: [DockPillItem] = []
        for (idx, app) in pinnedApps.enumerated() {
            let c = app
            let isRunning = runningApp(for: app) != nil
            items.append(
                DockPillItem(
                    id: "pinned-\(app.id)", index: idx,
                    icon: resolvedPinnedIcon(for: app), label: app.name,
                    subtitle: isRunning ? "Running" : "Launch",
                    hoverKey: "dock-pinned-\(app.id.uuidString)",
                    action: {
                        launchPinnedApp(c)
                        if isGlobalContextActive {
                            scheduleContextDockTransition(
                                bundleId: c.bundleIdentifier, appName: c.name)
                        }
                    },
                    destructiveAction: nil,
                    removeAction: { settings.unpinApp(c) }
                ))
        }
        for (off, app) in runningApps.enumerated() {
            let i = pinnedCount + off
            let c = app
            items.append(
                DockPillItem(
                    id: "running-\(app.processIdentifier)", index: i,
                    icon: resolvedRunningAppIcon(for: app), label: app.localizedName ?? "App",
                    subtitle: "Running",
                    hoverKey: "dock-running-\(app.processIdentifier)",
                    action: {
                        activateRunningAppFromDock(c)
                        if isGlobalContextActive {
                            scheduleContextDockTransition(
                                bundleId: c.bundleIdentifier, appName: c.localizedName ?? "App")
                        }
                    },
                    destructiveAction: { terminateRunningAppFromDock(c) },
                    removeAction: nil
                ))
        }
        return items
    }

    @ViewBuilder
    var pinnedAndRecentAppsRow: some View {
        let searchQuery = searchState.query.trimmingCharacters(in: .whitespaces).lowercased()

        let basePinnedApps = settings.pinnedApps
        let visiblePinnedApps =
            searchQuery.isEmpty
            ? basePinnedApps
            : basePinnedApps.filter { $0.name.lowercased().contains(searchQuery) }

        let pinnedCount = visiblePinnedApps.count
        let focusedIdx = focusedAppPillIndex

        if let kbIdx = focusedAppPillIndex {
            // ── Keyboard nav cascade: prev compact | FOCUSED expanded fills | next compact ──
            // Mirrors context dock action-pill cascade exactly.
            let allAppItems = buildAppCascadeItems(
                pinnedApps: visiblePinnedApps,
                runningApps: [],
                pinnedCount: pinnedCount
            )
            let prevItem = allAppItems.first(where: { $0.index == kbIdx - 1 })
            let focusedItem = allAppItems.first(where: { $0.index == kbIdx })
            let nextItem = allAppItems.first(where: { $0.index == kbIdx + 1 })

            HStack(alignment: .top, spacing: 6) {
                if let p = prevItem {
                    appPillButton(
                        icon: p.icon, label: p.label, subtitle: p.subtitle, hoverKey: p.hoverKey,
                        focused: false, index: p.index, isExpanded: false,
                        destructiveAction: p.destructiveAction, removeAction: p.removeAction,
                        action: p.action
                    )
                    .transition(
                        .asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
                if let f = focusedItem {
                    appPillButton(
                        icon: f.icon, label: f.label, subtitle: f.subtitle, hoverKey: f.hoverKey,
                        focused: true, index: f.index, isExpanded: true,
                        destructiveAction: nil, removeAction: nil, action: f.action
                    )
                    .frame(maxWidth: .infinity)
                    .transition(.opacity)
                }
                if let n = nextItem {
                    appPillButton(
                        icon: n.icon, label: n.label, subtitle: n.subtitle, hoverKey: n.hoverKey,
                        focused: false, index: n.index, isExpanded: false,
                        destructiveAction: n.destructiveAction, removeAction: n.removeAction,
                        action: n.action
                    )
                    .transition(
                        .asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
            }
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: focusedAppPillIndex)
        } else {
            // ── Normal scrollable row — all apps visible, frontmost auto-highlighted ──
            ScrollViewReader { proxy in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 10) {
                        ForEach(Array(visiblePinnedApps.enumerated()), id: \.element.id) {
                            idx, app in
                            appPillButton(
                                icon: resolvedPinnedIcon(for: app), label: app.name,
                                hoverKey: "dock-pinned-\(app.id.uuidString)",
                                focused: idx == focusedIdx, index: idx,
                                removeAction: { settings.unpinApp(app) },
                                action: {
                                    launchPinnedApp(app)
                                    if isGlobalContextActive {
                                        scheduleContextDockTransition(
                                            bundleId: app.bundleIdentifier, appName: app.name)
                                    }
                                }
                            )
                            .id("app-pill-\(idx)")
                            .scrollTransition(.interactive, axis: .horizontal) { effect, phase in
                                effect
                                    .rotation3DEffect(
                                        .degrees(phase.value * 22), axis: (x: 0, y: 1, z: 0),
                                        perspective: 0.45
                                    )
                                    .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                                    .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
                            }
                            .contextMenu {
                                Button {
                                    settings.unpinApp(app)
                                } label: {
                                    Label("Unpin from Launcher", systemImage: "pin.slash")
                                }
                                Divider()
                                Button {
                                    launchPinnedApp(app)
                                } label: {
                                    Label("Open", systemImage: "arrow.up.right.square")
                                }
                                if app.type == .folder {
                                    Button {
                                        NSWorkspace.shared.selectFile(
                                            app.path, inFileViewerRootedAtPath: "")
                                    } label: {
                                        Label("Show in Finder", systemImage: "folder")
                                    }
                                }
                            }
                        }

                    }
                }
                .onChange(of: focusedAppPillIndex) { idx in
                    guard let idx else { return }
                    withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                        proxy.scrollTo("app-pill-\(idx)", anchor: .center)
                    }
                }
            }
        }
    }

    @ViewBuilder
    func globalAppSearchPillRow(
        query: String, matches providedMatches: [SearchResult]? = nil
    ) -> some View {
        let matches = providedMatches ?? globalApplicationMatches(for: query)

        let makeAction: (SearchResult) -> () -> Void = { result in
            {
                result.action()
                searchState.query = ""
                focusedAppPillIndex = nil
                let bundleId = result.filePath.flatMap { Bundle(path: $0)?.bundleIdentifier }
                scheduleContextDockTransition(bundleId: bundleId, appName: result.title)
                if let bid = bundleId {
                    AppUsageLearner.shared.recordApp(bundleID: bid, appName: result.title)
                }
            }
        }
        let makeQuitAction: (SearchResult) -> (() -> Void)? = { result in
            guard let runningApp = runningApplication(forGlobalResult: result) else { return nil }
            return { terminateRunningAppFromDock(runningApp) }
        }

        let makePinAction: (SearchResult) -> (() -> Void)? = { result in
            guard let path = result.filePath, !settings.isPinned(path: path) else { return nil }
            return {
                let bid = Bundle(path: path)?.bundleIdentifier
                settings.pinApp(name: result.title, path: path, bundleIdentifier: bid)
                AppUsageLearner.shared.recordAction("pin:\(result.title)", inBundleID: nil)
            }
        }

        if matches.isEmpty {
            HStack {
                Text("No apps matching \"\(query)\"")
                    .font(.system(size: 12))
                    .foregroundStyle(.secondary.opacity(0.6))
                    .padding(.horizontal, 8)
            }
        } else if let focIdx = focusedAppPillIndex, focIdx < matches.count {
            // ── Keyboard nav: icon-anchor + prev(normal) + FOCUSED(expanded) + next(normal) ──
            let prev = focIdx > 0 ? matches[focIdx - 1] : nil
            let focused = matches[focIdx]
            let next = focIdx + 1 < matches.count ? matches[focIdx + 1] : nil

            HStack(alignment: .top, spacing: 6) {
                if let prev {
                    let pi = focIdx - 1
                    appPillButton(
                        icon: prev.icon, label: prev.title,
                        hoverKey: "gsearch-\(prev.title)", focused: false, index: pi,
                        isExpanded: false, destructiveAction: makeQuitAction(prev),
                        pinAction: makePinAction(prev), action: makeAction(prev)
                    )
                    .transition(
                        .asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }

                appPillButton(
                    icon: focused.icon, label: focused.title,
                    hoverKey: "gsearch-\(focused.title)", focused: true, index: focIdx,
                    isExpanded: true, destructiveAction: makeQuitAction(focused),
                    pinAction: makePinAction(focused), action: makeAction(focused)
                )
                .frame(maxWidth: .infinity)
                .transition(.opacity)

                if let next {
                    let ni = focIdx + 1
                    appPillButton(
                        icon: next.icon, label: next.title,
                        hoverKey: "gsearch-\(next.title)", focused: false, index: ni,
                        isExpanded: false, destructiveAction: makeQuitAction(next),
                        pinAction: makePinAction(next), action: makeAction(next)
                    )
                    .transition(
                        .asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
            }
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: focIdx)
        } else {
            // ── Normal scrollable row ──
            ScrollViewReader { proxy in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 10) {
                        ForEach(Array(matches.enumerated()), id: \.element.title) { idx, result in
                            appPillButton(
                                icon: result.icon,
                                label: result.title,
                                hoverKey: "global-search-\(result.title)",
                                focused: false,
                                index: idx,
                                isExpanded: false,
                                destructiveAction: makeQuitAction(result),
                                pinAction: makePinAction(result),
                                action: makeAction(result)
                            )
                            .id("gsearch-pill-\(idx)")
                            .scrollTransition(.interactive, axis: .horizontal) { effect, phase in
                                effect
                                    .rotation3DEffect(
                                        .degrees(phase.value * 22),
                                        axis: (x: 0, y: 1, z: 0),
                                        perspective: 0.45
                                    )
                                    .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                                    .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
                            }
                        }
                    }
                }
                .onChange(of: focusedAppPillIndex) { idx in
                    guard let idx else { return }
                    withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                        proxy.scrollTo("gsearch-pill-\(idx)", anchor: .center)
                    }
                }
            }
        }
    }

    func globalAppSearchListView(
        query: String,
        matches providedMatches: [SearchResult]? = nil,
        menuPills providedMenuPills: [DockPill] = [],
        appMenuGroups providedAppMenuGroups: [AppMenuGroup] = [],
        launchHint: (bundleId: String, appName: String, appPath: String?)? = nil,
        scopedMenuAppName: String? = nil,
        scopedMenuActionQuery: String = "",
        isLoading: Bool = false,
        menuFirst: Bool = false
    ) -> some View {
        let rawMatches = Array(
            (providedMatches ?? globalApplicationMatches(for: query)).prefix(maxListViewDockPills))
        let scopedMenuAppName = scopedMenuAppName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let isScopedMenuMode = scopedMenuAppName?.isEmpty == false
        let scopedMenuActionQuery = scopedMenuActionQuery.trimmingCharacters(
            in: .whitespacesAndNewlines)
        let candidateMenuPills =
            providedMenuPills
            .filter { !$0.isSeparator }
            .filter { $0.rankingKind != "appLaunch" }
            .filter { !$0.name.lowercased().hasPrefix("open ") || rawMatches.isEmpty }
        // Count all menu pills (frontmost/scoped + cross-app) to match the nav state's appLimit formula.
        // When cross-app groups exist, candidateMenuPills is empty (menuGroups=[]) so without this
        // the view includes more app results than the nav state, causing index mismatches and missing highlights.
        let totalMenuPillCount =
            candidateMenuPills.count + providedAppMenuGroups.flatMap(\.pills).count
        let appLimit =
            totalMenuPillCount == 0
            ? maxListViewDockPills
            : min(rawMatches.count, max(8, maxListViewDockPills - min(totalMenuPillCount, 12)))
        let limitedMatches = Array(
            dedupeGlobalApplicationResults(rawMatches).prefix(appLimit))
        let matches =
            limitedMatches.filter { runningApplication(forGlobalResult: $0) != nil }
            + limitedMatches.filter { runningApplication(forGlobalResult: $0) == nil }
        let indexedMatches = Array(matches.enumerated())
        // In global context, isEnabled reflects AX state of whatever app was frontmost at
        // snapshot time — meaningless here. Force enabled so no "Unavailable" badge shows.
        let visibleMenuPills = Array(
            candidateMenuPills.prefix(
                matches.isEmpty
                    ? maxListViewDockPills : max(0, maxListViewDockPills - matches.count))
        ).map { pill -> DockPill in
            var p = pill
            p.isEnabled = true
            return p
        }
        let menuGroups = groupMenuPillsByTitle(visibleMenuPills)
        let menuRowIDs: [String] = menuGroups.map { group in
            group.isGrouped
                ? "global-menu-group-\(group.id)"
                : "global-menu-pill-\(group.primaryPill.id)"
        }
        let appRowIDs: [String] = matches.map { "global-app-\($0.id)" }
        let showLaunchHint = launchHint != nil && visibleMenuPills.isEmpty
        let hasRenderableRows =
            !matches.isEmpty || !visibleMenuPills.isEmpty || !providedAppMenuGroups.isEmpty
            || showLaunchHint
        let isEmpty = !isLoading && !hasRenderableRows
        let listHeight: CGFloat = hasRenderableRows ? listViewVisibleHeight : 86

        let makeAction: (SearchResult) -> () -> Void = { result in
            {
                let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
                    .lowercased()
                result.action()
                searchState.query = ""
                focusedAppPillIndex = nil
                hoveredAppPillIndex = nil
                let bundleId = result.filePath.flatMap { Bundle(path: $0)?.bundleIdentifier }
                scheduleContextDockTransition(bundleId: bundleId, appName: result.title)
                if let bid = bundleId {
                    AppUsageLearner.shared.recordApp(bundleID: bid, appName: result.title)
                }
                // Teach intent: user picked an app for this query
                if !q.isEmpty { AppUsageLearner.shared.recordQueryIntent(query: q, wasMenu: false) }
            }
        }
        let makeQuitAction: (SearchResult) -> (() -> Void)? = { result in
            guard let runningApp = runningApplication(forGlobalResult: result) else { return nil }
            return { terminateRunningAppFromDock(runningApp) }
        }
        let makePinAction: (SearchResult) -> (() -> Void)? = { result in
            guard let path = result.filePath, !settings.isPinned(path: path) else { return nil }
            return {
                let bid = Bundle(path: path)?.bundleIdentifier
                settings.pinApp(name: result.title, path: path, bundleIdentifier: bid)
                AppUsageLearner.shared.recordAction("pin:\(result.title)", inBundleID: nil)
            }
        }

        return ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                LazyVStack(spacing: 2) {
                    if isEmpty {
                        HStack {
                            Text(
                                isScopedMenuMode
                                    ? (scopedMenuActionQuery.isEmpty
                                        ? "No cached menus for \(scopedMenuAppName ?? "this app")"
                                        : "No \(scopedMenuAppName ?? "app") menus matching \"\(scopedMenuActionQuery)\"")
                                    : "No apps matching \"\(query)\""
                            )
                            .font(.system(size: 13, weight: .medium))
                            .foregroundStyle(.secondary.opacity(0.65))
                            Spacer()
                        }
                        .padding(.horizontal, 12)
                        .padding(.vertical, 14)
                    }

                    // When intent favours a menu action, surface menus above app results.
                    if menuFirst {
                        if !menuGroups.isEmpty {
                            resultGroupHeader(
                                isScopedMenuMode ? "\(scopedMenuAppName ?? "App") Menus" : "Menus")
                        }
                        ForEach(Array(menuGroups.enumerated()), id: \.element.id) { idx, group in
                            if group.isGrouped {
                                groupedMenuPillRow(group: group, index: matches.count + idx)
                                    .id(menuRowIDs[idx])
                            } else {
                                pillListRow(pill: group.primaryPill, index: matches.count + idx)
                                    .id(menuRowIDs[idx])
                            }
                        }
                    }

                    if !indexedMatches.isEmpty {
                        resultGroupHeader("Apps")
                    }
                    ForEach(indexedMatches, id: \.element.id) { idx, result in
                        let isRunning = runningApplication(forGlobalResult: result) != nil
                        appListRow(
                            icon: result.icon,
                            name: result.title,
                            subtitle: isRunning
                                ? "Running"
                                : (settings.isPinned(path: result.filePath ?? result.subtitle)
                                    ? "Pinned" : "Open"),
                            index: idx,
                            quitAction: isRunning ? makeQuitAction(result) : nil,
                            action: makeAction(result)
                        )
                        .id(appRowIDs[idx])
                        .contextMenu {
                            if let pinAction = makePinAction(result) {
                                Button(action: pinAction) {
                                    Label("Pin to Launcher", systemImage: "pin")
                                }
                            }
                            if let quitAction = makeQuitAction(result) {
                                Divider()
                                Button(role: .destructive, action: quitAction) {
                                    Label("Quit \(result.title)", systemImage: "xmark.circle")
                                }
                            }
                        }
                    }

                    if !menuFirst {
                        if !menuGroups.isEmpty {
                            resultGroupHeader(
                                isScopedMenuMode ? "\(scopedMenuAppName ?? "App") Menus" : "Menus")
                        }
                        ForEach(Array(menuGroups.enumerated()), id: \.element.id) { idx, group in
                            if group.isGrouped {
                                groupedMenuPillRow(group: group, index: matches.count + idx)
                                    .id(menuRowIDs[idx])
                            } else {
                                pillListRow(pill: group.primaryPill, index: matches.count + idx)
                                    .id(menuRowIDs[idx])
                            }
                        }
                    }

                    // Cross-app menus grouped by source app.
                    // Each group shows app icon + name header, then matching menu pills below.
                    if !providedAppMenuGroups.isEmpty {
                        let crossBase = matches.count + menuGroups.count
                        let groupStartIndices: [String: Int] = {
                            var d: [String: Int] = [:]
                            var offset = 0
                            for g in providedAppMenuGroups {
                                d[g.id] = crossBase + offset
                                offset += g.pills.count
                            }
                            return d
                        }()
                        ForEach(providedAppMenuGroups) { group in
                            let groupBase = groupStartIndices[group.id] ?? crossBase
                            resultGroupHeader(group.appName, icon: group.icon)
                            ForEach(Array(group.pills.enumerated()), id: \.element.id) {
                                pillIdx, pill in
                                pillListRow(pill: pill, index: groupBase + pillIdx)
                                    .id("xapp-pill-\(group.id)-\(pill.id)")
                            }
                        }
                    }

                    // No cached menus + app not running: invite user to open it once so menus get snapshotted.
                    if showLaunchHint, let hint = launchHint {
                        Button {
                            if let path = hint.appPath {
                                NSWorkspace.shared.openApplication(
                                    at: URL(fileURLWithPath: path),
                                    configuration: .init()
                                )
                            } else {
                                NSWorkspace.shared.launchApplication(
                                    withBundleIdentifier: hint.bundleId,
                                    options: [], additionalEventParamDescriptor: nil,
                                    launchIdentifier: nil)
                            }
                            searchState.query = ""
                        } label: {
                            HStack(spacing: 12) {
                                if let path = hint.appPath {
                                    Image(nsImage: NSWorkspace.shared.icon(forFile: path))
                                        .resizable().aspectRatio(contentMode: .fit)
                                        .frame(width: 32, height: 32)
                                } else {
                                    Image(systemName: "app.badge.checkmark")
                                        .font(.system(size: 20))
                                        .foregroundStyle(.secondary)
                                        .frame(width: 32, height: 32)
                                }
                                VStack(alignment: .leading, spacing: 2) {
                                    Text("Open \(hint.appName) to enable menu search")
                                        .font(.system(size: 13, weight: .medium))
                                        .foregroundStyle(.primary)
                                    Text("Menus are cached after first launch")
                                        .font(.system(size: 11))
                                        .foregroundStyle(.secondary)
                                }
                                Spacer()
                                Image(systemName: "arrow.up.right")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundStyle(.tertiary)
                            }
                            .padding(.horizontal, 8)
                            .padding(.vertical, 10)
                        }
                        .buttonStyle(.plain)
                        .transition(.opacity)
                    }
                }
                .padding(6)
                .frame(maxWidth: .infinity, alignment: .topLeading)
            }
            .frame(maxWidth: .infinity, alignment: .topLeading)
            .frame(height: listHeight, alignment: .topLeading)
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            .animation(.easeOut(duration: 0.16), value: hasRenderableRows)
            .onChange(of: focusedAppPillIndex) { idx in
                guard let idx, idx < appRowIDs.count else { return }
                withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                    proxy.scrollTo(appRowIDs[idx], anchor: .center)
                }
            }
            .onChange(of: l2.focusedPillIndex) { idx in
                guard let idx, idx >= matches.count else { return }
                let menuIdx = idx - matches.count
                refreshQuickLookPreviewForCurrentFocusIfVisible()
                if menuIdx >= 0, menuIdx < menuRowIDs.count {
                    withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                        proxy.scrollTo(menuRowIDs[menuIdx], anchor: .center)
                    }
                } else if menuIdx >= menuGroups.count {
                    // Cross-app group pill — find which group and local index
                    let crossIdx = menuIdx - menuGroups.count
                    var offset = 0
                    for group in providedAppMenuGroups {
                        let localIdx = crossIdx - offset
                        if localIdx < group.pills.count {
                            withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                                proxy.scrollTo(
                                    "xapp-pill-\(group.id)-\(group.pills[localIdx].id)",
                                    anchor: .center)
                            }
                            break
                        }
                        offset += group.pills.count
                    }
                }
            }
            .onChange(of: matches.count) { count in
                guard let idx = focusedAppPillIndex else { return }
                let totalCount = count + visibleMenuPills.count
                if totalCount <= 0 {
                    focusedAppPillIndex = nil
                    l2.focusedPillIndex = nil
                    l2.pillNavViaKeyboard = false
                } else if idx >= totalCount {
                    focusedAppPillIndex = totalCount - 1
                }
            }
        }
    }

    func resolvedPinnedIcon(for app: PinnedApp) -> NSImage? {
        if app.type == .application {
            if let bundleId = app.bundleIdentifier,
                let runningURL = runningRegularApps.first(where: {
                    $0.bundleIdentifier == bundleId
                })?.bundleURL
            {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: runningURL.path))
            }
            if let bundleId = app.bundleIdentifier,
                let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleId)
            {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: appURL.path))
            }
        }

        return preparedDockIcon(NSWorkspace.shared.icon(forFile: app.path))
    }

    func globalApplicationMatches(
        for query: String,
        limit: Int = Int.max,
        includeRecentItems: Bool = true
    ) -> [SearchResult] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }

        if isGenericApplicationListQuery(q) {
            return groupedGlobalApplicationList(limit: limit)
        }

        var candidates: [(result: SearchResult, score: Double, order: Int)] = []
        var seen = Set<String>()
        var order = 0

        func add(_ result: SearchResult, bundleIdentifier explicitBundleId: String? = nil) {
            let bundleId = explicitBundleId ?? bundleIdentifier(forApplicationResult: result)
            guard
                let score = appSearchMatchScore(
                    query: q,
                    appName: result.title,
                    bundleIdentifier: bundleId
                )
            else { return }

            let key = bundleId ?? result.filePath ?? result.title.lowercased()
            guard seen.insert(key).inserted else { return }
            // Cross-register the file path so a later path-keyed entry for the same app is blocked.
            if let bid = bundleId, !bid.isEmpty, let path = result.filePath, !path.isEmpty,
                path != bid
            {
                seen.insert(path)
            }
            var enriched = result
            enriched.score = score
            candidates.append((enriched, score, order))
            order += 1
        }

        for app in settings.pinnedApps where app.type == .application {
            guard
                !shouldIgnoreApplicationFromAppSearch(
                    appName: app.name,
                    bundleIdentifier: app.bundleIdentifier,
                    path: app.path
                )
            else { continue }
            let path = app.path
            let title = app.name
            add(
                SearchResult(
                    title: title,
                    subtitle: path,
                    icon: resolvedPinnedIcon(for: app),
                    action: { launchPinnedApp(app) },
                    type: .application,
                    filePath: path,
                    contactData: nil
                ), bundleIdentifier: app.bundleIdentifier)
        }

        // Recent apps from macOS Recent Items — higher signal than full installed list.
        // Deduped by seen set; running/pinned apps already inserted win on action (activate vs open).
        if isGlobalContextActive && includeRecentItems {
            for recent in RecentItemsService.shared.recentApplications() {
                guard
                    !shouldIgnoreApplicationFromAppSearch(
                        appName: recent.name,
                        bundleIdentifier: recent.bundleId,
                        path: recent.url.path
                    )
                else { continue }
                let capturedURL = recent.url
                add(
                    SearchResult(
                        title: recent.name,
                        subtitle: recent.url.path,
                        icon: recent.icon,
                        action: {
                            NSWorkspace.shared.openApplication(
                                at: capturedURL, configuration: .init())
                        },
                        type: .application,
                        filePath: recent.url.path,
                        contactData: nil
                    ), bundleIdentifier: recent.bundleId)
            }
        }

        let runningSource =
            runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
        for app in runningSource {
            guard let name = app.localizedName else { continue }
            guard
                !shouldIgnoreApplicationFromAppSearch(
                    appName: name,
                    bundleIdentifier: app.bundleIdentifier,
                    path: app.bundleURL?.path
                )
            else { continue }
            let path = app.bundleURL?.path
            add(
                SearchResult(
                    title: name,
                    subtitle: path ?? "Running",
                    icon: resolvedRunningAppIcon(for: app),
                    action: { activateRunningAppFromDock(app) },
                    type: .application,
                    filePath: path,
                    contactData: nil
                ), bundleIdentifier: app.bundleIdentifier)
        }

        let installedMatches =
            allApplications
            .filter {
                $0.type == .application
                    && !shouldIgnoreApplicationFromAppSearch(
                        appName: $0.title,
                        bundleIdentifier: Bundle(url: URL(fileURLWithPath: $0.subtitle))?
                            .bundleIdentifier,
                        path: $0.subtitle
                    )
            }

        for app in installedMatches {
            add(app)
        }

        let builtInAppTargets: [(name: String, bundleId: String, path: String)] = [
            ("Safari", "com.apple.Safari", "/Applications/Safari.app"),
            ("Notes", "com.apple.Notes", "/System/Applications/Notes.app"),
            ("Messages", "com.apple.MobileSMS", "/System/Applications/Messages.app"),
            ("Mail", "com.apple.mail", "/System/Applications/Mail.app"),
            ("Calendar", "com.apple.iCal", "/System/Applications/Calendar.app"),
            ("Reminders", "com.apple.reminders", "/System/Applications/Reminders.app"),
            ("Photos", "com.apple.Photos", "/System/Applications/Photos.app"),
            ("Contacts", "com.apple.AddressBook", "/System/Applications/Contacts.app"),
            (
                "System Settings", "com.apple.systempreferences",
                "/System/Applications/System Settings.app"
            ),
            ("FaceTime", "com.apple.FaceTime", "/System/Applications/FaceTime.app"),
            ("Freeform", "com.apple.freeform", "/System/Applications/Freeform.app"),
            ("Maps", "com.apple.Maps", "/System/Applications/Maps.app"),
            ("Music", "com.apple.Music", "/System/Applications/Music.app"),
            (
                "QuickTime Player", "com.apple.QuickTimePlayerX",
                "/System/Applications/QuickTime Player.app"
            ),
        ]
        for target in builtInAppTargets {
            let path =
                NSWorkspace.shared.urlForApplication(withBundleIdentifier: target.bundleId)?.path
                ?? target.path
            guard
                !shouldIgnoreApplicationFromAppSearch(
                    appName: target.name,
                    bundleIdentifier: target.bundleId,
                    path: path
                )
            else { continue }
            add(
                SearchResult(
                    title: target.name,
                    subtitle: path,
                    icon: resolvedApplicationIcon(
                        bundleIdentifier: target.bundleId, appName: target.name)
                        ?? preparedDockIcon(NSWorkspace.shared.icon(forFile: path)),
                    action: {
                        if let url = NSWorkspace.shared.urlForApplication(
                            withBundleIdentifier: target.bundleId)
                        {
                            NSWorkspace.shared.openApplication(
                                at: url, configuration: NSWorkspace.OpenConfiguration())
                        } else {
                            NSWorkspace.shared.open(URL(fileURLWithPath: path))
                        }
                    },
                    type: .application,
                    filePath: path,
                    contactData: nil
                ), bundleIdentifier: target.bundleId)
        }

        // Recent documents from macOS Recent Items — cross-app files.
        // Only included when query is long enough (≥3 chars) to reduce noise.
        if isGlobalContextActive, includeRecentItems, q.count >= 3 {
            for doc in RecentItemsService.shared.recentDocuments() {
                let docName = doc.name.lowercased()
                guard docName.contains(q) || docName.hasPrefix(q) else { continue }
                let capturedURL = doc.url
                let key = doc.url.path
                guard seen.insert(key).inserted else { continue }
                let score: Double = docName.hasPrefix(q) ? 2_500 - Double(docName.count) : 1_800
                var result = SearchResult(
                    title: doc.name,
                    subtitle: doc.url.deletingLastPathComponent().path,
                    icon: doc.icon,
                    action: { NSWorkspace.shared.open(capturedURL) },
                    type: .document,
                    filePath: doc.url.path,
                    contactData: nil
                )
                result.score = score
                candidates.append((result, score, order))
                order += 1
            }
        }

        return Array(
            candidates
                .sorted {
                    if $0.score != $1.score { return $0.score > $1.score }
                    if $0.result.title.count != $1.result.title.count {
                        return $0.result.title.count < $1.result.title.count
                    }
                    return $0.order < $1.order
                }
                .map(\.result)
                .prefix(limit)
        )
    }

    func groupedGlobalApplicationList(limit: Int) -> [SearchResult] {
        var results: [SearchResult] = []
        var seen = Set<String>()

        func bundleIdentifier(for path: String?) -> String? {
            guard let path, !path.isEmpty else { return nil }
            return Bundle(url: URL(fileURLWithPath: path))?.bundleIdentifier
        }

        func add(_ result: SearchResult) {
            guard results.count < limit else { return }
            let bundleId = bundleIdentifier(for: result.filePath ?? result.subtitle)
            guard
                !shouldIgnoreApplicationFromAppSearch(
                    appName: result.title,
                    bundleIdentifier: bundleId,
                    path: result.filePath ?? result.subtitle
                )
            else { return }

            let key = bundleId ?? result.filePath ?? result.subtitle.lowercased()
            guard seen.insert(key).inserted else { return }
            results.append(result)
        }

        let runningSource =
            runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
        for app in runningSource where results.count < limit {
            guard let name = app.localizedName else { continue }
            let path = app.bundleURL?.path
            let bundleId = app.bundleIdentifier
            guard
                !shouldIgnoreApplicationFromAppSearch(
                    appName: name,
                    bundleIdentifier: bundleId,
                    path: path
                )
            else { continue }

            let key = bundleId ?? path ?? name.lowercased()
            guard seen.insert(key).inserted else { continue }
            results.append(
                SearchResult(
                    title: name,
                    subtitle: path ?? "Running",
                    icon: resolvedRunningAppIcon(for: app),
                    action: { activateRunningAppFromDock(app) },
                    type: .application,
                    filePath: path,
                    contactData: nil
                ))
        }

        for app in settings.pinnedApps where app.type == .application {
            add(
                SearchResult(
                    title: app.name,
                    subtitle: app.path,
                    icon: resolvedPinnedIcon(for: app),
                    action: { launchPinnedApp(app) },
                    type: .application,
                    filePath: app.path,
                    contactData: nil
                ))
        }

        for app in allApplications where app.type == .application {
            add(app)
        }

        return results
    }

    func runningApplication(forGlobalResult result: SearchResult) -> NSRunningApplication? {
        let source = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps

        if let path = result.filePath {
            if let bundleId = Bundle(path: path)?.bundleIdentifier,
                let match = source.first(where: { $0.bundleIdentifier == bundleId })
            {
                return match
            }
            if let match = source.first(where: { $0.bundleURL?.path == path }) {
                return match
            }
        }

        return source.first {
            $0.localizedName?.compare(
                result.title,
                options: [.caseInsensitive, .diacriticInsensitive]
            ) == .orderedSame
        }
    }

    func resolvedApplicationIcon(bundleIdentifier: String?, appName: String? = nil)
        -> NSImage?
    {
        if let bundleIdentifier, !bundleIdentifier.isEmpty {
            if let runningURL = runningRegularApps.first(where: {
                $0.bundleIdentifier == bundleIdentifier
            })?.bundleURL {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: runningURL.path))
            }
            if let appURL = NSWorkspace.shared.urlForApplication(
                withBundleIdentifier: bundleIdentifier)
            {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: appURL.path))
            }
        }

        guard let appName, !appName.isEmpty else { return nil }
        if let result = allApplications.first(where: {
            $0.title.compare(appName, options: [.caseInsensitive, .diacriticInsensitive])
                == .orderedSame
        }) {
            return preparedDockIcon(result.icon)
        }

        let appDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        let fileManager = FileManager.default
        for directory in appDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if fileManager.fileExists(atPath: url.path) {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: url.path))
            }
        }

        return nil
    }

    func typedL2AppIcon(for query: String) -> (icon: NSImage, bundleId: String)? {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard isL2ContextActive, isGlobalContextActive, !trimmed.isEmpty else { return nil }

        let normalized = trimmed.lowercased()
        let installedScopeMode = contextDockInstalledAppScopeMatching
        let dockOnlyMode = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningBundleIdsForContextDock()
        if let target = L2AppActionRouter.shared.appScopeTarget(for: normalized),
            !dockOnlyMode || runningBundleIds.contains(target.bundleId),
            let icon = resolvedApplicationIcon(
                bundleIdentifier: target.bundleId, appName: target.appName)
        {
            return (icon, target.bundleId)
        }

        if let target = installedAppMenuTarget(
            for: normalized,
            runningOnly: dockOnlyMode,
            includeAppsWithoutMenuSnapshot: installedScopeMode,
            allowPrefixAlias: installedScopeMode
        ),
            let icon = resolvedApplicationIcon(
                bundleIdentifier: target.bundleId,
                appName: target.appName
            ) ?? preparedDockIcon(NSWorkspace.shared.icon(forFile: target.appPath))
        {
            return (icon, target.bundleId)
        }

        if let completion = l2.appCompletion,
            let icon = resolvedApplicationIcon(
                bundleIdentifier: completion.bundleId, appName: completion.appName)
        {
            return (icon, completion.bundleId)
        }

        if let completion = bestL2PartialAppCompletion(for: normalized, runningOnly: dockOnlyMode),
            let icon = resolvedApplicationIcon(
                bundleIdentifier: completion.bundleId,
                appName: completion.appName
            )
                ?? installedApplicationResult(bundleIdentifier: completion.bundleId)?.icon
                .flatMap(preparedDockIcon)
        {
            return (icon, completion.bundleId)
        }

        guard let firstToken = normalized.split(separator: " ").first,
            firstToken.count >= (dockOnlyMode ? 3 : 2)
        else { return nil }
        let first = String(firstToken)
        if dockOnlyMode {
            let runningSource =
                runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
            if let app = runningSource.first(where: { app in
                guard let name = app.localizedName?.lowercased() else { return false }
                return name == first || name.hasPrefix(first)
            }), let bundleId = app.bundleIdentifier,
                let icon = resolvedRunningAppIcon(for: app)
            {
                return (icon, bundleId)
            }
            return nil
        }
        let appMatch = allApplications.first { result in
            let title = result.title.lowercased()
            let bundleId = Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
            return title == first
                || (title.hasPrefix(first)
                    && shouldAllowShortAppPrefixMatch(
                        prefix: first,
                        appName: result.title,
                        bundleIdentifier: bundleId
                    ))
        }
        guard let appMatch else { return nil }

        let bundleId =
            Bundle(url: URL(fileURLWithPath: appMatch.subtitle))?.bundleIdentifier
            ?? appMatch.subtitle
        if let icon = resolvedApplicationIcon(bundleIdentifier: bundleId, appName: appMatch.title)
            ?? preparedDockIcon(appMatch.icon)
        {
            return (icon, bundleId)
        }
        return nil
    }

    func globalScopedAppIcon(for query: String) -> (icon: NSImage, bundleId: String)? {
        guard isL2ContextActive, isGlobalContextActive, !hasActiveDockContextSelection else {
            return nil
        }
        let scope = resolveDockScope(for: query)
        guard scope.isExplicitAppScope, !scope.scopedBundleId.isEmpty else { return nil }
        let appPath =
            allApplications.first { result in
                Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
                    == scope.scopedBundleId
            }?.subtitle
            ?? NSWorkspace.shared.urlForApplication(withBundleIdentifier: scope.scopedBundleId)?
            .path
        let icon =
            resolvedApplicationIcon(
                bundleIdentifier: scope.scopedBundleId, appName: scope.scopedAppName)
            ?? appPath.map { preparedDockIcon(NSWorkspace.shared.icon(forFile: $0)) } ?? nil
        guard let icon else { return nil }
        return (icon, scope.scopedBundleId)
    }

    func bestL2PartialAppCompletion(
        for query: String, runningOnly: Bool = false
    ) -> AppCompletion? {
        let rawTrimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        // Strip .app suffix so "Clock.app" completes the same as "Clock"
        let trimmed =
            rawTrimmed.hasSuffix(".app")
            ? String(rawTrimmed.dropLast(4)).trimmingCharacters(in: .whitespacesAndNewlines)
            : rawTrimmed
        guard trimmed.count >= (runningOnly ? 3 : 2) else { return nil }
        let runningBundleIds: Set<String>? =
            runningOnly
            ? Set(NSWorkspace.shared.runningApplications.compactMap { $0.bundleIdentifier })
            : nil

        if !runningOnly, "clipboard".hasPrefix(trimmed) && trimmed != "clipboard" {
            return AppCompletion(
                appName: "Clipboard",
                bundleId: "scope://clipboard",
                ghost: String("clipboard".dropFirst(trimmed.count)),
                actionQuery: ""
            )
        }

        if let routerCompletion = L2AppActionRouter.shared.partialAppCompletion(for: trimmed),
            runningBundleIds == nil || runningBundleIds?.contains(routerCompletion.bundleId) == true
        {
            return routerCompletion
        }

        let tokens = trimmed.split(separator: " ").map(String.init)
        guard let firstToken = tokens.first, firstToken.count >= (runningOnly ? 3 : 2) else {
            return nil
        }
        let actionQuery = tokens.dropFirst().joined(separator: " ")
        guard
            shouldAllowLocalAppPartialCompletion(
                fullQuery: trimmed,
                firstToken: firstToken,
                actionQuery: actionQuery
            )
        else { return nil }

        func normalizeAppAlias(_ text: String) -> String {
            text.lowercased()
                .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }

        var best:
            (appName: String, bundleId: String, ghost: String, actionQuery: String, score: Double)?

        for result in allApplications where result.type == .application {
            let appName = result.title.trimmingCharacters(in: .whitespacesAndNewlines)
            let appPath = result.subtitle.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !appName.isEmpty, !appPath.isEmpty else { continue }

            let bundleId = Bundle(url: URL(fileURLWithPath: appPath))?.bundleIdentifier ?? appPath
            // In context dock mode: skip apps that aren't currently running
            if let runningBundleIds, !runningBundleIds.contains(bundleId) { continue }
            let normalizedName = normalizeAppAlias(appName)
            guard !normalizedName.isEmpty else { continue }

            var aliases = Set<String>()
            aliases.insert(normalizedName)
            if let first = normalizedName.split(separator: " ").first {
                aliases.insert(String(first))
            }
            if normalizedName.hasSuffix("s"), normalizedName.count > 3 {
                aliases.insert(String(normalizedName.dropLast()))
            }

            for alias in aliases {
                let aliasTokens = alias.split(separator: " ").map(String.init)
                guard let firstAliasToken = aliasTokens.first else { continue }
                guard firstAliasToken.hasPrefix(firstToken), firstAliasToken != firstToken else {
                    continue
                }
                guard
                    shouldAllowShortAppPrefixMatch(
                        prefix: firstToken,
                        appName: appName,
                        bundleIdentifier: bundleId
                    )
                else { continue }

                let ghost = String(alias.dropFirst(firstToken.count))
                let aliasUsage = UsageTracker.shared.getScore(for: "app:\(appPath)") / 100.0
                let exactFirstTokenBonus = firstAliasToken == normalizedName ? 0.4 : 0.0
                let score = Double(firstAliasToken.count) + aliasUsage + exactFirstTokenBonus

                if best == nil || score > best!.score {
                    best = (appName, bundleId, ghost, actionQuery, score)
                }
            }
        }

        guard let best else { return nil }
        return AppCompletion(
            appName: best.appName,
            bundleId: best.bundleId,
            ghost: best.ghost,
            actionQuery: best.actionQuery
        )
    }

    func installedApplicationResult(bundleIdentifier: String) -> SearchResult? {
        allApplications.first { result in
            result.type == .application
                && Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
                    == bundleIdentifier
        }
    }

    func launchTypedAppMatchIfNeeded() -> Bool {
        let trimmed = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalized = trimmed.lowercased()
        guard normalized.count >= 2 else { return false }
        guard !(isL2ContextActive && !isGlobalContextActive) else { return false }

        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []

        if let target = L2AppActionRouter.shared.appScopeTarget(for: normalized),
            !runningOnly || runningBundleIds.contains(target.bundleId),
            target.actionQuery.isEmpty
        {
            return launchApplication(
                bundleIdentifier: target.bundleId,
                appName: target.appName
            )
        }

        if let target = installedAppMenuTarget(
            for: normalized,
            runningOnly: runningOnly,
            includeAppsWithoutMenuSnapshot: installedScopeMode,
            allowPrefixAlias: installedScopeMode
        ),
            target.actionQuery.isEmpty
        {
            return launchApplication(
                bundleIdentifier: target.bundleId,
                appName: target.appName,
                path: target.appPath
            )
        }

        guard !normalized.contains(" ") else { return false }
        let shouldUsePrefixMatch = (runningOnly ? 3...3 : 2...3).contains(normalized.count)

        if isL2ContextActive,
            let completion = l2.appCompletion
                ?? bestL2PartialAppCompletion(for: normalized, runningOnly: runningOnly),
            completion.actionQuery.isEmpty,
            !completion.ghost.isEmpty
        {
            return launchApplication(
                bundleIdentifier: completion.bundleId, appName: completion.appName)
        }

        if shouldUsePrefixMatch,
            let completion = bestL2PartialAppCompletion(for: normalized, runningOnly: runningOnly),
            completion.actionQuery.isEmpty
        {
            return launchApplication(
                bundleIdentifier: completion.bundleId, appName: completion.appName)
        }

        if let result = allApplications.first(where: { result in
            guard !runningOnly else { return false }
            let title = result.title.lowercased()
            return title == normalized
                || (shouldUsePrefixMatch
                    && title.hasPrefix(normalized)
                    && shouldAllowShortAppPrefixMatch(
                        prefix: normalized,
                        appName: result.title,
                        bundleIdentifier: Bundle(url: URL(fileURLWithPath: result.subtitle))?
                            .bundleIdentifier
                    ))
        }) {
            let bundleId = Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
            return launchApplication(
                bundleIdentifier: bundleId, appName: result.title, path: result.subtitle)
        }

        if let app = runningRegularApps.first(where: { app in
            guard let name = app.localizedName?.lowercased() else { return false }
            return name == normalized
                || (shouldUsePrefixMatch
                    && name.hasPrefix(normalized)
                    && shouldAllowShortAppPrefixMatch(
                        prefix: normalized,
                        appName: app.localizedName ?? "",
                        bundleIdentifier: app.bundleIdentifier
                    ))
        }) {
            return launchApplication(
                bundleIdentifier: app.bundleIdentifier,
                appName: app.localizedName,
                path: app.bundleURL?.path
            )
        }

        return false
    }

    func launchApplication(bundleIdentifier: String?, appName: String?, path: String? = nil)
        -> Bool
    {
        // Track launch for usage-based completion ranking
        if let bid = bundleIdentifier, !bid.isEmpty {
            AppLaunchTracker.shared.record(bundleId: bid)
        }

        if let path, !path.isEmpty {
            openApplicationKeepingDockFocus(
                URL(fileURLWithPath: path),
                bundleIdentifier: bundleIdentifier
            )
            return true
        }

        if let bundleIdentifier,
            let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier)
        {
            openApplicationKeepingDockFocus(url, bundleIdentifier: bundleIdentifier)
            return true
        }

        guard let appName, !appName.isEmpty else { return false }
        let appDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        for directory in appDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if FileManager.default.fileExists(atPath: url.path) {
                openApplicationKeepingDockFocus(url, bundleIdentifier: bundleIdentifier)
                return true
            }
        }

        return false
    }

    func runningApp(for pinnedApp: PinnedApp) -> NSRunningApplication? {
        if let bundleId = pinnedApp.bundleIdentifier, !bundleId.isEmpty {
            return runningRegularApps.first {
                $0.bundleIdentifier == bundleId && !$0.isTerminated
            }
        }
        let itemPath = URL(fileURLWithPath: pinnedApp.path).path
        return runningRegularApps.first {
            guard let runningPath = $0.bundleURL?.path else { return false }
            return runningPath == itemPath && !$0.isTerminated
        }
    }

    func bundleIdentifier(for pinnedApp: PinnedApp) -> String? {
        if let bundleId = pinnedApp.bundleIdentifier, !bundleId.isEmpty {
            return bundleId
        }
        if let running = runningApp(for: pinnedApp)?.bundleIdentifier, !running.isEmpty {
            return running
        }
        guard pinnedApp.type == .application else { return nil }
        return Bundle(path: pinnedApp.path)?.bundleIdentifier
    }

    func resetDockStateAfterAppAction() {
        searchState.query = ""
        searchState.results = []
        searchState.selectedIndex = nil
        l2.focusedPillIndex = nil
        hoveredDockAppKey = nil
        lockedSubmenuParent = nil
    }

    func refocusLauncherWindowAfterAppAction(delay: TimeInterval = 0.12) {
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
            self.isVisible = true
            self.expandSearchBar()
            self.isSearchFieldFocused = true

            if let window = AppDelegate.shared?.launcherWindow
                ?? NSApp.windows.first(where: { $0.isVisible })
            {
                window.orderFrontRegardless()
                window.makeKeyAndOrderFront(nil)
            }

            NSApp.activate(ignoringOtherApps: true)
        }
    }

    func openApplicationKeepingDockFocus(_ url: URL, bundleIdentifier: String? = nil) {
        let resolvedBundleId = bundleIdentifier ?? Bundle(url: url)?.bundleIdentifier
        let urlAppName = url.deletingPathExtension().lastPathComponent
        resetDockStateAfterAppAction()
        collapseDockAfterResultExecution()

        if let resolvedBundleId,
            let runningApp = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == resolvedBundleId && !$0.isTerminated
            })
        {
            activateRunningAppFromDock(runningApp)
            return
        }

        let launchId = DockActionFeedback.start(
            "Opening", subject: urlAppName, icon: "arrow.up.right.circle.fill", tint: .accentColor)

        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true

        Task {
            var launchedApp: NSRunningApplication?
            do {
                launchedApp = try await NSWorkspace.shared.openApplication(
                    at: url, configuration: configuration)
            } catch {
                NSWorkspace.shared.open(url)
            }

            await MainActor.run {
                let name = launchedApp?.localizedName ?? urlAppName
                DockActionFeedback.complete(launchId, label: "\(name) opened")
                if let pid = launchedApp?.processIdentifier {
                    centerAppWindowIfPersistentDock(pid: pid)
                }
            }
        }
    }

    func activateRunningAppFromDock(_ app: NSRunningApplication) {
        resetDockStateAfterAppAction()
        collapseDockAfterResultExecution()
        let name = app.localizedName ?? "App"
        let switchId = DockActionFeedback.start(
            "Switching to", subject: name, icon: "arrow.up.right.circle", tint: .white.opacity(0.8))
        if app.isHidden { app.unhide() }
        app.activate(options: [.activateIgnoringOtherApps])
        let pid = app.processIdentifier
        // Dismiss the "Switching to" toast once the app has had time to become frontmost
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.45) {
            DockActionFeedback.complete(switchId)
        }
        // Un-minimize any minimized windows
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            let axApp = AXUIElementCreateApplication(pid)
            var windowsRef: CFTypeRef?
            if AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef)
                == .success,
                let windows = windowsRef as? [AXUIElement]
            {
                for win in windows {
                    var minimized: CFTypeRef?
                    if AXUIElementCopyAttributeValue(
                        win, kAXMinimizedAttribute as CFString, &minimized) == .success,
                        (minimized as? Bool) == true
                    {
                        AXUIElementSetAttributeValue(
                            win, kAXMinimizedAttribute as CFString, kCFBooleanFalse)
                    }
                }
            }
        }
        centerAppWindowIfPersistentDock(pid: pid)
        // Don't steal focus back — the activated app should remain frontmost
    }

    /// Called when an app is launched/activated from global context.
    /// Waits for macOS to confirm the app is frontmost, then hands off to Context Dock.
    func scheduleContextDockTransition(bundleId: String?, appName: String) {
        let normalizedAppName = appName.trimmingCharacters(in: .whitespacesAndNewlines)
        let resolvedBundleId = bundleId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let fallbackBundleId = NSWorkspace.shared.runningApplications.first { app in
            guard !app.isTerminated else { return false }
            return app.localizedName?.compare(
                normalizedAppName,
                options: [.caseInsensitive, .diacriticInsensitive]
            ) == .orderedSame
        }?.bundleIdentifier

        guard
            let bundleId = [resolvedBundleId, fallbackBundleId].compactMap({ $0 }).first(where: {
                !$0.isEmpty
            })
        else {
            return
        }
        pendingGlobalLaunchContextSwitch = (bundleId: bundleId, appName: appName)
        globalInlineAppScope = nil
        additionalGlobalInlineAppScopes = []
        dismissedGlobalInlineAppScopes = [:]
        l2.targetApp = nil
        searchState.query = ""
        focusedAppPillIndex = nil
        hoveredAppPillIndex = nil
        l2.focusedPillIndex = nil
        l2.pillNavViaKeyboard = false
        scheduleGlobalGroupedListRebuild(query: "", delayNanoseconds: 0)

        // If the user picks the already-frontmost running app, macOS may not emit a
        // didActivateApplication notification. Switch immediately instead of waiting.
        let activeBundleId = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        if frontmost.bundleID == bundleId || activeBundleId == bundleId {
            switchGlobalLaunchToContextDock(bundleId: bundleId, appName: appName)
            return
        }

        // Fallback for apps that activate before the observer publishes its event.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.75) {
            guard self.pendingGlobalLaunchContextSwitch?.bundleId == bundleId else { return }
            let activeBundleId = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
            guard self.frontmost.bundleID == bundleId || activeBundleId == bundleId else { return }
            self.switchGlobalLaunchToContextDock(bundleId: bundleId, appName: appName)
        }
    }

    func switchGlobalLaunchToContextDock(bundleId: String, appName: String) {
        pendingGlobalLaunchContextSwitch = nil
        globalContextActivation = nil
        globalInlineAppScope = nil
        additionalGlobalInlineAppScopes = []
        suppressGlobalInlineAppScopeDetection = false
        dismissedGlobalInlineAppScopes = [:]
        l2.targetApp = nil
        searchState.query = ""
        focusedAppPillIndex = nil
        hoveredAppPillIndex = nil
        l2.focusedPillIndex = nil
        l2.pillNavViaKeyboard = false
        showMediaLayer = false
        aiMode.isActive = false
        showContextInDock = true
        if let app = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleId
        }) {
            frontmost.bundleID = bundleId
            frontmost.name = app.localizedName ?? appName
            frontmost.icon =
                resolvedApplicationIcon(bundleIdentifier: bundleId, appName: frontmost.name)
                ?? preparedDockIcon(app.icon)
        } else {
            frontmost.bundleID = bundleId
            frontmost.name = appName
            frontmost.icon = resolvedApplicationIcon(bundleIdentifier: bundleId, appName: appName)
        }
        setFrontmostAppContextOnly(reason: "global launch became frontmost")
        syncL2DockSession(force: true)
        scheduleDockPillRebuild(query: "", delayNanoseconds: 0, refreshContext: false)
        collapseDockAfterResultExecution()
    }

    /// When Persistent Dock Mode is active, center the app's frontmost window in the
    /// visible screen area so it doesn't hide behind the dock.
    func centerAppWindowIfPersistentDock(pid: pid_t) {
        guard settings.persistentContextDock else { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
            guard let screen = NSScreen.main else { return }
            let visibleFrame = screen.visibleFrame  // Cocoa coords (Y from bottom)
            let screenHeight = screen.frame.height  // For flipping to AX coords
            let axApp = AXUIElementCreateApplication(pid)
            var windowsRef: CFTypeRef?
            guard
                AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef)
                    == .success,
                let windows = windowsRef as? [AXUIElement], let win = windows.first
            else { return }

            var sizeRef: CFTypeRef?
            guard
                AXUIElementCopyAttributeValue(win, kAXSizeAttribute as CFString, &sizeRef)
                    == .success,
                let sv = sizeRef
            else { return }
            var winSize = CGSize.zero
            AXValueGetValue(sv as! AXValue, .cgSize, &winSize)
            guard winSize.width > 0 else { return }

            // Convert visible frame to AX coordinate space (Y increases downward from top)
            let axVisibleTop = screenHeight - visibleFrame.maxY
            let axVisibleLeft = visibleFrame.minX
            let cx = axVisibleLeft + (visibleFrame.width - winSize.width) / 2
            let cy = axVisibleTop + (visibleFrame.height - winSize.height) / 2
            var pt = CGPoint(x: max(axVisibleLeft, cx), y: max(axVisibleTop, cy))
            if let posVal = AXValueCreate(.cgPoint, &pt) {
                AXUIElementSetAttributeValue(win, kAXPositionAttribute as CFString, posVal)
            }
        }
    }

    func terminateRunningAppFromDock(_ app: NSRunningApplication) {
        let name = app.localizedName ?? "App"
        hoveredDockAppKey = nil
        app.terminate()
        DockActionFeedback.start(
            "Quit", subject: name, icon: "xmark.circle.fill", tint: .red.opacity(0.85))
        refocusLauncherWindowAfterAppAction(delay: 0.06)
        scheduleDockRefreshAfterTerminationAttempt(for: app)
    }

    func shouldRequireFullAppNameMatch(
        appName: String,
        bundleIdentifier: String?
    ) -> Bool {
        let normalizedName = normalizedDockPillText(appName)
        if normalizedName == "news" { return true }
        return bundleIdentifier == "com.apple.news"
    }

    func shouldAllowShortAppPrefixMatch(
        prefix: String,
        appName: String,
        bundleIdentifier: String?
    ) -> Bool {
        guard
            !shouldRequireFullAppNameMatch(
                appName: appName,
                bundleIdentifier: bundleIdentifier
            )
        else {
            return prefix.count >= 4
        }
        return true
    }

    func shouldAllowLocalAppPartialCompletion(
        fullQuery: String,
        firstToken: String,
        actionQuery: String
    ) -> Bool {
        guard !actionQuery.isEmpty else { return true }
        if isQuestionLikeAppPartialQuery(fullQuery) { return false }
        if isCommonLanguageAppPartialStart(firstToken)
            && !looksLikeAppCommandRemainder(actionQuery)
        {
            return false
        }
        return true
    }

    func isQuestionLikeAppPartialQuery(_ query: String) -> Bool {
        let tokens = query.split(separator: " ").map(String.init)
        guard let first = tokens.first else { return false }
        let questionStarts: Set<String> = [
            "what", "whats", "who", "when", "where", "why", "how",
            "is", "are", "do", "does", "did", "can", "could", "should",
            "tell", "explain", "describe", "summarize", "analyse", "analyze",
        ]
        if questionStarts.contains(first) { return true }
        if tokens.count >= 2 {
            let firstTwo = tokens.prefix(2).joined(separator: " ")
            if ["what is", "what are", "how do", "how can", "tell me"].contains(firstTwo) {
                return true
            }
        }
        return false
    }

    func isCommonLanguageAppPartialStart(_ token: String) -> Bool {
        let commonStarts: Set<String> = [
            "a", "an", "the", "this", "that", "these", "those",
            "what", "whats", "who", "when", "where", "why", "how",
            "is", "are", "do", "does", "did", "can", "could", "should",
            "i", "me", "my", "we", "you", "it", "its",
            "tell", "explain", "describe", "summarize", "analyse", "analyze",
        ]
        return commonStarts.contains(token)
    }

    func looksLikeAppCommandRemainder(_ actionQuery: String) -> Bool {
        guard let first = actionQuery.split(separator: " ").map(String.init).first else {
            return false
        }
        let commandStarts: Set<String> = [
            "open", "new", "close", "send", "message", "call", "search", "find",
            "show", "list", "compose", "create", "add", "play", "pause", "stop",
            "next", "previous", "download", "share", "copy", "paste", "reply",
        ]
        return commandStarts.contains(first)
    }

    func fallbackRunningAppAfterTermination(
        excludingProcessIdentifier processIdentifier: pid_t,
        excludingBundleIdentifier bundleIdentifier: String?
    ) -> NSRunningApplication? {
        let candidates = currentRegularRunningApps().filter { app in
            guard app.processIdentifier != processIdentifier else { return false }
            if let bundleIdentifier, !bundleIdentifier.isEmpty {
                return app.bundleIdentifier != bundleIdentifier
            }
            return true
        }

        if let finder = candidates.first(where: { $0.bundleIdentifier == "com.apple.finder" }) {
            return finder
        }
        return candidates.first
    }

    func clearLiveDockMenuState() {
        liveMenuItems = []
        crossAppMenuItems = []
        crossAppMenuTargetPID = 0
        contextMenuPills = []
        previousEnabledIDs = []
        menuDebugText = "menu debug unavailable"
    }

    func reconcileDockAfterTermination(of app: NSRunningApplication) {
        runningRegularApps = currentRegularRunningApps()

        if let delegate = AppDelegate.shared,
            delegate.previousFrontmostApp?.processIdentifier == app.processIdentifier
                || (!(app.bundleIdentifier ?? "").isEmpty
                    && delegate.previousFrontmostApp?.bundleIdentifier == app.bundleIdentifier)
        {
            delegate.previousFrontmostApp = fallbackRunningAppAfterTermination(
                excludingProcessIdentifier: app.processIdentifier,
                excludingBundleIdentifier: app.bundleIdentifier
            )
        }

        if frontmost.bundleID == app.bundleIdentifier
            || frontmost.name == (app.localizedName ?? "")
        {
            frontmost.bundleID = ""
            frontmost.name = ""
            frontmost.icon = nil
        }

        detectAndUpdateContext()

        if showContextInDock, let targetApp = contextTargetApp() {
            reloadMenuForApp(targetApp)
        } else {
            clearLiveDockMenuState()
        }

        updateWindowSize()
    }

    func scheduleDockRefreshAfterTerminationAttempt(for app: NSRunningApplication) {
        let targetPID = app.processIdentifier
        let targetBundleId = app.bundleIdentifier

        Task {
            for _ in 0..<18 {
                try? await Task.sleep(nanoseconds: 150_000_000)
                let apps = currentRegularRunningApps()
                runningRegularApps = apps

                let stillRunning = apps.contains { running in
                    if running.processIdentifier == targetPID { return true }
                    if let targetBundleId, !targetBundleId.isEmpty {
                        return running.bundleIdentifier == targetBundleId
                    }
                    return false
                }

                guard !stillRunning else { continue }
                reconcileDockAfterTermination(of: app)
                return
            }

            runningRegularApps = currentRegularRunningApps()
        }
    }

    func executeDockMenuAction(
        sourcePID: pid_t,
        path: [String],
        shortcutChar: String?,
        shortcutModifiers: Int
    ) {
        MenuExecutionCoordinator.shared.executeDockMenuAction(
            request: .init(
                sourcePID: sourcePID,
                path: path,
                shortcutChar: shortcutChar,
                shortcutModifiers: shortcutModifiers,
                knownMenuItems: liveMenuItems + crossAppMenuItems,
                isGlobalContextActive: isGlobalContextActive,
                hasActiveDockContextSelection: hasActiveDockContextSelection
            ),
            callbacks: .init(
                collapseBeforeExecution: { collapseDockAfterResultExecution() },
                collapseFinderToIcon: { collapseDockToIconAfterFinderAction() },
                focusLauncher: {
                    AppDelegate.shared?.launcherWindow?.makeKeyAndOrderFront(nil)
                    isSearchFieldFocused = true
                },
                refreshRunningApps: {
                    runningRegularApps = currentRegularRunningApps()
                },
                scheduleTerminationRefresh: { app in
                    scheduleDockRefreshAfterTerminationAttempt(for: app)
                },
                reloadMenu: { app in
                    reloadMenuForApp(app)
                },
                clearLiveDockMenuState: {
                    clearLiveDockMenuState()
                }
            )
        )
    }

    func resolvedRunningAppIcon(for app: NSRunningApplication) -> NSImage? {
        if let bundleURL = app.bundleURL {
            return preparedDockIcon(NSWorkspace.shared.icon(forFile: bundleURL.path))
        }
        return preparedDockIcon(app.icon)
    }

    var shouldShowGlobalRunningAppStrip: Bool {
        isGlobalContextActive
            && showContextInDock
            && !aiMode.isActive
            && !showMediaLayer
            && !isCompactSmartScope
            && searchState.contextApp == nil
            && searchState.selectedIndex == nil
            && activeSelectionLabel == nil
    }

    var currentGlobalScopedBundleID: String? {
        if let target = l2.targetApp?.bundleId,
            !target.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return target
        }
        if let target = globalInlineAppScope?.bundleId,
            !target.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return target
        }
        return nil
    }

    var globalRunningAppStripApps: [NSRunningApplication] {
        guard shouldShowGlobalRunningAppStrip else { return [] }
        let frontmostBundle = frontmost.bundleID.trimmingCharacters(in: .whitespacesAndNewlines)
        let scopedBundle = currentGlobalScopedBundleID
        return (runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps)
            .filter { app in
                guard let bundleID = app.bundleIdentifier else { return true }
                return bundleID != frontmostBundle && bundleID != scopedBundle
            }
            .prefix(5)
            .map { $0 }
    }

    var globalScopeCycleApps: [NSRunningApplication] {
        guard isGlobalContextActive,
            showContextInDock,
            !aiMode.isActive,
            !showMediaLayer,
            !isCompactSmartScope,
            searchState.contextApp == nil,
            activeSelectionLabel == nil
        else { return [] }

        let frontmostBundle = frontmost.bundleID.trimmingCharacters(in: .whitespacesAndNewlines)
        let scopedBundle = currentGlobalScopedBundleID
        var seen = Set<String>()
        return (runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps)
            .filter { app in
                guard let bundleID = app.bundleIdentifier, !bundleID.isEmpty else { return false }
                guard seen.insert(bundleID).inserted else { return false }
                if bundleID == Bundle.main.bundleIdentifier { return false }
                if bundleID == "com.apple.finder" { return false }
                if bundleID == scopedBundle { return true }
                return bundleID != frontmostBundle
            }
    }

    @discardableResult
    func switchGlobalContextScope(to app: NSRunningApplication) -> Bool {
        guard let bundleID = app.bundleIdentifier,
            let appName = app.localizedName?.trimmingCharacters(in: .whitespacesAndNewlines),
            !bundleID.isEmpty,
            !appName.isEmpty
        else { return false }
        let activated = activateInlineDockAppScope(
            bundleIdentifier: bundleID,
            appName: appName,
            queryOverride: searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? "" : nil,
            preserveGlobalContext: true
        )
        if activated {
            DispatchQueue.main.async {
                DispatchQueue.main.async {
                    self.reclaimSearchInputFocus()
                }
            }
        }
        return activated
    }

    @discardableResult
    func cycleGlobalContextAppScope(direction: Int) -> Bool {
        let apps = globalScopeCycleApps
        guard !apps.isEmpty else { return false }

        let nextApp: NSRunningApplication
        if let scopedBundle = currentGlobalScopedBundleID,
            let currentIndex = apps.firstIndex(where: { $0.bundleIdentifier == scopedBundle })
        {
            let count = apps.count
            let offset = direction >= 0 ? 1 : -1
            let nextIndex = (currentIndex + offset + count) % count
            nextApp = apps[nextIndex]
        } else {
            nextApp = direction >= 0 ? apps[0] : apps[apps.count - 1]
        }

        return switchGlobalContextScope(to: nextApp)
    }

    @ViewBuilder
    var globalRunningAppStrip: some View {
        let apps = globalRunningAppStripApps
        if !apps.isEmpty {
            HStack(spacing: 5) {
                ForEach(apps, id: \.processIdentifier) { app in
                    Button {
                        _ = switchGlobalContextScope(to: app)
                    } label: {
                        if let icon = resolvedRunningAppIcon(for: app) {
                            Image(nsImage: icon)
                                .resizable()
                                .aspectRatio(contentMode: .fit)
                                .frame(width: 17, height: 17)
                                .clipShape(RoundedRectangle(cornerRadius: 4, style: .continuous))
                        } else {
                            Image(systemName: "app")
                                .font(.system(size: 13, weight: .semibold))
                                .foregroundStyle(.secondary.opacity(0.75))
                                .frame(width: 17, height: 17)
                        }
                    }
                    .buttonStyle(.plain)
                    .focusable(false)
                    .help("Scope to \(app.localizedName ?? "app")")
                }
            }
            .padding(.horizontal, 7)
            .padding(.vertical, 4)
            .background(.regularMaterial, in: Capsule(style: .continuous))
            .overlay(
                Capsule(style: .continuous)
                    .strokeBorder(
                        Color.white.opacity(systemColorScheme == .dark ? 0.16 : 0.22),
                        lineWidth: 0.7)
            )
            .transition(.scale(scale: 0.9, anchor: .trailing).combined(with: .opacity))
        }
    }

    func preparedDockIcon(_ icon: NSImage?) -> NSImage? {
        guard let icon else { return nil }
        let copy = icon.copy() as? NSImage ?? icon
        copy.size = NSSize(width: 64, height: 64)
        return copy
    }

    @ViewBuilder
    func appPillButton(
        icon: NSImage?,
        label: String,
        subtitle: String? = nil,
        hoverKey: String,
        focused: Bool = false,
        index: Int? = nil,
        isExpanded: Bool = false,  // fills the vacated search-bar width
        destructiveAction: (() -> Void)? = nil,
        removeAction: (() -> Void)? = nil,
        pinAction: (() -> Void)? = nil,  // double-click to pin
        action: @escaping () -> Void
    ) -> some View {
        let hovered = hoveredDockAppKey == hoverKey || focused
        let sz = CGFloat(settings.dockIconSize)
        let iconSize: CGFloat = isExpanded ? sz * 0.78 : sz * 0.72
        let textSize: CGFloat = min(isExpanded ? 15 : 13, max(12, sz * (isExpanded ? 0.24 : 0.22)))
        let pillHeight: CGFloat = isExpanded ? sz + 8 : sz + 4
        let cornerRadius: CGFloat = max(5, iconSize / 4.2)
        let leadingPad: CGFloat = isExpanded ? max(10, sz * 0.20) : max(10, sz * 0.18)
        let separatorHeight: CGFloat = isExpanded ? max(24, sz * 0.50) : max(24, sz * 0.46)
        let trailingPad: CGFloat =
            isExpanded ? 12 : (destructiveAction != nil || removeAction != nil ? 8 : 12)
        let isDarkMode = systemColorScheme == .dark

        ZStack(alignment: .topTrailing) {
            Button(action: action) {
                HStack(spacing: 0) {
                    if let icon {
                        Image(nsImage: icon)
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                            .frame(width: iconSize, height: iconSize)
                            .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
                            .padding(.leading, leadingPad)
                    } else {
                        Image(systemName: "app.fill")
                            .font(.system(size: iconSize * 0.72, weight: .medium))
                            .foregroundStyle(.secondary)
                            .frame(width: iconSize, height: iconSize)
                            .padding(.leading, leadingPad)
                    }
                    Rectangle()
                        .fill(Color.white.opacity(isExpanded ? 0.16 : 0.12))
                        .frame(width: 1, height: separatorHeight)
                        .padding(.horizontal, isExpanded ? 10 : 8)
                    VStack(alignment: .leading, spacing: 1) {
                        HStack(spacing: 4) {
                            Text(label)
                                .font(
                                    .system(
                                        size: textSize, weight: isExpanded ? .semibold : .medium)
                                )
                                .foregroundStyle(
                                    Color.primary.opacity(isExpanded ? 1.0 : (focused ? 1.0 : 0.9)))
                            if destructiveAction != nil {
                                Image(systemName: "chevron.right")
                                    .font(.system(size: max(9, textSize - 3), weight: .semibold))
                                    .foregroundStyle(.secondary.opacity(isExpanded ? 0.75 : 0.62))
                            }
                        }
                        .lineLimit(1)
                        if isExpanded, let sub = subtitle {
                            Text(sub)
                                .font(.system(size: 10, weight: .medium))
                                .foregroundStyle(
                                    sub == "Running"
                                        ? Color.green.opacity(0.85)
                                        : Color.secondary.opacity(0.65)
                                )
                                .lineLimit(1)
                        }
                    }
                    .padding(.trailing, isExpanded ? 4 : trailingPad)
                    .mask(alignment: .leading) {
                        // Smooth gradient fade on the trailing edge for expanded pills
                        if isExpanded {
                            LinearGradient(
                                stops: [
                                    .init(color: .black, location: 0),
                                    .init(color: .black, location: 0.75),
                                    .init(color: .clear, location: 1.0),
                                ],
                                startPoint: .leading, endPoint: .trailing)
                        } else {
                            Color.black
                        }
                    }
                    if isExpanded {
                        Spacer(minLength: 0)
                        if destructiveAction != nil {
                            Image(systemName: "delete.left")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.secondary.opacity(0.55))
                                .padding(.trailing, 8)
                        }
                        Image(systemName: "return")
                            .font(.system(size: 11, weight: .medium))
                            .foregroundStyle(.secondary.opacity(0.55))
                            .padding(.trailing, pinAction != nil ? 8 : 12)
                        if let pin = pinAction {
                            Button(action: pin) {
                                Image(systemName: "pin")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundStyle(.secondary.opacity(0.55))
                                    .padding(.trailing, 12)
                            }
                            .buttonStyle(.plain)
                            .help("Pin \(label)")
                        }
                    }
                }
                .frame(maxWidth: isExpanded ? .infinity : nil)
                .frame(height: pillHeight)
                .background {
                    ZStack {
                        Capsule().fill(.ultraThinMaterial)
                        Capsule().fill(
                            isDarkMode
                                ? Color.black.opacity(isExpanded ? 0.10 : 0.06)
                                : Color.white.opacity(isExpanded ? 0.22 : 0.14)
                        )
                        Capsule().fill(
                            LinearGradient(
                                colors: [
                                    .white.opacity(
                                        isExpanded
                                            ? 0.18 : (focused ? 0.16 : (hovered ? 0.12 : 0.07))),
                                    .white.opacity(isExpanded ? 0.035 : (focused ? 0.04 : 0.015)),
                                ],
                                startPoint: .top, endPoint: .bottom)
                        )
                        Capsule().strokeBorder(
                            LinearGradient(
                                colors: [
                                    .white.opacity(isExpanded ? 0.34 : (hovered ? 0.28 : 0.16)),
                                    .white.opacity(0.035),
                                ],
                                startPoint: .topLeading, endPoint: .bottomTrailing),
                            lineWidth: isExpanded ? 1.0 : (focused ? 1.0 : 0.75))
                    }
                }
                .shadow(
                    color: .black.opacity(
                        isExpanded ? 0.20 : (focused ? 0.16 : (hovered ? 0.10 : 0.06))),
                    radius: isExpanded ? 10 : (focused ? 8 : 5),
                    y: isExpanded ? 5 : 3
                )
                .animation(.spring(response: 0.22, dampingFraction: 0.75), value: isExpanded)
                .animation(.spring(response: 0.18, dampingFraction: 0.75), value: focused)
            }
            .buttonStyle(.plain)
            .zIndex(isExpanded ? 20 : (focused ? 10 : (hovered ? 5 : 0)))

            if hovered, !isExpanded, let quit = destructiveAction {
                Button(action: quit) {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: max(14, sz * 0.24), weight: .semibold))
                        .foregroundStyle(.white, Color.black.opacity(0.65))
                }
                .buttonStyle(.plain)
                .offset(x: max(4, sz * 0.08), y: -max(4, sz * 0.08))
                .transition(.scale(scale: 0.6).combined(with: .opacity))
            } else if hovered, !isExpanded, let remove = removeAction {
                Button(action: remove) {
                    Image(systemName: "minus.circle.fill")
                        .font(.system(size: max(14, sz * 0.24), weight: .semibold))
                        .foregroundStyle(.white, Color.black.opacity(0.65))
                }
                .buttonStyle(.plain)
                .offset(x: max(4, sz * 0.08), y: -max(4, sz * 0.08))
                .transition(.scale(scale: 0.6).combined(with: .opacity))
            }

        }
        .simultaneousGesture(
            TapGesture(count: 2).onEnded { pinAction?() }
        )
        .onHover { hovering in
            guard acceptsMouseDrivenDockInteraction else { return }
            withAnimation(.spring(response: 0.15, dampingFraction: 0.80)) {
                hoveredDockAppKey = hovering ? hoverKey : nil
                if let index { hoveredAppPillIndex = hovering ? index : nil }
            }
        }
        .help(pinAction != nil ? "\(label) — double-click to pin" : label)
    }

    func appIconButton(
        icon: NSImage?,
        label: String,
        isRunning: Bool,
        hoverKey: String? = nil,
        onCloseRunningApp: (() -> Void)? = nil,
        action: @escaping () -> Void
    ) -> some View {
        let sz = CGFloat(settings.dockIconSize)
        let outerSz = sz + 4
        let cornerRadius = sz / 4.4
        let dotSize = max(5, sz * 0.159)
        return ZStack(alignment: .topTrailing) {
            Button(action: action) {
                ZStack(alignment: .bottomTrailing) {
                    if let icon {
                        Image(nsImage: icon)
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                            .frame(width: sz, height: sz)
                            .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
                    } else {
                        Image(systemName: "app")
                            .font(.system(size: sz * 0.636, weight: .medium))
                            .foregroundStyle(.secondary)
                            .frame(width: sz, height: sz)
                    }

                    if isRunning {
                        Circle()
                            .fill(.green)
                            .frame(width: dotSize, height: dotSize)
                            .overlay(
                                Circle().strokeBorder(Color.black.opacity(0.3), lineWidth: 0.5)
                            )
                            .offset(x: 2, y: 2)
                    }
                }
                .frame(width: outerSz, height: outerSz)
            }
            .buttonStyle(.plain)

            if let hoverKey, let onCloseRunningApp, isRunning {
                Button(action: onCloseRunningApp) {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundStyle(.white, Color.black.opacity(0.72))
                        .background(Color.black.opacity(0.12), in: Circle())
                }
                .buttonStyle(.plain)
                .opacity(hoveredDockAppKey == hoverKey ? 1 : 0)
                .offset(x: 4, y: -4)
                .help("Quit \(label)")
            }
        }
        .frame(width: outerSz, height: outerSz)
        .onHover { hovering in
            guard acceptsMouseDrivenDockInteraction else { return }
            guard let hoverKey else { return }
            if hovering {
                hoveredDockAppKey = hoverKey
            } else if hoveredDockAppKey == hoverKey {
                hoveredDockAppKey = nil
            }
        }
        .help(label)
        .animation(.spring(response: 0.25, dampingFraction: 0.72), value: sz)
    }

    @ViewBuilder
    func compactSuggestionPillButton(pill: DockPill, index: Int) -> some View {
        let accent = accentColor(for: pill.accentColorName)
        Button {
            executeDockPill(pill)
            l2.focusedPillIndex = nil
        } label: {
            HStack(spacing: 6) {
                Image(systemName: pill.icon)
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(accent)
                Text(pill.name)
                    .font(.system(size: 11, weight: .medium))
                    .foregroundStyle(.primary)
                    .lineLimit(1)
                let status = pill.menuStatusBadge?.trimmingCharacters(in: .whitespacesAndNewlines)
                let badge = pill.badge?.trimmingCharacters(in: .whitespacesAndNewlines)
                if let badge, !badge.isEmpty {
                    compactPillBadge(badge)
                }
                if let status, !status.isEmpty, status != badge {
                    compactPillBadge(status)
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .background(.regularMaterial, in: Capsule())
            .overlay(Capsule().strokeBorder(accent.opacity(0.28), lineWidth: 0.5))
        }
        .buttonStyle(.plain)
        .help(pill.name)
        .onHover { hovering in
            guard acceptsMouseDrivenDockInteraction else { return }
            if !l2.pillNavViaKeyboard {
                l2.focusedPillIndex = hovering ? index : nil
            }
        }
    }

    @ViewBuilder
    func compactPillBadge(_ text: String) -> some View {
        Text(text)
            .font(.system(size: 9, weight: .medium))
            .foregroundStyle(.secondary)
            .lineLimit(1)
            .padding(.horizontal, 4)
            .padding(.vertical, 1)
            .background(.secondary.opacity(0.12), in: Capsule())
    }

    @ViewBuilder
    var contextChipsInDock: some View {
        // Combine frontmost app shortcuts and context-aware shortcuts
        let allContextShortcuts: [SearchResult] = {
            var shortcuts: [SearchResult] = []

            // Add context-aware shortcuts
            if !searchState.query.isEmpty && !searchState.grouped.suggestedShortcuts.isEmpty {
                shortcuts.append(contentsOf: searchState.grouped.suggestedShortcuts)
            } else if searchState.query.isEmpty && hasContextToShow {
                let contextMatched = allShortcuts.filter { shortcut in
                    guard let metadata = shortcutMetadataCache[shortcut.title] else { return false }
                    return metadata.matches(context: currentContext)
                }
                shortcuts.append(contentsOf: contextMatched)
            }

            // Remove duplicates by id
            var seen = Set<String>()
            return shortcuts.filter { shortcut in
                guard !seen.contains(shortcut.id.uuidString) else { return false }
                seen.insert(shortcut.id.uuidString)
                return true
            }
        }()

        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(allContextShortcuts) { shortcut in
                    Button(action: {
                        executeResult(shortcut)
                    }) {
                        HStack(spacing: 6) {
                            if let icon = shortcut.icon {
                                Image(nsImage: icon)
                                    .resizable()
                                    .aspectRatio(contentMode: .fit)
                                    .frame(width: 20, height: 20)
                            } else {
                                Image(systemName: "bolt.fill")
                                    .font(.system(size: 12))
                                    .foregroundStyle(.orange)
                            }
                            Text(shortcut.title)
                                .font(.system(size: 13, weight: .medium))
                                .lineLimit(1)
                        }
                        .padding(.horizontal, 10)
                        .padding(.vertical, 6)
                        .background(
                            Capsule()
                                .fill(Color.blue.opacity(0.15))
                        )
                    }
                    .buttonStyle(.plain)
                    .help(shortcut.subtitle)
                }
            }
        }
    }

    // Check if AI extensions are available to show
    var hasAIExtensionsToShow: Bool {
        return aiMode.isActive && settings.enableContextAIExtensions
            && !aiExtensionSuggestions.isEmpty
    }

    var hasL2ExtensionsToShow: Bool {
        return settings.enableContextAIExtensions && !l2.contextExtensions.isEmpty
    }

    var isL2ContextActive: Bool {
        // L2 is active whenever the context dock is showing, we're not in pure AI mode,
        // and we're not in L3 browser layer. L3 must stay independent from L2.
        showContextInDock && !aiMode.isActive && !showMediaLayer
    }

    func dismissMediaLayer() {
        if showMediaLayer {
            showMediaLayer = false
        }
    }

    @ViewBuilder
    var aiExtensionsInDock: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(aiExtensionSuggestions) { suggestion in
                    AIExtensionChipButton(
                        suggestion: suggestion,
                        context: currentContext,
                        chatMessages: aiModeMessagesBinding
                    )
                }
            }
        }
    }

    // ── L2 Panel Quick Action Pills ─────────────────────────────────────────
    /// Quick actions from all user-created panels, shown as floating pills in L2 mode.
    /// Groups by panel key and shows up to 6 most recently used.
    var l2PanelQuickActions: [AppShortcut] {
        let allKeys = AppPanelChatStore.shared.allPanelKeys()
        let frontApp = frontmost.name.lowercased()
        // Prioritise panels matching the current frontmost app, then rest
        var keys = allKeys.filter {
            $0.localizedCaseInsensitiveContains(frontApp) && !frontApp.isEmpty
        }
        keys += allKeys.filter {
            !($0.localizedCaseInsensitiveContains(frontApp) && !frontApp.isEmpty)
        }
        // Gather shortcuts for these panel keys (max 8)
        var result: [AppShortcut] = []
        for key in keys {
            let shortcuts = settings.shortcuts(for: key)
            result.append(contentsOf: shortcuts)
            if result.count >= 8 { break }
        }
        return Array(result.prefix(8))
    }

    @ViewBuilder
    var l2QuickActionPills: some View {
        let pills = l2PanelQuickActions
        if !pills.isEmpty {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    ForEach(pills) { sc in
                        Button {
                            executeAppShortcut(sc)
                        } label: {
                            HStack(spacing: 5) {
                                Image(systemName: sc.iconName)
                                    .font(.system(size: 10, weight: .semibold))
                                Text(sc.name)
                                    .font(.system(size: 11, weight: .medium))
                                    .lineLimit(1)
                            }
                            .padding(.horizontal, 10)
                            .padding(.vertical, 5)
                            .background(.regularMaterial, in: Capsule())
                            .overlay(Capsule().strokeBorder(.primary.opacity(0.07), lineWidth: 0.5))
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(.horizontal, 2)
            }
        }
    }

    /// L2Extensions from L2ExtensionManager that match the current frontmost app.
    var frontmostAppL2Extensions: [L2Extension] {
        let appName: String
        let bundleID: String
        if !frontmost.name.isEmpty {
            appName = frontmost.name
            bundleID = frontmost.bundleID
        } else if let ws = NSWorkspace.shared.frontmostApplication,
            let name = ws.localizedName,
            !(ws.bundleIdentifier ?? "").contains("ILauncher")
        {
            appName = name
            bundleID = ws.bundleIdentifier ?? ""
        } else {
            return []
        }
        return l2Extensions(forAppName: appName, bundleID: bundleID)
    }

    func l2Extensions(forAppName appName: String, bundleID: String) -> [L2Extension] {
        let appLower = appName.lowercased()
        let bundleLower = bundleID.lowercased()
        return L2ExtensionManager.shared.extensions.filter { ext in
            guard !ext.contextApps.isEmpty else { return false }
            // Check ALL contextApps entries (app name OR bundle ID match)
            return ext.contextApps.contains { ctx in
                let ctxLower = ctx.lowercased()
                return ctxLower == appLower
                    || ctxLower.contains(appLower)
                    || appLower.contains(ctxLower)
                    || (!bundleLower.isEmpty
                        && (ctxLower == bundleLower || ctxLower.contains(bundleLower)))
            }
        }
    }

    func scopedContextExtensions(query: String, appName: String?, bundleId: String?)
        -> [ExtensionDiscoveryResult]
    {
        guard settings.enableContextAIExtensions else { return [] }

        let trimmedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let includeSelectionContext =
            !isL2ContextActive && AppDelegate.shared?.isDockContextMode != true

        let contextFiles: [URL] = {
            guard includeSelectionContext else { return [] }
            switch currentContext {
            case .filesSelected(let urls): return urls
            default:
                return axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            }
        }()
        let selectedText: String? = {
            guard includeSelectionContext else { return nil }
            switch currentContext {
            case .textSelected(let t): return t.isEmpty ? nil : t
            default: return nil
            }
        }()

        let resolvedAppName: String? = {
            if let appName, !appName.isEmpty { return appName }
            if let bundleId,
                let app = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleId
                })
            {
                return app.localizedName
            }
            return nil
        }()

        guard resolvedAppName != nil || !contextFiles.isEmpty || selectedText != nil else {
            return []
        }

        let results = LayeredExtensionManager.shared.discoverExtensions(
            for: trimmedQuery,
            selectedFiles: contextFiles,
            selectedText: selectedText,
            frontmostApp: resolvedAppName,
            layer: .l2_context
        )

        return Array(results.prefix(6))
    }

    // MARK: - Context Dock Filter (type to find actions)

    struct L2FilteredItem {
        let id: String
        let icon: String
        let name: String
        let isExtension: Bool
    }

    var l2FilteredContextActions: [L2FilteredItem] {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }
        let appKey = searchState.activeSmartQueryKey ?? settings.autoDetectedAppKey ?? ""
        var results: [L2FilteredItem] = []
        for sc in settings.shortcuts(for: appKey) where sc.name.lowercased().contains(q) {
            results.append(
                L2FilteredItem(
                    id: "sc_\(sc.id)", icon: sc.iconName, name: sc.name, isExtension: false))
        }
        for ext in appPillScriptExtensions(for: appKey, query: q)
        where ext.toolName.lowercased().contains(q) || ext.aiHint.lowercased().contains(q) {
            let icon = ext.scriptLanguage?.systemImage ?? "terminal"
            results.append(
                L2FilteredItem(
                    id: "usr_ext_\(ext.id.uuidString)",
                    icon: icon,
                    name: ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized,
                    isExtension: false
                )
            )
        }
        for tool in frontmostAppL2Extensions
        where tool.displayName.lowercased().contains(q) || tool.toolName.lowercased().contains(q) {
            results.append(
                L2FilteredItem(
                    id: "ext_\(tool.toolName)", icon: tool.icon, name: tool.displayName,
                    isExtension: true))
        }
        return results
    }

    func executeL2FilteredItem(_ item: L2FilteredItem) {
        if item.isExtension {
            let toolName = String(item.id.dropFirst(4))  // strip "ext_"
            guard let tool = frontmostAppL2Extensions.first(where: { $0.toolName == toolName })
            else { return }
            l2.chatMessages.append(AIChatMessage(role: .user, content: tool.displayName))
            l2.isLoading = true
            Task {
                let (success, output) = await L2ExtensionManager.shared.execute(
                    toolName: tool.toolName, arguments: [:])
                await MainActor.run {
                    let content =
                        success
                        ? (output.isEmpty ? "✅ \(tool.displayName) done." : output)
                        : "❌ \(tool.displayName) failed: \(output)"
                    l2.chatMessages.append(AIChatMessage(role: .assistant, content: content))
                    l2.isLoading = false
                }
            }
        } else {
            let scIdStr = String(item.id.dropFirst(3))  // strip "sc_"
            let appKey = searchState.activeSmartQueryKey ?? settings.autoDetectedAppKey ?? ""
            if item.id.hasPrefix("usr_ext_"),
                let ext = appPillScriptExtensions(for: appKey, query: searchState.query)
                    .first(where: {
                        $0.id.uuidString == String(item.id.dropFirst("usr_ext_".count))
                    })
            {
                executeAppToolExtension(ext, launchQuery: searchState.query)
            } else if let sc = settings.shortcuts(for: appKey).first(where: {
                $0.id.uuidString == scIdStr
            }
            ) {
                executeAppShortcut(sc)
            }
        }
        searchState.query = ""
    }

    // MARK: - Instant menu reload on app switch

    /// Called immediately when the frontmost app changes while the dock is open.
    /// Cancels any in-flight menu load and starts a fresh one for `app`.
    func reloadMenuForApp(_ app: NSRunningApplication) {
        guard showContextInDock, !app.isTerminated else { return }
        let pid = app.processIdentifier
        let name = app.localizedName ?? ""
        let bundleId = app.bundleIdentifier ?? ""
        let useCacheOnly = isGlobalContextActive

        menuLoadTask?.cancel()
        liveMenuRefreshTask?.cancel()
        liveMenuRefreshTask = nil
        lastLiveMenuStructureRefresh = .distantPast
        contextMenuPills = []
        previousEnabledIDs = []

        let cachedItems = ContextDockEngine.shared.cachedMenuItems(for: app, maxResults: 120)
        if useCacheOnly || !cachedItems.isEmpty {
            if !useCacheOnly, !bundleId.isEmpty {
                warmingMenuBundleIds.insert(bundleId)
            }
            liveMenuItems = cachedItems
            menuDebugText = "\(name): \(cachedItems.count) cached menus"
            lastLiveMenuSignature = menuSignature(for: cachedItems)
            previousEnabledIDs = Set(cachedItems.filter(\.isEnabled).map(\.id))
            syncRecentAppsFromAppleMenu(cachedItems)
            scheduleDockPillRebuild(
                query: lastPillQuery, delayNanoseconds: 0, refreshContext: false)
            if useCacheOnly {
                return
            }
        }

        menuLoadTask = Task.detached(priority: .userInitiated) {
            let fallbackItems = await MainActor.run {
                AXContextReader.shared.current.menuItems.compactMap { info -> AXMenuItem? in
                    let path = info.fullPath
                        .components(separatedBy: " > ")
                        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                        .filter { !$0.isEmpty }
                    guard let title = path.last, !title.isEmpty else { return nil }
                    return AXMenuItem(
                        title: title,
                        path: path,
                        isEnabled: info.enabled,
                        element: AXUIElementCreateApplication(pid),
                        children: [],
                        sourcePID: pid,
                        sourceAppName: name,
                        isAppleMenu: path.first == "Apple",
                        shortcutChar: nil,
                        shortcutModifiers: 0
                    )
                }
            }

            guard
                let refresh = await ContextDockEngine.shared.refreshMenus(
                    for: app,
                    cachedItems: cachedItems,
                    fallbackItems: fallbackItems,
                    maxResults: 120,
                    force: true
                )
            else {
                await MainActor.run {
                    if !bundleId.isEmpty {
                        self.warmingMenuBundleIds.remove(bundleId)
                    }
                    if cachedItems.isEmpty {
                        self.liveMenuItems = []
                        self.menuDebugText = "\(name): no menu cache yet"
                    }
                }
                return
            }

            await MainActor.run {
                guard self.contextTargetApp()?.processIdentifier == pid else { return }
                if !bundleId.isEmpty {
                    self.warmingMenuBundleIds.remove(bundleId)
                }
                self.liveMenuItems = refresh.items
                self.menuDebugText = refresh.debugText
                self.lastLiveMenuSignature = self.menuSignature(for: refresh.items)
                self.previousEnabledIDs = Set(refresh.items.filter(\.isEnabled).map(\.id))
                self.syncRecentAppsFromAppleMenu(refresh.items)
                self.scheduleDockPillRebuild(
                    query: self.lastPillQuery, delayNanoseconds: 0, refreshContext: false)
                self.refreshVisibleGlobalContextAfterMenuCacheUpdate(bundleIdentifier: bundleId)
            }
        }

        // Restart observer for the new app
        selectionModel.start(for: pid)

        // Refresh AX context snapshot
        AXContextReader.shared.refresh(from: app)
        axContext = AXContextReader.shared.current
    }

     // MARK: - Apple menu recent apps sync

    /// Reads "Recent Items > Applications" from the already-loaded liveMenuItems and
    /// updates AppDelegate.recentApps with running apps that match — giving us the
    /// same list macOS itself tracks, not just apps activated while our dock was open.
    func syncRecentAppsFromAppleMenu(_ items: [AXMenuItem]) {
        // Apple menu items: path[0] == "" (the  symbol), path[1] == "Recent Items"
        let recentNames =
            items
            .filter { $0.path.count >= 2 && $0.path[0].isEmpty && $0.path[1] == "Recent Items" }
            .map { $0.title.replacingOccurrences(of: ".app", with: "") }
            .filter { !$0.isEmpty && $0 != "Clear Menu" }

        guard !recentNames.isEmpty else { return }

        let running = NSWorkspace.shared.runningApplications
        let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0

        // Match names to running processes, preserving Apple menu order, skip frontmost & self
        let matched: [NSRunningApplication] = recentNames.compactMap { name in
            running.first {
                $0.activationPolicy == .regular
                    && !$0.isTerminated
                    && $0.processIdentifier != frontPID
                    && $0.bundleIdentifier != Bundle.main.bundleIdentifier
                    && ($0.localizedName ?? "") == name
            }
        }

        // Deduplicate and update
        var seen = Set<pid_t>()
        let deduped = matched.filter { seen.insert($0.processIdentifier).inserted }
        AppDelegate.shared?.setRecentAppsFromMenu(Array(deduped.prefix(5)))
    }

    func menuSignature(for items: [AXMenuItem]) -> String {
        items
            .prefix(500)
            .map { item in
                [
                    item.path.joined(separator: " > "),
                    item.isEnabled ? "1" : "0",
                    item.shortcutChar ?? "",
                    "\(item.shortcutModifiers)",
                ].joined(separator: "|")
            }
            .joined(separator: "\n")
    }

    func refreshFrontmostMenuStructureIfNeeded(
        for app: NSRunningApplication,
        force: Bool = false
    ) {
        guard showContextInDock, !app.isTerminated else { return }
        guard liveMenuRefreshTask == nil else { return }
        if !force,
            !searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return
        }

        let now = Date()
        let minInterval: TimeInterval = force ? 0 : 30
        guard force || now.timeIntervalSince(lastLiveMenuStructureRefresh) >= minInterval else {
            return
        }
        lastLiveMenuStructureRefresh = now

        let pid = app.processIdentifier
        let name = app.localizedName ?? ""
        let bundleId = app.bundleIdentifier

        liveMenuRefreshTask = Task.detached(priority: force ? .userInitiated : .utility) {
            await MenuWarmCacheService.shared.warm(app: app, force: force)
            var items = await AXMenuReader.shared.peekCachedAllMenuItems(for: pid)
            if items.isEmpty {
                items = ContextDockEngine.shared.cachedMenuItems(for: app, maxResults: 120)
            }
            guard !Task.isCancelled else { return }
            guard !items.isEmpty else {
                await MainActor.run {
                    if self.liveMenuRefreshTask != nil {
                        self.liveMenuRefreshTask = nil
                    }
                }
                return
            }

            for i in items.indices {
                items[i].sourcePID = pid
                items[i].sourceAppName = name
            }

            let debug = await AXMenuReader.shared.lastDebug(for: pid) ?? "no reader detail"
            let resolvedItems = items
            await MainActor.run {
                self.liveMenuRefreshTask = nil
                guard self.showContextInDock else { return }
                guard self.contextTargetApp()?.processIdentifier == pid else {
                    return
                }
                let baseItems =
                    self.liveMenuItems.isEmpty
                    ? ContextDockEngine.shared.cachedMenuItems(for: app, maxResults: 120)
                    : self.liveMenuItems
                let mergedItems = self.mergeCachedMenusWithLiveAvailability(
                    cached: baseItems,
                    live: resolvedItems
                )
                let signature = self.menuSignature(for: mergedItems)
                guard force || signature != self.lastLiveMenuSignature else { return }

                self.liveMenuItems = mergedItems
                self.lastLiveMenuSignature = signature
                self.menuDebugText = "\(name): \(mergedItems.count) menus, \(debug), cache+live"
                self.previousEnabledIDs = Set(mergedItems.filter(\.isEnabled).map(\.id))
                self.contextMenuPills = []
                self.syncRecentAppsFromAppleMenu(mergedItems)
                if self.frontmost.bundleID.isEmpty, let bundleId {
                    self.frontmost.bundleID = bundleId
                }
                self.refreshVisibleGlobalContextAfterMenuCacheUpdate(bundleIdentifier: bundleId)
            }
        }
    }

    // MARK: - Selection-change handler

    /// Called (debounced 200ms) whenever AXObserver detects a selection/focus change
    /// in the frontmost app. Re-reads only `kAXEnabled` for all cached menu items,
    /// computes the delta (newly enabled items), and surfaces them as context pills.
    func handleSelectionChange() {
        guard showContextInDock else { return }

        if !liveMenuItems.isEmpty {
            let items = liveMenuItems
            let previousIDs = previousEnabledIDs
            let appForAvailability = contextTargetApp()
            Task.detached(priority: .userInitiated) {
                // Re-read enabled states off the main thread — one attribute call per item,
                // no tree traversal, but still AX IPC and therefore not free.
                let enabledMap = AXMenuReader.shared.refreshEnabledStates(for: items)
                var updated = items
                for i in updated.indices {
                    if let enabled = enabledMap[updated[i].id] {
                        updated[i].isEnabled = enabled
                    }
                }

                let newEnabledIDs = Set(updated.filter(\.isEnabled).map(\.id))
                let deltaIDs = newEnabledIDs.subtracting(previousIDs)
                let delta = updated.filter { deltaIDs.contains($0.id) && !self.isAppleMenuItem($0) }
                    .sorted { ($0.shortcutChar != nil ? 0 : 1) < ($1.shortcutChar != nil ? 0 : 1) }

                if let appForAvailability {
                    AppMenuCapabilityCache.shared.updateAvailability(
                        items: updated, for: appForAvailability)
                }

                await MainActor.run {
                    self.previousEnabledIDs = newEnabledIDs
                    self.liveMenuItems = updated
                    self.contextMenuPills = Array(delta.prefix(6))
                    self.refreshVisibleGlobalContextAfterMenuCacheUpdate(
                        bundleIdentifier: appForAvailability?.bundleIdentifier)
                }
            }
        }

        refreshLiveContextDockState()
    }

    func refreshLiveContextDockState() {
        guard showContextInDock, let app = contextTargetApp() else { return }

        refreshFrontmostMenuStructureIfNeeded(for: app)

        AXContextReader.shared.refresh(from: app)
        let newCtx = AXContextReader.shared.current
        refreshCachedFinderCurrentDirectory(for: app.bundleIdentifier ?? "")

        // URL-change detection: recache page when user navigates
        if AXWebReader.shared.isBrowser(bundleId: app.bundleIdentifier ?? ""),
            let newURL = newCtx.currentURL, !newURL.isEmpty,
            newURL != lastKnownBrowserURL
        {
            lastKnownBrowserURL = newURL
            AXWebReader.shared.invalidate(pid: app.processIdentifier)
            scheduleBrowserContextWarmup(reason: "browser URL changed", urlOverride: newURL)
        }

        if newCtx.bundleId == "com.apple.finder" {
            updateSuppressedAutomaticFinderSelectionAfterSelectionChange(newCtx.selectedFilePaths)
            if isSuppressedAutomaticFinderSelection(newCtx.selectedFilePaths) {
                var suppressedCtx = newCtx
                suppressedCtx.selectedFilePaths = []
                if case .filesSelected(let urls) = currentContext,
                    isSuppressedAutomaticFinderSelection(urls)
                {
                    currentContext = .none
                }
                axContext = suppressedCtx
                detectAndUpdateContext()
                checkClipboardForGlobalContext()
                autoReturnFromGlobalContextIfNeeded()
                return
            }
            updateDismissedFinderSelectionAfterSelectionChange(newCtx.selectedFilePaths)
            if isDismissedFinderSelection(newCtx.selectedFilePaths) {
                var suppressedCtx = newCtx
                suppressedCtx.selectedFilePaths = []
                if case .filesSelected(let urls) = currentContext,
                    isDismissedFinderSelection(urls)
                {
                    currentContext = .none
                }
                axContext = suppressedCtx
                detectAndUpdateContext()
                checkClipboardForGlobalContext()
                autoReturnFromGlobalContextIfNeeded()
                return
            }
        }

        let contextChanged =
            newCtx.selectedFilePaths != axContext.selectedFilePaths
            || newCtx.selectedText != axContext.selectedText
            || newCtx.currentURL != axContext.currentURL
            || newCtx.windowTitle != axContext.windowTitle

        if contextChanged {
            axContext = newCtx
            detectAndUpdateContext()
        }
        // Clipboard monitoring: detect copies from any app (covers Electron/VS Code where AX selectedText is nil)
        checkClipboardForGlobalContext()
        // Always check for selection-based global context switch after AX refresh
        autoSwitchGlobalContextIfNeeded()
        // Auto-return to dock if selection was cleared since last poll
        autoReturnFromGlobalContextIfNeeded()
    }

    func refreshFinderSelectionContextFromFinder() {
        guard showContextInDock, !showMediaLayer, !aiMode.isActive else { return }
        let now = Date()
        guard now.timeIntervalSince(lastFinderSelectionRefresh) > 0.25 else { return }
        lastFinderSelectionRefresh = now
        guard
            frontmost.bundleID == "com.apple.finder"
                || AppDelegate.shared?.previousFrontmostApp?.bundleIdentifier == "com.apple.finder"
                || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
        else { return }

        let urls = canonicalExistingURLs(ContextDetector.shared.getFinderSelectedFiles())
        guard !urls.isEmpty else { return }
        let paths = urls.map(\.path)
        updateSuppressedAutomaticFinderSelectionAfterSelectionChange(paths)
        if isSuppressedAutomaticFinderSelection(paths) {
            if axContext.bundleId == "com.apple.finder" {
                axContext.selectedFilePaths = []
            }
            if case .filesSelected(let current) = currentContext,
                isSuppressedAutomaticFinderSelection(current)
            {
                currentContext = .none
            }
            return
        }
        updateDismissedFinderSelectionAfterSelectionChange(paths)
        if isDismissedFinderSelection(paths) {
            if axContext.bundleId == "com.apple.finder" {
                axContext.selectedFilePaths = []
            }
            if case .filesSelected(let current) = currentContext,
                isDismissedFinderSelection(current)
            {
                currentContext = .none
            }
            return
        }

        if axContext.bundleId != "com.apple.finder" || axContext.selectedFilePaths != paths {
            axContext.bundleId = "com.apple.finder"
            axContext.selectedFilePaths = paths
        }
        if case .filesSelected(let current) = currentContext, current.map(\.path) == paths {
            return
        }
        currentContext = .filesSelected(urls)
    }

    func checkClipboardForGlobalContext() {
        let pb = NSPasteboard.general
        let currentCount = pb.changeCount
        guard currentCount != lastCheckedPasteboardCount else { return }
        lastCheckedPasteboardCount = currentCount

        pruneExpiredClipboardEntries()

        _ = importCurrentPasteboardToClipboardHistory()
    }

    @discardableResult
    func importCurrentPasteboardToClipboardHistory() -> Bool {
        let pb = NSPasteboard.general

        if let fileURLs = pb.readObjects(forClasses: [NSURL.self], options: nil) as? [URL] {
            let paths =
                fileURLs
                .filter { $0.isFileURL }
                .map(\.path)
                .filter { !$0.isEmpty }
            if !paths.isEmpty {
                addClipboardEntry(text: paths.joined(separator: "\n"), filePaths: paths)
                return true
            }
        }

        if let image = NSImage(pasteboard: pb),
            let tiffData = image.tiffRepresentation
        {
            addClipboardEntry(text: "Image copied to clipboard", filePaths: [], imageData: tiffData)
            return true
        }

        guard pb.pasteboardItems?.first?.types.contains(.string) == true,
            let text = pb.string(forType: .string)
        else { return false }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > 3 else { return false }

        addClipboardEntry(text: trimmed, filePaths: [])
        return true
    }

    func addClipboardEntry(text: String, filePaths: [String], imageData: Data? = nil) {
        let sourceApp = clipboardSourceApp()
        let entry = ClipboardEntry(
            text: text,
            timestamp: Date(),
            filePaths: filePaths,
            imageData: imageData,
            sourceAppName: sourceApp.name,
            sourceBundleId: sourceApp.bundleId
        )

        let duplicateKey =
            imageData != nil
            ? "image:\(imageData?.count ?? 0)"
            : (filePaths.isEmpty ? text : filePaths.joined(separator: "\n"))
        clipboardHistory.removeAll { old in
            let oldKey =
                old.imageData != nil
                ? "image:\(old.imageData?.count ?? 0)"
                : (old.filePaths.isEmpty ? old.text : old.filePaths.joined(separator: "\n"))
            return oldKey == duplicateKey
        }
        clipboardHistory.insert(entry, at: 0)
        trimClipboardHistoryToLimits()
        savePersistedClipboardHistory()
        if imageData != nil {
            scheduleClipboardOCR(for: entry.id, imageData: imageData)
        }
        if searchState.activeSmartQueryKey == "clipboard" {
            refreshCompactScopeResults(resetSelection: false)
        }

        globalClipboardText = text
        showGlobalClipboardPill = false
        clipboardHistoryExpanded = false
        // Rebuild clipboard scope rows immediately when scope is open.
        let rebuildQuery =
            searchState.activeSmartQueryKey == "clipboard"
            ? searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : lastPillQuery
        scheduleDockPillRebuild(query: rebuildQuery, delayNanoseconds: 0, refreshContext: false)
    }

    func scheduleClipboardIndicatorAutoHide() {
        clipboardIndicatorHideTask?.cancel()
        clipboardIndicatorHideTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 5_000_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                showGlobalClipboardPill = false
                clipboardHistoryExpanded = false
            }
            updateWindowSize()
        }
        updateWindowSize()
    }

    func clipboardSourceApp() -> (name: String, bundleId: String) {
        let app =
            AppDelegate.shared?.previousFrontmostApp
            ?? NSWorkspace.shared.frontmostApplication
        return (app?.localizedName ?? "", app?.bundleIdentifier ?? "")
    }

    func clipboardRetentionInterval() -> TimeInterval {
        TimeInterval(max(1, settings.clipboardHistoryRetentionHours)) * 3600
    }

    var clipboardHistoryStoreURL: URL {
        let base =
            FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(
                "Library/Application Support")
        return
            base
            .appendingPathComponent("Context-Dock", isDirectory: true)
            .appendingPathComponent("clipboard-history.json")
    }

    func loadPersistedClipboardHistory() {
        let url = clipboardHistoryStoreURL
        guard FileManager.default.fileExists(atPath: url.path),
            let data = try? Data(contentsOf: url),
            let entries = try? JSONDecoder().decode([ClipboardEntry].self, from: data)
        else {
            syncVisibleClipboardStateAfterPrune()
            return
        }
        clipboardHistory = entries.sorted { $0.timestamp > $1.timestamp }
        trimClipboardHistoryToLimits(save: false)
        syncVisibleClipboardStateAfterPrune()
        savePersistedClipboardHistory()
    }

    func savePersistedClipboardHistory() {
        let url = clipboardHistoryStoreURL
        do {
            try FileManager.default.createDirectory(
                at: url.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            let data = try JSONEncoder().encode(clipboardHistory)
            try data.write(to: url, options: .atomic)
        } catch {
            print("Failed to persist clipboard history: \(error.localizedDescription)")
        }
    }

    func scheduleClipboardOCR(for entryID: UUID, imageData: Data?) {
        guard let imageData,
            let nsImage = NSImage(data: imageData),
            let cgImage = nsImage.cgImage(forProposedRect: nil, context: nil, hints: nil)
        else { return }

        Task.detached(priority: .utility) {
            let request = VNRecognizeTextRequest()
            request.recognitionLevel = .accurate
            request.usesLanguageCorrection = true
            let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])
            do {
                try handler.perform([request])
                let text = (request.results ?? [])
                    .compactMap { $0.topCandidates(1).first?.string }
                    .joined(separator: "\n")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                guard !text.isEmpty else { return }
                await MainActor.run {
                    updateClipboardOCR(entryID: entryID, text: text)
                }
            } catch {
                // OCR is best-effort; clipboard row still works without recognized text.
            }
        }
    }

    func updateClipboardOCR(entryID: UUID, text: String) {
        guard let index = clipboardHistory.firstIndex(where: { $0.id == entryID }) else { return }
        clipboardHistory[index].ocrText = text
        savePersistedClipboardHistory()
        if searchState.activeSmartQueryKey == "clipboard" {
            let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            scheduleDockPillRebuild(query: q, delayNanoseconds: 0, refreshContext: false)
        }
    }

    func trimClipboardHistoryToLimits(save: Bool = true) {
        let before = clipboardHistory.map(\.id)
        pruneExpiredClipboardEntries(updateVisibleState: false, save: false)
        let limit = settings.clipboardHistoryLimit
        if clipboardHistory.count > limit {
            clipboardHistory = Array(clipboardHistory.prefix(limit))
        }
        syncVisibleClipboardStateAfterPrune()
        if save && before != clipboardHistory.map(\.id) {
            savePersistedClipboardHistory()
        }
    }

    func pruneExpiredClipboardEntries(updateVisibleState: Bool = true, save: Bool = true) {
        let cutoff = Date().addingTimeInterval(-clipboardRetentionInterval())
        let before = clipboardHistory.count
        clipboardHistory.removeAll { $0.timestamp < cutoff }
        if updateVisibleState {
            syncVisibleClipboardStateAfterPrune()
        }
        if save && clipboardHistory.count != before {
            savePersistedClipboardHistory()
        }
    }

    func syncVisibleClipboardStateAfterPrune() {
        if let first = clipboardHistory.first {
            globalClipboardText = first.text
        } else {
            globalClipboardText = ""
            showGlobalClipboardPill = false
            showClipboardHistory = false
            clipboardHistoryExpanded = false
        }
    }

    func startClipboardExpiryTimer() {
        clipboardExpiryTimer?.invalidate()
        clipboardExpiryTimer = Timer.scheduledTimer(withTimeInterval: 60, repeats: true) {
            [self] _ in
            self.pruneExpiredClipboardEntries()
        }
    }

    /// Switches to Global Context automatically for text or URL selections.
    /// Finder files and folders stay in Context Dock until user explicitly drops them
    /// onto the dock. This prevents Finder row focus from stealing launcher scope.
    func autoSwitchGlobalContextIfNeeded() {
        guard showContextInDock, !isExplicitAppScopeLocked, l2.targetApp == nil,
            !isGlobalContextActive
        else { return }
        guard !isAutomaticGlobalContextTemporarilySuppressed else { return }
        // Don't re-trigger within 600ms of an app switch — the AX observer fires for the
        // new app with stale/cursor-position state which would immediately flip back to global.
        guard Date().timeIntervalSince(frontmost.lastSwitchDate) > 0.6 else { return }
        // Ignore AX selection if it came from a different app than the current frontmost —
        // stale events from the previous app can arrive after the switch.
        if !axContext.bundleId.isEmpty, axContext.bundleId != frontmost.bundleID {
            return
        }
        refreshFinderSelectionContextFromFinder()

        // Text: require > 15 chars to avoid cursor-position false positives in Electron apps
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasTextSelection = axText.count > 15
        let hasContextSelection: Bool = {
            switch currentContext {
            case .textSelected(let t):
                return t.trimmingCharacters(in: .whitespacesAndNewlines).count > 15
            case .url(let s):
                return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            default: return false
            }
        }()
        if hasTextSelection || hasContextSelection {
            // Compute frozen label + icon before creating the activation struct
            let (frozenText, frozenIcon): (String?, String?) = {
                if hasTextSelection {
                    return (String(axText.prefix(50)), "text.cursor")
                } else {
                    switch currentContext {
                    case .textSelected(let t):
                        return (
                            String(t.trimmingCharacters(in: .whitespacesAndNewlines).prefix(50)),
                            "text.cursor"
                        )
                    case .url(let u):
                        let text = URL(string: u)?.host ?? String(u.prefix(40))
                        return (text, "link")
                    default:
                        return (nil, nil)
                    }
                }
            }()
            globalContextActivation = GlobalContextActivation(
                autoActivated: true,
                frozenText: frozenText,
                frozenIcon: frozenIcon,
                sourceBundleId: axContext.bundleId,
                frozenFilePaths: []
            )
            // Expand and focus the search bar so the user can type their query immediately
            isSearchBarExpanded = true
            DispatchQueue.main.async { self.isSearchFieldFocused = true }
        }
    }

    /// Auto-returns to Context Dock when the selection that triggered global context is gone.
    /// Only fires if global context was auto-activated (not manually swiped by user).
    func autoReturnFromGlobalContextIfNeeded() {
        guard isGlobalContextActive, isGlobalContextAutoActivated, !aiMode.isActive else { return }

        // If we have a frozen selection, only allow auto-return when the AX update comes from the
        // same source app that originally provided the selection — not from our own dock gaining focus.
        if let sourceId = frozenSelectionSourceBundleId {
            let currentContextApp = axContext.bundleId ?? ""
            let ownBundleId = Bundle.main.bundleIdentifier ?? ""
            // Ignore AX updates from our own app — user is typing in our dock
            guard currentContextApp != ownBundleId else { return }
            // Ignore updates from unrelated apps — only the source app can invalidate the frozen selection
            guard currentContextApp == sourceId || currentContextApp.isEmpty else { return }
        }

        let hasFileSelection =
            !axContext.selectedFilePaths.isEmpty
            && !isDismissedFinderSelection(axContext.selectedFilePaths)
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasTextSelection = axText.count > 15
        let hasCtxSel: Bool = {
            switch currentContext {
            case .filesSelected(let u): return !u.isEmpty && !isDismissedFinderSelection(u)
            case .textSelected(let t):
                return t.trimmingCharacters(in: .whitespacesAndNewlines).count > 15
            case .url(let s): return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            default: return false
            }
        }()
        let hasClipboard = showGlobalClipboardPill && !globalClipboardText.isEmpty
        if !hasFileSelection && !hasTextSelection && !hasCtxSel && !hasClipboard {
            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                globalContextActivation = nil
            }
            scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
        }
    }

    // MARK: - Share sheet

    func presentSharingPicker(items: [Any]) {
        guard !items.isEmpty else { return }
        let picker = NSSharingServicePicker(items: items)
        let coordinator = SharePickerCoordinator {
            self.isSharingSheetActive = false
        }
        picker.delegate = coordinator
        objc_setAssociatedObject(
            picker,
            &SharePickerCoordinator.key,
            coordinator,
            .OBJC_ASSOCIATION_RETAIN_NONATOMIC
        )

        isSharingSheetActive = true
        DispatchQueue.main.async {
            guard let window = NSApp.keyWindow,
                let view = window.contentView
            else {
                self.isSharingSheetActive = false
                return
            }
            let rect = NSRect(x: window.frame.width / 2 - 60, y: 52, width: 120, height: 1)
            picker.show(relativeTo: rect, of: view, preferredEdge: .maxY)
        }
    }

    /// Shows NSSharingServicePicker anchored above the pill row,
    /// using the current AX context (selected files, URL, or text).
    /// Sets shareSheetVisible = true so arrow keys are passed through to the picker.
    func showShareSheetForContext() {
        var items = ShareIntentRouter.shared.shareItems(for: effectiveAXContextForConversation())
        if items.isEmpty {
            // Fallback: show picker with app URL so at least something appears
            if let app = AppDelegate.shared?.previousFrontmostApp,
                let bid = app.bundleIdentifier,
                let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bid)
            {
                items = [url]
            } else {
                return
            }
        }
        presentSharingPicker(items: items)
    }

    func executeShareIntent(
        _ intent: ShareIntent,
        userMessage: String? = nil
    ) {
        let capturedContext = effectiveAXContextForConversation()
        if let userMessage, !userMessage.isEmpty {
            l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
        }
        l2.isLoading = true
        Task {
            let resolution = await ShareIntentRouter.shared.resolve(intent)
            let output = await ShareIntentRouter.shared.execute(
                resolution,
                axContext: capturedContext,
                presentSharingPicker: { items in
                    self.presentSharingPicker(items: items)
                }
            )
            await MainActor.run {
                self.l2.chatMessages.append(AIChatMessage(role: .assistant, content: output))
                self.l2.isLoading = false
            }
        }
    }

    func executeTransformShareIntent(
        _ intent: ShareIntent,
        userMessage: String
    ) {
        let selectedFiles = effectiveSelectedFileURLsForConversation()
        guard !selectedFiles.isEmpty else {
            l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
            l2.chatMessages.append(
                AIChatMessage(
                    role: .assistant,
                    content:
                        "Select a small text or PDF document first, then ask me to summarize and send it.",
                    isError: true
                ))
            return
        }

        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2.isLoading = true
        searchState.query = ""
        l2.focusedPillIndex = nil

        l2.currentTask = Task {
            let readable = transformShareReadableContent(from: selectedFiles)
            guard !readable.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "I couldn't read text from the selected file. This works best with small text, Markdown, source, CSV, RTF, or text-based PDF files.",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            do {
                let summaryPrompt = transformSharePrompt(
                    userMessage: userMessage,
                    fileSummary: readable.summary,
                    fileContent: readable.content
                )
                let summary = try await sendToAIProviderWithContext(
                    query: summaryPrompt,
                    messageHistory: l2.chatMessages
                ).trimmingCharacters(in: .whitespacesAndNewlines)

                guard !Task.isCancelled else { return }
                let resolution = await ShareIntentRouter.shared.resolve(intent)
                let subject = "Summary of \(readable.primaryFileName)"
                let output = await ShareIntentRouter.shared.executeText(
                    summary,
                    resolution: resolution,
                    subject: subject,
                    presentSharingPicker: { items in
                        self.presentSharingPicker(items: items)
                    }
                )

                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(role: .assistant, content: "\(output)\n\n\(summary)")
                    )
                    l2.isLoading = false
                    l2.currentTask = nil
                }
            } catch {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "Sorry, I couldn't summarize and send that: \(error.localizedDescription)",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
            }
        }
    }

    func transformShareIntent(for query: String) -> ShareIntent? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return nil }
        let hasTransformWord = [
            "summary", "summarize", "summarise", "tldr", "tl;dr",
            "explain", "describe", "key points", "short version", "brief",
        ].contains { q.contains($0) }
        let hasDeliveryWord = [
            "send", "share", "message", "messages", "imessage", "text",
            "sms", "mail", "email",
        ].contains { q.contains($0) }
        let referencesSelection = [
            "this file", "selected file", "selection", "this document",
            "selected document", "this pdf", "selected pdf", "this",
        ].contains { q.contains($0) }
        guard hasTransformWord, hasDeliveryWord, referencesSelection else { return nil }
        guard !effectiveSelectedFileURLsForConversation().isEmpty else { return nil }
        return ShareIntentRouter.shared.parse(query)
    }

    func transformShareReadableContent(from urls: [URL])
        -> (summary: String, content: String, primaryFileName: String)
    {
        let files = Array(urls.prefix(3))
        let analyses = ContextDetector.shared.analyzeFiles(files)
        var chunks: [String] = []
        var summaryLines: [String] = []

        for analysis in analyses {
            summaryLines.append(
                "- \(analysis.url.lastPathComponent) (\(analysis.type), \(analysis.size))")
            guard
                let content = analysis.content?
                    .trimmingCharacters(in: .whitespacesAndNewlines),
                !content.isEmpty
            else { continue }
            chunks.append(
                """
                FILE: \(analysis.url.lastPathComponent)
                CONTENT:
                \(String(content.prefix(6000)))
                """
            )
        }

        return (
            summaryLines.joined(separator: "\n"),
            chunks.joined(separator: "\n\n---\n\n"),
            files.first?.lastPathComponent ?? "selected file"
        )
    }

    func transformSharePrompt(
        userMessage: String,
        fileSummary: String,
        fileContent: String
    ) -> String {
        """
        The user wants a generated message derived from the selected file, then sent to someone.

        User request:
        \(userMessage)

        Selected file metadata:
        \(fileSummary)

        Selected file text:
        \(fileContent)

        Produce only the message body to send. Keep it short unless the user asked otherwise.
        Do not mention implementation details, file paths, or that you are an AI.
        """
    }

    func executeCrossAppIntent(
        _ intent: CrossAppIntent,
        userMessage: String,
        unresolvedMessage: String =
            "❌ Couldn't resolve that. Try: \"send this to [name]\" or \"email this to [name]\""
    ) {
        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }
        let capturedContext = effectiveAXContextForConversation()
        let actionId = DockActionFeedback.start(
            "Working", subject: intent.targetAppName ?? "", icon: "bolt.fill", tint: .accentColor)
        l2.currentTask = Task {
            guard let resolved = await CrossAppNLHandler.shared.resolve(intent) else {
                await MainActor.run {
                    DockActionFeedback.fail(actionId, label: "Couldn't resolve action")
                    l2.currentTask = nil
                }
                return
            }
            let output = await CrossAppNLHandler.shared.execute(
                resolved,
                axContext: capturedContext,
                presentSharingPicker: { items in
                    self.presentSharingPicker(items: items)
                }
            )
            await MainActor.run {
                let clean = output.replacingOccurrences(of: "✅ ", with: "").replacingOccurrences(
                    of: "❌ ", with: "")
                let success = !output.hasPrefix("❌")
                if success {
                    DockActionFeedback.complete(actionId, label: clean)
                } else {
                    DockActionFeedback.fail(actionId, label: clean)
                }
                l2.currentTask = nil
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        }
    }

    func executeResolvedAppAction(
        _ resolution: L2AppActionResolution,
        userMessage: String
    ) {
        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        let match = resolution.primary
        let capturedContext = effectiveAXContextForConversation()
        let actionId = DockActionFeedback.start(
            match.action.name, subject: match.adapter.appName, icon: "bolt.fill", tint: .accentColor
        )
        l2.currentTask = Task {
            AppInteractionStore.shared.record(
                bundleId: match.adapter.bundleId,
                appName: match.adapter.appName,
                query: userMessage,
                kind: match.action.type == .pageJS ? .pageJS : .adapterAction,
                actionId: match.action.id
            )

            let result = await adapterManager.execute(
                match.action,
                context: capturedContext,
                targetBundleId: match.adapter.bundleId,
                query: userMessage
            )

            await MainActor.run {
                let success = result.0
                let detail = result.1.trimmingCharacters(in: .whitespacesAndNewlines)
                let label =
                    success
                    ? (detail.isEmpty ? "\(match.action.name) done" : detail)
                    : "Couldn't run \(match.action.name)"
                if success {
                    DockActionFeedback.complete(actionId, label: label)
                } else {
                    DockActionFeedback.fail(actionId, label: label)
                }
                l2.currentTask = nil
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        }
    }

    func executeGlobalAppLaunch(
        bundleId: String,
        appName: String,
        userMessage: String
    ) {
        let launched = launchApplication(bundleIdentifier: bundleId, appName: appName)
        if launched {
            DockActionFeedback.start(
                "Opening", subject: appName, icon: "arrow.up.right.circle.fill", tint: .accentColor)
        } else {
            let fid = DockActionFeedback.start(
                "Opening", subject: appName, icon: "arrow.up.right.circle.fill", tint: .accentColor)
            DockActionFeedback.fail(fid, label: "Couldn't open \(appName)")
        }
        searchState.query = ""
        l2.focusedPillIndex = nil
    }

    var isGlobalQueryModeActive: Bool {
        showContextInDock && isGlobalContextActive
    }

    var effectiveConversationUserContext: UserContext {
        // Global Context: use live AX selection as the authoritative context
        if showContextInDock && isGlobalContextActive {
            let axFiles = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            if !axFiles.isEmpty { return .filesSelected(axFiles) }
            if let t = axContext.selectedText,
                !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            {
                return .textSelected(t)
            }
            switch currentContext {
            case .filesSelected, .textSelected, .url, .contactSelected: return currentContext
            default: break
            }
            // Clipboard pill: user explicitly copied content (covers VS Code/Electron/any app)
            if showGlobalClipboardPill && !globalClipboardText.isEmpty {
                if let url = URL(string: globalClipboardText), url.scheme != nil {
                    return .url(globalClipboardText)
                }
                return .textSelected(globalClipboardText)
            }
            return .none
        }

        if showContextInDock {
            let scope = resolveDockScope(for: searchState.query)
            if scope.isExplicitAppScope,
                !scope.scopedBundleId.isEmpty,
                !scope.scopedAppName.isEmpty
            {
                return .appFocused(name: scope.scopedAppName, bundleID: scope.scopedBundleId)
            }
        }

        guard isGlobalQueryModeActive else { return currentContext }
        switch currentContext {
        case .appFocused:
            return .none
        default:
            return currentContext
        }
    }

    func resolveGlobalActionQuery(_ query: String) -> L2AppActionResolution? {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return nil }

        let queryTokens = Set(dockPillTokens(normalizedQuery))
        var matches: [L2AppActionMatch] = []

        for adapter in AppAdapterManager.shared.adapters where adapter.isEnabled {
            let normalizedAppName = normalizedDockPillText(adapter.appName)

            for action in adapter.actions {
                let normalizedActionName = normalizedDockPillText(action.name)
                let normalizedTriggers = action.triggers.map(normalizedDockPillText)
                let corpora = ([normalizedActionName] + normalizedTriggers).filter { !$0.isEmpty }

                var score = 0.0

                if corpora.contains(normalizedQuery) {
                    score += 155
                }
                if normalizedActionName == normalizedQuery {
                    score += 135
                }
                if corpora.contains(where: { $0.hasPrefix(normalizedQuery) }) {
                    score += 96
                }
                if corpora.contains(where: { $0.contains(normalizedQuery) }) {
                    score += 72
                }

                let actionTokens = Set(corpora.flatMap { dockPillTokens($0) })
                let overlap = queryTokens.intersection(actionTokens).count
                if overlap > 0 {
                    score += Double(overlap * 26)
                }

                if !normalizedAppName.isEmpty && normalizedQuery.contains(normalizedAppName) {
                    score += 24
                }
                if queryTokens.contains(where: { normalizedAppName.contains($0) }) {
                    score += 16
                }

                guard score >= 90 else { continue }

                matches.append(
                    L2AppActionMatch(
                        adapter: adapter,
                        action: action,
                        score: score,
                        matchedAppPhrase: normalizedAppName,
                        matchedActionPhrase: normalizedQuery,
                        usedFrontmostFallback: false
                    )
                )
            }
        }

        let ranked = matches.sorted {
            if $0.score != $1.score { return $0.score > $1.score }
            return $0.action.name.localizedCaseInsensitiveCompare($1.action.name)
                == .orderedAscending
        }

        guard let primary = ranked.first else { return nil }
        let alternatives = Array(ranked.dropFirst().prefix(3)).filter {
            $0.score >= primary.score - 20
        }
        return L2AppActionResolution(primary: primary, alternatives: alternatives)
    }

    func globalAIContextBlock() -> String {
        var lines: [String] = [
            "## Global Context Mode", "Treat the frontmost app as passive context only.",
        ]

        let context = effectiveAXContextForConversation()
        if !context.isEmpty {
            lines.append("## Passive Live Context")
            lines.append(context.contextSummary)
        }

        let selectedFiles = effectiveSelectedFileURLsForConversation()
        if !selectedFiles.isEmpty {
            lines.append("## Selected Files")
            for url in selectedFiles.prefix(8) {
                lines.append("- \(url.lastPathComponent)")
            }
        }

        return lines.joined(separator: "\n")
    }

    func messagesScopedSemanticIntent(for scopedQuery: String) -> CrossAppIntent? {
        let normalized = scopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return nil }
        return CrossAppNLHandler.shared.parseMessagesScopedIntent(normalized)
    }

    func rawDockQuery(matching normalizedQuery: String) -> String {
        let rawQuery = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !rawQuery.isEmpty,
            normalizedDockPillText(rawQuery) == normalizedDockPillText(normalizedQuery)
        else {
            return normalizedQuery
        }
        return rawQuery
    }

    func stripScopedAlias(
        _ alias: String,
        from rawQuery: String,
        allowPrefixAlias: Bool = false
    ) -> String {
        let trimmed = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let aliasTokens = alias.split(separator: " ").map { $0.lowercased() }
        let queryTokens = trimmed.split(separator: " ", omittingEmptySubsequences: true)
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return trimmed }

        let prefix = queryTokens.prefix(aliasTokens.count).map { $0.lowercased() }
        if prefix == aliasTokens
            || (allowPrefixAlias
                && firstScopedAliasRange(aliasTokens, in: prefix, allowPrefixLastToken: true)?
                    .lowerBound == 0)
        {
            return trimScopedAppFillerWords(
                queryTokens.dropFirst(aliasTokens.count).map(String.init)
            )
        }

        let normalizedTokens = queryTokens.map { normalizedDockPillText(String($0)) }
        guard
            let range = firstScopedAliasRange(
                aliasTokens,
                in: normalizedTokens,
                allowPrefixLastToken: allowPrefixAlias
            )
        else {
            return trimmed
        }
        var remaining = queryTokens.map(String.init)
        remaining.removeSubrange(range)
        return trimScopedAppFillerWords(remaining)
    }

    func firstScopedAliasRange(
        _ aliasTokens: [String],
        in queryTokens: [String],
        allowPrefixLastToken: Bool = false
    ) -> Range<Int>? {
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return nil }
        let maxStart = queryTokens.count - aliasTokens.count
        for start in 0...maxStart {
            let candidate = Array(queryTokens[start..<(start + aliasTokens.count)])
            let matches = candidate.enumerated().allSatisfy { index, token in
                let aliasToken = aliasTokens[index]
                if token == aliasToken { return true }
                let isLastToken = index == aliasTokens.count - 1
                return allowPrefixLastToken
                    && aliasTokens.count > 1
                    && isLastToken
                    && token.count >= 3
                    && aliasToken.hasPrefix(token)
            }
            if matches {
                return start..<(start + aliasTokens.count)
            }
        }
        return nil
    }

    func trimScopedAppFillerWords(_ tokens: [String]) -> String {
        var words = tokens
        let filler: Set<String> = [
            "app", "open", "go", "goto", "navigate", "launch", "show", "use",
            "please", "the", "a", "an", "to", "in", "on", "for", "with", "into", "using", "and",
        ]
        while let first = words.first,
            filler.contains(normalizedDockPillText(first))
        {
            words.removeFirst()
        }
        while let last = words.last,
            filler.contains(normalizedDockPillText(last))
        {
            words.removeLast()
        }
        return words.joined(separator: " ").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func rawScopedActionQuery(for normalizedQuery: String, scope: DockScopeResolution)
        -> String
    {
        let rawQuery = rawDockQuery(matching: normalizedQuery)
        let normalizedRawQuery = normalizedDockPillText(rawQuery)

        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []

        if scope.isExplicitAppScope,
            let explicitTarget = L2AppActionRouter.shared.appScopeTarget(for: normalizedRawQuery),
            !runningOnly || runningBundleIds.contains(explicitTarget.bundleId),
            explicitTarget.bundleId == scope.scopedBundleId
        {
            return stripScopedAlias(
                explicitTarget.matchedAlias,
                from: rawQuery,
                allowPrefixAlias: runningOnly
            )
        }

        if scope.isExplicitAppScope,
            let installedTarget = installedAppMenuTarget(
                for: normalizedRawQuery,
                runningOnly: runningOnly,
                includeAppsWithoutMenuSnapshot: installedScopeMode,
                allowPrefixAlias: installedScopeMode
            ),
            installedTarget.bundleId == scope.scopedBundleId
        {
            return stripScopedAlias(
                installedTarget.matchedAlias,
                from: rawQuery,
                allowPrefixAlias: runningOnly || installedScopeMode
            )
        }

        return rawQuery
    }

    func messageIntentDisplayText(_ value: String, limit: Int) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > limit else { return trimmed }
        return String(trimmed.prefix(limit - 1)) + "…"
    }

    func firstQuotedPhrase(in value: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: #""([^"]+)""#, options: []) else {
            return nil
        }
        let range = NSRange(value.startIndex..<value.endIndex, in: value)
        guard let match = regex.firstMatch(in: value, options: [], range: range),
            match.numberOfRanges > 1,
            let captureRange = Range(match.range(at: 1), in: value)
        else {
            return nil
        }
        return String(value[captureRange])
    }

    enum MailSearchTokenKind {
        case generic
        case sender
        case subject
        case attachment
        case date
    }

    struct MailSearchIntent {
        let query: String
        let tokenKind: MailSearchTokenKind
        let displayLabel: String
    }

    struct AppFindIntent {
        let query: String
        let targetBundleId: String
        let targetAppName: String
        let userMessage: String
        let commandTitle: String
        let preferMailboxSearch: Bool
    }

    struct AppFindToken {
        let title: String
        let targetBundleId: String
        let targetAppName: String
        let parentMenu: AXMenuItem?
        var selectedMenu: AXMenuItem?

        var hasChildMenu: Bool {
            guard let parentMenu else { return false }
            return parentMenu.children.contains { child in
                child.isEnabled || child.children.contains(where: { $0.isEnabled })
            }
        }
    }

    struct AppSearchProfile {
        let preferredMenuTitles: [String]
        let tryVisibleSearchFieldFirst: Bool
        let pressReturnAfterInject: Bool
    }

    func mailSearchDisplayLabel(
        query: String,
        tokenKind: MailSearchTokenKind
    ) -> String {
        switch tokenKind {
        case .date:
            return query
        case .sender:
            return "from \(query)"
        case .subject:
            return "subject \(query)"
        case .attachment:
            return "attachment \(query)"
        case .generic:
            return query
        }
    }

    func mailSearchTokenKind(from value: String) -> MailSearchTokenKind {
        switch normalizedDockPillText(value) {
        case "sender":
            return .sender
        case "subject":
            return .subject
        case "attachment":
            return .attachment
        case "date":
            return .date
        default:
            return .generic
        }
    }

    func resolvedMailMailboxSearchIntent(for rawScopedQuery: String) async
        -> MailSearchIntent?
    {
        #if canImport(FoundationModels)
            if #available(macOS 26.0, *) {
                if let generated = try? await generateMailIntent(
                    from: rawScopedQuery,
                    dateTimeContext: currentDateTimeContextBlock()
                ) {
                    let mode = normalizedDockPillText(generated.mode)
                    if mode == "question" || mode == "none" {
                        return nil
                    }

                    let resolvedQuery = generated.searchQuery
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                    if !resolvedQuery.isEmpty {
                        let tokenKind = mailSearchTokenKind(from: generated.tokenKind)
                        return MailSearchIntent(
                            query: resolvedQuery,
                            tokenKind: tokenKind,
                            displayLabel: mailSearchDisplayLabel(
                                query: resolvedQuery,
                                tokenKind: tokenKind
                            )
                        )
                    }
                }
            }
        #endif

        return shouldExecuteMailMailboxSearch(for: rawScopedQuery)
    }

    func weekdayNameCandidate(for normalizedQuery: String) -> String? {
        let weekdays = [
            "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
        ]
        return weekdays.first(where: {
            $0.hasPrefix(normalizedQuery) || normalizedQuery.hasPrefix($0)
        })
    }

    func mailDateSuggestionCandidates(for query: String) -> [String] {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return [] }

        var candidates: [String] = []
        let formatter = DateFormatter()
        formatter.locale = Locale.current
        formatter.dateFormat = "EEEE, d MMMM yyyy"
        let calendar = Calendar.current
        let now = Date()

        if let weekday = weekdayNameCandidate(for: normalized) {
            candidates.append(weekday)
            if let weekdayIndex = [
                "sunday": 1, "monday": 2, "tuesday": 3, "wednesday": 4,
                "thursday": 5, "friday": 6, "saturday": 7,
            ][weekday] {
                let currentWeekday = calendar.component(.weekday, from: now)
                let offset = (weekdayIndex - currentWeekday + 7) % 7
                if let date = calendar.date(byAdding: .day, value: offset, to: now) {
                    candidates.append(formatter.string(from: date))
                }
            }
        }

        if ["today", "tod"].contains(where: { normalized.hasPrefix($0) }) {
            candidates.append(formatter.string(from: now))
        } else if ["yesterday", "yest"].contains(where: { normalized.hasPrefix($0) }),
            let date = calendar.date(byAdding: .day, value: -1, to: now)
        {
            candidates.append(formatter.string(from: date))
        } else if ["tomorrow", "tomo"].contains(where: { normalized.hasPrefix($0) }),
            let date = calendar.date(byAdding: .day, value: 1, to: now)
        {
            candidates.append(formatter.string(from: date))
        }

        return Array(NSOrderedSet(array: candidates)) as? [String] ?? candidates
    }

    func mailSemanticSearchIntent(from rawScopedQuery: String) -> MailSearchIntent? {
        let trimmed = rawScopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        let normalized = normalizedDockPillText(trimmed)
        let tokens = Set(dockPillTokens(normalized))
        let intentWords: Set<String> = ["search", "find", "lookup", "look", "show"]
        let dateCandidates = mailDateSuggestionCandidates(for: trimmed)
        let explicitSenderIntent = tokens.contains("from") || tokens.contains("sender")
        let explicitSubjectIntent = tokens.contains("subject")
        let explicitAttachmentIntent =
            tokens.contains("attachment") || tokens.contains("attachments")
            || tokens.contains("attach")
        let explicitDateIntent =
            tokens.contains("date") || !dateCandidates.isEmpty

        guard
            !tokens.isDisjoint(with: intentWords)
                || explicitSenderIntent
                || explicitSubjectIntent
                || explicitAttachmentIntent
                || explicitDateIntent
        else { return nil }

        if let quoted = firstQuotedPhrase(in: trimmed)?
            .trimmingCharacters(in: .whitespacesAndNewlines),
            !quoted.isEmpty
        {
            let tokenKind: MailSearchTokenKind =
                explicitSenderIntent
                ? .sender
                : explicitSubjectIntent
                    ? .subject
                    : explicitAttachmentIntent
                        ? .attachment
                        : explicitDateIntent
                            ? .date
                            : .generic
            let label: String =
                tokenKind == .date
                ? quoted
                : tokenKind == .sender
                    ? "from \(quoted)"
                    : tokenKind == .subject
                        ? "subject \(quoted)"
                        : tokenKind == .attachment
                            ? "attachment \(quoted)"
                            : quoted
            return MailSearchIntent(query: quoted, tokenKind: tokenKind, displayLabel: label)
        }

        var cleaned = trimmed
        let patterns = [
            #"(?i)\b(search|find|lookup|look\s+for|show)\b"#,
            #"(?i)\b(mail|mails|email|emails|mailbox|inbox)\b"#,
            #"(?i)\b(sender|from|subject|attachment|attachments|attach|for|about|with|in|date)\b"#,
        ]
        for pattern in patterns {
            cleaned = cleaned.replacingOccurrences(
                of: pattern,
                with: " ",
                options: .regularExpression
            )
        }
        cleaned =
            cleaned
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleaned.isEmpty else { return nil }

        let tokenKind: MailSearchTokenKind =
            explicitSenderIntent
            ? .sender
            : explicitSubjectIntent
                ? .subject
                : explicitAttachmentIntent
                    ? .attachment
                    : explicitDateIntent
                        ? .date
                        : .generic
        let label: String =
            tokenKind == .date
            ? cleaned
            : tokenKind == .sender
                ? "from \(cleaned)"
                : tokenKind == .subject
                    ? "subject \(cleaned)"
                    : tokenKind == .attachment
                        ? "attachment \(cleaned)"
                        : cleaned

        return MailSearchIntent(query: cleaned, tokenKind: tokenKind, displayLabel: label)
    }

    func mailSemanticSearchQuery(from rawScopedQuery: String) -> String? {
        mailSemanticSearchIntent(from: rawScopedQuery)?.query
    }

    func isQuestionStyleMailQuery(_ rawScopedQuery: String) -> Bool {
        let normalized = normalizedDockPillText(rawScopedQuery)
        guard !normalized.isEmpty else { return false }

        if rawScopedQuery.contains("?") { return true }

        let questionPrefixes = [
            "is", "are", "do", "does", "did", "have", "has", "what", "which", "who", "when",
            "where", "why", "how", "can", "could", "would", "should", "any", "show me",
            "tell me",
        ]
        if questionPrefixes.contains(where: { normalized == $0 || normalized.hasPrefix($0 + " ") })
        {
            return true
        }

        return normalized.contains("any mail")
            || normalized.contains("any mails")
            || normalized.contains("there any")
    }

    func shouldExecuteMailMailboxSearch(for rawScopedQuery: String) -> MailSearchIntent? {
        guard let intent = mailSemanticSearchIntent(from: rawScopedQuery) else { return nil }
        guard !isQuestionStyleMailQuery(rawScopedQuery) else { return nil }
        return intent
    }

    struct MailQuestionFilters {
        let senderFilter: String
        let subjectFilter: String
        let unreadOnly: Bool
        let relativeDay: String
        let criteriaSummary: [String]
    }

    func mailFieldFilter(
        from query: String,
        triggers: Set<String>
    ) -> String? {
        let tokens = dockPillTokens(normalizedDockPillText(query))
        guard let triggerIndex = tokens.firstIndex(where: { triggers.contains($0) }) else {
            return nil
        }

        let stopWords: Set<String> = [
            "today", "yesterday", "tomorrow", "unread", "read", "mail", "mails", "email",
            "emails", "mailbox", "inbox", "is", "are", "was", "were", "any", "there", "show",
            "find", "search", "lookup", "look", "for", "about", "with", "and", "or", "the",
            "a", "an", "messages", "message", "date",
        ]

        var collected: [String] = []
        for token in tokens.dropFirst(triggerIndex + 1) {
            if stopWords.contains(token) { break }
            collected.append(token)
        }

        let result = collected.joined(separator: " ").trimmingCharacters(
            in: .whitespacesAndNewlines)
        return result.isEmpty ? nil : result
    }

    func mailQuestionFilters(for query: String) -> MailQuestionFilters {
        let normalized = normalizedDockPillText(query)
        let senderFilter = mailFieldFilter(from: query, triggers: ["from", "sender"]) ?? ""
        let subjectFilter = mailFieldFilter(from: query, triggers: ["subject"]) ?? ""
        let unreadOnly = normalized.contains("unread")

        let relativeDay: String =
            normalized.contains("today")
            ? "today"
            : normalized.contains("yesterday")
                ? "yesterday"
                : ""

        let criteriaSummary: [String] = [
            !senderFilter.isEmpty ? "sender contains “\(senderFilter)”" : nil,
            !subjectFilter.isEmpty ? "subject contains “\(subjectFilter)”" : nil,
            !relativeDay.isEmpty ? "received \(relativeDay)" : nil,
            unreadOnly ? "unread only" : nil,
        ].compactMap { $0 }

        return MailQuestionFilters(
            senderFilter: senderFilter,
            subjectFilter: subjectFilter,
            unreadOnly: unreadOnly,
            relativeDay: relativeDay,
            criteriaSummary: criteriaSummary
        )
    }

    func answerAttachedMailQuestion(for rawScopedQuery: String) -> String? {
        guard isCurrentMailContextAttached(), isQuestionStyleMailQuery(rawScopedQuery) else {
            return nil
        }

        let filters = mailQuestionFilters(for: rawScopedQuery)
        let normalized = normalizedDockPillText(rawScopedQuery)
        let hasUsefulFilters =
            !filters.senderFilter.isEmpty
            || !filters.subjectFilter.isEmpty
            || filters.unreadOnly
            || !filters.relativeDay.isEmpty

        guard hasUsefulFilters || normalized.contains("mail") || normalized.contains("email") else {
            return nil
        }

        guard
            let snapshot = MailAutomation.mailboxSnapshotData(
                senderContains: filters.senderFilter,
                subjectContains: filters.subjectFilter,
                unreadOnly: filters.unreadOnly,
                relativeDay: filters.relativeDay,
                limit: 12,
                maxScan: 150
            )
        else {
            return "Mail context could not be read from the current mailbox."
        }

        let expectsYesNo =
            rawScopedQuery.contains("?")
            || normalized.hasPrefix("is ")
            || normalized.hasPrefix("are ")
            || normalized.hasPrefix("do ")
            || normalized.hasPrefix("does ")
            || normalized.hasPrefix("did ")
            || normalized.hasPrefix("have ")
            || normalized.hasPrefix("has ")
            || normalized.contains("any mail")
            || normalized.contains("any mails")

        let criteriaText = filters.criteriaSummary.joined(separator: ", ")
        let matchCount = snapshot.messages.count

        if matchCount == 0 {
            if expectsYesNo {
                return criteriaText.isEmpty
                    ? "No — I couldn't find matching mail in \(snapshot.mailboxName)."
                    : "No — I couldn't find mail in \(snapshot.mailboxName) matching \(criteriaText)."
            }
            return criteriaText.isEmpty
                ? "No matching mail found in \(snapshot.mailboxName)."
                : "No mail in \(snapshot.mailboxName) matched \(criteriaText)."
        }

        var answer =
            expectsYesNo
            ? "Yes — found \(matchCount) matching \(matchCount == 1 ? "mail" : "mails") in \(snapshot.mailboxName)"
            : "Found \(matchCount) matching \(matchCount == 1 ? "mail" : "mails") in \(snapshot.mailboxName)"
        if !criteriaText.isEmpty {
            answer += " (\(criteriaText))."
        } else {
            answer += "."
        }

        for message in snapshot.messages.prefix(4) {
            answer += "\n- \(message.subject) — \(message.sender) — \(message.dateText)"
        }
        if matchCount > 4 {
            answer += "\n+ \(matchCount - 4) more"
        }

        return answer
    }

    func buildAttachedMailContextBlock(for query: String) -> String? {
        let filters = mailQuestionFilters(for: query)
        guard
            let snapshot = MailAutomation.mailboxSnapshotData(
                senderContains: filters.senderFilter,
                subjectContains: filters.subjectFilter,
                unreadOnly: filters.unreadOnly,
                relativeDay: filters.relativeDay,
                limit: 12,
                maxScan: 150
            )
        else {
            return "\n📧 ACTUAL MAIL DATA:\nMail context could not be read.\n"
        }

        var block = "\n📧 ACTUAL MAIL DATA (recent \(snapshot.mailboxName) scan):\n"
        if !filters.criteriaSummary.isEmpty {
            block += "Criteria: " + filters.criteriaSummary.joined(separator: ", ") + "\n"
        }
        block += "Mailbox: \(snapshot.mailboxName)\n"

        if snapshot.messages.isEmpty {
            block += "No matching messages were found in the recent Mail scan.\n"
            return block
        }

        for message in snapshot.messages {
            block +=
                "- \(message.subject) | From: \(message.sender) | \(message.dateText) | Read: \(message.isRead)\n"
        }
        block +=
            "IMPORTANT: Use this ACTUAL mail data to answer mailbox questions. Do not make up email results.\n"
        return block
    }

    func applicationURL(bundleIdentifier: String, appName: String) -> URL? {
        if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier) {
            return url
        }
        if let match = allApplications.first(where: { result in
            Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier == bundleIdentifier
        }) {
            return URL(fileURLWithPath: match.subtitle)
        }
        let fallbackDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        for directory in fallbackDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if FileManager.default.fileExists(atPath: url.path) {
                return url
            }
        }
        return nil
    }

    func activateOrLaunchSemanticApp(bundleIdentifier: String, appName: String) async
        -> NSRunningApplication?
    {
        if let runningApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        }) {
            await MainActor.run { runningApp.activate() }
            return runningApp
        }

        guard let appURL = applicationURL(bundleIdentifier: bundleIdentifier, appName: appName)
        else { return nil }

        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true

        do {
            let launchedApp = try await NSWorkspace.shared.openApplication(
                at: appURL,
                configuration: configuration
            )
            return launchedApp
        } catch {
            NSWorkspace.shared.open(appURL)
            for _ in 0..<20 {
                try? await Task.sleep(nanoseconds: 120_000_000)
                if let runningApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
                }) {
                    await MainActor.run { runningApp.activate() }
                    return runningApp
                }
            }
            return nil
        }
    }

    func axStringAttribute(_ element: AXUIElement, _ attribute: CFString) -> String? {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute, &ref) == .success else {
            return nil
        }
        return ref as? String
    }

    func axStringArrayAttribute(_ element: AXUIElement, _ attribute: CFString) -> [String] {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute, &ref) == .success else { return [] }
        return ref as? [String] ?? []
    }

    func axChildElements(_ element: AXUIElement) -> [AXUIElement] {
        var ref: CFTypeRef?
        guard
            AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &ref)
                == .success,
            let children = ref as? [AXUIElement]
        else { return [] }
        return children
    }

    func currentFocusedElement(in pid: pid_t) -> AXUIElement? {
        let appElement = AXUIElementCreateApplication(pid)
        var ref: CFTypeRef?
        guard
            AXUIElementCopyAttributeValue(
                appElement,
                kAXFocusedUIElementAttribute as CFString,
                &ref
            ) == .success, let focused = ref
        else { return nil }
        return unsafeBitCast(focused, to: AXUIElement.self)
    }

    func isEditableAXElement(_ element: AXUIElement) -> Bool {
        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        return ["AXSearchField", "AXTextField", "AXComboBox", "AXTextArea"].contains(role)
    }

    func findMailSearchField(in element: AXUIElement, depth: Int = 0) -> AXUIElement? {
        guard depth < 8 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        if role == "AXSearchField" {
            return element
        }

        let description = axStringAttribute(element, kAXDescriptionAttribute as CFString) ?? ""
        let title = axStringAttribute(element, kAXTitleAttribute as CFString) ?? ""
        let help = axStringAttribute(element, kAXHelpAttribute as CFString) ?? ""
        let metadata = normalizedDockPillText([description, title, help].joined(separator: " "))

        if isEditableAXElement(element),
            metadata.contains("search") || metadata.contains("mailbox")
        {
            return element
        }

        var firstEditableField: AXUIElement?
        for child in axChildElements(element) {
            if let exact = findMailSearchField(in: child, depth: depth + 1) {
                return exact
            }
            if firstEditableField == nil, isEditableAXElement(child) {
                firstEditableField = child
            }
        }
        return firstEditableField
    }

    func findGenericSearchField(in element: AXUIElement, depth: Int = 0) -> AXUIElement? {
        guard depth < 9 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        if role == "AXSearchField" {
            return element
        }

        let description = axStringAttribute(element, kAXDescriptionAttribute as CFString) ?? ""
        let title = axStringAttribute(element, kAXTitleAttribute as CFString) ?? ""
        let help = axStringAttribute(element, kAXHelpAttribute as CFString) ?? ""
        let placeholder =
            axStringAttribute(element, "AXPlaceholderValue" as CFString) ?? ""
        let metadata = normalizedDockPillText(
            [description, title, help, placeholder].joined(separator: " ")
        )

        if isEditableAXElement(element),
            metadata.contains("search")
                || metadata.contains("find")
                || metadata.contains("filter")
        {
            return element
        }

        var firstEditableField: AXUIElement?
        for child in axChildElements(element) {
            if let exact = findGenericSearchField(in: child, depth: depth + 1) {
                return exact
            }
            if firstEditableField == nil, isEditableAXElement(child) {
                firstEditableField = child
            }
        }
        return firstEditableField
    }

    func setAXTextValue(_ text: String, on element: AXUIElement) -> Bool {
        let setFocusStatus = AXUIElementSetAttributeValue(
            element,
            kAXFocusedAttribute as CFString,
            kCFBooleanTrue
        )
        _ = setFocusStatus
        guard
            AXUIElementSetAttributeValue(
                element,
                kAXValueAttribute as CFString,
                text as CFTypeRef
            ) == .success
        else { return false }

        guard let currentValue = axStringAttribute(element, kAXValueAttribute as CFString) else {
            return false
        }

        let normalizedCurrent = normalizedDockPillText(currentValue)
        let normalizedTarget = normalizedDockPillText(text)
        return normalizedCurrent == normalizedTarget
            || normalizedCurrent.contains(normalizedTarget)
    }

    func postKeyCode(_ keyCode: CGKeyCode, to pid: pid_t) {
        guard let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        else { return }
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    func postModifiedKeyCode(_ keyCode: CGKeyCode, flags: CGEventFlags, to pid: pid_t) {
        guard let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        else { return }
        keyDown.flags = flags
        keyUp.flags = flags
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    func postUnicodeText(_ text: String, to pid: pid_t) {
        let utf16 = Array(text.utf16)
        guard !utf16.isEmpty,
            let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: false)
        else { return }
        keyDown.keyboardSetUnicodeString(stringLength: utf16.count, unicodeString: utf16)
        keyUp.keyboardSetUnicodeString(stringLength: utf16.count, unicodeString: utf16)
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    func pasteString(_ text: String, to pid: pid_t) {
        let pasteboard = NSPasteboard.general
        let previousString = pasteboard.string(forType: .string)
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        postModifiedKeyCode(9, flags: .maskCommand, to: pid)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
            pasteboard.clearContents()
            if let previousString {
                pasteboard.setString(previousString, forType: .string)
            }
        }
    }

    func setFindPasteboardString(_ text: String) {
        let findPasteboard = NSPasteboard(name: NSPasteboard.Name("NSFindPboard"))
        findPasteboard.clearContents()
        findPasteboard.setString(text, forType: .string)
    }

    func injectSearchQuery(_ query: String, into pid: pid_t, pressReturn: Bool = false)
        async
        -> Bool
    {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        for _ in 0..<16 {
            if let focusedElement = currentFocusedElement(in: pid),
                isEditableAXElement(focusedElement)
            {
                let didPasteValue = await typeMailSearchQuery(
                    trimmed,
                    into: focusedElement,
                    pid: pid
                )
                let didSetAXValue =
                    didPasteValue
                    ? false
                    : setAXTextValue(trimmed, on: focusedElement)
                if didPasteValue || didSetAXValue {
                    if pressReturn { postKeyCode(36, to: pid) }
                    return true
                }
            }

            let appElement = AXUIElementCreateApplication(pid)
            if let searchField = findGenericSearchField(in: appElement) {
                let didPasteValue = await typeMailSearchQuery(trimmed, into: searchField, pid: pid)
                let didSetAXValue =
                    didPasteValue
                    ? false
                    : setAXTextValue(trimmed, on: searchField)
                if didPasteValue || didSetAXValue {
                    if pressReturn { postKeyCode(36, to: pid) }
                    return true
                }
            }

            try? await Task.sleep(nanoseconds: 90_000_000)
        }

        return false
    }

    func typeMailSearchQuery(_ query: String, into element: AXUIElement, pid: pid_t) async
        -> Bool
    {
        _ = AXUIElementSetAttributeValue(
            element,
            kAXFocusedAttribute as CFString,
            kCFBooleanTrue
        )
        try? await Task.sleep(nanoseconds: 60_000_000)
        postModifiedKeyCode(0, flags: .maskCommand, to: pid)
        try? await Task.sleep(nanoseconds: 40_000_000)
        pasteString(query, to: pid)
        try? await Task.sleep(nanoseconds: 80_000_000)

        if let currentValue = axStringAttribute(element, kAXValueAttribute as CFString) {
            let normalizedCurrent = normalizedDockPillText(currentValue)
            let normalizedTarget = normalizedDockPillText(query)
            return normalizedCurrent == normalizedTarget
                || normalizedCurrent.contains(normalizedTarget)
        }

        return true
    }

    func axSearchableStrings(for element: AXUIElement) -> [String] {
        [
            axStringAttribute(element, kAXTitleAttribute as CFString),
            axStringAttribute(element, kAXValueAttribute as CFString),
            axStringAttribute(element, kAXDescriptionAttribute as CFString),
            axStringAttribute(element, kAXHelpAttribute as CFString),
        ]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    }

    func axSubtreeSearchableStrings(for element: AXUIElement, depth: Int = 0) -> [String] {
        guard depth < 2 else { return axSearchableStrings(for: element) }

        var results = axSearchableStrings(for: element)
        for child in axChildElements(element).prefix(12) {
            results.append(contentsOf: axSubtreeSearchableStrings(for: child, depth: depth + 1))
        }
        return results
    }

    func isMailSuggestionActionRole(_ role: String) -> Bool {
        [
            "AXRow",
            "AXGroup",
            "AXButton",
            "AXMenuItem",
            "AXListItem",
            "AXCell",
        ].contains(role)
    }

    struct MailSuggestionMatcher {
        let tokenKind: MailSearchTokenKind
        let normalizedQuery: String
        let normalizedQueryTokens: [String]
        let normalizedCandidates: [String]
        let normalizedFieldTokens: [String]

        private static func normalize(_ text: String) -> String {
            let lowered = text.lowercased()
            let mapped = lowered.unicodeScalars.map { scalar -> Character in
                if CharacterSet.alphanumerics.contains(scalar)
                    || CharacterSet.whitespacesAndNewlines.contains(scalar)
                {
                    return Character(scalar)
                }
                return " "
            }
            return String(mapped)
                .components(separatedBy: .whitespacesAndNewlines)
                .filter { !$0.isEmpty }
                .joined(separator: " ")
        }

        private static func isActionRole(_ role: String) -> Bool {
            ["AXRow", "AXGroup", "AXButton", "AXMenuItem", "AXListItem", "AXCell"].contains(role)
        }

        init(intent: MailSearchIntent, candidates: [String]) {
            tokenKind = intent.tokenKind
            normalizedQuery = Self.normalize(intent.query)
            normalizedQueryTokens =
                normalizedQuery
                .split(whereSeparator: \.isWhitespace)
                .map(String.init)
                .filter { !$0.isEmpty }
            normalizedCandidates = candidates.map { Self.normalize($0) }.filter { !$0.isEmpty }

            switch intent.tokenKind {
            case .generic:
                normalizedFieldTokens = []
            case .sender:
                normalizedFieldTokens = ["sender", "contains"]
            case .subject:
                normalizedFieldTokens = ["subject", "contains"]
            case .attachment:
                normalizedFieldTokens = ["attachment", "name", "contains"]
            case .date:
                normalizedFieldTokens = ["date"]
            }
        }

        func score(
            role: String,
            actionNames: [String],
            directStrings: [String],
            subtreeStrings: [String]
        ) -> Int? {
            let normalizedDirect = directStrings.map { Self.normalize($0) }.filter { !$0.isEmpty }
            let normalizedSubtree = subtreeStrings.map { Self.normalize($0) }.filter { !$0.isEmpty }
            let combinedDirect = normalizedDirect.joined(separator: " ")
            let combinedSubtree = normalizedSubtree.joined(separator: " ")

            guard !combinedSubtree.isEmpty else { return nil }

            let exactDirectMatch = normalizedCandidates.contains { candidate in
                combinedDirect == candidate || combinedDirect.contains(candidate)
            }
            let exactSubtreeMatch = normalizedCandidates.contains { candidate in
                combinedSubtree == candidate || combinedSubtree.contains(candidate)
            }

            let tokenMatch: Bool = {
                switch tokenKind {
                case .generic:
                    return false
                case .date:
                    return exactDirectMatch
                        || exactSubtreeMatch
                        || normalizedQueryTokens.contains(where: { combinedSubtree.contains($0) })
                case .sender, .subject, .attachment:
                    let hasFieldTokens = normalizedFieldTokens.allSatisfy {
                        combinedSubtree.contains($0)
                    }
                    let hasQueryTokens =
                        !normalizedQueryTokens.isEmpty
                        && normalizedQueryTokens.allSatisfy { combinedSubtree.contains($0) }
                    return exactDirectMatch || exactSubtreeMatch
                        || (hasFieldTokens && hasQueryTokens)
                }
            }()

            guard tokenMatch else { return nil }

            var score = 0
            if exactDirectMatch { score += 240 }
            if exactSubtreeMatch { score += 180 }
            if Self.isActionRole(role) { score += 120 }
            if role == "AXStaticText" { score -= 240 }
            if role == "AXRow" { score += 80 }
            if role == "AXMenuItem" || role == "AXListItem" || role == "AXCell" { score += 60 }
            if role == "AXGroup" || role == "AXButton" { score += 40 }
            if actionNames.contains(kAXPressAction as String) { score += 30 }
            if actionNames.contains(kAXConfirmAction as String) { score += 15 }
            if combinedDirect.contains(normalizedQuery) { score += 20 }
            if combinedSubtree.contains(normalizedQuery) { score += 10 }
            return score
        }
    }

    func bestMailSuggestionTarget(
        in element: AXUIElement,
        matcher: MailSuggestionMatcher,
        depth: Int = 0
    ) -> (element: AXUIElement, score: Int)? {
        guard depth < 10 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        let actionNames = axStringArrayAttribute(element, "AXActions" as CFString)
        let directStrings = axSearchableStrings(for: element)
        let subtreeStrings =
            isMailSuggestionActionRole(role)
            ? axSubtreeSearchableStrings(for: element)
            : directStrings

        var best: (element: AXUIElement, score: Int)?
        if let score = matcher.score(
            role: role,
            actionNames: actionNames,
            directStrings: directStrings,
            subtreeStrings: subtreeStrings
        ) {
            best = (element, score)
        }

        for child in axChildElements(element) {
            guard
                let childBest = bestMailSuggestionTarget(
                    in: child,
                    matcher: matcher,
                    depth: depth + 1
                )
            else { continue }

            if let currentBest = best {
                if childBest.score > currentBest.score {
                    best = childBest
                }
            } else {
                best = childBest
            }
        }

        return best
    }

    func pressMailSuggestion(
        in element: AXUIElement,
        matcher: MailSuggestionMatcher,
        depth: Int = 0
    ) -> Bool {
        guard depth == 0 else { return false }
        guard let best = bestMailSuggestionTarget(in: element, matcher: matcher) else {
            return false
        }

        if AXUIElementPerformAction(best.element, kAXPressAction as CFString) == .success {
            return true
        }
        if AXUIElementPerformAction(best.element, kAXConfirmAction as CFString) == .success {
            return true
        }

        for child in axChildElements(best.element) {
            if AXUIElementPerformAction(child, kAXPressAction as CFString) == .success {
                return true
            }
            if AXUIElementPerformAction(child, kAXConfirmAction as CFString) == .success {
                return true
            }
        }
        return false
    }

    func applyMailSearchTokenIntent(_ intent: MailSearchIntent, in pid: pid_t) async -> Bool
    {
        let candidates: [String] = {
            switch intent.tokenKind {
            case .generic:
                return []
            case .sender:
                return ["Sender contains: \(intent.query)"]
            case .subject:
                return ["Subject contains: \(intent.query)"]
            case .attachment:
                return ["Attachment name contains: \(intent.query)"]
            case .date:
                return mailDateSuggestionCandidates(for: intent.query)
            }
        }()

        guard !candidates.isEmpty else { return true }
        let matcher = MailSuggestionMatcher(intent: intent, candidates: candidates)

        for _ in 0..<12 {
            let appElement = AXUIElementCreateApplication(pid)
            if pressMailSuggestion(in: appElement, matcher: matcher) {
                return true
            }
            try? await Task.sleep(nanoseconds: 90_000_000)
        }

        return false
    }

    func injectMailSearchQuery(_ query: String, into pid: pid_t) async -> Bool {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        for _ in 0..<18 {
            if let focusedElement = currentFocusedElement(in: pid),
                isEditableAXElement(focusedElement)
            {
                let didSetAXValue = setAXTextValue(trimmed, on: focusedElement)
                let didTypeValue =
                    didSetAXValue
                    ? false
                    : await typeMailSearchQuery(trimmed, into: focusedElement, pid: pid)
                if didSetAXValue || didTypeValue {
                    postKeyCode(36, to: pid)
                    return true
                }
            }

            let appElement = AXUIElementCreateApplication(pid)
            if let searchField = findMailSearchField(in: appElement) {
                let didSetAXValue = setAXTextValue(trimmed, on: searchField)
                let didTypeValue =
                    didSetAXValue
                    ? false
                    : await typeMailSearchQuery(trimmed, into: searchField, pid: pid)
                if didSetAXValue || didTypeValue {
                    postKeyCode(36, to: pid)
                    return true
                }
            }

            try? await Task.sleep(nanoseconds: 100_000_000)
        }

        return false
    }

    func executeMailMailboxSearch(intent: MailSearchIntent, userMessage: String) {
        let searchQuery = intent.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !searchQuery.isEmpty else { return }

        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2.isLoading = true

        l2.currentTask = Task {
            guard
                let mailApp = await activateOrLaunchSemanticApp(
                    bundleIdentifier: "com.apple.mail",
                    appName: "Mail"
                )
            else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open Mail.",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            let pid = mailApp.processIdentifier
            try? await Task.sleep(nanoseconds: 220_000_000)

            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            let mailboxSearchPath =
                liveItems.first(where: { item in
                    normalizedDockPillText(item.title) == "mailbox search"
                        || normalizedDockPillText(item.path.joined(separator: " "))
                            == "edit find mailbox search"
                })?.path

            var triggeredSearch = false
            if let mailboxSearchPath {
                triggeredSearch = AXMenuReader.shared.clickMenuItem(
                    path: mailboxSearchPath, in: pid)
            }
            if !triggeredSearch {
                AXMenuReader.shared.executeShortcut(char: "f", modifiers: 2, in: pid)
                triggeredSearch = true
            }

            guard triggeredSearch else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open Mail search.",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            let injected = await injectMailSearchQuery(searchQuery, into: pid)
            let appliedToken = injected ? await applyMailSearchTokenIntent(intent, in: pid) : false

            await MainActor.run {
                if injected {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: appliedToken && intent.tokenKind != .generic
                                ? "Opened Mailbox Search for \(intent.displayLabel)."
                                : "Opened Mailbox Search for “\(searchQuery)”."
                        ))
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                } else {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "⚠️ Opened Mail search, but couldn't inject the query automatically.",
                            isError: true
                        ))
                }
                l2.isLoading = false
                l2.currentTask = nil
            }
        }
    }

    func selectedTextPayloadForFindIntent() -> String {
        let context = effectiveAXContextForConversation()
        if let selected = context.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines),
            !selected.isEmpty
        {
            return selected
        }

        if case .textSelected(let text) = currentContext {
            let selected = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if !selected.isEmpty {
                return selected
            }
        }

        return ""
    }

    func findIntentPayload(from rawScopedQuery: String) -> String {
        let trimmed = rawScopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }

        if let quoted = firstQuotedPhrase(in: trimmed)?
            .trimmingCharacters(in: .whitespacesAndNewlines),
            !quoted.isEmpty
        {
            return quoted
        }

        var cleaned = trimmed
        let patterns = [
            #"(?i)\b(search|find|lookup|look\s+for|show|display)\b"#,
            #"(?i)\b(photos?\s+of|pictures?\s+of|images?\s+of)\b"#,
            #"(?i)^\s*of\s+"#,
            #"(?i)\b(selected|selection|this|that|text)\b"#,
            #"(?i)\b(in|inside|within|for|on|with|using|app|application)\b"#,
        ]
        for pattern in patterns {
            cleaned = cleaned.replacingOccurrences(
                of: pattern,
                with: " ",
                options: .regularExpression
            )
        }
        return
            cleaned
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func isFindIntentCommand(_ rawScopedQuery: String, fullQuery: String) -> Bool {
        let raw = normalizedDockPillText(rawScopedQuery)
        let full = normalizedDockPillText(fullQuery)
        let prefixes = ["find", "search", "lookup", "look for", "show", "display"]
        if prefixes.contains(where: { prefix in
            raw == prefix || raw.hasPrefix(prefix + " ")
                || full == prefix || full.hasPrefix(prefix + " ")
        }) {
            return true
        }
        // "photos of X", "pictures of X" as standalone pattern
        let mediaPatterns = [
            #"(?i)^photos?\s+of\b"#, #"(?i)^pictures?\s+of\b"#, #"(?i)^images?\s+of\b"#,
        ]
        return mediaPatterns.contains { pat in
            raw.range(of: pat, options: .regularExpression) != nil
                || full.range(of: pat, options: .regularExpression) != nil
        }
    }

    func findTokenTitle(for rawScopedQuery: String) -> String {
        let normalized = normalizedDockPillText(rawScopedQuery)
        if normalized == "search" || normalized.hasPrefix("search ") {
            return "Search"
        }
        if normalized == "lookup" || normalized.hasPrefix("lookup ")
            || normalized == "look for" || normalized.hasPrefix("look for ")
        {
            return "Search"
        }
        return "Find"
    }

    func appSearchProfile(
        bundleIdentifier: String,
        appName: String,
        commandTitle: String
    ) -> AppSearchProfile {
        let bundle = bundleIdentifier.lowercased()
        let name = normalizedDockPillText(appName)
        let command = normalizedDockPillText(commandTitle)
        let isSearchCommand = command == "search"

        if bundle == "com.apple.mail" {
            return AppSearchProfile(
                preferredMenuTitles: ["mailbox search", "find..."],
                tryVisibleSearchFieldFirst: false,
                pressReturnAfterInject: true
            )
        }

        if bundle == "com.apple.notes" || name == "notes" {
            return AppSearchProfile(
                preferredMenuTitles: ["note list search...", "note list search", "find..."],
                tryVisibleSearchFieldFirst: false,
                pressReturnAfterInject: false
            )
        }

        if bundle == "com.apple.photos" || name == "photos" {
            return AppSearchProfile(
                preferredMenuTitles: ["search", "find", "find..."],
                tryVisibleSearchFieldFirst: true,
                pressReturnAfterInject: false
            )
        }

        let browserLike =
            name.contains("youtube")
            || name.contains("safari")
            || name.contains("chrome")
            || name.contains("firefox")
            || name.contains("brave")
            || name.contains("edge")
            || bundle.contains("safari")
            || bundle.contains("chrome")
            || bundle.contains("firefox")
            || bundle.contains("brave")
            || bundle.contains("edge")

        if browserLike || isSearchCommand {
            return AppSearchProfile(
                preferredMenuTitles: ["search", "find", "find..."],
                tryVisibleSearchFieldFirst: browserLike,
                pressReturnAfterInject: browserLike
            )
        }

        return AppSearchProfile(
            preferredMenuTitles: ["find", "find..."],
            tryVisibleSearchFieldFirst: false,
            pressReturnAfterInject: false
        )
    }

    func resolvedFindTarget(
        dockScope: DockScopeResolution
    ) -> (bundleId: String, appName: String)? {
        if dockScope.isExplicitAppScope,
            !dockScope.scopedBundleId.isEmpty,
            !dockScope.scopedAppName.isEmpty
        {
            return (dockScope.scopedBundleId, dockScope.scopedAppName)
        }

        if let target = l2.targetApp, !target.bundleId.hasPrefix("scope://") {
            return (target.bundleId, target.name)
        }

        if let app = contextTargetApp(),
            let bundleId = app.bundleIdentifier,
            !bundleId.isEmpty,
            bundleId != Bundle.main.bundleIdentifier
        {
            return (bundleId, app.localizedName ?? frontmost.name)
        }

        return nil
    }

    func leafFindChildren(for parent: AXMenuItem) -> [AXMenuItem] {
        var leaves: [AXMenuItem] = []
        for child in parent.children {
            if child.isLeaf {
                leaves.append(child)
            } else {
                leaves.append(contentsOf: child.children.filter(\.isLeaf))
            }
        }
        return leaves.filter { $0.isEnabled }
    }

    func findMenuParent(
        targetBundleId: String,
        targetAppName: String
    ) -> AXMenuItem? {
        let liveMatches = targetBundleId == frontmost.bundleID ? liveMenuItems : []
        let cachedMatches = GlobalContextEngine.shared.cachedMenuItems(
            bundleIdentifier: targetBundleId,
            appName: targetAppName,
            processIdentifier: 0,
            query: "find",
            maxResults: 32
        )
        let candidates = liveMatches + cachedMatches
        let normalizedFindTitles: Set<String> = ["find", "find..."]

        let parent =
            candidates.first { item in
                !item.children.isEmpty
                    && normalizedFindTitles.contains(normalizedDockPillText(item.title))
                    && !leafFindChildren(for: item).isEmpty
            }
            ?? synthesizedFindParentFromCachedPaths(
                cachedMatches,
                targetBundleId: targetBundleId,
                targetAppName: targetAppName
            )

        guard let parent else { return nil }

        let fallbackPID =
            parent.sourcePID != 0
            ? parent.sourcePID
            : (NSWorkspace.shared.runningApplications.first {
                $0.bundleIdentifier == targetBundleId && !$0.isTerminated
            }?.processIdentifier ?? 0)
        return menuItemWithSourceFallback(parent, pid: fallbackPID, appName: targetAppName)
    }

    func synthesizedFindParentFromCachedPaths(
        _ items: [AXMenuItem],
        targetBundleId: String,
        targetAppName: String
    ) -> AXMenuItem? {
        let placeholder = AXUIElementCreateSystemWide()
        var seen = Set<String>()
        let children: [AXMenuItem] = items.compactMap { item in
            let normalizedPath = item.path.map(normalizedDockPillText)
            guard
                let findIndex = normalizedPath.firstIndex(where: { $0 == "find" || $0 == "find..." }
                )
            else {
                return nil
            }
            guard item.path.count > findIndex + 1 else { return nil }
            let title = item.title.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !title.isEmpty else { return nil }
            let key = item.path.joined(separator: " > ").lowercased()
            guard seen.insert(key).inserted else { return nil }
            var child = item
            child.children = []
            child.element = placeholder
            child.sourceAppName = targetAppName
            return child
        }

        guard !children.isEmpty else { return nil }
        return AXMenuItem(
            title: "Find",
            path: ["Edit", "Find"],
            isEnabled: true,
            element: placeholder,
            children: children,
            sourcePID: 0,
            sourceAppName: targetAppName
        )
    }

    func makeFindToken(
        title: String,
        targetBundleId: String,
        targetAppName: String
    ) -> AppFindToken {
        AppFindToken(
            title: title,
            targetBundleId: targetBundleId,
            targetAppName: targetAppName,
            parentMenu: findMenuParent(
                targetBundleId: targetBundleId,
                targetAppName: targetAppName
            ),
            selectedMenu: nil
        )
    }

    @discardableResult
    func activateFindTokenIfNeeded(from rawQuery: String) -> Bool {
        guard showContextInDock, !aiMode.isActive, lockedFindToken == nil else { return false }

        let trimmed = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        let scope = resolveDockScope(for: trimmed)
        let rawScopedQuery = rawScopedActionQuery(for: trimmed, scope: scope)
        guard isFindIntentCommand(rawScopedQuery, fullQuery: trimmed),
            let target = resolvedFindTarget(dockScope: scope)
        else { return false }

        let payload = findIntentPayload(from: rawScopedQuery)
        withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
            lockedFindToken = makeFindToken(
                title: findTokenTitle(for: rawScopedQuery),
                targetBundleId: target.bundleId,
                targetAppName: target.appName
            )
            showFindTokenMenu = false
            if searchState.query != payload {
                searchState.query = payload
            }
            l2.focusedPillIndex = nil
            l2.pillNavViaKeyboard = false
            listViewHoveredIndex = nil
        }
        l2.appCompletion = nil
        l2.showResultsPopover = false
        cachedDockPills = []
        if scope.isExplicitAppScope,
            l2.targetApp?.bundleId != target.bundleId
        {
            _ = activateInlineDockAppScope(
                bundleIdentifier: target.bundleId,
                appName: target.appName,
                queryOverride: payload,
                preserveGlobalContext: isGlobalContextActive
            )
        }
        return true
    }

    func clearFindToken(preserveQuery: Bool = true) {
        withAnimation(.spring(response: 0.2, dampingFraction: 0.82)) {
            lockedFindToken = nil
            showFindTokenMenu = false
            if !preserveQuery {
                searchState.query = ""
            }
        }
        scheduleDockPillRebuild(query: searchState.query, delayNanoseconds: 0)
    }

    func resolvedFindIntent(
        for query: String,
        dockScope: DockScopeResolution,
        rawScopedQuery: String
    ) -> AppFindIntent? {
        guard isFindIntentCommand(rawScopedQuery, fullQuery: query) else { return nil }

        let directPayload = findIntentPayload(from: rawScopedQuery)
        let selectedPayload = selectedTextPayloadForFindIntent()
        let searchQuery = directPayload.isEmpty ? selectedPayload : directPayload
        guard !searchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return nil
        }

        guard let target = resolvedFindTarget(dockScope: dockScope) else { return nil }
        return AppFindIntent(
            query: searchQuery,
            targetBundleId: target.bundleId,
            targetAppName: target.appName,
            userMessage: query,
            commandTitle: findTokenTitle(for: rawScopedQuery),
            preferMailboxSearch: target.bundleId == "com.apple.mail"
        )
    }

    func openFindInterface(
        in pid: pid_t,
        bundleIdentifier: String,
        appName: String,
        commandTitle: String = "Find"
    ) async -> Bool {
        let profile = appSearchProfile(
            bundleIdentifier: bundleIdentifier,
            appName: appName,
            commandTitle: commandTitle
        )
        let preferredTitles = Set(profile.preferredMenuTitles.map { normalizedDockPillText($0) })
        let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)

        if let preferredPath = liveItems.first(where: { item in
            let title = normalizedDockPillText(item.title)
            let path = normalizedDockPillText(item.path.joined(separator: " "))
            return preferredTitles.contains(title)
                || profile.preferredMenuTitles.contains(where: { preferred in
                    path.hasSuffix(" " + normalizedDockPillText(preferred))
                })
        })?.path,
            AXMenuReader.shared.clickMenuItem(path: preferredPath, in: pid)
        {
            return true
        }

        AXMenuReader.shared.executeShortcut(char: "f", modifiers: 2, in: pid)
        return true
    }

    func openAppFindInterface(
        targetBundleId: String,
        targetAppName: String,
        userMessage: String
    ) {
        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.activeRequestID = nil
        }

        let actionId = DockActionFeedback.start(
            "Opening Find",
            subject: targetAppName,
            icon: "magnifyingglass",
            tint: .accentColor
        )

        l2.currentTask = Task {
            guard
                let app = await activateOrLaunchSemanticApp(
                    bundleIdentifier: targetBundleId,
                    appName: targetAppName
                )
            else {
                await MainActor.run {
                    DockActionFeedback.fail(actionId, label: "Couldn't open \(targetAppName)")
                    l2.currentTask = nil
                }
                return
            }

            try? await Task.sleep(nanoseconds: 180_000_000)
            let opened = await openFindInterface(
                in: app.processIdentifier,
                bundleIdentifier: targetBundleId,
                appName: targetAppName
            )

            await MainActor.run {
                if opened {
                    DockActionFeedback.complete(actionId)
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                    scheduleDockPillRebuild(query: "", delayNanoseconds: 0)
                } else {
                    DockActionFeedback.fail(actionId, label: "Find unavailable")
                }
                l2.currentTask = nil
            }
        }
    }

    func executeAppFindIntent(_ intent: AppFindIntent) {
        let searchQuery = intent.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !searchQuery.isEmpty else { return }

        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.activeRequestID = nil
        }

        let searchActionId = DockActionFeedback.start(
            "Searching", subject: "\(intent.targetAppName) for \"\(searchQuery)\"",
            icon: "magnifyingglass", tint: .accentColor)

        l2.currentTask = Task {
            guard
                let app = await activateOrLaunchSemanticApp(
                    bundleIdentifier: intent.targetBundleId,
                    appName: intent.targetAppName
                )
            else {
                await MainActor.run {
                    DockActionFeedback.fail(
                        searchActionId, label: "Couldn't open \(intent.targetAppName)")
                    l2.currentTask = nil
                }
                return
            }

            let pid = app.processIdentifier
            try? await Task.sleep(nanoseconds: 180_000_000)
            setFindPasteboardString(searchQuery)
            let profile = appSearchProfile(
                bundleIdentifier: intent.targetBundleId,
                appName: intent.targetAppName,
                commandTitle: intent.commandTitle
            )
            var injected = false
            if profile.tryVisibleSearchFieldFirst {
                injected = await injectSearchQuery(
                    searchQuery,
                    into: pid,
                    pressReturn: profile.pressReturnAfterInject
                )
            }
            if !injected {
                _ = await openFindInterface(
                    in: pid,
                    bundleIdentifier: intent.targetBundleId,
                    appName: intent.targetAppName,
                    commandTitle: intent.commandTitle
                )
                try? await Task.sleep(nanoseconds: 160_000_000)
                injected = await injectSearchQuery(
                    searchQuery,
                    into: pid,
                    pressReturn: profile.pressReturnAfterInject
                )
            }

            await MainActor.run {
                if injected {
                    DockActionFeedback.complete(searchActionId)
                    searchState.query = ""
                    clearFindToken(preserveQuery: false)
                    l2.focusedPillIndex = nil
                    scheduleDockPillRebuild(query: "", delayNanoseconds: 0)
                } else {
                    DockActionFeedback.fail(searchActionId, label: "Search field not found")
                }
                l2.currentTask = nil
            }
        }
    }

    func executeFindToken(_ token: AppFindToken, userMessage: String) {
        let searchQuery = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)

        if let selectedMenu = token.selectedMenu {
            executeFindTokenMenu(
                selectedMenu,
                token: token,
                searchQuery: searchQuery,
                userMessage: userMessage
            )
            return
        }

        if searchQuery.isEmpty {
            openAppFindInterface(
                targetBundleId: token.targetBundleId,
                targetAppName: token.targetAppName,
                userMessage: userMessage
            )
            return
        }

        executeAppFindIntent(
            AppFindIntent(
                query: searchQuery,
                targetBundleId: token.targetBundleId,
                targetAppName: token.targetAppName,
                userMessage: userMessage,
                commandTitle: token.title,
                preferMailboxSearch: token.targetBundleId == "com.apple.mail"
            )
        )
    }

    func executeFindTokenMenu(
        _ menuItem: AXMenuItem,
        token: AppFindToken,
        searchQuery: String,
        userMessage: String
    ) {
        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.activeRequestID = nil
        }

        let actionId = DockActionFeedback.start(
            searchQuery.isEmpty ? "Opening Find" : "Searching",
            subject: searchQuery.isEmpty
                ? token.targetAppName
                : "\(token.targetAppName) for \"\(searchQuery)\"",
            icon: "magnifyingglass",
            tint: .accentColor
        )

        l2.currentTask = Task {
            guard
                let app = await activateOrLaunchSemanticApp(
                    bundleIdentifier: token.targetBundleId,
                    appName: token.targetAppName
                )
            else {
                await MainActor.run {
                    DockActionFeedback.fail(actionId, label: "Couldn't open \(token.targetAppName)")
                    l2.currentTask = nil
                }
                return
            }

            let pid = app.processIdentifier
            let path = menuItem.path
            let clicked = AXMenuReader.shared.clickMenuItem(path: path, in: pid)
            if !clicked, let sc = menuItem.shortcutChar, !sc.isEmpty {
                _ = AXMenuReader.shared.executeShortcut(
                    char: sc,
                    modifiers: menuItem.shortcutModifiers,
                    in: pid
                )
            }

            var injected = searchQuery.isEmpty
            if !searchQuery.isEmpty {
                setFindPasteboardString(searchQuery)
                try? await Task.sleep(nanoseconds: 160_000_000)
                injected = await injectSearchQuery(searchQuery, into: pid)
            }

            await MainActor.run {
                if injected {
                    DockActionFeedback.complete(actionId)
                    clearFindToken(preserveQuery: false)
                    l2.focusedPillIndex = nil
                    scheduleDockPillRebuild(query: "", delayNanoseconds: 0)
                } else {
                    DockActionFeedback.fail(actionId, label: "Search field not found")
                }
                l2.currentTask = nil
            }
        }
    }

    func makeMessagesSemanticIntentPill(
        fullQuery: String,
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String
    ) -> DockPill? {
        guard let intent = messagesScopedSemanticIntent(for: rawScopedQuery),
            let recipientName = intent.recipientName?.trimmingCharacters(
                in: .whitespacesAndNewlines),
            let messageBody = intent.messageBody?.trimmingCharacters(in: .whitespacesAndNewlines),
            !recipientName.isEmpty,
            !messageBody.isEmpty
        else { return nil }

        let rawUserQuery = rawDockQuery(matching: fullQuery)
        let bodyLabel = messageIntentDisplayText(messageBody, limit: 36)
        let recipientLabel = messageIntentDisplayText(recipientName, limit: 26)

        var pill = DockPill(
            id: "messages-intent-send-\(normalizedDockPillText(rawScopedQuery))",
            name: "Send \"\(bodyLabel)\" to \(recipientLabel)",
            icon: "message.fill",
            accentColorName: "green",
            badge: "Conversation",
            execute: {
                self.executeCrossAppIntent(
                    intent,
                    userMessage: rawUserQuery,
                    unresolvedMessage:
                        "❌ Couldn't resolve that Messages recipient. Try: message send \"hi\" to [name]"
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier =
            "messages-intent:\(normalizedDockPillText(recipientName)):\(normalizedDockPillText(messageBody))"
        pill.searchTerms = [
            scopedAppName, "messages", "message", "send", recipientName, messageBody,
            "conversation",
        ]
        return pill
    }

    func makeMailSemanticSearchPill(
        fullQuery: String,
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String
    ) -> DockPill? {
        guard let intent = mailSemanticSearchIntent(from: rawScopedQuery) else { return nil }

        let rawUserQuery = rawDockQuery(matching: fullQuery)
        let queryLabel = messageIntentDisplayText(intent.displayLabel, limit: 42)

        var pill = DockPill(
            id: "mail-search-\(normalizedDockPillText(rawScopedQuery))",
            name: "Search Mail for \"\(queryLabel)\"",
            icon: "magnifyingglass",
            accentColorName: "blue",
            badge: "Mailbox",
            execute: {
                self.executeMailMailboxSearch(
                    intent: intent,
                    userMessage: rawUserQuery
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier =
            "mail-search:\(intent.tokenKind):\(normalizedDockPillText(intent.query))"
        pill.searchTerms = [scopedAppName, "mail", "mailbox", "search", "find", intent.query]
        return pill
    }

    func makeAppWindowSemanticPill(
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        isGlobalScope: Bool
    ) -> DockPill? {
        guard !isGlobalScope,
            !scopedBundleId.isEmpty,
            !scopedBundleId.hasPrefix("cli://"),
            !scopedBundleId.hasPrefix("scope://"),
            !scopedAppName.isEmpty
        else { return nil }

        let normalized =
            rawScopedQuery
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard !normalized.isEmpty else { return nil }

        let minimizeTerms = [
            "minimize", "minimise", "miniaturize", "miniaturise",
            "minimize window", "minimise window", "hide window",
        ]
        guard minimizeTerms.contains(where: normalized.contains) else { return nil }

        var pill = DockPill(
            id: "window-minimize-\(scopedBundleId)",
            name: "Minimize \(scopedAppName)",
            icon: "minus.square",
            accentColorName: "blue",
            badge: "Window",
            execute: {
                self.minimizeAppWindowsWithoutActivation(
                    bundleIdentifier: scopedBundleId,
                    appName: scopedAppName
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier = "window-minimize:\(scopedBundleId)"
        pill.searchTerms = [
            scopedAppName, "minimize", "minimise", "miniaturize", "window", "hide window",
        ]
        return pill
    }

    func makeChatGPTNewChatPill(
        scopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        appPath: String?
    ) -> DockPill? {
        guard scopedBundleId == "com.openai.chat" else { return nil }
        let normalized = normalizedDockPillText(scopedQuery)
        guard !normalized.isEmpty else { return nil }
        let isNewChat =
            normalized == "new chat"
            || normalized == "new conversation"
            || normalized == "start chat"
            || normalized == "start new chat"
            || normalized.contains("new chat")
        guard isNewChat else { return nil }

        var pill = DockPill(
            id: "chatgpt-new-chat",
            name: "New Chat",
            icon: "plus.message",
            accentColorName: "green",
            badge: scopedAppName.isEmpty ? "ChatGPT" : scopedAppName,
            execute: {
                self.executeChatGPTNewChat(appPath: appPath)
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName.isEmpty ? "ChatGPT" : scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier = "chatgpt:new-chat"
        pill.searchTerms = ["chatgpt", "chat gpt", "new chat", "new conversation", "start chat"]
        return pill
    }

    func executeChatGPTNewChat(appPath: String?) {
        let menuPath = ["File", "New Chat"]
        if let app = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == "com.openai.chat" && !$0.isTerminated
        }) {
            executeDockMenuAction(
                sourcePID: app.processIdentifier,
                path: menuPath,
                shortcutChar: nil,
                shortcutModifiers: 0
            )
            return
        }

        guard
            launchApplication(
                bundleIdentifier: "com.openai.chat",
                appName: "ChatGPT",
                path: appPath
            )
        else { return }

        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 900_000_000)
            guard
                let app = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == "com.openai.chat" && !$0.isTerminated
                })
            else { return }
            executeDockMenuAction(
                sourcePID: app.processIdentifier,
                path: menuPath,
                shortcutChar: nil,
                shortcutModifiers: 0
            )
        }
    }

    func minimizeAppWindowsWithoutActivation(
        bundleIdentifier: String,
        appName: String
    ) {
        guard
            let app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
            })
        else {
            AppToast.show(
                "\(appName) is not running", icon: "exclamationmark.triangle", tint: .orange)
            return
        }

        let axApp = AXUIElementCreateApplication(app.processIdentifier)
        var windowsRef: CFTypeRef?
        var minimizedCount = 0

        if AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef)
            == .success,
            let windows = windowsRef as? [AXUIElement]
        {
            for window in windows {
                var currentValue: CFTypeRef?
                if AXUIElementCopyAttributeValue(
                    window, kAXMinimizedAttribute as CFString, &currentValue) == .success,
                    (currentValue as? Bool) == true
                {
                    continue
                }

                if AXUIElementSetAttributeValue(
                    window, kAXMinimizedAttribute as CFString, kCFBooleanTrue) == .success
                {
                    minimizedCount += 1
                    continue
                }

                var minimizeButtonRef: CFTypeRef?
                if AXUIElementCopyAttributeValue(
                    window, kAXMinimizeButtonAttribute as CFString, &minimizeButtonRef) == .success,
                    let minimizeButton = minimizeButtonRef
                {
                    let button = unsafeBitCast(minimizeButton, to: AXUIElement.self)
                    if AXUIElementPerformAction(button, kAXPressAction as CFString) == .success {
                        minimizedCount += 1
                    }
                }
            }
        }

        if minimizedCount > 0 {
            AppToast.show(
                minimizedCount == 1
                    ? "Minimized \(appName)" : "Minimized \(minimizedCount) \(appName) windows",
                icon: "minus.square",
                tint: .blue.opacity(0.9)
            )
        } else {
            AppToast.show(
                "No visible \(appName) window to minimize",
                icon: "minus.square",
                tint: .secondary
            )
        }

        resetDockStateAfterAppAction()
        isSearchFieldFocused = true
    }

    func buildPayloadActionPills(query: String) -> [DockPill] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }

        let selectedPaths = effectiveSelectedFileURLsForConversation().map(\.path)
        let selectedText = (axContext.selectedText ?? "").trimmingCharacters(
            in: .whitespacesAndNewlines)
        let currentURL = (axContext.currentURL ?? "").trimmingCharacters(
            in: .whitespacesAndNewlines)
        let windowTitle = (axContext.windowTitle ?? frontmost.name).trimmingCharacters(
            in: .whitespacesAndNewlines)
        let clipboardText = (NSPasteboard.general.string(forType: .string) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let hasFiles = !selectedPaths.isEmpty
        let selectedURLs = selectedPaths.map { URL(fileURLWithPath: $0) }
        let hasText = !selectedText.isEmpty
        let hasURL = !currentURL.isEmpty
        let textPayload = hasText ? selectedText : clipboardText
        let noteBody = [hasText ? selectedText : nil, hasURL ? currentURL : nil]
            .compactMap { $0 }
            .joined(separator: "\n\n")
        let reminderText = !textPayload.isEmpty ? textPayload : windowTitle
        let downloadsPath = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(
            "Downloads")

        func matches(_ terms: [String]) -> Bool {
            terms.contains { q.contains($0) || $0.contains(q) }
        }

        var pills: [DockPill] = []

        if hasFiles, let transformIntent = transformShareIntent(for: query) {
            let channelLabel: String = {
                switch transformIntent.channelHint {
                case .messages: return "Messages"
                case .mail: return "Mail"
                case .airDrop: return "AirDrop"
                case .picker: return "Share"
                }
            }()
            let recipient = transformIntent.recipientQuery?
                .trimmingCharacters(in: .whitespacesAndNewlines)
            let name = recipient.map { "Summarize + Send to \($0)" } ?? "Summarize + Send"
            var pill = DockPill(
                id: "payload-transform-share-\(normalizedDockPillText(query))",
                name: name,
                icon: transformIntent.channelHint == .mail ? "envelope" : "message",
                accentColorName: transformIntent.channelHint == .mail ? "blue" : "green",
                badge: channelLabel,
                execute: {
                    self.executeTransformShareIntent(transformIntent, userMessage: query)
                }
            )
            pill.rankingKind = "transformShare"
            pill.searchTerms = [
                "summarize", "summary", "explain", "send", "message", "mail", "file",
            ]
            pill.trackingIdentifier = "transform-share:\(normalizedDockPillText(query))"
            pills.append(pill)
        }

        if hasText || hasURL, matches(["notes", "note", "quick note", "save note", "capture"]) {
            pills.append(
                DockPill(
                    id: "payload-notes",
                    name: "Save to Notes",
                    icon: "note.text",
                    accentColorName: "yellow",
                    badge: hasText ? "Selection" : "URL",
                    execute: {
                        guard self.settings.allowAutomation else {
                            self.l2.chatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content: "Automation permission is disabled for Notes actions.",
                                    isError: true))
                            return
                        }
                        let title = windowTitle.isEmpty ? "Context Capture" : windowTitle
                        let ok: Bool
                        if !noteBody.isEmpty {
                            ok = AppleAppsAPI.shared.createNote(
                                title: title, body: noteBody, folder: "Context Dock")
                        } else {
                            ok = false
                        }
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok ? "Saved to Notes." : "Failed to save to Notes.",
                                isError: !ok
                            ))
                    }
                ))
        }

        if hasText || hasURL || hasFiles,
            matches(["mail", "email", "compose", "new mail", "send email", "share via mail"])
        {
            pills.append(
                DockPill(
                    id: "payload-mail",
                    name: hasFiles ? "Share via Mail" : "Compose Mail",
                    icon: "envelope",
                    accentColorName: "blue",
                    badge: hasFiles ? "Files" : "Selection",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: hasFiles ? "share via mail" : "compose mail",
                                channelHint: .mail,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        if !textPayload.isEmpty || hasURL, matches(["reminder", "remind", "todo", "task"]) {
            pills.append(
                DockPill(
                    id: "payload-reminder",
                    name: "Create Reminder",
                    icon: "checklist",
                    accentColorName: "orange",
                    badge: "Selection",
                    execute: {
                        guard self.settings.allowAutomation else {
                            self.l2.chatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content:
                                        "Automation permission is disabled for Reminders actions.",
                                    isError: true))
                            return
                        }
                        let ok = AppleAppsAPI.shared.createReminder(title: reminderText)
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok ? "Reminder created." : "Failed to create reminder.",
                                isError: !ok
                            ))
                    }
                ))
        }

        if hasText || hasURL || hasFiles,
            matches(["message", "messages", "imessage", "new message", "send message"])
        {
            pills.append(
                DockPill(
                    id: "payload-messages",
                    name: "Send via Messages",
                    icon: "message",
                    accentColorName: "green",
                    badge: hasFiles ? "Files" : "Share",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: hasFiles ? "send via messages" : "send this via messages",
                                channelHint: .messages,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        if hasFiles, matches(["downloads", "download", "move to downloads", "send to downloads"]) {
            pills.append(
                DockPill(
                    id: "payload-downloads-move",
                    name: "Move to Downloads",
                    icon: "arrow.down.circle",
                    accentColorName: "teal",
                    badge: "\(selectedPaths.count)",
                    execute: {
                        let fm = FileManager.default
                        try? fm.createDirectory(
                            at: downloadsPath, withIntermediateDirectories: true)
                        var moved = 0
                        for source in selectedURLs {
                            let destination = downloadsPath.appendingPathComponent(
                                source.lastPathComponent)
                            let uniqueDestination = self.uniqueMoveDestination(for: destination)
                            do {
                                try fm.moveItem(at: source, to: uniqueDestination)
                                moved += 1
                            } catch {
                                continue
                            }
                        }
                        let ok = moved > 0
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok
                                    ? "Moved \(moved) item\(moved == 1 ? "" : "s") to Downloads."
                                    : "Failed to move items to Downloads.",
                                isError: !ok
                            ))
                    }
                ))
            pills.append(
                DockPill(
                    id: "payload-downloads-open",
                    name: "Open Downloads",
                    icon: "folder",
                    accentColorName: "gray",
                    badge: "Downloads",
                    execute: {
                        NSWorkspace.shared.open(downloadsPath)
                    }
                ))
        }

        if hasFiles, matches(["share", "send", "export"]) {
            pills.append(
                DockPill(
                    id: "payload-share-files",
                    name: "Share Selected Files",
                    icon: "square.and.arrow.up",
                    accentColorName: "blue",
                    badge: "\(selectedPaths.count)",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: "share selected files",
                                channelHint: .picker,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        return pills
    }

    func uniqueMoveDestination(for desiredURL: URL) -> URL {
        let fm = FileManager.default
        guard fm.fileExists(atPath: desiredURL.path) else { return desiredURL }

        let directory = desiredURL.deletingLastPathComponent()
        let baseName = desiredURL.deletingPathExtension().lastPathComponent
        let ext = desiredURL.pathExtension

        for index in 2...500 {
            let candidateName = ext.isEmpty ? "\(baseName) \(index)" : "\(baseName) \(index).\(ext)"
            let candidate = directory.appendingPathComponent(candidateName)
            if !fm.fileExists(atPath: candidate.path) {
                return candidate
            }
        }

        return desiredURL
    }

    func detectCrossAppQuery(_ q: String) -> (NSRunningApplication, String)? {
        guard !q.isEmpty, let delegate = AppDelegate.shared else { return nil }
        let recentApps = delegate.recentApps.filter { !$0.isTerminated }
        let frontPID = delegate.previousFrontmostApp?.processIdentifier ?? 0
        for app in recentApps {
            guard app.processIdentifier != frontPID else { continue }
            let name = (app.localizedName ?? "").lowercased()
            guard !name.isEmpty else { continue }
            // Require a space after the app name so single-word queries like "centre"
            // never accidentally match a recent app whose name starts with "cent" etc.
            if q.hasPrefix(name + " ") {
                let remainder = String(q.dropFirst(name.count + 1))
                return (app, remainder)
            }
            // Also match shortened names: "safari close tab" matches "Safari Technology Preview"
            let firstWord = name.components(separatedBy: " ").first ?? name
            if firstWord.count >= 3, q.hasPrefix(firstWord + " ") {
                let remainder = String(q.dropFirst(firstWord.count + 1))
                return (app, remainder)
            }
        }
        return nil
    }

    func installedAppMenuTarget(
        for query: String,
        runningOnly: Bool = false,
        includeAppsWithoutMenuSnapshot: Bool = false,
        allowPrefixAlias: Bool = false,
        excludingBundleIds: Set<String> = []
    ) -> InstalledAppMenuTarget? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard q.count >= (runningOnly ? 3 : 2) else { return nil }

        let runningBundleIds: Set<String>? =
            runningOnly
            ? Set(NSWorkspace.shared.runningApplications.compactMap { $0.bundleIdentifier })
            : nil

        var best: (target: InstalledAppMenuTarget, score: Int)?

        func consider(
            appName: String,
            bundleId: String,
            appPath: String,
            baseScore: Int
        ) {
            guard !excludingBundleIds.contains(bundleId) else { return }
            let normalizedName = appName.lowercased()
                .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !normalizedName.isEmpty else { return }

            let aliases = Set(dockPillAppAliases(appName: appName, bundleId: bundleId))

            for alias in aliases where alias.count >= 2 {
                guard
                    let extraction = installedAppActionExtraction(
                        query: q,
                        alias: alias,
                        allowPrefixAlias: runningOnly || allowPrefixAlias
                    )
                else {
                    continue
                }
                let actionQuery = extraction.actionQuery
                let exactFullNameBonus =
                    alias == normalizedName && !extraction.usedPrefixAlias ? 1_200 : 0
                let exactAliasBonus = extraction.usedPrefixAlias ? 0 : 520
                let positionBonus =
                    extraction.aliasAtStart ? 120 : max(20, 95 - (extraction.aliasStartIndex * 18))
                let score =
                    baseScore
                    + positionBonus
                    + (extraction.usedPrefixAlias ? -220 : 0)
                    + exactAliasBonus
                    + (extraction.aliasTokenCount * 80)
                    + exactFullNameBonus
                    + alias.count
                    + min(actionQuery.count, 24)
                    + (actionQuery.isEmpty ? 25 : 0)
                    + (bundleId == "com.apple.Photos" && alias == "photos" ? 600 : 0)

                let target = InstalledAppMenuTarget(
                    appName: appName,
                    bundleId: bundleId,
                    appPath: appPath,
                    actionQuery: actionQuery,
                    matchedAlias: alias,
                    aliasStartIndex: extraction.aliasStartIndex
                )
                if best == nil || score > best!.score {
                    best = (target, score)
                }
            }
        }

        if runningOnly {
            let runningApps =
                runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
            for app in runningApps {
                guard
                    let appName = app.localizedName?.trimmingCharacters(
                        in: .whitespacesAndNewlines),
                    !appName.isEmpty,
                    let bundleId = app.bundleIdentifier,
                    !bundleId.isEmpty
                else { continue }
                let appPath =
                    app.bundleURL?.path
                    ?? installedApplicationResult(bundleIdentifier: bundleId)?.subtitle
                    ?? ""
                consider(
                    appName: appName,
                    bundleId: bundleId,
                    appPath: appPath,
                    baseScore: 128
                )
            }

            return best?.target
        }

        for result in allApplications where result.type == .application {
            let appName = result.title.trimmingCharacters(in: .whitespacesAndNewlines)
            let appPath = result.subtitle
            guard !appName.isEmpty, !appPath.isEmpty else { continue }

            let bundleId = Bundle(url: URL(fileURLWithPath: appPath))?.bundleIdentifier ?? ""
            guard !bundleId.isEmpty else { continue }
            if includeAppsWithoutMenuSnapshot,
                implicitContextDockAppScopeBlockedBundleIds.contains(bundleId)
            {
                continue
            }
            // In context dock mode: skip apps that aren't currently running
            if let runningBundleIds, !runningBundleIds.contains(bundleId) { continue }
            let hasMenuSnapshot = GlobalContextEngine.shared.hasMenuSnapshot(
                bundleIdentifier: bundleId
            )
            let appKey = settings.appKey(forBundleID: bundleId, appName: appName)
            let hasShortcutSurface =
                appKey.map {
                    !appScopeShortcuts(for: $0, placements: [.quickActions, .contextDock, .both])
                        .isEmpty
                } ?? false
            guard
                includeAppsWithoutMenuSnapshot || runningOnly || hasMenuSnapshot
                    || hasShortcutSurface || bundleId == "com.openai.chat"
            else {
                continue
            }

            consider(appName: appName, bundleId: bundleId, appPath: appPath, baseScore: 112)
        }

        // System app scopes must work even before the app index/menu snapshot cache is warm.
        // Otherwise natural queries like "new notes" stay in global mode and only Apple-menu
        // matches are visible.
        let builtInAppTargets: [(name: String, bundleId: String, path: String)] = [
            ("Safari", "com.apple.Safari", "/Applications/Safari.app"),
            ("Notes", "com.apple.Notes", "/System/Applications/Notes.app"),
            ("Messages", "com.apple.MobileSMS", "/System/Applications/Messages.app"),
            ("Mail", "com.apple.mail", "/System/Applications/Mail.app"),
            ("Calendar", "com.apple.iCal", "/System/Applications/Calendar.app"),
            ("Reminders", "com.apple.reminders", "/System/Applications/Reminders.app"),
            ("Photos", "com.apple.Photos", "/System/Applications/Photos.app"),
            ("Contacts", "com.apple.AddressBook", "/System/Applications/Contacts.app"),
            (
                "System Settings", "com.apple.systempreferences",
                "/System/Applications/System Settings.app"
            ),
        ]
        for target in builtInAppTargets {
            if let runningBundleIds, !runningBundleIds.contains(target.bundleId) { continue }
            consider(
                appName: target.name,
                bundleId: target.bundleId,
                appPath: target.path,
                baseScore: 108
            )
        }

        return best?.target
    }

    func cachedScopedAppMenuPills(
        bundleIdentifier: String,
        appName: String,
        appPath: String?,
        query: String = "",
        maxResults: Int = 24,
        allowLiveRefresh: Bool = true
    ) -> [DockPill] {
        guard !bundleIdentifier.isEmpty else { return [] }
        let trimmedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let effectiveMaxResults = trimmedQuery.isEmpty ? maxResults : max(maxResults, 2_000)
        let runningApp = NSWorkspace.shared.runningApplications.first {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        }
        let liveMatches: [AXMenuItem] = {
            guard allowLiveRefresh, let runningApp else { return [] }
            let pid = runningApp.processIdentifier
            var live = AXMenuReader.shared.peekCachedAllMenuItems(for: pid)
            guard !live.isEmpty else { return [] }
            for index in live.indices {
                live[index].sourcePID = pid
                live[index].sourceAppName = runningApp.localizedName ?? appName
            }
            AppMenuCapabilityCache.shared.store(items: live, for: runningApp)
            return live
        }()
        let persistentMatches = GlobalContextEngine.shared.cachedMenuItems(
            bundleIdentifier: bundleIdentifier,
            appName: runningApp?.localizedName ?? appName,
            processIdentifier: runningApp?.processIdentifier ?? 0,
            query: "",
            maxResults: effectiveMaxResults
        )
        let items = {
            var seen = Set<String>()
            var merged: [AXMenuItem] = []
            for item in liveMatches + persistentMatches {
                let key = item.path.joined(separator: " > ").lowercased()
                guard !key.isEmpty, seen.insert(key).inserted else { continue }
                merged.append(item)
            }
            return merged
        }()
        let filteredItems: [AXMenuItem] = {
            let appItems = items.filter {
                !isAppleMenuItem($0) && shouldExposeCachedMenuItem($0)
            }
            guard !trimmedQuery.isEmpty else { return appItems }
            return orderedScopedMenuItemsLikeContextDock(
                appItems.filter {
                    cachedScopedMenuItemMatchesQuery($0, query: trimmedQuery)
                },
                filterQuery: trimmedQuery,
                limit: maxResults
            )
        }()

        return filteredItems.map { item in
            let path = item.path
            let shortcutChar = item.shortcutChar
            let shortcutModifiers = item.shortcutModifiers
            let menuAppPath = appPath
            return makeMenuDockPill(
                id: "cached-all-menu-\(bundleIdentifier)-\(path.joined(separator: ">"))",
                item: item,
                sourceBundleId: bundleIdentifier,
                sourceAppName: appName,
                badge: item.shortcutDisplay,
                trackingIdentifier:
                    "cached-menu:\(bundleIdentifier):\(path.joined(separator: " > ").lowercased())",
                searchTerms: item.path + [appName],
                executeLeaf: {
                    executeCachedMenuAction(
                        bundleIdentifier: bundleIdentifier,
                        appName: appName,
                        appPath: menuAppPath,
                        path: path,
                        shortcutChar: shortcutChar,
                        shortcutModifiers: shortcutModifiers
                    )
                }
            )
        }
    }

    func cachedScopedMenuItemMatchesQuery(_ item: AXMenuItem, query: String) -> Bool {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return true }

        let title = normalizedDockPillText(item.title)
        let pathParts = item.path.map(normalizedDockPillText).filter { !$0.isEmpty }
        let menuContext = pathParts.dropLast().last ?? pathParts.first ?? ""
        let corpora = ([title, menuContext] + pathParts).filter { !$0.isEmpty }

        if corpora.contains(normalizedQuery) { return true }
        if title.hasPrefix(normalizedQuery) || menuContext.hasPrefix(normalizedQuery) {
            return true
        }
        if title.contains(normalizedQuery) || menuContext.contains(normalizedQuery) { return true }
        if pathParts.contains(where: {
            $0.hasPrefix(normalizedQuery) || $0.contains(normalizedQuery)
        }) {
            return true
        }

        let queryTokens = Set(dockPillTokens(normalizedQuery))
        guard !queryTokens.isEmpty else { return false }
        let titleTokens = Set(dockPillTokens(title))
        let pathTokens = Set(corpora.flatMap(dockPillTokens))
        let orderedQueryTokens = dockPillTokens(normalizedQuery)
        if orderedQueryTokens.allSatisfy({ qToken in
            qToken.count == 1
                ? titleTokens.contains { $0.hasPrefix(qToken) }
                : pathTokens.contains {
                    $0 == qToken || $0.hasPrefix(qToken) || $0.contains(qToken)
                }
        }) {
            return true
        }
        if !queryTokens.intersection(titleTokens).isEmpty { return true }
        if !queryTokens.intersection(pathTokens).isEmpty { return true }

        for qt in queryTokens where qt.count >= 4 {
            for ct in pathTokens where ct.count >= 4 {
                if pillEditDistance(qt, ct) <= 2 { return true }
            }
        }
        return false
    }

    func orderedScopedMenuItemsLikeContextDock(
        _ items: [AXMenuItem],
        filterQuery: String,
        limit: Int
    ) -> [AXMenuItem] {
        let normalizedQuery = normalizedDockPillText(filterQuery)
        guard !normalizedQuery.isEmpty else { return Array(items.prefix(limit)) }

        func score(_ item: AXMenuItem) -> Int {
            let title = normalizedDockPillText(item.title)
            let pathParts = item.path.map(normalizedDockPillText).filter { !$0.isEmpty }
            let menuContext = pathParts.dropLast().last ?? pathParts.first ?? ""
            let path = pathParts.joined(separator: " ")
            var score = Int(
                rankedTextMatchScore(
                    query: normalizedQuery,
                    primary: title,
                    contexts: [menuContext, path] + pathParts
                ) ?? 0)

            let queryTokens = Set(dockPillTokens(normalizedQuery))
            let orderedQueryTokens = dockPillTokens(normalizedQuery)
            let titleTokens = Set(dockPillTokens(title))
            let contextTokens = Set(dockPillTokens(menuContext))
            let pathTokens = Set(pathParts.flatMap(dockPillTokens))
            score += queryTokens.intersection(titleTokens).count * 120
            score += queryTokens.intersection(contextTokens).count * 96
            score += queryTokens.intersection(pathTokens).count * 54
            if orderedQueryTokens.allSatisfy({ qToken in
                qToken.count == 1
                    ? titleTokens.contains { $0.hasPrefix(qToken) }
                    : pathTokens.contains {
                        $0 == qToken || $0.hasPrefix(qToken) || $0.contains(qToken)
                    }
            }) {
                score += 260 + orderedQueryTokens.count * 40
            }

            if !item.isEnabled { score -= 60 }
            if menuContext == "services" || menuContext == "open with" {
                score -= 180
            }
            score -= min(item.path.count, 12)
            return score
        }

        return Array(
            items.sorted {
                let lhsScore = score($0)
                let rhsScore = score($1)
                if lhsScore != rhsScore { return lhsScore > rhsScore }
                return $0.path.count < $1.path.count
            }
            .prefix(limit)
        )
    }

    func scopedSpecialAppPills(
        bundleIdentifier: String,
        appName: String,
        query: String
    ) -> [DockPill] {
        switch bundleIdentifier {
        case "com.apple.systempreferences":
            return buildSystemSettingsPills(
                query: query,
                scopedBundleId: bundleIdentifier,
                scopedAppName: appName
            )
        default:
            return []
        }
    }

    // Warm menu cache for a specific app if it's running but not yet snapshotted.
    // After scraping, updates crossAppMenuItems if that app is the current scope target,
    // then triggers a pill rebuild so results appear without another keystroke.
    func warmMenuCacheIfNeeded(bundleId: String, appName: String) {
        guard !bundleId.isEmpty else { return }
        let staleThreshold: TimeInterval = 7 * 24 * 3600
        let age = AppMenuCapabilityCache.shared.snapshotAge(bundleIdentifier: bundleId) ?? .infinity
        guard age > staleThreshold else { return }  // fresh snapshot exists — skip
        guard warmingMenuBundleIds.insert(bundleId).inserted else { return }
        guard
            let app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == bundleId && !$0.isTerminated
            })
        else {
            warmingMenuBundleIds.remove(bundleId)
            return
        }
        Task.detached(priority: .background) {
            // Defer 2 s so the user finishes typing before we start an AX scan.
            // AX API is globally serialized — an immediate scan blocks main-thread AX reads → input freeze.
            try? await Task.sleep(nanoseconds: 2_000_000_000)
            guard !Task.isCancelled else {
                await MainActor.run { self.warmingMenuBundleIds.remove(bundleId) }
                return
            }
            // Skip if another scan already running (avoid concurrent AX contention).
            guard !AXMenuReader.shared.isScanningMenus else {
                await MainActor.run { self.warmingMenuBundleIds.remove(bundleId) }
                return
            }
            let pid = app.processIdentifier
            await MenuWarmCacheService.shared.warm(app: app, force: false)
            var items = AXMenuReader.shared.peekCachedAllMenuItems(for: pid)
            if items.isEmpty {
                items = ContextDockEngine.shared.cachedMenuItems(for: app, maxResults: 120)
            }
            for i in items.indices {
                items[i].sourcePID = pid
                items[i].sourceAppName = app.localizedName ?? appName
            }
            await MainActor.run {
                if self.l2.targetApp?.bundleId == bundleId {
                    self.crossAppMenuItems = items
                }
                self.warmingMenuBundleIds.remove(bundleId)
                scheduleDockPillRebuild(
                    query: searchState.query, delayNanoseconds: 0, refreshContext: false)
                refreshVisibleGlobalContextAfterMenuCacheUpdate(bundleIdentifier: bundleId)
            }
        }
    }

    func installedAppActionExtraction(
        query q: String,
        alias: String,
        allowPrefixAlias: Bool = false
    )
        -> (
            actionQuery: String, aliasAtStart: Bool, aliasTokenCount: Int, usedPrefixAlias: Bool,
            aliasStartIndex: Int
        )?
    {
        let aliasTokens = alias.split(separator: " ").map(String.init)
        let queryTokens = q.split(separator: " ", omittingEmptySubsequences: true).map(String.init)
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return nil }

        let normalizedQueryTokens = queryTokens.map(normalizedDockPillText)
        let exactRange = firstScopedAliasRange(aliasTokens, in: normalizedQueryTokens)
        let prefixRange =
            allowPrefixAlias
            ? firstScopedAliasRange(
                aliasTokens, in: normalizedQueryTokens, allowPrefixLastToken: true)
            : nil
        guard let range = exactRange ?? prefixRange else { return nil }

        var remaining = queryTokens
        remaining.removeSubrange(range)
        let actionQuery = trimScopedAppFillerWords(remaining)
        return (
            actionQuery,
            range.lowerBound == 0,
            aliasTokens.count,
            exactRange == nil,
            range.lowerBound
        )
    }

    func resolveDockScope(for query: String) -> DockScopeResolution {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if shouldUsePureGlobalAppSearch,
            isGlobalContextActive,
            !hasActiveDockContextSelection,
            l2.targetApp == nil,
            let inlineScope = globalInlineAppScope
        {
            return DockScopeResolution(
                scopedBundleId: inlineScope.bundleId,
                scopedAppName: inlineScope.appName,
                scopedSearchQuery: q,
                isExplicitAppScope: true,
                isGlobalScope: false
            )
        }

        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []
        let explicitAppTarget: L2ExplicitAppTarget? =
            (!isGlobalContextActive || q.isEmpty)
            ? nil
            : L2AppActionRouter.shared.appScopeTarget(for: q).flatMap {
                target -> L2ExplicitAppTarget? in
                if installedScopeMode,
                    implicitContextDockAppScopeBlockedBundleIds.contains(target.bundleId)
                {
                    return nil
                }
                return (!runningOnly || runningBundleIds.contains(target.bundleId)) ? target : nil
            }
        let installedMenuTarget =
            (isGlobalContextActive && explicitAppTarget == nil && l2.targetApp == nil)
            ? installedAppMenuTarget(
                for: q,
                runningOnly: false,
                // Use permissive matching so natural app-scope queries like
                // "safari new tab" route into Safari menu search.
                includeAppsWithoutMenuSnapshot: true,
                allowPrefixAlias: true
            )
            : nil
        let isExplicitAppScope =
            l2.targetApp != nil || explicitAppTarget != nil || installedMenuTarget != nil
        let isGlobalScope = isGlobalContextActive && !isExplicitAppScope

        if isGlobalScope {
            return DockScopeResolution(
                scopedBundleId: "",
                scopedAppName: "Global Context",
                scopedSearchQuery: q,
                isExplicitAppScope: false,
                isGlobalScope: true
            )
        }

        let scopedBundleId =
            l2.targetApp?.bundleId
            ?? explicitAppTarget?.bundleId
            ?? installedMenuTarget?.bundleId
            ?? (frontmost.bundleID.isEmpty ? axContext.bundleId : frontmost.bundleID)
        let scopedAppName =
            l2.targetApp?.name
            ?? explicitAppTarget?.appName
            ?? installedMenuTarget?.appName
            ?? contextTargetApp()?.localizedName
            ?? axContext.appName
        let scopedSearchQuery: String = {
            if let actionQuery = explicitAppTarget?.actionQuery ?? installedMenuTarget?.actionQuery
            {
                return actionQuery
            }
            // In explicit app scope (l2.targetApp set), strip trailing "in [appname]" or
            // "[appname]" from the query so "new tab in safari" → filterQ "new tab".
            if let pinnedTarget = l2.targetApp {
                let appLower = pinnedTarget.name.lowercased()
                for suffix in [" in \(appLower)", " \(appLower)"] {
                    if q.hasSuffix(suffix) {
                        return String(q.dropLast(suffix.count))
                            .trimmingCharacters(in: .whitespaces)
                    }
                }
            }
            return q
        }()

        return DockScopeResolution(
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            scopedSearchQuery: scopedSearchQuery,
            isExplicitAppScope: isExplicitAppScope,
            isGlobalScope: false
        )
    }

    func isPureScopedAppSelection(for query: String) -> Bool {
        let scope = resolveDockScope(for: query)
        return scope.isExplicitAppScope
            && scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    var dockScopeDisplayName: String {
        let scope = resolveDockScope(for: searchState.query)
        if scope.isGlobalScope {
            return "Global Context"
        }
        if scope.isExplicitAppScope {
            let scoped = scope.scopedAppName.trimmingCharacters(in: .whitespacesAndNewlines)
            if !scoped.isEmpty {
                return scoped
            }
        }
        return frontmost.name
    }

    var dockHeaderDisplayName: String {
        let label = dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines)
        return label.isEmpty ? "Context" : label
    }

    var dockScopeGhostPrompt: String {
        let label = dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines)
        let scopeName = label.isEmpty ? "Context" : label
        let bundleId = resolveDockScope(for: searchState.query).scopedBundleId
        let lowerName = scopeName.lowercased()

        let hints: String
        if bundleId == "com.apple.finder" || lowerName == "finder" {
            hints =
                attachedFinderFolderSearchPath.isEmpty
                ? "launch apps and home folders, menu cmds"
                : "search this folder, open files, menu cmds"
        } else if AXWebReader.shared.isBrowser(bundleId: bundleId) {
            hints = "tabs, page cmds, menu cmds"
        } else if bundleId == "com.microsoft.VSCode" || lowerName.contains("code") {
            hints = "run tasks, commands, menu cmds"
        } else if bundleId == "com.apple.mail" || lowerName.contains("mail") {
            hints = "mailboxes, compose, search, menu cmds"
        } else if bundleId == "com.apple.MobileSMS" || lowerName.contains("message") {
            hints = "send, search chats, menu cmds"
        } else if bundleId.hasPrefix("cli://") {
            hints = "run commands, inspect help"
        } else {
            let scopedAppKey =
                settings.appKey(forBundleID: bundleId, appName: scopeName)
                ?? settings.autoDetectedAppKey
                ?? ""
            let hasShortcuts =
                !settings.contextDockShortcuts(for: scopedAppKey).isEmpty
                || !settings.shortcuts(for: scopedAppKey).isEmpty
            let hasAdapters = !bundleId.isEmpty && !adapterManager.actions(for: bundleId).isEmpty
            var parts = [String]()
            if hasShortcuts || hasAdapters { parts.append("app actions") }
            parts.append("menu cmds")
            hints = parts.joined(separator: ", ")
        }

        return "\(scopeName) — \(hints)"
    }

    func finderDisplayPath(_ path: String) -> String {
        path.replacingOccurrences(of: NSHomeDirectory(), with: "~")
    }

    func scopedDockWorkspaceKey(bundleIdentifier: String, appName: String) -> String {
        if let mapped = settings.appKey(forBundleID: bundleIdentifier, appName: appName),
            !mapped.isEmpty
        {
            return mapped
        }
        let normalized =
            appName
            .lowercased()
            .replacingOccurrences(of: " ", with: "_")
            .components(
                separatedBy: CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "_"))
                    .inverted
            )
            .joined()
        return normalized.isEmpty ? bundleIdentifier : normalized
    }

    var currentL2DockSessionKey: String? {
        guard showContextInDock else { return nil }
        let scope = resolveDockScope(for: searchState.query)
        if scope.isGlobalScope {
            return "dock_global"
        }
        let scopedBundleId = scope.scopedBundleId.trimmingCharacters(in: .whitespacesAndNewlines)
        if !scopedBundleId.isEmpty {
            return "dock_app_\(scopedBundleId)"
        }
        let appName = scope.scopedAppName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !appName.isEmpty else { return nil }
        return "dock_app_\(scopedDockWorkspaceKey(bundleIdentifier: appName, appName: appName))"
    }

    func syncL2DockSession(force: Bool = false) {
        let newKey = currentL2DockSessionKey
        guard force || newKey != l2.activeDockSessionKey else { return }

        if let previousKey = l2.activeDockSessionKey {
            AppPanelChatStore.shared.save(l2.chatMessages, for: previousKey)
        }

        l2.activeDockSessionKey = newKey
        l2.currentTask?.cancel()
        l2.currentTask = nil
        l2.isLoading = false
        l2.activeRequestID = nil
        l2.handledApprovalIds = []
        l2.contextExtensions = []
        l2.lastAutoRunExtensionID = nil
        l2.chatMessages = newKey.map { AppPanelChatStore.shared.load(for: $0) } ?? []
        updateL2Results([])
    }

    @discardableResult
    func activateInlineDockAppScope(
        bundleIdentifier: String,
        appName: String,
        queryOverride: String? = nil,
        expand: Bool = true,
        preserveGlobalContext: Bool = false
    ) -> Bool {
        guard !bundleIdentifier.isEmpty, !appName.isEmpty else { return false }

        let targetApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        })
        let appURL = applicationURL(bundleIdentifier: bundleIdentifier, appName: appName)
        let appPath = appURL?.path ?? ""
        let icon =
            !appPath.isEmpty
            ? NSWorkspace.shared.icon(forFile: appPath)
            : (resolvedApplicationIcon(bundleIdentifier: bundleIdentifier, appName: appName)
                ?? preparedDockIcon(targetApp?.icon))
        let hasLegacyPanelState =
            searchState.activeSmartQueryKey != nil
            || searchState.contextApp != nil
            || searchState.isInSmartMode
            || !searchState.appPanelAllItems.isEmpty
            || !remPanelChatMessages.isEmpty
        let isNewScope = l2.targetApp?.bundleId != bundleIdentifier
        let shouldSyncSession =
            isNewScope
            || searchState.activeSmartQueryKey != nil
            || searchState.contextApp != nil
        // Reset terminal dismissal when switching to a different app scope
        if isNewScope { l2.terminalDismissed = false }
        let normalizedOverride =
            queryOverride?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased() ?? ""
        let isPureScopeSelection =
            normalizedOverride.isEmpty
            || isPureScopedAppSelection(for: normalizedOverride)

        if let previousKey = searchState.activeSmartQueryKey, hasLegacyPanelState {
            AppPanelChatStore.shared.save(remPanelChatMessages, for: previousKey)
        }

        if hasLegacyPanelState {
            remPanelAITask?.cancel()
            remPanelIsProcessing = false
        }

        withAnimation(.spring(response: 0.22, dampingFraction: 0.84)) {
            if hasLegacyPanelState {
                searchState.contextApp = nil
                searchState.activeSmartQueryKey = nil
                searchState.isInSmartMode = false
                searchState.appPanelAllItems = []
                remPanelChatMessages = []
                clearPinnedResults()
            }
            l2.targetApp = ScopedApp(name: appName, bundleId: bundleIdentifier, icon: icon)
            showContextInDock = true
            showMediaLayer = false
            aiMode.isActive = false
            if !preserveGlobalContext {
                globalContextActivation = nil
            }
            searchState.results = []
            searchState.selectedIndex = nil
            if expand { isSearchBarExpanded = true }
            if expand {
                if livePanelMode != .terminal { livePanelVisible = false }
            }
            if let queryOverride {
                searchState.query = queryOverride
            }
        }

        if let targetApp {
            seedCrossAppMenuCache(for: targetApp)
            loadCrossAppMenu(for: targetApp)
        } else {
            crossAppMenuTargetPID = 0
            crossAppMenuNeedsLiveLoad = false
            // App not running — load from persistent disk cache so command palette still works.
            // Actions route via executeCachedMenuAction (no live PID needed).
            let cached = GlobalContextEngine.shared.cachedMenuItems(
                bundleIdentifier: bundleIdentifier,
                appName: appName,
                processIdentifier: 0,
                query: "",
                maxResults: 120
            )
            crossAppMenuItems = cached
        }

        if shouldSyncSession {
            syncL2DockSession(force: true)
        }

        // Pre-warm the scoped terminal PTY so it's ready when a command needs to run.
        // Do NOT open or show the terminal here — it only appears after the user approves a command.
        let hasAnyCLI =
            !terminalPackageManager.packages(
                forContextBundleId: bundleIdentifier, query: "", maxResults: 1
            ).isEmpty
            || adapterManager.actions(for: bundleIdentifier)
                .contains {
                    $0.type == .cliTool
                        && !($0.cliToolCommand ?? "").trimmingCharacters(
                            in: .whitespacesAndNewlines
                        ).isEmpty
                }
        if hasAnyCLI {
            _ = prepareScopedWorkspaceTerminal()
        }

        l2.focusedPillIndex = nil
        isSearchFieldFocused = true
        // SwiftUI may defer focus assignment during the spring animation above.
        // Two deferred dispatches guarantee the field receives first-responder
        // status after the current run-loop turn and the next render pass.
        DispatchQueue.main.async {
            DispatchQueue.main.async {
                self.isSearchFieldFocused = false
                self.isSearchFieldFocused = true
            }
        }
        return true
    }

    func activateClipboardScope(queryOverride: String = "") {
        if let previousKey = searchState.activeSmartQueryKey {
            AppPanelChatStore.shared.save(remPanelChatMessages, for: previousKey)
        }
        remPanelAITask?.cancel()
        remPanelIsProcessing = false

        withAnimation(.spring(response: 0.22, dampingFraction: 0.84)) {
            searchState.contextApp = nil
            searchState.activeSmartQueryKey = "clipboard"
            l2.targetApp = nil
            showContextInDock = true
            showMediaLayer = false
            aiMode.isActive = false
            globalContextActivation = nil
            searchState.isInSmartMode = false
            searchState.results = []
            searchState.grouped = GroupedResults()
            searchState.selectedIndex = nil
            clearPinnedResults()
            searchState.appPanelAllItems = []
            remPanelChatMessages = []
            searchState.query = queryOverride
            isSearchBarExpanded = true
            focusedClipboardEntryIndex = nil
            livePanelVisible = false
        }
        l2.focusedPillIndex = nil
        isSearchFieldFocused = true
        _ = importCurrentPasteboardToClipboardHistory()
        refreshCompactScopeResults()
        let q = queryOverride.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        scheduleDockPillRebuild(query: q, delayNanoseconds: 0, refreshContext: false)
        updateWindowSize()
    }

