    }

    func scopedWorkspaceIdentity() -> (
        appName: String, bundleId: String, axContext: AXContext
    )? {
        if let target = l2.targetApp, !target.bundleId.isEmpty,
            !target.bundleId.hasPrefix("scope://")
        {
            return (
                target.name,
                target.bundleId,
                scopedWorkspaceAXContext(appName: target.name, bundleId: target.bundleId)
            )
        }

        if let ctx = searchState.contextApp {
            let bundleIdFromPath =
                ctx.appPath.isEmpty ? nil : Bundle(path: ctx.appPath)?.bundleIdentifier
            let bundleIdFromRunningApp = NSWorkspace.shared.runningApplications.first(where: {
                !$0.isTerminated && $0.localizedName == ctx.name
            })?.bundleIdentifier
            let resolvedBundleId = bundleIdFromPath ?? bundleIdFromRunningApp ?? ""
            if !resolvedBundleId.isEmpty {
                return (
                    ctx.name,
                    resolvedBundleId,
                    scopedWorkspaceAXContext(appName: ctx.name, bundleId: resolvedBundleId)
                )
            }
        }

        let meta = smartQueryMeta
        if !meta.appPath.isEmpty, let bundleId = Bundle(path: meta.appPath)?.bundleIdentifier {
            return (
                searchState.contextApp?.name ?? meta.label,
                bundleId,
                scopedWorkspaceAXContext(
                    appName: searchState.contextApp?.name ?? meta.label,
                    bundleId: bundleId
                )
            )
        }

        let fallbackBundleId =
            frontmost.bundleID.isEmpty ? axContext.bundleId : frontmost.bundleID
        let fallbackAppName =
            searchState.contextApp?.name
            ?? (frontmost.name.isEmpty ? axContext.appName : frontmost.name)
        guard !fallbackBundleId.isEmpty, !fallbackAppName.isEmpty else { return nil }
        return (
            fallbackAppName,
            fallbackBundleId,
            scopedWorkspaceAXContext(appName: fallbackAppName, bundleId: fallbackBundleId)
        )
    }

    func scopedWorkspaceAXContext(appName: String, bundleId: String) -> AXContext {
        if axContext.bundleId == bundleId {
            return effectiveAXContextForConversation()
        }

        let runningApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleId && !$0.isTerminated
        })

        return AXContext(
            appName: appName,
            bundleId: bundleId,
            pid: runningApp?.processIdentifier ?? 0,
            selectedText: nil,
            currentURL: nil,
            windowTitle: nil,
            focusedElementRole: nil,
            selectedFilePaths: effectiveSelectedFileURLsForConversation().map(\.path),
            menuItems: []
        )
    }

    func prepareScopedWorkspaceTerminal() -> String {
        let consoleKey = activeConsoleKey
        let terminal = panelTerminal(for: consoleKey)
        TerminalAIBridge.shared.terminalController = terminal
        panelShowConsoleMap[consoleKey] = true
        return consoleKey
    }

    func currentDateTimeContextBlock() -> String {
        let now = Date()
        let formatter = DateFormatter()
        formatter.dateStyle = .full
        formatter.timeStyle = .medium
        let localDateTime = formatter.string(from: now)
        let isoFormatter = ISO8601DateFormatter()
        isoFormatter.timeZone = .current
        let isoDateTime = isoFormatter.string(from: now)
        let timeZoneName = TimeZone.current.identifier

        return """
            CURRENT DATE & TIME:
            - Local: \(localDateTime)
            - ISO 8601: \(isoDateTime)
            - Time Zone: \(timeZoneName)
            Use this exact date/time for relative time references like today, yesterday, tomorrow, recent, and this week.
            """
    }

    func canonicalExistingURLs(_ urls: [URL]) -> [URL] {
        var seen: Set<String> = []
        return urls.filter { url in
            let path = url.standardizedFileURL.path
            guard !path.isEmpty else { return false }
            guard FileManager.default.fileExists(atPath: path) else { return false }
            return seen.insert(path).inserted
        }
    }

    func clearFinderFollowUpTargets() {
        finderFollowUpTargetPaths = []
        finderFollowUpFolderPath = ""
        finderFollowUpSourceQuery = ""
    }

    func rememberFinderFollowUpTargets(
        _ urls: [URL],
        folderPath: String,
        sourceQuery: String = ""
    ) {
        let canonical = canonicalExistingURLs(urls)
        guard !canonical.isEmpty else { return }
        finderFollowUpTargetPaths = canonical.map(\.path)
        finderFollowUpFolderPath = folderPath
        finderFollowUpSourceQuery = sourceQuery
    }

    func finderFollowUpTargetURLs(for folderPath: String? = nil) -> [URL] {
        guard !finderFollowUpTargetPaths.isEmpty else { return [] }
        if let folderPath,
            !folderPath.isEmpty,
            !finderFollowUpFolderPath.isEmpty,
            finderFollowUpFolderPath != folderPath
        {
            return []
        }
        return canonicalExistingURLs(finderFollowUpTargetPaths.map { URL(fileURLWithPath: $0) })
    }

    func queryNeedsFinderFollowUpTargets(_ query: String) -> Bool {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return false }

        let tokens = Set(dockPillTokens(normalized))
        let pronounTerms: Set<String> = [
            "it", "them", "this", "that", "these", "those", "same", "again",
            "selected", "selection", "current",
        ]
        if !tokens.isDisjoint(with: pronounTerms) { return true }

        let actionTerms = [
            "share", "send", "mail", "email", "message", "open", "convert", "export",
            "save", "move", "copy", "duplicate", "rename", "compress", "zip", "print",
            "preview", "reveal", "quick look", "attach", "upload", "delete", "trash",
            "remove", "merge", "split", "extract", "encode", "transcode",
        ]
        let hasActionIntent = actionTerms.contains { normalized.contains($0) }
        let hasExplicitTarget = !finderTargetReferenceQuery(from: normalized).isEmpty
        return hasActionIntent && !hasExplicitTarget
    }

    func effectiveFinderSelectedFileURLs(for query: String, currentFolderPath: String)
        -> [URL]
    {
        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty {
            rememberFinderFollowUpTargets(
                liveSelection,
                folderPath: currentFolderPath,
                sourceQuery: query
            )
            return liveSelection
        }

        if case .filesSelected(let urls) = currentContext {
            let contextURLs = canonicalExistingURLs(urls)
            if !contextURLs.isEmpty {
                let normalizedCurrentFolderPath =
                    URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path
                let isStaleAttachedFolderContext =
                    contextURLs.count == 1
                    && contextURLs[0].hasDirectoryPath
                    && contextURLs[0].standardizedFileURL.path == attachedFinderFolderSearchPath
                    && attachedFinderFolderSearchPath != normalizedCurrentFolderPath
                guard !isStaleAttachedFolderContext else { return [] }

                rememberFinderFollowUpTargets(
                    contextURLs,
                    folderPath: currentFolderPath,
                    sourceQuery: query
                )
                return contextURLs
            }
        }

        guard queryNeedsFinderFollowUpTargets(query) else { return [] }
        return finderFollowUpTargetURLs(for: currentFolderPath)
    }

    func effectiveSelectedFileURLsForConversation() -> [URL] {
        let frozenSelection = frozenSelectionFileURLs
        if !frozenSelection.isEmpty {
            return isDismissedFinderSelection(frozenSelection) ? [] : frozenSelection
        }

        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty {
            return isDismissedFinderSelection(liveSelection) ? [] : liveSelection
        }

        if case .filesSelected(let urls) = currentContext {
            let contextURLs = canonicalExistingURLs(urls)
            if !contextURLs.isEmpty {
                return isDismissedFinderSelection(contextURLs) ? [] : contextURLs
            }
        }

        guard
            frontmost.bundleID == "com.apple.finder"
                || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
        else { return [] }

        if isFinderFolderSearchAttached(currentFolderPath: currentFinderFolderPath()) {
            let folderURL = URL(fileURLWithPath: attachedFinderFolderSearchPath)
            if FileManager.default.fileExists(atPath: folderURL.path) {
                return [folderURL]
            }
        }

        return finderFollowUpTargetURLs(for: currentFinderFolderPath())
    }

    func effectiveAXContextForConversation() -> AXContext {
        var context = axContext
        if context.selectedFilePaths.isEmpty {
            context.selectedFilePaths = effectiveSelectedFileURLsForConversation().map(\.path)
        }
        if (context.currentURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
            case .url(let urlString) = currentContext
        {
            context.currentURL = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        if (context.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            if case .textSelected(let text) = currentContext {
                let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
                if !trimmed.isEmpty { context.selectedText = trimmed }
            } else if let frozenSelectionText {
                let trimmed = frozenSelectionText.trimmingCharacters(in: .whitespacesAndNewlines)
                if !trimmed.isEmpty { context.selectedText = trimmed }
            }
        }
        return context
    }

    func finderTargetReferenceQuery(from query: String) -> String {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return "" }

        let ignoredWords: Set<String> = [
            "convert", "conversion", "export", "save", "open", "move", "copy", "duplicate",
            "share", "send", "attach", "upload", "rename", "delete", "trash", "remove",
            "reveal", "preview", "print", "merge", "split", "extract", "encode", "compress",
            "zip", "unzip", "transform", "change", "make", "create", "render", "transcode",
            "format", "into", "from", "with", "using", "via", "to", "as", "file", "files",
            "folder", "folders", "document", "documents", "image", "images", "photo", "photos",
            "picture", "pictures", "pdf", "png", "jpg", "jpeg", "webp", "heic", "gif", "tiff",
            "bmp", "selected", "selection", "current", "this", "that", "these", "those",
            "please", "here",
        ]

        let remaining = dockPillTokens(normalized).filter {
            !$0.isEmpty && !ignoredWords.contains($0) && $0.count >= 2
        }
        return remaining.joined(separator: " ")
    }

    func finderMetadataSummary(for url: URL) -> String {
        let resourceValues =
            (try? url.resourceValues(
                forKeys: [
                    .isDirectoryKey, .localizedTypeDescriptionKey, .contentModificationDateKey,
                    .fileSizeKey,
                ])) ?? URLResourceValues()
        let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
        let typeLabel =
            resourceValues.localizedTypeDescription
            ?? (isDirectory
                ? "Folder"
                : (url.pathExtension.isEmpty ? "File" : "\(url.pathExtension.uppercased()) file"))
        let sizeLabel: String = {
            guard !isDirectory else { return "folder" }
            let byteCount = Int64(resourceValues.fileSize ?? 0)
            guard byteCount > 0 else { return "size unknown" }
            return ByteCountFormatter.string(fromByteCount: byteCount, countStyle: .file)
        }()
        let modifiedLabel: String = {
            guard let modified = resourceValues.contentModificationDate else {
                return "modified unknown"
            }
            let formatter = RelativeDateTimeFormatter()
            formatter.unitsStyle = .full
            return "modified " + formatter.localizedString(for: modified, relativeTo: Date())
        }()
        return "\(typeLabel) | \(sizeLabel) | \(modifiedLabel) | \(finderDisplayPath(url.path))"
    }

    func buildFinderFileCatalogBlock(
        currentFolderPath: String,
        selectedFilePaths: [String]
    ) -> String {
        let folderURL = URL(fileURLWithPath: currentFolderPath)
        let fileManager = FileManager.default

        var orderedURLs = selectedFilePaths.map { URL(fileURLWithPath: $0) }
        if let currentItems = try? fileManager.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) {
            let sortedItems = currentItems.sorted { lhs, rhs in
                let lhsValues =
                    (try? lhs.resourceValues(forKeys: [
                        .isDirectoryKey, .contentModificationDateKey,
                    ]))
                    ?? URLResourceValues()
                let rhsValues =
                    (try? rhs.resourceValues(forKeys: [
                        .isDirectoryKey, .contentModificationDateKey,
                    ]))
                    ?? URLResourceValues()
                let lhsDirectory = lhsValues.isDirectory ?? lhs.hasDirectoryPath
                let rhsDirectory = rhsValues.isDirectory ?? rhs.hasDirectoryPath
                if lhsDirectory != rhsDirectory { return lhsDirectory && !rhsDirectory }
                let lhsDate = lhsValues.contentModificationDate ?? .distantPast
                let rhsDate = rhsValues.contentModificationDate ?? .distantPast
                if lhsDate != rhsDate { return lhsDate > rhsDate }
                return lhs.lastPathComponent.localizedCaseInsensitiveCompare(rhs.lastPathComponent)
                    == .orderedAscending
            }
            orderedURLs.append(contentsOf: sortedItems)
        }

        var seen: Set<String> = []
        let uniqueURLs = orderedURLs.filter { seen.insert($0.path).inserted }
        guard !uniqueURLs.isEmpty else { return "" }

        let limit = min(uniqueURLs.count, 40)
        let lines = uniqueURLs.prefix(limit).map { url in
            "- \(url.lastPathComponent) | \(finderMetadataSummary(for: url))"
        }

        var block = "\nCURRENT FOLDER FILE CATALOG:\n" + lines.joined(separator: "\n")
        if uniqueURLs.count > limit {
            block += "\n- ... and \(uniqueURLs.count - limit) more items in this folder"
        }
        return block
    }

    func buildFinderTargetSemanticMatches(
        for query: String,
        currentFolderPath: String,
        spotlightEnabled: Bool
    ) async -> [FinderSemanticMatch] {
        let targetQuery = finderTargetReferenceQuery(from: query)
        guard !targetQuery.isEmpty, targetQuery != normalizedDockPillText(query) else { return [] }

        let fastMatches = await buildFastFinderSemanticMatches(
            query: targetQuery,
            currentFolderPath: currentFolderPath
        )
        let spotlightMatches =
            spotlightEnabled && targetQuery.count >= 3
            ? runFinderSpotlightSearch(
                query: targetQuery,
                currentFolderPath: currentFolderPath,
                limit: 8
            )
            : []
        return mergeFinderSemanticMatches(fastMatches, with: spotlightMatches)
    }

    func buildFinderResolvedTargetContext(
        query: String,
        selectedFilePaths: [String],
        retrievedMatches: [FinderSemanticMatch]
    ) -> (targetURLs: [URL], summaryBlock: String, contentBlock: String) {
        let selectedURLs = selectedFilePaths.map { URL(fileURLWithPath: $0) }
        let candidateURLs: [URL] =
            !selectedURLs.isEmpty
            ? Array(selectedURLs.prefix(5))
            : Array(retrievedMatches.prefix(5).map { URL(fileURLWithPath: $0.path) })

        guard !candidateURLs.isEmpty else {
            return ([], "", "")
        }

        let summaryLines = candidateURLs.map { url in
            "- \(url.lastPathComponent) | \(finderMetadataSummary(for: url))"
        }
        let summaryBlock =
            "\nRESOLVED TARGET FILES FOR THIS QUERY:\n" + summaryLines.joined(separator: "\n")

        let analyzableURLs = candidateURLs.filter {
            let values =
                (try? $0.resourceValues(forKeys: [.isDirectoryKey])) ?? URLResourceValues()
            return !(values.isDirectory ?? $0.hasDirectoryPath)
        }
        let analyzedFiles = ContextDetector.shared.analyzeFiles(Array(analyzableURLs.prefix(2)))
        var contentBlock = ""
        for file in analyzedFiles {
            guard let content = file.content,
                !content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            else { continue }
            contentBlock +=
                "\n\n### Resolved target content from \(file.url.lastPathComponent):\n```\n\(String(content.prefix(2500)))\n```"
        }

        return (candidateURLs, summaryBlock, contentBlock)
    }

    func finderSemanticCategoryTokens(_ category: FinderFileCategory) -> Set<String> {
        switch category {
        case .pdf:
            return ["pdf", "pdfs"]
        case .image:
            return [
                "image", "images", "photo", "photos", "picture", "pictures", "screenshot",
                "screenshots",
            ]
        case .video:
            return ["video", "videos", "movie", "movies"]
        case .audio:
            return ["audio", "music", "song", "songs", "mp3"]
        case .archive:
            return ["archive", "archives", "zip", "zips", "dmg", "dmgs", "torrent", "torrents"]
        case .app:
            return ["app", "apps", "application", "applications"]
        case .folder:
            return ["folder", "folders", "directory", "directories"]
        case .document:
            return ["document", "documents", "doc", "docs", "text"]
        }
    }

    func finderExplicitLocationPath(in normalizedQuery: String) -> (
        path: String, tokens: Set<String>
    )? {
        let home = FileManager.default.homeDirectoryForCurrentUser
        let locations: [(names: [String], path: URL, tokens: [String])] = [
            (
                ["downloads", "download folder", "download directory"],
                home.appendingPathComponent("Downloads"), ["downloads", "download"]
            ),
            (["desktop"], home.appendingPathComponent("Desktop"), ["desktop"]),
            (
                ["documents", "documents folder", "docs folder"],
                home.appendingPathComponent("Documents"), ["documents", "docs"]
            ),
            (
                ["movies", "movies folder", "videos folder"], home.appendingPathComponent("Movies"),
                ["movies"]
            ),
            (
                ["pictures", "pictures folder", "photos folder"],
                home.appendingPathComponent("Pictures"), ["pictures", "photos"]
            ),
            (["music", "music folder"], home.appendingPathComponent("Music"), ["music"]),
            (["home", "home folder"], home, ["home"]),
        ]

        for location in locations {
            let matched = location.names.contains { name in
                normalizedQuery == name
                    || normalizedQuery.contains(" in \(name)")
                    || normalizedQuery.contains(" inside \(name)")
                    || normalizedQuery.contains(" under \(name)")
                    || normalizedQuery.contains(" from \(name)")
                    || normalizedQuery.contains(" at \(name)")
            }
            if matched {
                return (
                    location.path.standardizedFileURL.path,
                    Set(location.tokens + ["in", "inside", "under", "from"])
                )
            }
        }

        if normalizedQuery.contains("here") || normalizedQuery.contains("current folder")
            || normalizedQuery.contains("this folder")
        {
            return nil
        }
        return nil
    }

    func finderExplicitSizeBounds(in normalizedQuery: String) -> (
        min: Int64?, max: Int64?, tokens: Set<String>
    ) {
        var consumed: Set<String> = []

        func bytes(_ value: Double, _ unit: String) -> Int64 {
            let normalizedUnit = unit.lowercased()
            let multiplier: Double
            if normalizedUnit.hasPrefix("g") {
                multiplier = 1_073_741_824
            } else if normalizedUnit.hasPrefix("k") {
                multiplier = 1_024
            } else {
                multiplier = 1_048_576
            }
            return Int64(value * multiplier)
        }

        let patterns: [(pattern: String, isMin: Bool)] = [
            (
                #"(?:over|above|larger than|bigger than|greater than|more than)\s+([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)"#,
                true
            ),
            (
                #"(?:under|below|smaller than|less than)\s+([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)"#,
                false
            ),
            (
                #"([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)\s*(?:or )?(?:larger|bigger|plus|\+)"#,
                true
            ),
            (#"([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)\s*(?:or )?(?:smaller|less|under)"#, false),
        ]

        var minBytes: Int64?
        var maxBytes: Int64?
        for item in patterns {
            guard
                let regex = try? NSRegularExpression(
                    pattern: item.pattern, options: [.caseInsensitive])
            else { continue }
            let range = NSRange(
                normalizedQuery.startIndex..<normalizedQuery.endIndex, in: normalizedQuery)
            guard let match = regex.firstMatch(in: normalizedQuery, range: range),
                match.numberOfRanges >= 3,
                let valueRange = Range(match.range(at: 1), in: normalizedQuery),
                let unitRange = Range(match.range(at: 2), in: normalizedQuery),
                let value = Double(normalizedQuery[valueRange])
            else { continue }
            let size = bytes(value, String(normalizedQuery[unitRange]))
            if item.isMin {
                minBytes = max(minBytes ?? 0, size)
            } else {
                maxBytes = min(maxBytes ?? Int64.max, size)
            }
            if let fullRange = Range(match.range(at: 0), in: normalizedQuery) {
                consumed.formUnion(dockPillTokens(String(normalizedQuery[fullRange])))
            }
        }

        if minBytes == nil {
            let tokens = Set(dockPillTokens(normalizedQuery))
            if !tokens.isDisjoint(with: ["huge", "largest"]) {
                minBytes = 500 * 1_024 * 1_024
            } else if !tokens.isDisjoint(with: ["large", "larger", "big"]) {
                minBytes = 100 * 1_024 * 1_024
            }
        }
        if maxBytes == nil {
            let tokens = Set(dockPillTokens(normalizedQuery))
            if !tokens.isDisjoint(with: ["small", "tiny", "smallest"]) {
                maxBytes = 1 * 1_024 * 1_024
            }
        }

        return (minBytes, maxBytes, consumed)
    }

    func finderSemanticProfile(for query: String) -> FinderSemanticQueryProfile {
        let normalized = normalizedDockPillText(query)
        let tokens = dockPillTokens(normalized)
        let category = FinderFileCategory.detect(in: normalized)
        let explicitLocation = finderExplicitLocationPath(in: normalized)
        let explicitSize = finderExplicitSizeBounds(in: normalized)
        let wantsFoldersOnly =
            category == .folder || tokens.contains("folder") || tokens.contains("folders")
            || tokens.contains("directory") || tokens.contains("directories")
        let wantsFilesOnly =
            !wantsFoldersOnly
            && (tokens.contains("file") || tokens.contains("files")
                || tokens.contains("item") || tokens.contains("items"))
        let wantsRecent =
            tokens.contains("recent") || tokens.contains("latest") || tokens.contains("newest")
        let wantsToday = tokens.contains("today") || tokens.contains("tonight")
        let wantsYesterday = tokens.contains("yesterday")
        let wantsThisWeek = tokens.contains("week") || normalized.contains("this week")
        let wantsLargeFiles =
            tokens.contains("large") || tokens.contains("larger") || tokens.contains("big")
            || tokens.contains("huge") || tokens.contains("largest")
        let wantsSmallFiles =
            tokens.contains("small") || tokens.contains("tiny") || tokens.contains("smallest")

        var semanticTokens: Set<String> = [
            "today", "tonight", "yesterday", "recent", "latest", "newest",
            "this", "week", "here", "current", "folder", "folders", "directory", "directories",
            "file", "files", "item", "items", "modified", "updated", "edited", "changed",
            "large", "larger", "big", "huge", "largest", "small", "tiny", "smallest",
            "any", "all", "show", "list", "find", "search", "display", "check",
            "there", "is", "are", "do", "have", "got", "called", "named", "titled",
            "name", "names", "claled", "with", "matching", "match", "contains",
            "contain", "please", "me", "my", "a", "an", "the", "of", "to", "for",
        ]
        if let category {
            semanticTokens.formUnion(finderSemanticCategoryTokens(category))
        }
        if let explicitLocation {
            semanticTokens.formUnion(explicitLocation.tokens)
        }
        semanticTokens.formUnion(explicitSize.tokens)

        let residualQuery = tokens.filter { !semanticTokens.contains($0) }.joined(separator: " ")
        return FinderSemanticQueryProfile(
            originalQuery: normalized,
            residualQuery: residualQuery,
            category: category,
            wantsFoldersOnly: wantsFoldersOnly,
            wantsFilesOnly: wantsFilesOnly,
            wantsRecent: wantsRecent,
            wantsToday: wantsToday,
            wantsYesterday: wantsYesterday,
            wantsThisWeek: wantsThisWeek,
            wantsLargeFiles: wantsLargeFiles,
            wantsSmallFiles: wantsSmallFiles,
            explicitLocationPath: explicitLocation?.path,
            minSizeBytes: explicitSize.min,
            maxSizeBytes: explicitSize.max
        )
    }

    func finderSemanticDateInterval(for profile: FinderSemanticQueryProfile, now: Date)
        -> DateInterval?
    {
        let calendar = Calendar.current
        if profile.wantsToday {
            let start = calendar.startOfDay(for: now)
            guard let end = calendar.date(byAdding: .day, value: 1, to: start) else { return nil }
            return DateInterval(start: start, end: end)
        }
        if profile.wantsYesterday {
            let todayStart = calendar.startOfDay(for: now)
            guard
                let start = calendar.date(byAdding: .day, value: -1, to: todayStart)
            else { return nil }
            return DateInterval(start: start, end: todayStart)
        }
        if profile.wantsThisWeek {
            let components = calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now)
            guard
                let start = calendar.date(from: components),
                let end = calendar.date(byAdding: .day, value: 7, to: start)
            else { return nil }
            return DateInterval(start: start, end: end)
        }
        return nil
    }

    func finderAdvancedSearchRoot(
        for profile: FinderSemanticQueryProfile, currentFolderPath: String
    ) -> String {
        if let explicitLocationPath = profile.explicitLocationPath {
            return URL(fileURLWithPath: explicitLocationPath).standardizedFileURL.path
        }
        if !attachedFinderFolderSearchPath.isEmpty {
            return URL(fileURLWithPath: attachedFinderFolderSearchPath).standardizedFileURL.path
        }
        return URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path
    }

    func buildAdvancedFinderDataMatches(
        profile: FinderSemanticQueryProfile,
        currentFolderPath: String,
        limit: Int = 24
    ) -> [FinderSemanticMatch] {
        guard profile.hasAdvancedDataConstraint else { return [] }

        let rootPath = finderAdvancedSearchRoot(for: profile, currentFolderPath: currentFolderPath)
        let now = Date()
        let dateInterval = finderSemanticDateInterval(for: profile, now: now)
        let query = AdvancedFileSearchQuery(
            rootPath: rootPath,
            residualQuery: profile.residualQuery,
            allowedExtensions: profile.category?.fileExtensions,
            includeDirectories: profile.wantsFoldersOnly || profile.category == .folder,
            filesOnly: profile.wantsFilesOnly
                || (profile.category != nil && profile.category != .folder)
                || profile.wantsLargeFiles || profile.wantsSmallFiles,
            minSizeBytes: profile.minSizeBytes,
            maxSizeBytes: profile.maxSizeBytes,
            modifiedAfter: dateInterval?.start,
            modifiedBefore: dateInterval?.end,
            limit: limit
        )

        let indexedMatches = fileIndexManager.advancedSearch(query).filter { file in
            if profile.wantsFoldersOnly || profile.category == .folder {
                return file.isDirectory
            }
            return true
        }
        if !indexedMatches.isEmpty {
            return indexedMatches.map { file in
                let source =
                    profile.explicitLocationPath == nil
                    ? "Current Folder" : URL(fileURLWithPath: rootPath).lastPathComponent
                let sizeLabel =
                    file.size > 0
                    ? ByteCountFormatter.string(fromByteCount: file.size, countStyle: .file)
                    : "size unknown"
                return FinderSemanticMatch(
                    path: file.path,
                    title: file.name,
                    subtitle: "\(source) • \(sizeLabel) • \(finderDisplayPath(file.path))",
                    isDirectory: file.isDirectory,
                    score: 900 + min(500, Double(file.size) / 1_048_576.0),
                    source: source,
                    searchTerms: [
                        file.name, file.path, source, "finder", "spotlight", "advanced query",
                        profile.originalQuery,
                    ],
                    sizeBytes: file.size
                )
            }
        }

        return buildAdvancedFinderDirectoryFallbackMatches(
            profile: profile,
            rootPath: rootPath,
            limit: limit
        )
    }

    func buildAdvancedFinderDirectoryFallbackMatches(
        profile: FinderSemanticQueryProfile,
        rootPath: String,
        limit: Int
    ) -> [FinderSemanticMatch] {
        let rootURL = URL(fileURLWithPath: rootPath)
        let keys: [URLResourceKey] = [
            .isDirectoryKey, .contentModificationDateKey, .fileSizeKey,
        ]
        guard
            let enumerator = FileManager.default.enumerator(
                at: rootURL,
                includingPropertiesForKeys: keys,
                options: [.skipsHiddenFiles, .skipsPackageDescendants]
            )
        else { return [] }

        let now = Date()
        var matches: [FinderSemanticMatch] = []
        for case let url as URL in enumerator {
            guard matches.count < max(limit * 4, 80) else { break }
            let values = (try? url.resourceValues(forKeys: Set(keys))) ?? URLResourceValues()
            guard
                let semanticBoost = finderSemanticConstraintBoost(
                    for: url,
                    profile: profile,
                    resourceValues: values,
                    now: now
                )
            else { continue }
            if !profile.residualQuery.isEmpty,
                finderSemanticScore(query: profile.residualQuery, for: url) == nil
            {
                continue
            }
            let isDirectory = values.isDirectory ?? url.hasDirectoryPath
            let size = Int64(values.fileSize ?? 0)
            let sizeLabel =
                size > 0
                ? ByteCountFormatter.string(fromByteCount: size, countStyle: .file)
                : (isDirectory ? "folder" : "size unknown")
            let source = URL(fileURLWithPath: rootPath).lastPathComponent
            matches.append(
                FinderSemanticMatch(
                    path: url.standardizedFileURL.path,
                    title: url.lastPathComponent,
                    subtitle: "\(source) • \(sizeLabel) • \(finderDisplayPath(url.path))",
                    isDirectory: isDirectory,
                    score: semanticBoost + min(400, Double(size) / 1_048_576.0),
                    source: source,
                    searchTerms: [
                        url.lastPathComponent, url.path, source, "finder", "advanced query",
                    ],
                    sizeBytes: size
                )
            )
        }

        return
            matches
            .sorted {
                if $0.score != $1.score { return $0.score > $1.score }
                return ($0.sizeBytes ?? 0) > ($1.sizeBytes ?? 0)
            }
            .prefix(limit)
            .map { $0 }
    }

    func finderSemanticConstraintBoost(
        for url: URL,
        profile: FinderSemanticQueryProfile,
        resourceValues: URLResourceValues,
        now: Date
    ) -> Double? {
        let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath

        if profile.wantsFoldersOnly && !isDirectory { return nil }
        if profile.wantsFilesOnly && isDirectory { return nil }
        if let category = profile.category {
            if category == .folder {
                guard isDirectory else { return nil }
            } else if !category.matches(url) {
                return nil
            }
        }

        var score = 0.0
        var matchedAnyConstraint = false

        if profile.wantsFoldersOnly && isDirectory {
            matchedAnyConstraint = true
            score += 140
        }
        if profile.wantsFilesOnly && !isDirectory {
            matchedAnyConstraint = true
            score += 110
        }
        if let category = profile.category {
            matchedAnyConstraint = true
            score += category == .folder ? 150 : 125
        }

        if let interval = finderSemanticDateInterval(for: profile, now: now) {
            guard let modified = resourceValues.contentModificationDate,
                interval.contains(modified)
            else { return nil }
            matchedAnyConstraint = true
            score += profile.wantsToday ? 240 : 220
            let ageHours = max(0, now.timeIntervalSince(modified) / 3600)
            score += max(0, 36 - min(36, ageHours))
        } else if profile.wantsRecent {
            guard let modified = resourceValues.contentModificationDate else { return nil }
            matchedAnyConstraint = true
            let ageHours = max(0, now.timeIntervalSince(modified) / 3600)
            score += max(80, 240 - min(180, ageHours * 4))
        }

        let size = Int64(resourceValues.fileSize ?? 0)
        if profile.wantsLargeFiles {
            guard !isDirectory, size >= 5 * 1_024 * 1_024 else { return nil }
            matchedAnyConstraint = true
            score += 150 + min(180, Double(size) / 1_048_576.0)
        }
        if profile.wantsSmallFiles {
            guard !isDirectory, size > 0, size <= 1 * 1_024 * 1_024 else { return nil }
            matchedAnyConstraint = true
            score += 130 + max(0, 24 - Double(size) / 65_536.0)
        }

        return matchedAnyConstraint ? score : nil
    }

    func finderSemanticScore(query: String, for url: URL) -> Double? {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return nil }

        let name = normalizedDockPillText(url.lastPathComponent)
        let path = normalizedDockPillText(url.path)
        guard !name.isEmpty || !path.isEmpty else { return nil }

        var bestScore: Double? = nil

        if name == normalizedQuery {
            bestScore = 1100
        } else if name.hasPrefix(normalizedQuery) {
            bestScore = 980 + Double(min(normalizedQuery.count, 12) * 6)
        } else if name.contains(normalizedQuery) {
            bestScore = 900 + Double(min(normalizedQuery.count, 10) * 4)
        }

        if path.contains(normalizedQuery) {
            bestScore = max(bestScore ?? 0, 820 + Double(min(normalizedQuery.count, 12) * 3))
        }

        let queryTerms = dockPillTokens(normalizedQuery).filter { $0.count >= 2 }
        if !queryTerms.isEmpty {
            let matchedTerms = queryTerms.filter { name.contains($0) || path.contains($0) }
            if !matchedTerms.isEmpty {
                bestScore = max(
                    bestScore ?? 0,
                    780 + Double(matchedTerms.count * 42)
                )
            }
        }

        if let fuzzyName = FuzzyMatcher.score(normalizedQuery, against: name) {
            bestScore = max(bestScore ?? 0, fuzzyName)
        }
        if let typoName = finderNameTypoScore(query: normalizedQuery, target: name) {
            bestScore = max(bestScore ?? 0, typoName)
        }
        if bestScore == nil,
            let fuzzyPath = FuzzyMatcher.score(normalizedQuery, against: path)
        {
            bestScore = max(bestScore ?? 0, fuzzyPath * 0.78)
        }

        let isDirectory = (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) ?? false
        if isDirectory {
            bestScore = (bestScore ?? 0) + 18
        }

        return bestScore
    }

    func finderNameTypoScore(query: String, target: String) -> Double? {
        let queryTerms = dockPillTokens(query).filter { $0.count >= 3 }
        let targetTerms = dockPillTokens(target).filter { $0.count >= 3 }
        guard !queryTerms.isEmpty, !targetTerms.isEmpty else { return nil }

        var matched = 0
        var score = 0.0
        for q in queryTerms {
            guard let best = targetTerms.map({ levenshteinDistance(q, $0) }).min() else { continue }
            let allowed = max(1, min(3, q.count / 3))
            if best <= allowed {
                matched += 1
                score += 720 + Double(max(0, q.count - best) * 24)
            }
        }
        guard matched > 0 else { return nil }
        return score / Double(queryTerms.count)
    }

    func levenshteinDistance(_ lhs: String, _ rhs: String) -> Int {
        let a = Array(lhs)
        let b = Array(rhs)
        if a.isEmpty { return b.count }
        if b.isEmpty { return a.count }

        var previous = Array(0...b.count)
        var current = Array(repeating: 0, count: b.count + 1)

        for i in 1...a.count {
            current[0] = i
            for j in 1...b.count {
                let cost = a[i - 1] == b[j - 1] ? 0 : 1
                current[j] = min(
                    previous[j] + 1,
                    current[j - 1] + 1,
                    previous[j - 1] + cost
                )
            }
            swap(&previous, &current)
        }

        return previous[b.count]
    }

    func mergeFinderSemanticMatches(
        _ base: [FinderSemanticMatch],
        with additional: [FinderSemanticMatch]
    ) -> [FinderSemanticMatch] {
        var merged: [String: FinderSemanticMatch] = [:]
        for match in base + additional {
            if let existing = merged[match.path], existing.score >= match.score {
                continue
            }
            merged[match.path] = match
        }
        return merged.values.sorted { lhs, rhs in
            if lhs.score != rhs.score { return lhs.score > rhs.score }
            if lhs.isDirectory != rhs.isDirectory { return lhs.isDirectory && !rhs.isDirectory }
            return lhs.title.localizedCaseInsensitiveCompare(rhs.title) == .orderedAscending
        }
    }

    func buildFastFinderSemanticMatches(query: String, currentFolderPath: String) async
        -> [FinderSemanticMatch]
    {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return [] }
        let profile = finderSemanticProfile(for: normalizedQuery)
        let textQuery =
            !profile.residualQuery.isEmpty
            ? profile.residualQuery
            : (profile.hasSemanticConstraint ? "" : normalizedQuery)
        let now = Date()

        var matches: [FinderSemanticMatch] = []
        let fileManager = FileManager.default

        func addMatch(_ url: URL, baseScore: Double, source: String, extraTerms: [String] = []) {
            let resourceValues =
                (try? url.resourceValues(forKeys: [
                    .isDirectoryKey, .contentModificationDateKey, .fileSizeKey,
                ]))
                ?? URLResourceValues()
            let textScore =
                !textQuery.isEmpty ? finderSemanticScore(query: textQuery, for: url) : nil
            let semanticBoost = finderSemanticConstraintBoost(
                for: url,
                profile: profile,
                resourceValues: resourceValues,
                now: now
            )

            if !profile.residualQuery.isEmpty, textScore == nil { return }
            if profile.hasSemanticConstraint, semanticBoost == nil { return }
            guard textScore != nil || semanticBoost != nil else { return }

            let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
            matches.append(
                FinderSemanticMatch(
                    path: url.path,
                    title: url.lastPathComponent.isEmpty ? url.path : url.lastPathComponent,
                    subtitle: "\(source) • \(finderDisplayPath(url.path))",
                    isDirectory: isDirectory,
                    score: (textScore ?? 0) + (semanticBoost ?? 0) + baseScore,
                    source: source,
                    searchTerms: extraTerms + [source, url.lastPathComponent, url.path]
                ))
        }

        let folderURL = URL(fileURLWithPath: currentFolderPath)
        let isTemporalOrSizeQuery =
            profile.wantsRecent || profile.wantsToday || profile.wantsYesterday
            || profile.wantsThisWeek || profile.wantsLargeFiles || profile.wantsSmallFiles
        if !isTemporalOrSizeQuery,
            !profile.hasSemanticConstraint || profile.wantsFoldersOnly
                || !profile.residualQuery.isEmpty
        {
            addMatch(
                folderURL, baseScore: 180, source: "Current Folder",
                extraTerms: ["finder", "current directory"])
        }

        let selectedURLs = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        for url in selectedURLs {
            addMatch(
                url, baseScore: 165, source: "Selected Item", extraTerms: ["finder", "selection"])
        }

        if let currentItems = try? fileManager.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) {
            for url in currentItems {
                addMatch(url, baseScore: 140, source: "Current Folder", extraTerms: ["finder"])
            }
        }

        return mergeFinderSemanticMatches([], with: matches)
    }

    func runFinderSpotlightSearch(query: String, currentFolderPath: String, limit: Int)
        -> [FinderSemanticMatch]
    {
        let normalizedQuery = normalizedDockPillText(query)
        guard normalizedQuery.count >= 3 else { return [] }
        let profile = finderSemanticProfile(for: normalizedQuery)
        let contentQuery = profile.residualQuery
        guard !contentQuery.isEmpty else { return [] }
        let now = Date()
        let normalizedFolderPath = URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path

        func executeMDFind(arguments: [String], source: String, boost: Double)
            -> [FinderSemanticMatch]
        {
            let task = Process()
            let pipe = Pipe()
            task.executableURL = URL(fileURLWithPath: "/usr/bin/mdfind")
            task.arguments = arguments
            task.standardOutput = pipe
            task.standardError = Pipe()

            do {
                try task.run()
                task.waitUntilExit()
                let data = pipe.fileHandleForReading.readDataToEndOfFile()
                guard let output = String(data: data, encoding: .utf8), !output.isEmpty else {
                    return []
                }

                var results: [FinderSemanticMatch] = []
                for path in output.components(separatedBy: .newlines)
                    .filter({ !$0.isEmpty })
                    .prefix(limit)
                {
                    let url = URL(fileURLWithPath: path)
                    let normalizedPath = url.standardizedFileURL.path
                    let parentPath = url.deletingLastPathComponent().standardizedFileURL.path
                    guard parentPath == normalizedFolderPath else { continue }
                    let resourceValues =
                        (try? url.resourceValues(forKeys: [
                            .isDirectoryKey, .contentModificationDateKey, .fileSizeKey,
                        ]))
                        ?? URLResourceValues()
                    let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
                    let textScore = finderSemanticScore(query: contentQuery, for: url) ?? 720
                    let semanticBoost = finderSemanticConstraintBoost(
                        for: url,
                        profile: profile,
                        resourceValues: resourceValues,
                        now: now
                    )
                    if profile.hasSemanticConstraint && semanticBoost == nil { continue }
                    results.append(
                        FinderSemanticMatch(
                            path: normalizedPath,
                            title: url.lastPathComponent.isEmpty
                                ? normalizedPath : url.lastPathComponent,
                            subtitle: "\(source) • \(finderDisplayPath(normalizedPath))",
                            isDirectory: isDirectory,
                            score: textScore + (semanticBoost ?? 0) + boost,
                            source: source,
                            searchTerms: [
                                url.lastPathComponent, normalizedPath, source, "content", "finder",
                            ]
                        ))
                }
                return results
            } catch {
                return []
            }
        }

        let currentFolderMatches = executeMDFind(
            arguments: ["-onlyin", currentFolderPath, contentQuery],
            source: "Current Folder Content",
            boost: 150
        )
        return currentFolderMatches
    }

    func finderResultType(for path: String, isDirectory: Bool) -> SearchResult.ResultType {
        if isDirectory { return .folder }
        let ext = URL(fileURLWithPath: path).pathExtension.lowercased()
        if [
            "pdf", "txt", "md", "rtf", "doc", "docx", "pages", "json", "csv", "xml", "yaml", "yml",
            "swift", "js", "ts", "py", "sh",
        ].contains(ext) {
            return .document
        }
        return .file
    }

    func finderSemanticSymbol(for match: FinderSemanticMatch) -> String {
        if match.isDirectory { return "folder" }
        switch URL(fileURLWithPath: match.path).pathExtension.lowercased() {
        case "pdf":
            return "doc.richtext"
        case "png", "jpg", "jpeg", "gif", "heic", "webp", "tiff", "bmp":
            return "photo"
        case "zip", "rar", "7z", "gz", "tar":
            return "archivebox"
        case "mp4", "mov", "m4v", "avi", "mkv":
            return "film"
        case "mp3", "wav", "m4a", "flac":
            return "music.note"
        default:
            return "doc"
        }
    }

    func finderSemanticAction(for path: String, isDirectory: Bool) -> () -> Void {
        {
            let url = URL(fileURLWithPath: path)
            let folderPath =
                isDirectory
                ? url.deletingLastPathComponent().path : url.deletingLastPathComponent().path
            if isFinderCurrentWindowSearchAttached(currentFolderPath: folderPath) {
                recordFinderCurrentFolderLaunch(itemPath: url.path, folderPath: folderPath)
            }
            rememberFinderFollowUpTargets(
                [url],
                folderPath: isDirectory ? url.path : url.deletingLastPathComponent().path,
                sourceQuery: url.lastPathComponent
            )
            NSWorkspace.shared.open(url)
            searchState.query = ""
            l2.focusedPillIndex = nil
        }
    }

    func makeFinderSemanticSearchResults(from matches: [FinderSemanticMatch])
        -> [SearchResult]
    {
        matches.prefix(24).map { match in
            let icon = NSWorkspace.shared.icon(forFile: match.path)
            icon.size = NSSize(width: 32, height: 32)
            return SearchResult(
                title: match.title,
                subtitle: match.subtitle,
                icon: icon,
                action: finderSemanticAction(for: match.path, isDirectory: match.isDirectory),
                score: match.score,
                type: finderResultType(for: match.path, isDirectory: match.isDirectory),
                filePath: match.path,
                contactData: nil
            )
        }
    }

    func makeFinderSemanticDockPills(from matches: [FinderSemanticMatch]) -> [DockPill] {
        matches.prefix(8).map { match in
            var pill = DockPill(
                id: "finder-search-\(match.path)",
                name: match.title,
                icon: finderSemanticSymbol(for: match),
                accentColorName: match.isDirectory ? "blue" : "teal",
                badge: match.source,
                execute: finderSemanticAction(for: match.path, isDirectory: match.isDirectory)
            )
            pill.sourceBundleId = "com.apple.finder"
            pill.sourceAppName = "Finder"
            pill.rankingKind = match.source == "Current Folder" ? "finderCurrent" : "finderSearch"
            pill.quickLookURL = URL(fileURLWithPath: match.path)
            pill.trackingIdentifier = "finder-search:\(match.path.lowercased())"
            pill.searchTerms = match.searchTerms
            pill.rankingScore = match.score
            return pill
        }
    }

    func finderSemanticActionTargetURLs() -> [URL] {
        finderSemanticResults
            .compactMap { result -> URL? in
                guard let path = result.filePath, FileManager.default.fileExists(atPath: path)
                else { return nil }
                return URL(fileURLWithPath: path)
            }
            .prefix(8)
            .map { $0 }
    }

    func makeFinderSemanticQuickActionPills(query: String) -> [DockPill] {
        let urls = finderSemanticActionTargetURLs()
        guard !urls.isEmpty else { return [] }
        let normalized = normalizedDockPillText(query)
        let firstURL = urls[0]
        let targetLabel = urls.count == 1 ? firstURL.lastPathComponent : "\(urls.count) results"

        var pills: [DockPill] = []

        var preview = DockPill(
            id: "finder-search-preview-\(firstURL.path)",
            name: "Preview \(firstURL.lastPathComponent)",
            icon: "eye",
            accentColorName: "blue",
            badge: "Quick Look",
            execute: {
                quickLookDataSource = QuickLookDataSource(urls: [firstURL])
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        )
        preview.sourceBundleId = "com.apple.finder"
        preview.sourceAppName = "Finder"
        preview.rankingKind = "finderContext"
        preview.quickLookURL = firstURL
        preview.trackingIdentifier = "finder-preview:\(firstURL.path.lowercased())"
        preview.searchTerms = [
            "preview", "quick look", "finder", firstURL.lastPathComponent, normalized,
        ]
        pills.append(preview)

        var reveal = DockPill(
            id: "finder-search-reveal-\(firstURL.path)",
            name: "Reveal \(firstURL.lastPathComponent)",
            icon: "folder",
            accentColorName: "gray",
            badge: "Finder",
            execute: {
                NSWorkspace.shared.activateFileViewerSelecting([firstURL])
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        )
        reveal.sourceBundleId = "com.apple.finder"
        reveal.sourceAppName = "Finder"
        reveal.rankingKind = "finderContext"
        reveal.trackingIdentifier = "finder-reveal:\(firstURL.path.lowercased())"
        reveal.searchTerms = ["reveal", "show", "finder", firstURL.lastPathComponent, normalized]
        pills.append(reveal)

        if normalized.contains("compress") || normalized.contains("zip")
            || normalized.contains("archive") || normalized.contains("large")
        {
            var compress = DockPill(
                id: "finder-search-compress-\(urls.map(\.path).joined(separator: "|").hashValue)",
                name: "Compress \(targetLabel)",
                icon: "archivebox",
                accentColorName: "orange",
                badge: "ZIP",
                execute: {
                    compressFinderSearchResults(urls)
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                }
            )
            compress.sourceBundleId = "com.apple.finder"
            compress.sourceAppName = "Finder"
            compress.rankingKind = "finderContext"
            compress.trackingIdentifier = "finder-compress:\(normalized)"
            compress.searchTerms = [
                "compress", "zip", "archive", "finder", targetLabel, normalized,
            ]
            pills.append(compress)
        }

        if normalized.contains("move") || normalized.contains("organize") {
            var move = DockPill(
                id: "finder-search-move-\(urls.map(\.path).joined(separator: "|").hashValue)",
                name: "Move \(targetLabel)",
                icon: "folder.badge.plus",
                accentColorName: "teal",
                badge: "Choose",
                execute: {
                    moveFinderSearchResultsWithPanel(urls)
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                }
            )
            move.sourceBundleId = "com.apple.finder"
            move.sourceAppName = "Finder"
            move.rankingKind = "finderContext"
            move.trackingIdentifier = "finder-move:\(normalized)"
            move.searchTerms = ["move", "organize", "finder", targetLabel, normalized]
            pills.append(move)
        }

        return pills
    }

    func compressFinderSearchResults(_ urls: [URL]) {
        let existingURLs = canonicalExistingURLs(urls).filter { !$0.hasDirectoryPath }
        guard !existingURLs.isEmpty else {
            AppToast.show("No files to compress", icon: "exclamationmark.triangle", tint: .orange)
            return
        }
        let parentURL = existingURLs[0].deletingLastPathComponent()
        let archiveBase =
            existingURLs.count == 1
            ? existingURLs[0].deletingPathExtension().lastPathComponent
            : "Context-Dock Selection"
        let archiveURL = uniqueFinderDestination(
            for: parentURL.appendingPathComponent("\(archiveBase).zip"),
            in: parentURL
        )

        Task.detached(priority: .userInitiated) {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/ditto")
            if existingURLs.count == 1 {
                process.arguments = [
                    "-c", "-k", "--sequesterRsrc", "--keepParent",
                    existingURLs[0].path,
                    archiveURL.path,
                ]
            } else {
                process.executableURL = URL(fileURLWithPath: "/usr/bin/zip")
                process.currentDirectoryURL = parentURL
                process.arguments = ["-r", archiveURL.path] + existingURLs.map(\.lastPathComponent)
            }
            try? process.run()
            process.waitUntilExit()
            await MainActor.run {
                if process.terminationStatus == 0 {
                    AppToast.show(
                        "Created \(archiveURL.lastPathComponent)", icon: "archivebox", tint: .green)
                    rememberFinderFollowUpTargets(
                        [archiveURL], folderPath: parentURL.path, sourceQuery: "compress")
                } else {
                    AppToast.show(
                        "Compression failed", icon: "exclamationmark.triangle", tint: .orange)
                }
            }
        }
    }

    func moveFinderSearchResultsWithPanel(_ urls: [URL]) {
        let existingURLs = canonicalExistingURLs(urls)
        guard !existingURLs.isEmpty else { return }
        let panel = NSOpenPanel()
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.allowsMultipleSelection = false
        panel.prompt = "Move"
        let moveLabel =
            existingURLs.count == 1
            ? existingURLs[0].lastPathComponent
            : "\(existingURLs.count) Finder results"
        panel.message = "Choose a destination folder for \(moveLabel)."
        guard panel.runModal() == .OK, let destinationFolder = panel.url else { return }

        var moved: [URL] = []
        var failures = 0
        for url in existingURLs {
            let destination = uniqueFinderDestination(
                for: url,
                in: destinationFolder
            )
            do {
                try FileManager.default.moveItem(at: url, to: destination)
                moved.append(destination)
            } catch {
                failures += 1
            }
        }

        if !moved.isEmpty {
            rememberFinderFollowUpTargets(
                moved, folderPath: destinationFolder.path, sourceQuery: "move")
            AppToast.show(
                "Moved \(moved.count) item\(moved.count == 1 ? "" : "s")",
                icon: "folder.badge.plus", tint: .green)
        }
        if failures > 0 {
            AppToast.show(
                "Skipped \(failures) item\(failures == 1 ? "" : "s")",
                icon: "exclamationmark.triangle", tint: .orange)
        }
    }

    func buildAttachedFinderFolderPills(query: String) -> [DockPill] {
        let semanticQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !semanticQuery.isEmpty, !semanticQuery.hasPrefix("+") else { return [] }
        guard semanticQuery.count >= 2 else { return [] }
        guard isFinderCurrentWindowSearchAttached() else { return [] }

        let folderPath = URL(fileURLWithPath: attachedFinderFolderSearchPath).standardizedFileURL
            .path
        let folderURL = URL(fileURLWithPath: folderPath)
        let folderName =
            folderURL.lastPathComponent.isEmpty ? "Current Folder" : folderURL.lastPathComponent

        if attachedFinderFolderSnapshotPath != folderPath
            || attachedFinderFolderSnapshotItems.isEmpty
            || Date().timeIntervalSince(attachedFinderFolderSnapshotDate) > 2.0
        {
            refreshAttachedFinderFolderSnapshot(path: folderPath, force: false)
        }

        return
            attachedFinderFolderSnapshotItems
            .compactMap { item -> (item: FinderFolderSnapshotItem, score: Double)? in
                guard item.url.deletingLastPathComponent().standardizedFileURL.path == folderPath
                else { return nil }
                guard let score = finderSemanticScore(query: semanticQuery, for: item.url),
                    score >= 120
                else { return nil }
                let recencyBoost: Double = {
                    guard let modifiedDate = item.modifiedDate else { return 0 }
                    let age = Date().timeIntervalSince(modifiedDate)
                    guard age >= 0, age < 7 * 24 * 60 * 60 else { return 0 }
                    return max(0, 80 - (age / 10_800))
                }()
                return (item, score + recencyBoost + (item.isDirectory ? 20 : 0))
            }
            .sorted {
                if $0.score != $1.score { return $0.score > $1.score }
                if $0.item.isDirectory != $1.item.isDirectory {
                    return $0.item.isDirectory && !$1.item.isDirectory
                }
                return $0.item.displayName.localizedCaseInsensitiveCompare($1.item.displayName)
                    == .orderedAscending
            }
            .prefix(10)
            .map { match in
                let item = match.item
                let itemPath = item.path
                let icon = NSWorkspace.shared.icon(forFile: itemPath)
                icon.size = NSSize(width: 32, height: 32)
                var pill = DockPill(
                    id: "finder-attached-\(itemPath)",
                    name: item.displayName,
                    icon: item.isDirectory
                        ? "folder.fill"
                        : finderSemanticSymbol(
                            for: FinderSemanticMatch(
                                path: itemPath,
                                title: item.displayName,
                                subtitle: "",
                                isDirectory: item.isDirectory,
                                score: match.score,
                                source: "Current Folder",
                                searchTerms: []
                            )),
                    accentColorName: item.isDirectory ? "blue" : "teal",
                    badge: folderName,
                    execute: {
                        recordFinderCurrentFolderLaunch(itemPath: itemPath, folderPath: folderPath)
                        NSWorkspace.shared.open(item.url)
                        searchState.query = ""
                        l2.focusedPillIndex = nil
                        collapseDockToIconAfterFinderAction()
                    }
                )
                pill.sourceBundleId = "com.apple.finder"
                pill.sourceAppName = "Finder"
                pill.rankingKind = "finderCurrent"
                pill.menuItemImage = icon
                pill.quickLookURL = item.url
                pill.trackingIdentifier = finderCurrentFolderTrackingIdentifier(
                    folderPath: folderPath,
                    itemPath: itemPath
                )
                pill.searchTerms = [
                    item.displayName, itemPath, folderPath, "finder", "current folder",
                ]
                pill.rankingScore = match.score
                return pill
            }
    }

    func applyFinderSemanticMatches(_ matches: [FinderSemanticMatch], query: String) {
        let latestScope = resolveDockScope(for: searchState.query)
        let latestQuery =
            latestScope.scopedBundleId == "com.apple.finder"
            ? latestScope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            : ""
        guard latestQuery == query else { return }

        finderSemanticQuery = query
        let results = makeFinderSemanticSearchResults(from: matches)
        finderSemanticResults = results
        finderSemanticPills = makeFinderSemanticDockPills(from: matches)
        applyFinderSemanticPanelResults(results)
    }

    func clearFinderSemanticState() {
        let shouldClearPanelResults =
            !finderSemanticQuery.isEmpty || !finderSemanticResults.isEmpty
            || isFinderSemanticLoading
        finderSemanticTask?.cancel()
        finderSemanticTask = nil
        isFinderSemanticLoading = false
        finderSemanticQuery = ""
        finderSemanticResults = []
        finderSemanticPills = []
        l2.showResultsPopover = false
        if shouldClearPanelResults {
            applyFinderSemanticPanelResults([])
        }
    }

    // MARK: - Finder Go-To-Folder ("+prefix" mode)

    func isFinderGoToMode(query: String) -> Bool {
        guard query.hasPrefix("+") else { return false }
        return frontmost.bundleID == "com.apple.finder"
            || l2.targetApp?.bundleId == "com.apple.finder"
            || axContext.bundleId == "com.apple.finder"
    }

    func updateFinderGoToPills(for query: String) {
        guard isFinderGoToMode(query: query) else {
            if !finderGoToPills.isEmpty { finderGoToPills = [] }
            return
        }
        let pathQuery = String(query.dropFirst()).trimmingCharacters(in: .whitespacesAndNewlines)
        finderGoToPills = buildFinderGoToPills(pathQuery: pathQuery)
        scheduleDockPillRebuild(query: query, delayNanoseconds: 0)
    }

    func buildFinderGoToPills(pathQuery: String) -> [DockPill] {
        let query = pathQuery.lowercased()
        let fm = FileManager.default
        let home = NSHomeDirectory()
        let desktopOnlyMode = isFinderDesktopOnlyMode

        // Direct absolute-path completion
        if query.hasPrefix("/") {
            if fm.fileExists(atPath: pathQuery) {
                return [makeFinderGoToPill(path: pathQuery)]
            }
            let parent = (pathQuery as NSString).deletingLastPathComponent
            let stem = (pathQuery as NSString).lastPathComponent.lowercased()
            if let items = try? fm.contentsOfDirectory(atPath: parent) {
                return
                    items
                    .filter { !$0.hasPrefix(".") && $0.lowercased().hasPrefix(stem) }
                    .compactMap { item -> DockPill? in
                        let full = (parent as NSString).appendingPathComponent(item)
                        var isDir: ObjCBool = false
                        guard fm.fileExists(atPath: full, isDirectory: &isDir), isDir.boolValue
                        else { return nil }
                        return makeFinderGoToPill(path: full)
                    }
                    .prefix(8).map { $0 }
            }
            return []
        }

        // Common quick-access locations
        let quickAccess: [(path: String, alias: String?)] = [
            ("\(home)/Desktop", "desktop"),
            ("\(home)/Documents", "documents"),
            ("\(home)/Downloads", "downloads"),
            ("\(home)/Pictures", "pictures"),
            ("\(home)/Movies", "movies"),
            ("\(home)/Music", "music"),
            ("\(home)/Library/Mobile Documents/com~apple~CloudDocs", "icloud"),
            (home, "home"),
        ]

        var results: [DockPill] = []
        var seen = Set<String>()

        for entry in quickAccess {
            guard fm.fileExists(atPath: entry.path) else { continue }
            let name = URL(fileURLWithPath: entry.path).lastPathComponent.lowercased()
            let alias = entry.alias ?? name
            let matches =
                query.isEmpty
                || name.hasPrefix(query) || name.contains(query)
                || alias.hasPrefix(query) || alias.contains(query)
            if matches, seen.insert(entry.path).inserted {
                results.append(makeFinderGoToPill(path: entry.path))
            }
        }

        guard !desktopOnlyMode else {
            return Array(results.prefix(8))
        }

        // Current Finder folder's subdirectories
        let finderFolder = currentFinderFolderPath()
        if !finderFolder.isEmpty, let items = try? fm.contentsOfDirectory(atPath: finderFolder) {
            for item in items.sorted() where !item.hasPrefix(".") && results.count < 8 {
                let full = (finderFolder as NSString).appendingPathComponent(item)
                var isDir: ObjCBool = false
                guard fm.fileExists(atPath: full, isDirectory: &isDir), isDir.boolValue else {
                    continue
                }
                let itemLower = item.lowercased()
                guard query.isEmpty || itemLower.hasPrefix(query) || itemLower.contains(query)
                else { continue }
                if seen.insert(full).inserted { results.append(makeFinderGoToPill(path: full)) }
            }
        }

        // One level deep inside Desktop + Documents
        for root in ["\(home)/Desktop", "\(home)/Documents"] where results.count < 8 {
            guard let items = try? fm.contentsOfDirectory(atPath: root) else { continue }
            for item in items.sorted() where !item.hasPrefix(".") && results.count < 8 {
                let full = (root as NSString).appendingPathComponent(item)
                var isDir: ObjCBool = false
                guard fm.fileExists(atPath: full, isDirectory: &isDir), isDir.boolValue else {
                    continue
                }
                let itemLower = item.lowercased()
                guard query.isEmpty || itemLower.hasPrefix(query) || itemLower.contains(query)
                else { continue }
                if seen.insert(full).inserted { results.append(makeFinderGoToPill(path: full)) }
            }
        }

        return Array(results.prefix(8))
    }

    func makeFinderGoToPill(path: String) -> DockPill {
        let name = URL(fileURLWithPath: path).lastPathComponent
        var pill = DockPill(
            id: "finder-goto-\(path)",
            name: name.isEmpty ? path : name,
            icon: "folder.fill",
            accentColorName: "blue",
            badge: nil,
            execute: { [self] in navigateFinderToPath(path) }
        )
        pill.sourceBundleId = "com.apple.finder"
        pill.rankingKind = "finderGoTo"
        pill.trackingIdentifier = finderGoToTrackingIdentifier(for: path)
        return pill
    }

    func finderGoToTrackingIdentifier(for path: String) -> String {
        "finder-goto:\(URL(fileURLWithPath: path).standardizedFileURL.path.lowercased())"
    }

    func finderCurrentFolderTrackingIdentifier(folderPath: String, itemPath: String)
        -> String
    {
        let folder = URL(fileURLWithPath: folderPath).standardizedFileURL.path.lowercased()
        let item = URL(fileURLWithPath: itemPath).standardizedFileURL.path.lowercased()
        return "finder-current:\(folder):\(item)"
    }

    func recordFinderCurrentFolderLaunch(itemPath: String, folderPath: String) {
        UsageTracker.shared.recordAccess(
            for: finderCurrentFolderTrackingIdentifier(folderPath: folderPath, itemPath: itemPath)
        )
    }

    var frequentFinderHomeFolderGhostText: String? {
        let home = NSHomeDirectory()
        let candidates = [
            "\(home)/Downloads",
            "\(home)/Documents",
            "\(home)/Pictures",
            "\(home)/Movies",
            "\(home)/Music",
            "\(home)/Desktop",
        ]

        let mostUsedPath =
            candidates
            .filter { FileManager.default.fileExists(atPath: $0) }
            .max(by: {
                UsageTracker.shared.getAccessCount(for: finderGoToTrackingIdentifier(for: $0))
                    < UsageTracker.shared.getAccessCount(for: finderGoToTrackingIdentifier(for: $1))
            })
        guard let path = mostUsedPath else { return nil }

        guard UsageTracker.shared.getAccessCount(for: finderGoToTrackingIdentifier(for: path)) > 3
        else {
            return nil
        }

        return
            "~/\(URL(fileURLWithPath: path).lastPathComponent)  — type to ask about this folder..."
    }

    var frequentAttachedFinderItemGhostText: String? {
        guard !attachedFinderFolderSearchPath.isEmpty else { return nil }
        let folderPath = URL(fileURLWithPath: attachedFinderFolderSearchPath).standardizedFileURL
            .path
        let prefix = "finder-current:\(folderPath.lowercased()):"
        guard
            let item = UsageTracker.shared.getTopItems(limit: 80)
                .first(where: { entry in
                    entry.identifier.hasPrefix(prefix)
                        && UsageTracker.shared.getAccessCount(for: entry.identifier) > 2
                })
        else { return nil }

        let itemPath = String(item.identifier.dropFirst(prefix.count))
        guard FileManager.default.fileExists(atPath: itemPath) else { return nil }
        return
            "\(URL(fileURLWithPath: itemPath).lastPathComponent)  — type to search this folder..."
    }

    func navigateFinderToPath(_ path: String) {
        NSWorkspace.shared.selectFile(nil, inFileViewerRootedAtPath: path)
        DispatchQueue.main.async {
            self.searchState.query = ""
            self.finderGoToPills = []
            self.replaceCachedDockPills(self.buildDockPills(query: ""), preserveFocus: true)
        }
    }

    func scheduleFinderSemanticSearchIfNeeded(for query: String) {
        finderSemanticTask?.cancel()

        guard isL2ContextActive, showContextInDock, !isGlobalContextActive, !showMediaLayer else {
            clearFinderSemanticState()
            return
        }

        let scope = resolveDockScope(for: query)
        let currentFolderPath = currentFinderFolderPath()
        guard finderFolderQueryModeActive,
            isFinderFolderSearchAttached(currentFolderPath: currentFolderPath)
        else {
            clearFinderSemanticState()
            return
        }
        let semanticQuery =
            scope.scopedBundleId == "com.apple.finder"
            ? scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : ""
        let profile = finderSemanticProfile(for: semanticQuery)
        guard scope.scopedBundleId == "com.apple.finder" else {
            clearFinderSemanticState()
            return
        }

        guard !semanticQuery.isEmpty else {
            isFinderSemanticLoading = false
            finderSemanticQuery = ""
            finderSemanticResults = []
            finderSemanticPills = []
            l2.showResultsPopover = shouldKeepFinderSearchPopoverVisible(for: query)
            applyFinderSemanticPanelResults([])
            return
        }

        guard semanticQuery.count >= 2 else {
            isFinderSemanticLoading = false
            finderSemanticQuery = ""
            finderSemanticResults = []
            finderSemanticPills = []
            l2.showResultsPopover = shouldKeepFinderSearchPopoverVisible(for: query)
            applyFinderSemanticPanelResults([])
            return
        }

        finderSemanticQuery = semanticQuery
        isFinderSemanticLoading = false
        finderSemanticTask = Task(priority: .userInitiated) {
            try? await Task.sleep(nanoseconds: 180_000_000)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                isFinderSemanticLoading = true
            }

            let advancedMatches = await MainActor.run {
                buildAdvancedFinderDataMatches(
                    profile: profile,
                    currentFolderPath: currentFolderPath,
                    limit: 24
                )
            }
            let fastMatches = await buildFastFinderSemanticMatches(
                query: semanticQuery,
                currentFolderPath: currentFolderPath
            )
            let initialMatches = mergeFinderSemanticMatches(advancedMatches, with: fastMatches)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard finderSemanticQuery == semanticQuery else { return }
                applyFinderSemanticMatches(initialMatches, query: semanticQuery)
                isFinderSemanticLoading = false
            }

            let spotlightEnabled = await MainActor.run { settings.enableSpotlightSearch }
            guard spotlightEnabled, semanticQuery.count >= 3 else { return }

            try? await Task.sleep(nanoseconds: 160_000_000)
            guard !Task.isCancelled else { return }

            let spotlightMatches = runFinderSpotlightSearch(
                query: semanticQuery,
                currentFolderPath: currentFolderPath,
                limit: 18
            )
            let merged = mergeFinderSemanticMatches(initialMatches, with: spotlightMatches)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard finderSemanticQuery == semanticQuery else { return }
                applyFinderSemanticMatches(merged, query: semanticQuery)
                isFinderSemanticLoading = false
            }
        }
    }

    func isFinderSearchStyleQuery(_ query: String) -> Bool {
        let normalized = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !normalized.isEmpty else { return false }

        let analyticalTerms = [
            "summarize", "summary", "explain", "review", "translate", "compare",
            "analyze", "analyse", "why", "how", "read", "rewrite", "draft",
            "rename", "organize", "sort", "clean up", "compress", "zip",
            "convert", "export", "save", "open", "move", "copy", "share", "send",
            "attach", "upload", "delete", "trash", "remove", "duplicate",
            "reveal", "preview", "quick look", "print", "merge", "split",
            "extract", "encode", "transcode",
        ]
        return !analyticalTerms.contains(where: normalized.contains)
    }

    func finderSubmissionSummary(for query: String, results: [SearchResult]) -> String {
        if results.isEmpty {
            return "No Finder matches for “\(query)”."
        }

        let folderCount = results.filter { $0.type == .folder }.count
        let fileCount = results.count - folderCount
        if folderCount > 0 && fileCount > 0 {
            return "Found \(results.count) Finder matches for “\(query)” across folders and files."
        }
        if folderCount > 0 {
            return
                "Found \(folderCount) Finder folder match\(folderCount == 1 ? "" : "es") for “\(query)”."
        }
        return "Found \(fileCount) Finder file match\(fileCount == 1 ? "" : "es") for “\(query)”."
    }

    func executeCachedMenuAction(
        bundleIdentifier: String,
        appName: String,
        appPath: String?,
        path: [String],
        shortcutChar: String?,
        shortcutModifiers: Int
    ) {
        Task.detached(priority: .userInitiated) {
            if !NSWorkspace.shared.runningApplications.contains(where: {
                $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
            }) {
                await MainActor.run {
                    AppToast.show(
                        "Opening \(appName)", icon: "app.badge", tint: .blue.opacity(0.85))
                }
            }

            let result = await GlobalContextEngine.shared.verifyAndExecuteCachedMenu(
                GlobalMenuExecutionRequest(
                    bundleIdentifier: bundleIdentifier,
                    appName: appName,
                    appPath: appPath,
                    path: path,
                    shortcutChar: shortcutChar,
                    shortcutModifiers: shortcutModifiers
                )
            )

            if let liveItem = result.liveItem,
                result.status == .executed || result.status == .executionFallback
            {
                AppInteractionStore.shared.record(
                    bundleId: bundleIdentifier,
                    appName: appName,
                    query: liveItem.title,
                    kind: .menuItem,
                    actionId: liveItem.path.joined(separator: " > ")
                )
            }

            await MainActor.run {
                switch result.status {
                case .executed:
                    break
                case .executionFallback:
                    AppToast.show(
                        result.message, icon: "checkmark.circle", tint: .blue.opacity(0.85))
                case .unavailable, .launchFailed:
                    AppToast.show(
                        result.message,
                        icon: "exclamationmark.triangle",
                        tint: .orange.opacity(0.9)
                    )
                }

                if let app = result.app {
                    self.reloadMenuForApp(app)
                    self.refreshVisibleGlobalContextAfterMenuCacheUpdate(
                        bundleIdentifier: app.bundleIdentifier
                    )
                }
            }
        }
    }

    /// Detect whether the current query targets a cross-app and trigger menu loading if needed.
    /// Safe to call from `.onChange` handlers (outside view body evaluation).
    func triggerCrossAppMenuLoadIfNeeded(for query: String) {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return }
        if let target = L2AppActionRouter.shared.appScopeTarget(for: q),
            !target.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
            let app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == target.bundleId
            })
        {
            loadCrossAppMenu(for: app)
            return
        }
        if settings.crossAppPills,
            let (app, actionQuery) = detectCrossAppQuery(q),
            !actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            loadCrossAppMenu(for: app)
        }
    }

    func seedCrossAppMenuCache(for app: NSRunningApplication) {
        let pid = app.processIdentifier
        let appName = app.localizedName ?? ""
        var cachedItems = GlobalContextEngine.shared.cachedMenuItems(for: app, maxResults: 120)
        for index in cachedItems.indices {
            cachedItems[index].sourcePID = pid
            cachedItems[index].sourceAppName = appName
        }

        crossAppMenuTargetPID = pid
        crossAppMenuNeedsLiveLoad = true
        crossAppMenuItems = cachedItems
    }

    /// Load menu items for a target app into crossAppMenuItems from the persistent cache.
    /// Live AX scraping is deferred by warmMenuCacheIfNeeded so typing stays responsive.
    func loadCrossAppMenu(for app: NSRunningApplication) {
        let pid = app.processIdentifier
        guard pid != 0 else { return }
        guard pid != crossAppMenuTargetPID || crossAppMenuNeedsLiveLoad else { return }
        // Defer state mutations to avoid modifying @State during view update (body evaluation).
        DispatchQueue.main.async {
            crossAppMenuTargetPID = pid
            crossAppMenuNeedsLiveLoad = false
            crossAppMenuTask?.cancel()
            crossAppMenuTask = Task.detached(priority: .userInitiated) {
                let name = app.localizedName ?? ""
                var items = GlobalContextEngine.shared.cachedMenuItems(for: app, maxResults: 120)
                for i in items.indices {
                    items[i].sourcePID = pid
                    items[i].sourceAppName = name
                }
                await MainActor.run {
                    guard self.crossAppMenuTargetPID == pid else { return }
                    self.crossAppMenuItems = items
                    self.warmMenuCacheIfNeeded(bundleId: app.bundleIdentifier ?? "", appName: name)
                }
            }
        }
    }

    func distributedMenuItems(_ items: [AXMenuItem], limit: Int) -> [AXMenuItem] {
        guard limit > 0, !items.isEmpty else { return [] }

        var buckets: [String: [AXMenuItem]] = [:]
        var rootOrder: [String] = []

        for item in items {
            let root = item.path.first ?? item.title
            if buckets[root] == nil {
                buckets[root] = []
                rootOrder.append(root)
            }
            buckets[root, default: []].append(item)
        }

        for root in rootOrder {
            buckets[root]?.sort {
                if $0.path.count != $1.path.count { return $0.path.count < $1.path.count }
                return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
            }
        }

        var distributed: [AXMenuItem] = []
        var didAppend = true
        while distributed.count < limit && didAppend {
            didAppend = false
            for root in rootOrder where distributed.count < limit {
                guard var bucket = buckets[root], !bucket.isEmpty else { continue }
                distributed.append(bucket.removeFirst())
                buckets[root] = bucket
                didAppend = true
            }
        }

        return distributed
    }

    func orderedScopedMenuMatches(_ items: [AXMenuItem], filterQuery: String, limit: Int)
        -> [AXMenuItem]
    {
        guard !items.isEmpty else { return [] }
        let normalizedFilter = filterQuery.trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        if normalizedFilter.isEmpty {
            return distributedMenuItems(items, limit: limit)
        }

        return Array(
            items.sorted {
                let aScore =
                    rankedTextMatchScore(
                        query: normalizedFilter,
                        primary: $0.title,
                        contexts: [$0.path.dropLast().last ?? "", $0.path.joined(separator: " ")]
                    ) ?? 0
                let bScore =
                    rankedTextMatchScore(
                        query: normalizedFilter,
                        primary: $1.title,
                        contexts: [$1.path.dropLast().last ?? "", $1.path.joined(separator: " ")]
                    ) ?? 0
                if aScore != bScore { return aScore > bScore }
                if $0.path.count != $1.path.count { return $0.path.count < $1.path.count }
                return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
            }
            .prefix(limit)
        )
    }

    func scheduleDockPillRebuild(
        query: String,
        delayNanoseconds: UInt64 = 55_000_000,
        refreshContext: Bool = true
    ) {
        dockPillBuildTask?.cancel()
        if isQuestionStyleDockQuery(query) {
            cachedDockPills = []
            lastPillQuery = query
            pendingDockPillQuery = nil
            return
        }
        pendingDockPillQuery = query
        if !refreshContext || !query.isEmpty {
            let started = Date()
            replaceCachedDockPills(buildDockPills(query: query), preserveFocus: true)
            logDockPerformance("sync pill rebuild", started: started, query: query)
            lastPillQuery = query
        }
        dockPillBuildTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: delayNanoseconds)
            guard !Task.isCancelled else {
                if pendingDockPillQuery == query { pendingDockPillQuery = nil }
                return
            }
            // Skip the AX IPC call when the user is typing — selection context doesn't
            // change while typing, and the call blocks the main thread causing hitches.
            let shouldRefresh = refreshContext && query.isEmpty
            if shouldRefresh {
                refreshFinderSelectionContextFromFinder()
                guard !Task.isCancelled else {
                    if pendingDockPillQuery == query { pendingDockPillQuery = nil }
                    return
                }
            }
            guard pendingDockPillQuery == query else { return }
            let started = Date()
            replaceCachedDockPills(buildDockPills(query: query), preserveFocus: true)
            logDockPerformance("deferred pill rebuild", started: started, query: query)
            lastPillQuery = query
            if pendingDockPillQuery == query { pendingDockPillQuery = nil }
            dockPillBuildTask = nil
        }
    }

    func replaceCachedDockPills(_ pills: [DockPill], preserveFocus: Bool) {
        let previousFocusedID: String? = {
            guard preserveFocus,
                let index = l2.focusedPillIndex,
                cachedDockPills.indices.contains(index)
            else { return nil }
            return cachedDockPills[index].id
        }()

        cachedDockPills = pills

        guard preserveFocus else { return }
        if let previousFocusedID,
            let newIndex = pills.firstIndex(where: { $0.id == previousFocusedID && !$0.isSeparator }
            )
        {
            l2.focusedPillIndex = newIndex
            return
        }
        if let index = l2.focusedPillIndex,
            !pills.indices.contains(index) || pills[index].isSeparator
        {
            l2.focusedPillIndex = nil
            l2.pillNavViaKeyboard = false
        }
    }

    func logDockPerformance(_ label: String, started: Date, query: String) {
        let elapsedMS = Date().timeIntervalSince(started) * 1000
        guard elapsedMS >= 16 else { return }
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines)
        print(
            "⏱️ [DockPerf] \(label) \(String(format: "%.1f", elapsedMS)) ms q='\(q)' pills=\(cachedDockPills.count)"
        )
    }

    /// Build the ordered list of visible pills for the current dock state.
    /// This is the single source of truth for both rendering and keyboard navigation.
    func buildDockPills(query q: String) -> [DockPill] {
        // When a submenu parent is locked, the dropdown handles child display directly —
        // skip all pill logic so no app/file/other pills compete with it.
        if lockedSubmenuParent != nil { return [] }
        if lockedFindToken != nil { return [] }
        if isQuestionStyleDockQuery(q) { return [] }

        if searchState.activeSmartQueryKey == "clipboard" {
            return buildClipboardHistoryPills(query: q)
        }

        // AI-found menu action: show as a focused pill instead of in the chat result sheet
        if q.isEmpty, let proposal = pendingAIMenuProposal {
            let path = proposal.path
            let sc = proposal.shortcutChar
            let mod = proposal.shortcutModifiers
            let pid = proposal.sourcePID
            let bId = proposal.sourceBundleId
            let aName = proposal.sourceAppName
            var pill = DockPill(
                id: "ai-proposal-\(proposal.fullPathLabel)",
                name: proposal.title,
                icon: "cursorarrow.click",
                accentColorName: "blue",
                badge: aName.isEmpty ? nil : aName,
                execute: {
                    self.pendingAIMenuProposal = nil
                    self.executeDockMenuAction(
                        sourcePID: pid,
                        path: path,
                        shortcutChar: sc,
                        shortcutModifiers: mod
                    )
                }
            )
            pill.menuItemImage = proposal.menuImage
            pill.menuItemName = proposal.title
            pill.sourceBundleId = bId
            pill.sourceAppName = aName
            pill.rankingKind = "menu"
            return [pill]
        }

        // "youtube on web" / "browse tamilgun" / "web X" → immediate web-search pill.
        // App-scoped search owns queries like "search gowri in photos".
        if L2AppActionRouter.shared.appScopeTarget(for: q) == nil,
            let searchTerm = L2AppActionRouter.shared.extractWebSearchQuery(from: q)
        {
            let browserName = L2AppActionRouter.defaultBrowserName()
            var pill = DockPill(
                id: "web-search-\(searchTerm)",
                name: "Search \"\(searchTerm)\" on Web",
                icon: "globe",
                accentColorName: "blue",
                badge: browserName,
                execute: { L2AppActionRouter.openWebSearch(searchTerm) }
            )
            pill.rankingKind = "webSearch"
            pill.searchTerms = [searchTerm, "web", "search", browserName]
            pill.trackingIdentifier = "web-search:\(searchTerm)"
            return [pill]
        }

        var pills: [DockPill] = []
        pills.append(contentsOf: buildGlobalSelectionSharePills(query: q))
        // Safari page-level command pills (search, click, open) — appear before AX menu items
        pills.append(contentsOf: buildSafariCommandPills(query: q))
        // System Settings pane deep-links (Wallpaper, Wi-Fi, etc.) — sidebar isn't menu-scanned
        pills.append(contentsOf: buildSystemSettingsPills(query: q))
        let scope = resolveDockScope(for: q)
        let rawScopedSearchQuery = rawScopedActionQuery(for: q, scope: scope)
        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []
        let explicitAppTarget: L2ExplicitAppTarget? =
            (!isGlobalContextActive || q.isEmpty)
            ? nil
            : L2AppActionRouter.shared.appScopeTarget(for: q).flatMap {
                target -> L2ExplicitAppTarget? in
                if installedScopeMode,
                    implicitContextDockAppScopeBlockedBundleIds.contains(target.bundleId)
                {
                    return nil
                }
                return (!runningOnly || runningBundleIds.contains(target.bundleId)) ? target : nil
            }
        let inlineInstalledMenuTarget: InstalledAppMenuTarget? =
            (shouldUsePureGlobalAppSearch && isGlobalContextActive && l2.targetApp == nil)
            ? globalInlineAppScope.map {
                InstalledAppMenuTarget(
                    appName: $0.appName,
                    bundleId: $0.bundleId,
                    appPath: $0.appPath,
                    actionQuery: q,
                    matchedAlias: $0.matchedAlias,
                    aliasStartIndex: $0.aliasStartIndex
                )
            }
            : nil
        let installedMenuTarget: InstalledAppMenuTarget? = {
            if let target = inlineInstalledMenuTarget { return target }
            guard isGlobalContextActive, explicitAppTarget == nil, l2.targetApp == nil else {
                return nil
            }
            let target = installedAppMenuTarget(
                for: q,
                runningOnly: false,
                includeAppsWithoutMenuSnapshot: true,
                allowPrefixAlias: true
            )
            // In pure global app search, a bare app name (e.g. "terminal") means "launch this app",
            // not "show all its menus". Empty actionQuery → skip installedMenuTarget so unrelated
            // menus don't flood the results list.
            if shouldUsePureGlobalAppSearch, target?.actionQuery.isEmpty == true { return nil }
            return target
        }()
        let isExplicitAppScope = scope.isExplicitAppScope
        let isGlobalScope = scope.isGlobalScope
        let allowAppleMenuItems = isGlobalContextActive
        let scopedBundleId = scope.scopedBundleId
        let scopedAppName = scope.scopedAppName
        let scopedSearchQuery = scope.scopedSearchQuery
        let isFinderScopedDock =
            !isGlobalScope
            && (!isExplicitAppScope || scopedBundleId == "com.apple.finder")
            && (scopedBundleId == "com.apple.finder"
                || frontmost.bundleID == "com.apple.finder"
                || axContext.bundleId == "com.apple.finder")
        let finderFolderAttachedForDock =
            isFinderScopedDock
            && finderFolderQueryModeActive
            && isFinderFolderSearchAttached(currentFolderPath: currentFinderFolderPath())
        let rawPayloadActionPills = buildPayloadActionPills(query: q)
        let rawFinderFilePills =
            isFinderScopedDock && !finderFolderAttachedForDock
            ? buildFinderFilePills(query: q) : []
        let rawFinderHomeFolderPills =
            isFinderScopedDock && !finderFolderAttachedForDock
            ? buildFinderHomeFolderPills(query: scopedSearchQuery.isEmpty ? q : scopedSearchQuery)
            : []
        let finderHomeSearchQuery = (scopedSearchQuery.isEmpty ? q : scopedSearchQuery)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let shouldShowFinderHomeSearchOnly =
            isFinderScopedDock
            && !finderFolderAttachedForDock
            && !finderHomeSearchQuery.isEmpty
            && !rawFinderHomeFolderPills.isEmpty
            && effectiveFinderSelectionURLsForPills().isEmpty
        let rawAttachedFinderFolderPills =
            isFinderScopedDock
            ? buildAttachedFinderFolderPills(
                query: scopedSearchQuery.isEmpty ? q : scopedSearchQuery) : []
        let finderFileTitleSet = Set(rawFinderFilePills.map { normalizedDockPillText($0.name) })
        let rawFinderSelectionMenuPills =
            isFinderScopedDock && !finderFolderAttachedForDock
            ? buildFinderSelectionMenuPills(query: q, excludingTitles: finderFileTitleSet) : []
        let finderMenuIntentTerms = [
            "menu", "command", "cmd", "shortcut", "finder menu",
            "view", "go", "sort", "arrange", "new folder", "new window",
            "show view options", "connect to server", "empty bin", "trash",
        ]
        let finderTypedQuery = (scopedSearchQuery.isEmpty ? q : scopedSearchQuery)
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        let finderShouldPreferFiles =
            isFinderScopedDock
            && finderTypedQuery.count >= 2
            && (!rawFinderFilePills.isEmpty || !rawFinderHomeFolderPills.isEmpty
                || !rawAttachedFinderFolderPills.isEmpty)
            && !finderMenuIntentTerms.contains { finderTypedQuery.contains($0) }
        let filteredFinderSelectionMenuPills = rawFinderSelectionMenuPills
        let payloadActionPills: [DockPill] = {
            guard isExplicitAppScope, !scopedSearchQuery.isEmpty else {
                return rawPayloadActionPills
            }
            let payloadIntentWords = [
                "send", "share", "message", "messages", "imessage", "sms",
                "mail", "email", "note", "notes", "reminder", "remind",
                "download", "downloads",
            ]
            let isPayloadIntent = payloadIntentWords.contains { scopedSearchQuery.contains($0) }
            return isPayloadIntent ? rawPayloadActionPills : []
        }()
        let crossAppPills = !isExplicitAppScope ? buildCrossAppPills(query: q) : []
        let semanticFinderPills: [DockPill] = {
            guard !shouldUseFinderSearchPopover(for: q) else { return [] }
            guard finderFolderAttachedForDock else { return [] }
            guard
                scopedBundleId == "com.apple.finder"
                    || frontmost.bundleID == "com.apple.finder"
                    || axContext.bundleId == "com.apple.finder"
            else { return [] }
            // "+prefix" go-to-folder mode: show path completion pills
            if isFinderGoToMode(query: q) { return finderGoToPills }
            let semanticQuery =
                scopedSearchQuery
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            let semanticProfile = finderSemanticProfile(for: semanticQuery)
            guard !semanticQuery.isEmpty, finderSemanticQuery == semanticQuery else { return [] }
            guard semanticProfile.explicitLocationPath == nil else { return [] }
            return finderSemanticPills
        }()
        let semanticFinderQuickActionPills: [DockPill] = {
            guard !semanticFinderPills.isEmpty else { return [] }
            let semanticQuery =
                scopedSearchQuery
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            return makeFinderSemanticQuickActionPills(query: semanticQuery)
        }()
        _ = shouldShowFinderHomeSearchOnly
        if finderFolderAttachedForDock {
            return rankDockPills(
                rawAttachedFinderFolderPills
                    + semanticFinderPills
                    + semanticFinderQuickActionPills,
                rawQuery: q,
                rankingQuery: scopedSearchQuery.isEmpty ? q : scopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName,
                isExplicitAppScope: isExplicitAppScope
            )
        }
        let messagesSemanticIntentPill =
            scopedBundleId == "com.apple.MobileSMS"
            ? makeMessagesSemanticIntentPill(
                fullQuery: q,
                rawScopedQuery: rawScopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName
            )
            : nil
        let mailSemanticSearchPill =
            scopedBundleId == "com.apple.mail"
            ? makeMailSemanticSearchPill(
                fullQuery: q,
                rawScopedQuery: rawScopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName
            )
            : nil
        let appWindowSemanticPill = makeAppWindowSemanticPill(
            rawScopedQuery: rawScopedSearchQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            isGlobalScope: isGlobalScope
        )
        let chatGPTNewChatPill = makeChatGPTNewChatPill(
            scopedQuery: scopedSearchQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            appPath: installedMenuTarget?.appPath
        )
        let hasStrongContextQuery = !payloadActionPills.isEmpty
        let shouldSuppressMenuForContext = finderFolderAttachedForDock
        let activeBundleId = isGlobalScope ? "" : scopedBundleId
        let scopedAppKey =
            isGlobalScope
            ? ""
            : (searchState.activeSmartQueryKey
                ?? settings.appKey(forBundleID: scopedBundleId, appName: scopedAppName)
                ?? settings.autoDetectedAppKey
                ?? "")
        let allQuickActions =
            isGlobalScope
            ? []
            : appScopeShortcuts(
                for: scopedAppKey,
                placements: [.quickActions, .contextDock, .both]
            )
        let userScriptExtensions =
            isGlobalScope || scopedAppKey.isEmpty
            ? [AppToolExtension]()
            : appPillScriptExtensions(for: scopedAppKey, query: scopedSearchQuery)
        let cliPackages: [TerminalPackage] = {
            guard !isGlobalScope, !scopedBundleId.isEmpty else { return [] }
            // For cli:// adapter scopes, directly surface the matching package by command name.
            if scopedBundleId.hasPrefix("cli://") {
                let cmd = String(scopedBundleId.dropFirst("cli://".count))
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                if let pkg = terminalPackageManager.packages.first(where: {
                    $0.isEnabled && $0.command.caseInsensitiveCompare(cmd) == .orderedSame
                }) {
                    if scopedSearchQuery.isEmpty { return [pkg] }
                    let q2 = scopedSearchQuery.lowercased()
                    let matches =
                        pkg.command.lowercased().contains(q2)
                        || pkg.name.lowercased().contains(q2)
                        || pkg.subcommands.contains { $0.lowercased().hasPrefix(q2) }
                    return matches ? [pkg] : []
                }
                return []
            }
            return terminalPackageManager.packages(
                forContextBundleId: scopedBundleId,
                query: scopedSearchQuery,
                maxResults: q.isEmpty ? 6 : 4
            )
        }()
        let adapterActions =
            isGlobalScope || scopedBundleId.isEmpty
            ? [AdapterAction]()
            : (q.isEmpty
                ? adapterManager.actions(for: scopedBundleId)
                : adapterManager.actions(for: scopedBundleId, query: scopedSearchQuery))
        let adapterCLICommands = Set<String>(
            adapterActions.compactMap { action in
                guard action.type == .cliTool else { return nil }
                let command =
                    action.cliToolCommand?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                return command.isEmpty ? nil : command.lowercased()
            }
        )
        let visibleCLIPackages = cliPackages.filter { package in
            !adapterCLICommands.contains(package.command.lowercased())
        }
        let visibleAdapterActions = adapterActions
        let allAppTools = {
            guard !isGlobalScope else { return [L2Extension]() }
            guard !scopedAppName.isEmpty || !scopedBundleId.isEmpty else {
                return frontmostAppL2Extensions
            }
            return l2Extensions(forAppName: scopedAppName, bundleID: scopedBundleId)
        }()
        let allCtxExts =
            isExplicitAppScope
            ? scopedContextExtensions(
                query: scopedSearchQuery, appName: scopedAppName, bundleId: scopedBundleId)
            : l2.contextExtensions
        let quickActions =
            q.isEmpty
            ? allQuickActions
            : allQuickActions.filter { $0.name.lowercased().contains(scopedSearchQuery) }
        let appTools =
            q.isEmpty
            ? allAppTools
            : allAppTools.filter {
                $0.displayName.lowercased().contains(scopedSearchQuery)
                    || $0.toolName.lowercased().contains(scopedSearchQuery)
            }
        let ctxExts =
            q.isEmpty
            ? allCtxExts
            : allCtxExts.filter { $0.ilExtension.name.lowercased().contains(scopedSearchQuery) }
        let scopedAppLaunchPill: DockPill? = {
            // No "Open" pill for cli:// adapters — they're not launchable apps
            guard !scopedBundleId.hasPrefix("cli://") else { return nil }
            guard isExplicitAppScope, !q.isEmpty, !scopedBundleId.isEmpty, !scopedAppName.isEmpty,
                scopedSearchQuery.isEmpty
            else { return nil }

            var pill = DockPill(
                id: "launch-\(scopedBundleId)",
                name: "Open \(scopedAppName)",
                icon: "app.badge",
                accentColorName: "blue",
                badge: nil,
                execute: {
                    _ = launchApplication(
                        bundleIdentifier: scopedBundleId,
                        appName: scopedAppName,
                        path: installedMenuTarget?.appPath
                    )
                }
            )
            pill.rankingKind = "appLaunch"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "app-launch:\(scopedBundleId)"
            pill.searchTerms = [scopedAppName, "open", "launch", "app"]
            return pill
        }()

        let favs = settings.favouriteMenuPills(for: activeBundleId)
        let isScopedToOtherApp =
            isExplicitAppScope && !scopedBundleId.isEmpty && scopedBundleId != frontmost.bundleID
        let useSeededMenuPills =
            q.isEmpty && !liveMenuItems.isEmpty && !shouldSuppressMenuForContext
            && !isScopedToOtherApp

        if isGlobalContextActive && hasActiveDockContextSelection {
            pills.append(contentsOf: crossAppPills)
        }

        if useSeededMenuPills && !hasStrongContextQuery {
            let seedItems = Array(
                liveMenuItems
                    .filter { !$0.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    .filter { allowAppleMenuItems || !isAppleMenuItem($0) }
                    .filter(shouldExposeCachedMenuItem)
                    .prefix(16)
            )

            for item in seedItems {
                let path = item.path
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let shortcutChar = item.shortcutChar
                let shortcutMods = item.shortcutModifiers
                let pill = makeMenuDockPill(
                    id: "menu-seed-\(item.id)",
                    item: item,
                    sourceBundleId: activeBundleId,
                    sourceAppName: scopedAppName,
                    badge: item.shortcutDisplay,
                    trackingIdentifier:
                        "menu-seed:\(activeBundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [scopedAppName],
                    executeLeaf: {
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutMods
                        )
                    }
                )
                pills.append(pill)
            }
        }

        // Submenu drill-down: when query matches a non-leaf menu item, surface its leaf
        // children as direct-action pills ranked before everything else.
        if let subCtx = submenuGhostContext {
            let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
            let visibleChildren =
                allowAppleMenuItems
                ? subCtx.children.filter(shouldExposeCachedMenuItem)
                : subCtx.children.filter { !isAppleMenuItem($0) && shouldExposeCachedMenuItem($0) }
            for child in visibleChildren {
                let path = child.path
                let pid = child.sourcePID != 0 ? child.sourcePID : frontPID
                let sc = child.shortcutChar
                let mod = child.shortcutModifiers
                var pill = DockPill(
                    id: "submenu-child-\(child.id)",
                    name: child.title,
                    icon: menuSymbol(for: child),
                    accentColorName: "blue",
                    badge: subCtx.parent.title,
                    execute: {
                        guard pid != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: pid, path: path,
                            shortcutChar: sc, shortcutModifiers: mod
                        )
                    }
                )
                pill.menuItemImage = resolvedMenuIcon(for: child)
                pill.menuItemName = child.title
                pill.menuContext = subCtx.parent.title
                pill.sourceBundleId = activeBundleId
                pill.sourceAppName = scopedAppName
                pill.rankingKind = "submenuChild"
                pill.isEnabled = true
                pill.rankingScore = 1_000  // pin above everything else
                pills.append(pill)
            }
        }

        if let scopedAppLaunchPill {
            pills.append(scopedAppLaunchPill)
        }

        if let messagesSemanticIntentPill {
            pills.append(messagesSemanticIntentPill)
        }

        if let mailSemanticSearchPill {
            pills.append(mailSemanticSearchPill)
        }

        if let appWindowSemanticPill {
            pills.append(appWindowSemanticPill)
        }

        if let chatGPTNewChatPill {
            pills.append(chatGPTNewChatPill)
        }

        pills.append(
            contentsOf: rawFinderFilePills.map { pill in
                var enriched = pill
                if enriched.rankingKind.isEmpty {
                    enriched.rankingKind = "finderSelection"
                }
                enriched.sourceBundleId =
                    enriched.sourceBundleId.isEmpty ? "com.apple.finder" : enriched.sourceBundleId
                enriched.sourceAppName =
                    enriched.sourceAppName.isEmpty ? "Finder" : enriched.sourceAppName
                if enriched.searchTerms.isEmpty {
                    enriched.searchTerms = [enriched.name, enriched.badge ?? "", "finder", "files"]
                }
                if enriched.trackingIdentifier.isEmpty {
                    enriched.trackingIdentifier =
                        "finder-selection:\(normalizedDockPillText(enriched.name))"
                }
                return enriched
            })

        pills.append(contentsOf: filteredFinderSelectionMenuPills)

        pills.append(contentsOf: rawFinderHomeFolderPills)

        pills.append(contentsOf: rawAttachedFinderFolderPills)

        pills.append(contentsOf: semanticFinderPills)

        pills.append(contentsOf: semanticFinderQuickActionPills)

        pills.append(
            contentsOf: payloadActionPills.map { pill in
                var enriched = pill
                if enriched.rankingKind.isEmpty {
                    enriched.rankingKind = "payload"
                }
                if enriched.searchTerms.isEmpty {
                    enriched.searchTerms = [enriched.name, enriched.badge ?? ""]
                }
                if enriched.trackingIdentifier.isEmpty {
                    enriched.trackingIdentifier = "payload:\(normalizedDockPillText(enriched.name))"
                }
                return enriched
            })

        let dedupeMenuItems: ([AXMenuItem]) -> [AXMenuItem] = { items in
            var seen = Set<String>()
            var deduped: [AXMenuItem] = []
            for item in items {
                let key = item.path.joined(separator: " > ").lowercased()
                guard !key.isEmpty, !seen.contains(key) else { continue }
                seen.insert(key)
                deduped.append(item)
            }
            return deduped
        }

        let persistentMenuMatches: (NSRunningApplication, String, Int) -> [AXMenuItem] = {
            app, query, limit in
            GlobalContextEngine.shared.cachedMenuItems(for: app, query: query, maxResults: limit)
        }
        let persistentClosedAppMatches: (String, String, String, Int) -> [AXMenuItem] = {
            bundleId, appName, query, limit in
            GlobalContextEngine.shared.cachedMenuItems(
                bundleIdentifier: bundleId,
                appName: appName,
                processIdentifier: 0,
                query: query,
                maxResults: limit
            )
        }
        let menuItemsAllowedForCurrentScope: ([AXMenuItem]) -> [AXMenuItem] = { items in
            items.filter { item in
                shouldExposeCachedMenuItem(item) && (allowAppleMenuItems || !isAppleMenuItem(item))
            }
        }
        let menuItemMatchesQuery: (AXMenuItem, String) -> Bool = { item, query in
            let normalizedQuery = normalizedDockPillText(query)
            guard !normalizedQuery.isEmpty else { return true }
            let corpora = ([item.title] + item.path)
                .map(normalizedDockPillText)
                .filter { !$0.isEmpty }
            if corpora.contains(normalizedQuery) { return true }
            if corpora.contains(where: {
                $0.hasPrefix(normalizedQuery) || $0.contains(normalizedQuery)
            }) {
                return true
            }

            let queryTokens = Set(dockPillTokens(normalizedQuery))
            guard !queryTokens.isEmpty else { return false }
            let corpusTokens = Set(corpora.flatMap(dockPillTokens))
            if !queryTokens.intersection(corpusTokens).isEmpty { return true }

            for qt in queryTokens where qt.count >= 4 {
                for ct in corpusTokens where ct.count >= 4 {
                    if pillEditDistance(qt, ct) <= 2 { return true }
                }
            }
            return false
        }
        let pureScopeMenuLimit = 10
        let pureScopeCandidateLimit = 12
        let scopedRunningMenuMatches: (NSRunningApplication, String, Bool) -> [AXMenuItem] = {
            app, filterQ, preferCached in
            let pid = app.processIdentifier
            let cachedMatches = crossAppMenuItems.filter { item in
                item.sourcePID == pid
                    && menuItemMatchesQuery(item, filterQ)
            }
            let persistentMatches = persistentMenuMatches(
                app,
                filterQ,
                preferCached ? pureScopeCandidateLimit : 24
            )
            let matches = dedupeMenuItems(
                menuItemsAllowedForCurrentScope(cachedMatches + persistentMatches)
            )
            return orderedScopedMenuMatches(
                matches,
                filterQuery: filterQ,
                limit: preferCached ? pureScopeMenuLimit : 16
            )
        }
        let scopedClosedMenuMatches: (String, String, String, Bool) -> [AXMenuItem] = {
            bundleId, appName, filterQ, preferCached in
            let matches = dedupeMenuItems(
                menuItemsAllowedForCurrentScope(
                    persistentClosedAppMatches(
                        bundleId,
                        appName,
                        filterQ,
                        preferCached ? pureScopeCandidateLimit : 24
                    )
                )
            )
            return orderedScopedMenuMatches(
                matches,
                filterQuery: filterQ,
                limit: preferCached ? pureScopeMenuLimit : 16
            )
        }

        // Live menu items: primary (frontmost app) + optional cross-app when query targets another app
        let menuMatches: [AXMenuItem] = {
            if let installedMenuTarget {
                let filterQ = installedMenuTarget.actionQuery
                let preferCached = isExplicitAppScope && filterQ.isEmpty
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == installedMenuTarget.bundleId && !$0.isTerminated
                })
                if let targetApp {
                    return scopedRunningMenuMatches(targetApp, filterQ, preferCached)
                }
                return scopedClosedMenuMatches(
                    installedMenuTarget.bundleId,
                    installedMenuTarget.appName,
                    filterQ,
                    preferCached
                )
            }
            if let pinnedTarget = l2.targetApp,
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == pinnedTarget.bundleId
                })
            {
                let filterQ = scopedSearchQuery
                return scopedRunningMenuMatches(
                    targetApp,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
            }
            if let pinnedTarget = l2.targetApp {
                let matches = scopedClosedMenuMatches(
                    pinnedTarget.bundleId,
                    pinnedTarget.name,
                    scopedSearchQuery,
                    isExplicitAppScope && scopedSearchQuery.isEmpty
                )
                if !matches.isEmpty {
                    return matches
                }
            }
            if let explicitAppTarget,
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == explicitAppTarget.bundleId
                })
            {
                let filterQ = explicitAppTarget.actionQuery
                return scopedRunningMenuMatches(
                    targetApp,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
            }
            if let explicitAppTarget {
                let filterQ = explicitAppTarget.actionQuery
                let matches = scopedClosedMenuMatches(
                    explicitAppTarget.bundleId,
                    explicitAppTarget.appName,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
                if !matches.isEmpty {
                    return matches
                }
            }
            // Check if query starts with a known app name → cross-app mode (requires Cross-App Connect)
            if settings.crossAppPills, let (targetApp, actionQuery) = detectCrossAppQuery(q) {
                let filterQ = actionQuery.isEmpty ? q : actionQuery
                let candidateLimit = filterQ.isEmpty ? 80 : 24
                let cachedMatches = crossAppMenuItems.filter { item in
                    item.sourcePID == targetApp.processIdentifier
                        && menuItemMatchesQuery(item, filterQ)
                }
                let matches = dedupeMenuItems(
                    menuItemsAllowedForCurrentScope(
                        cachedMatches + persistentMenuMatches(targetApp, filterQ, candidateLimit)
                    )
                )
                return orderedScopedMenuMatches(matches, filterQuery: filterQ, limit: 16)
            }
            // Default: frontmost app's real menu items first — query-time AX search is primary.
            let cachedMatches = liveMenuItems.filter { item in
                menuItemMatchesQuery(item, q)
            }
            let persistentMatches: [AXMenuItem] = {
                guard let app = AppDelegate.shared?.previousFrontmostApp else { return [] }
                return persistentMenuMatches(app, q, 24)
            }()
            let matches = dedupeMenuItems(
                menuItemsAllowedForCurrentScope(cachedMatches + persistentMatches)
            )
            return Array(
                matches.sorted {
                    let aFav = favs.contains($0.title) ? 0 : 1
                    let bFav = favs.contains($1.title) ? 0 : 1
                    if aFav != bFav { return aFav < bFav }
                    let aTitle = $0.title.lowercased().hasPrefix(q) ? 0 : 1
                    let bTitle = $1.title.lowercased().hasPrefix(q) ? 0 : 1
                    if aTitle != bTitle { return aTitle < bTitle }
                    return $0.path.count < $1.path.count
                }.prefix(16))
        }()

        // Context-reactive pills — menu items that just became enabled after a selection change.
        // Only shown when the user hasn't typed a query (they'd surface via menuMatches otherwise).
        if q.isEmpty && !shouldSuppressMenuForContext && menuMatches.isEmpty
            && !contextMenuPills.isEmpty
        {
            for item in menuItemsAllowedForCurrentScope(contextMenuPills) {
                let path = item.path
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let sc = item.shortcutChar
                let mod = item.shortcutModifiers
                let badge: String? =
                    item.shortcutDisplay ?? (path.count >= 2 ? path[path.count - 2] : nil)
                let pill = makeMenuDockPill(
                    id: "ctx-menu-\(item.id)",
                    item: item,
                    sourceBundleId: scopedBundleId,
                    sourceAppName: scopedAppName,
                    accentColorName: "blue",
                    badge: badge,
                    trackingIdentifier:
                        "ctx-menu:\(scopedBundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [scopedAppName],
                    executeLeaf: {
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: sc,
                            shortcutModifiers: mod
                        )
                    }
                )
                pills.append(pill)
            }
        }

        let visibleMenuMatches: [AXMenuItem] = {
            if shouldSuppressMenuForContext { return [] }
            return hasStrongContextQuery ? Array(menuMatches.prefix(6)) : menuMatches
        }()

        for result in ctxExts {
            let ext = result.ilExtension
            let ctx = currentContext
            var pill = DockPill(
                id: "ctx-\(ext.id)", name: ext.name,
                icon: ext.icon, accentColorName: "teal", badge: nil,
                execute: { Task { await executeL2Extension(ext, context: ctx) } })
            pill.rankingKind = "contextExtension"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "ctxext:\(ext.id)"
            pill.searchTerms = [ext.name]
            pills.append(pill)
        }

        for sc in quickActions {
            var pill = DockPill(
                id: "qa-\(sc.id)", name: sc.name,
                icon: sc.iconName, accentColorName: nil, badge: nil,
                execute: { executeAppShortcut(sc) })
            pill.rankingKind = "quickAction"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "quick:\(sc.id)"
            pill.searchTerms = [sc.name]
            pills.append(pill)
        }
        for ext in userScriptExtensions {
            let icon = ext.scriptLanguage?.systemImage ?? "terminal"
            let displayName = ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized
            var pill = DockPill(
                id: "usr-script-\(ext.id.uuidString)",
                name: displayName,
                icon: icon,
                accentColorName: "green",
                badge: "Script",
                execute: { executeAppToolExtension(ext, launchQuery: scopedSearchQuery) }
            )
            pill.rankingKind = "userExtension"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "userext:\(scopedAppKey):\(ext.id.uuidString)"
            pill.searchTerms =
                [displayName, ext.toolName, ext.aiHint] + ext.profile.capabilities
                + ext.profile.exampleCommands
            pills.append(pill)
        }
        for package in visibleCLIPackages {
            let isTUI = TerminalAIBridge.shared.isTUICommand(package.command)
            let icon = isTUI ? "terminal.fill" : "chevron.left.forwardslash.chevron.right"
            let displayName = package.name.isEmpty ? package.command : package.name
            var pill = DockPill(
                id: "cli-\(scopedBundleId)-\(package.command)",
                name: displayName,
                icon: icon,
                accentColorName: "green",
                badge: "CLI",
                execute: { openCLIToolPanel(for: package) }
            )
            pill.rankingKind = "cliTool"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "cli:\(scopedBundleId):\(package.command)"
            pill.searchTerms =
                [displayName, package.command, package.description]
                + package.keywords
                + package.subcommands
                + package.taskCategories
                + Array(package.usageExamples.prefix(3))
            pills.append(pill)

            for sub in package.subcommands.prefix(4) {
                let fullCmd = "\(package.command) \(sub)"
                var subPill = DockPill(
                    id: "cli-sub-\(scopedBundleId)-\(fullCmd)",
                    name: sub,
                    icon: icon,
                    accentColorName: "green",
                    badge: package.command,
                    execute: {
                        attachCLIToolToCurrentDock(
                            command: fullCmd, package: package, runImmediately: true)
                    }
                )
                subPill.rankingKind = "cliTool"
                subPill.sourceBundleId = scopedBundleId
                subPill.sourceAppName = scopedAppName
                subPill.trackingIdentifier = "cli-sub:\(scopedBundleId):\(fullCmd)"
                subPill.searchTerms = [sub, fullCmd, displayName, package.command]
                pills.append(subPill)
            }
        }
        for tool in appTools {
            var pill = DockPill(
                id: "tool-\(tool.toolName)", name: tool.displayName,
                icon: tool.icon, accentColorName: "indigo", badge: nil,
                execute: {
                    l2.chatMessages.append(AIChatMessage(role: .user, content: tool.displayName))
                    l2.isLoading = true
                    Task {
                        let (ok, out) = await L2ExtensionManager.shared.execute(
                            toolName: tool.toolName, arguments: [:])
                        await MainActor.run {
                            let msg =
                                ok
                                ? (out.isEmpty ? "✅ \(tool.displayName) done." : out)
                                : "❌ \(tool.displayName) failed: \(out)"
                            l2.chatMessages.append(AIChatMessage(role: .assistant, content: msg))
                            l2.isLoading = false
                        }
                    }
                })
            pill.rankingKind = "tool"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "tool:\(scopedBundleId):\(tool.toolName)"
            pill.searchTerms = [tool.displayName, tool.toolName]
            pills.append(pill)
        }
        for action in visibleAdapterActions {
            let cliCommand =
                action.cliToolCommand?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let pillName =
                action.type == .cliTool && !cliCommand.isEmpty
                ? cliCommand
                : action.name
            var pill = DockPill(
                id: "adapter-\(scopedBundleId)-\(action.id)",
                name: pillName,
                icon: action.icon,
                accentColorName: action.accentColor ?? "blue",
                badge: action.type == .menubar
                    ? "Custom" : (action.type == .cliTool ? "CLI" : action.type.displayName),
                execute: {
                    if action.type == .cliTool, !cliCommand.isEmpty {
                        attachCLIToolToCurrentDock(
                            command: cliCommand,
                            bundleIdentifier: scopedBundleId,
                            appName: scopedAppName
                        )
                        return
                    }
                    let capturedContext = effectiveAXContextForConversation()
                    Task {
                        AppInteractionStore.shared.record(
                            bundleId: scopedBundleId,
                            appName: scopedAppName,
                            query: scopedSearchQuery.isEmpty ? action.name : scopedSearchQuery,
                            kind: action.type == .pageJS ? .pageJS : .adapterAction,
                            actionId: action.id
                        )
                        let result = await adapterManager.execute(
                            action,
                            context: capturedContext,
                            targetBundleId: scopedBundleId,
                            query: scopedSearchQuery
                        )
                        await MainActor.run {
                            if action.type == .aiPrompt, result.0, !result.1.isEmpty {
                                searchState.query = result.1
                                isSearchFieldFocused = true
                            }
                        }
                    }
                })
            pill.rankingKind = action.type == .cliTool ? "cliTool" : "adapter"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "adapter:\(scopedBundleId):\(action.id)"
            pill.searchTerms =
                [action.name, pillName, action.description, action.type.displayName, cliCommand]
                + action.triggers
            pills.append(pill)

            // For CLI tool adapter actions, also emit subcommand pills so the user
            // gets the same scannable help-command pills as standalone CLI packages.
            if action.type == .cliTool, !cliCommand.isEmpty,
                let pkg = terminalPackageManager.packages.first(where: {
                    $0.command.caseInsensitiveCompare(cliCommand) == .orderedSame
                })
            {
                for sub in pkg.subcommands.prefix(5) {
                    let fullCmd = "\(cliCommand) \(sub)"
                    var subPill = DockPill(
                        id: "adapter-sub-\(scopedBundleId)-\(fullCmd)",
                        name: sub,
                        icon: action.icon,
                        accentColorName: action.accentColor ?? "green",
                        badge: cliCommand,
                        execute: {
                            attachCLIToolToCurrentDock(
                                command: fullCmd,
                                package: pkg,
                                runImmediately: true
                            )
                        }
                    )
                    subPill.rankingKind = "cliTool"
                    subPill.sourceBundleId = scopedBundleId
                    subPill.sourceAppName = scopedAppName
                    subPill.trackingIdentifier = "adapter-sub:\(scopedBundleId):\(fullCmd)"
                    subPill.searchTerms = [sub, fullCmd, action.name, cliCommand] + pkg.keywords
                    pills.append(subPill)
                }
            }
        }

        if !useSeededMenuPills || hasStrongContextQuery {
            for item in visibleMenuMatches {
                let path = item.path
                let menuBundleId = activeBundleId
                let menuAppName = item.sourceAppName.isEmpty ? scopedAppName : item.sourceAppName
                let menuAppPath =
                    installedMenuTarget?.bundleId == menuBundleId
                    ? installedMenuTarget?.appPath
                    : allApplications.first { result in
                        Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
                            == menuBundleId
                    }?.subtitle
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (menuBundleId.isEmpty
                        ? (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                        : 0)
                // Only show source badge for cross-app items; Apple menu items are universal — no badge
                let isFrontmost =
                    sourcePID == (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let pillBadge: String? = {
                    if isAppleMenuItem(item) { return nil }  // universal — no app badge
                    if !item.sourceAppName.isEmpty && !isFrontmost {
                        return item.sourceAppName  // cross-app badge
                    }
                    return path.count >= 2 ? path[path.count - 2] : nil  // parent menu name
                }()
                let shortcutChar = item.shortcutChar
                let shortcutMods = item.shortcutModifiers
                let shortcutHint = item.shortcutDisplay

                let isFav = favs.contains(item.title)
                var pill = makeMenuDockPill(
                    id: "menu-\(item.id)",
                    item: item,
                    sourceBundleId: menuBundleId,
                    sourceAppName: menuAppName,
                    accentColorName: isFav ? "yellow" : "gray",
                    badge: shortcutHint ?? pillBadge,
                    trackingIdentifier:
                        "menu:\(menuBundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [menuAppName],
                    executeLeaf: {
                        AppInteractionStore.shared.record(
                            bundleId: menuBundleId,
                            appName: menuAppName,
                            query: item.title,
                            kind: .menuItem,
                            actionId: path.joined(separator: " > ")
                        )
                        if sourcePID == 0, !menuBundleId.isEmpty {
                            executeCachedMenuAction(
                                bundleIdentifier: menuBundleId,
                                appName: menuAppName,
                                appPath: menuAppPath,
                                path: path,
                                shortcutChar: shortcutChar,
                                shortcutModifiers: shortcutMods
                            )
                            return
                        }
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutMods
                        )
                    })
                pill.isFavourited = isFav
                if item.children.isEmpty, sourcePID != 0, item.title.lowercased().hasPrefix("share")
                {
                    pill = DockPill(
                        id: pill.id, name: pill.name,
                        icon: "square.and.arrow.up",
                        accentColorName: "blue",
                        badge: pill.badge,
                        execute: { showShareSheetForContext() })
                    pill.isShareAction = true
                    pill.isFavourited = isFav
                    pill.menuItemName = item.title
                    pill.sourceBundleId = menuBundleId
                    pill.sourceAppName = menuAppName
                    pill.menuContext = menuContextLabel(from: item.path)
                    pill.rankingKind = "menu"
                    pill.hasLiveAvailability = item.hasLiveAvailability
                    pill.menuStatusBadge = menuStatusBadge(
                        for: item, bundleIdentifier: menuBundleId)
                    pill.trackingIdentifier =
                        "menu:\(menuBundleId):\(path.joined(separator: " > ").lowercased())"
                    pill.searchTerms = item.path + [menuAppName, "share"]
                }
                pills.append(pill)
            }
        }
        if !isExplicitAppScope {
            if !(isGlobalContextActive && hasActiveDockContextSelection) {
                pills += crossAppPills
            }
        }
        let resolvedRulePills = AXTriggerRuleEngine.shared.evaluate(context: axContext)
        if !isExplicitAppScope {
            let filteredRulePills =
                q.isEmpty
                ? resolvedRulePills : resolvedRulePills.filter { $0.name.lowercased().contains(q) }
            pills += filteredRulePills.map { r in
                DockPill(
                    id: r.id, name: r.name, icon: r.icon, accentColorName: r.accentColor,
                    badge: nil, execute: r.execute)
            }
        }

        let rankingQuery = isExplicitAppScope ? scopedSearchQuery : q
        let ranked = rankDockPills(
            pills,
            rawQuery: q,
            rankingQuery: rankingQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            isExplicitAppScope: isExplicitAppScope
        )
        let dedupedRanked = dedupeRankedDockPills(ranked)
        // Treat menu enabled state as advisory. Some apps lazily validate menus only when
        // their native menu opens, so AX can report a runnable action as disabled.
        let enabled = dedupedRanked.filter { pill in
            if isStaleAvailabilityMenuPill(pill) { return true }
            if !q.isEmpty,
                pill.rankingKind == "menu" || pill.rankingKind == "finderMenu",
                dockPillHasQuerySignal(
                    pill,
                    query: rankingQuery,
                    rawQuery: q,
                    scopedBundleId: scopedBundleId,
                    scopedAppName: scopedAppName
                )
            {
                return true
            }
            return pill.isEnabled || pill.rankingKind.isEmpty || pill.rankingKind == "appLaunch"
                || pill.rankingKind == "finderSelection" || pill.rankingKind == "payload"
                || pill.rankingKind == "cliTool" || pill.rankingKind == "tool"
                || pill.rankingKind == "userExtension" || pill.rankingKind == "submenuChild"
                || pill.rankingKind == "submenuParent"
        }

        // When global context has an active file/folder/text selection and no explicit app scope,
        // keep the Finder/menu surface broad. The selection state should feel like the native
        // menu bar after selecting a file: File/Edit/View/Go/Window/Help commands stay available,
        // while app launch/recent-app rows are still removed by the selection-scoped filter.
        guard isGlobalContextActive && hasActiveDockContextSelection && !isExplicitAppScope else {
            return enabled
        }
        return selectionScopedDockPills(enabled)
    }

    // MARK: - System Settings Deep-Link Pills

    func buildGlobalAppleMenuFallbackPills(query q: String) -> [DockPill] {
        let normalizedQuery = normalizedDockPillText(q)
        guard !normalizedQuery.isEmpty else { return [] }

        typealias AppleCommand = (name: String, aliases: [String], icon: String, action: () -> Void)
        let commands: [AppleCommand] = [
            (
                "About This Mac", ["about", "mac", "about this mac"], "laptopcomputer",
                {
                    clickAppleMenuItem(named: "About This Mac")
                }
            ),
            (
                "System Settings...",
                ["settings", "system settings", "preferences", "system preferences"], "gearshape",
                {
                    NSWorkspace.shared.open(
                        URL(fileURLWithPath: "/System/Applications/System Settings.app"))
                }
            ),
            (
                "App Store...", ["app store", "updates", "software"], "app.badge",
                {
                    NSWorkspace.shared.open(
                        URL(fileURLWithPath: "/System/Applications/App Store.app"))
                }
            ),
            (
                "Force Quit...", ["force quit", "quit app", "force"], "exclamationmark.octagon",
                {
                    clickAppleMenuItem(named: "Force Quit...")
                }
            ),
            (
                "Sleep", ["sleep", "slee", "standby"], "moon",
                {
                    runAppleMenuScript(#"tell application "System Events" to sleep"#)
                }
            ),
            (
                "Restart...", ["restart", "reboot"], "arrow.clockwise.circle",
                {
                    clickAppleMenuItem(named: "Restart...")
                }
            ),
            (
                "Shut Down...", ["shutdown", "shut down", "power off"], "power",
                {
                    clickAppleMenuItem(named: "Shut Down...")
                }
            ),
            (
                "Lock Screen", ["lock", "lock screen"], "lock",
                {
                    runAppleMenuScript(
                        #"tell application "System Events" to keystroke "q" using {control down, command down}"#
                    )
                }
            ),
            (
                "Log Out...", ["log out", "logout", "sign out"],
                "rectangle.portrait.and.arrow.right",
                {
                    clickAppleMenuItem(named: "Log Out...")
                }
            ),
        ]

        return commands.compactMap { command -> DockPill? in
            let haystack = ([command.name] + command.aliases)
                .map(normalizedDockPillText)
                .joined(separator: " ")
            let tokenMatch =
                normalizedQuery
                .split(separator: " ")
                .allSatisfy { haystack.contains($0) }
            guard haystack.contains(normalizedQuery) || tokenMatch else { return nil }

            var pill = DockPill(
                id: "apple-menu-fallback-\(normalizedDockPillText(command.name))",
                name: command.name,
                icon: command.icon,
                accentColorName: "gray",
                badge: "Apple Menu",
                execute: command.action
            )
            pill.menuContext = "Apple Menu"
            pill.rankingKind = "menu"
            pill.sourceAppName = "Apple Menu"
            pill.searchTerms = [command.name] + command.aliases
            pill.trackingIdentifier = "apple-menu:\(normalizedDockPillText(command.name))"
            pill.rankingScore = command.name.lowercased().hasPrefix(normalizedQuery) ? 600 : 420
            return pill
        }
    }

    func clickAppleMenuItem(named itemName: String) {
        let escaped = itemName.replacingOccurrences(of: "\"", with: "\\\"")
        let script = """
            tell application "System Events"
                set frontProc to first application process whose frontmost is true
                click menu item "\(escaped)" of menu 1 of menu bar item 1 of menu bar 1 of frontProc
            end tell
            """
        runAppleMenuScript(script)
    }

    func runAppleMenuScript(_ source: String) {
        Task.detached(priority: .userInitiated) {
            var error: NSDictionary?
            NSAppleScript(source: source)?.executeAndReturnError(&error)
            if let error {
                await MainActor.run {
                    AppToast.show(
                        error[NSAppleScript.errorMessage] as? String
                            ?? "Apple menu action unavailable",
                        icon: "exclamationmark.triangle",
                        tint: .orange.opacity(0.9)
                    )
                }
            }
        }
    }

