    @ViewBuilder
    func pillScrollRowItem(pill: DockPill, index: Int) -> some View {
        let base = unifiedPillButton(pill: pill, index: index)
            .id("pill-\(index)")
            .transition(.scale(scale: 0.8).combined(with: .opacity))
        let scaled =
            base
            .scaleEffect(dockMagnificationScale(for: index), anchor: .bottom)
            .animation(.spring(response: 0.18, dampingFraction: 0.65), value: hoveredDockPillIndex)
        scaled.scrollTransition(.interactive, axis: .horizontal) { effect, phase in
            effect
                .rotation3DEffect(
                    .degrees(phase.value * 22),
                    axis: (x: 0, y: 1, z: 0),
                    perspective: 0.45
                )
                .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
        }
    }

    @ViewBuilder
    func dockPillScrollRow(pills: [DockPill], appQuery: String = "") -> some View {
        // Filtered app icons: pinned + running apps whose name starts with or contains the query.
        // Suppressed in global context with an active selection — queries filter context pills there.
        let filteredApps:
            [(
                icon: NSImage?, label: String, bundleId: String?, isRunning: Bool,
                action: () -> Void
            )] = {
                guard !appQuery.isEmpty, !isExplicitAppScope, !isGlobalContextActive else {
                    return []
                }
                let q = appQuery.lowercased()
                var seen = Set<String>()
                var results:
                    [(
                        icon: NSImage?, label: String, bundleId: String?, isRunning: Bool,
                        action: () -> Void
                    )] = []
                // Pinned apps
                for app in settings.pinnedApps where app.type == .application {
                    let name = app.name.lowercased()
                    guard name.hasPrefix(q) || (q.count >= 2 && name.contains(q)) else { continue }
                    let key = app.bundleIdentifier ?? app.path
                    guard seen.insert(key).inserted else { continue }
                    let isRunning = runningApp(for: app) != nil
                    let icon = resolvedPinnedIcon(for: app)
                    let captured = app
                    results.append(
                        (
                            icon: icon, label: app.name, bundleId: app.bundleIdentifier,
                            isRunning: isRunning, action: { launchPinnedApp(captured) }
                        ))
                    if results.count >= 5 { break }
                }
                // Running apps not already in pinned
                for app in runningRegularApps where results.count < 5 {
                    guard let name = app.localizedName else { continue }
                    let lname = name.lowercased()
                    guard lname.hasPrefix(q) || (q.count >= 2 && lname.contains(q)) else {
                        continue
                    }
                    let key = app.bundleIdentifier ?? "\(app.processIdentifier)"
                    guard seen.insert(key).inserted else { continue }
                    let icon = resolvedRunningAppIcon(for: app)
                    let captured = app
                    results.append(
                        (
                            icon: icon, label: name, bundleId: app.bundleIdentifier,
                            isRunning: true, action: { activateRunningAppFromDock(captured) }
                        ))
                }
                return results
            }()

        Group {
            if let focIdx = l2.focusedPillIndex, !pills.isEmpty, focIdx < pills.count {
                // ── Cascade: at 820pt show prev2+prev+focused+next; at 640pt show prev+focused+next ──
                let leftSlots = visibleDockWidth >= 750 ? 2 : 1
                let prev2: Int? =
                    leftSlots >= 2
                    ? {
                        let i = focIdx - 2
                        guard i >= 0, !pills[i].isSeparator else { return nil }
                        return i
                    }() : nil
                let prev1: Int? = {
                    let i = focIdx - 1
                    guard i >= 0, !pills[i].isSeparator else { return nil }
                    return i
                }()
                let next1: Int? = {
                    let i = focIdx + 1
                    guard i < pills.count, !pills[i].isSeparator else { return nil }
                    return i
                }()
                HStack(spacing: 6) {
                    // Prev2 (only on wide dock)
                    if let p2 = prev2 {
                        unifiedPillButton(pill: pills[p2], index: p2)
                            .transition(
                                .asymmetric(
                                    insertion: .opacity.combined(with: .scale(scale: 0.9)),
                                    removal: .opacity.combined(with: .scale(scale: 0.9))))
                    }
                    // Prev
                    if let p1 = prev1 {
                        unifiedPillButton(pill: pills[p1], index: p1)
                            .transition(
                                .asymmetric(
                                    insertion: .opacity.combined(with: .scale(scale: 0.9)),
                                    removal: .opacity.combined(with: .scale(scale: 0.9))))
                    }
                    // Focused — expanded bright pill, fills remaining space
                    unifiedPillButton(pill: pills[focIdx], index: focIdx, isExpanded: true)
                        .frame(maxWidth: .infinity)
                        .transition(.opacity)
                    // Next
                    if let n1 = next1 {
                        unifiedPillButton(pill: pills[n1], index: n1)
                            .transition(
                                .asymmetric(
                                    insertion: .opacity.combined(with: .scale(scale: 0.9)),
                                    removal: .opacity.combined(with: .scale(scale: 0.9))))
                    }
                }
                .animation(.spring(response: 0.22, dampingFraction: 0.78), value: focIdx)
            } else {
                // ── Normal scrollable row ─────────────────────────────────────────────
                ScrollViewReader { proxy in
                    ScrollView(.horizontal, showsIndicators: false) {
                        LazyHStack(spacing: 6) {
                            if !pills.isEmpty {
                                ForEach(Array(pills.enumerated()), id: \.element.id) { idx, pill in
                                    pillScrollRowItem(pill: pill, index: idx)
                                }
                            } else {
                                Spacer(minLength: 0)
                            }
                        }
                    }
                    .onChange(of: l2.focusedPillIndex) { newIndex in
                        guard l2.pillNavViaKeyboard, let idx = newIndex else { return }
                        withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                            proxy.scrollTo("pill-\(idx)", anchor: .center)
                        }
                        refreshQuickLookPreviewForCurrentFocusIfVisible()
                        if idx < pills.count, pills[idx].isShareAction {
                            showShareSheetForContext()
                        }
                    }
                }
            }  // end else
        }  // end Group
        .onHover { hovering in
            guard acceptsMouseDrivenDockInteraction else { return }
            isHoveringPillRow = hovering
            if !hovering { pillScrollAccumulator = 0 }
        }
    }

    // MARK: - List view (Spotlight / Raycast-style vertical result sheet)

    func dockPillListView(pills: [DockPill]) -> some View {
        let visiblePills = Array(pills.prefix(maxListViewDockPills))
        return ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                LazyVStack(spacing: 2) {
                    ForEach(Array(visiblePills.enumerated()), id: \.element.id) { idx, pill in
                        if pill.isSeparator {
                            if !pill.name.isEmpty {
                                HStack {
                                    Text(pill.name.uppercased())
                                        .font(
                                            .system(size: 10, weight: .semibold, design: .rounded)
                                        )
                                        .foregroundStyle(.tertiary)
                                        .tracking(0.7)
                                    Spacer()
                                }
                                .padding(.horizontal, 12)
                                .padding(.top, idx == 0 ? 2 : 8)
                                .padding(.bottom, 1)
                                .id("pill-list-\(pill.id)")
                            }
                        } else {
                            let currentGroup = dockListGroupTitle(for: pill)
                            let previousGroup: String? = {
                                guard idx > 0 else { return nil }
                                let previous = visiblePills[idx - 1]
                                guard !previous.isSeparator else { return nil }
                                return dockListGroupTitle(for: previous)
                            }()
                            if currentGroup != previousGroup {
                                resultGroupHeader(currentGroup)
                                    .padding(.top, idx == 0 ? 0 : 6)
                            }
                            pillListRow(pill: pill, index: idx)
                                .id("pill-list-\(pill.id)")
                        }
                    }
                }
                .padding(6)
            }
            .frame(height: listViewVisibleHeight)
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            .onChange(of: l2.focusedPillIndex) { newIndex in
                guard l2.pillNavViaKeyboard, let idx = newIndex else { return }
                guard idx < visiblePills.count else { return }
                withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                    proxy.scrollTo("pill-list-\(visiblePills[idx].id)", anchor: .center)
                }
            }
        }
    }

    func dockListGroupTitle(for pill: DockPill) -> String {
        let kind = pill.rankingKind.lowercased()
        let badge = (pill.badge ?? "").lowercased()
        let context = (pill.menuContext ?? "").lowercased()
        let name = pill.name.lowercased()

        if kind == "clipboard" {
            return "Clipboard Items"
        }
        if kind == "findermenu" {
            return "Finder Menus"
        }
        if kind == "finderselection" || kind == "findercontext" {
            return "Finder Actions"
        }
        if kind == "findergoto" {
            return "Home Folders"
        }
        if kind == "findercurrent" || kind == "findersearch" {
            if pill.icon.localizedCaseInsensitiveContains("folder")
                || badge.contains("folder")
                || name.contains("folder")
            {
                return kind == "findercurrent" ? "Current Folder" : "Home Folders"
            }
            return "Files"
        }
        if kind.contains("finder") || badge.contains("finder") {
            return "Finder"
        }
        if kind.contains("menu") || !context.isEmpty {
            if let root = dockMenuRootTitle(for: pill) {
                return root == "Apple" ? "Apple Menu" : "\(root) Menu"
            }
            if let context = pill.menuContext, !context.isEmpty {
                return context == "Apple Menu" ? context : "\(context) Menu"
            }
            return "Menus"
        }
        if kind.contains("semantic") || kind.contains("payload") {
            return "Actions"
        }
        if kind.contains("applaunch") {
            return "Apps"
        }
        if badge.contains("folder") {
            return "Folders"
        }
        if badge.contains("file") || name.contains(".") {
            return "Files"
        }
        return "Actions"
    }

    func dockMenuRootTitle(for pill: DockPill) -> String? {
        let knownRoots = [
            "Apple", "File", "Edit", "Selection", "View", "Go", "Run", "Terminal",
            "Window", "Help", "History", "Bookmarks", "Navigate", "Product",
            "Debug", "Source Control", "Format", "Tools", "Playback", "Controls",
            "Audio", "Video", "Subtitles",
        ]
        for term in pill.searchTerms {
            let cleaned = term.trimmingCharacters(in: .whitespacesAndNewlines)
            if let match = knownRoots.first(where: {
                normalizedDockPillText($0) == normalizedDockPillText(cleaned)
            }) {
                return match
            }
        }
        return nil
    }

    // Liquid glass floating suggestion panel — appears below input like the macOS autocomplete popover.
    @ViewBuilder
    func submenuDropdownView(parent: AXMenuItem, children: [AXMenuItem], prefix: String)
        -> some View
    {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                VStack(alignment: .leading, spacing: 0) {
                    // "Sort By" section header
                    Text(parent.title)
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 16)
                        .padding(.top, 12)
                        .padding(.bottom, 4)

                    ForEach(Array(children.enumerated()), id: \.element.id) { idx, child in
                        let isHov = listViewHoveredIndex == (10000 + idx)
                        let isKeyFocused = l2.focusedPillIndex == idx
                        let isActive = isHov || isKeyFocused

                        Button {
                            let frontPID =
                                AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
                            let pid = child.sourcePID != 0 ? child.sourcePID : frontPID
                            let path = child.path
                            let sc = child.shortcutChar
                            let mod = child.shortcutModifiers
                            searchState.query = ""
                            lockedSubmenuParent = nil
                            executeDockMenuAction(
                                sourcePID: pid, path: path, shortcutChar: sc, shortcutModifiers: mod
                            )
                        } label: {
                            HStack(spacing: 10) {
                                // Prefix bold: typed part in accentColor, rest in primary
                                if !prefix.isEmpty,
                                    child.title.lowercased().hasPrefix(prefix)
                                {
                                    let boldPart = String(child.title.prefix(prefix.count))
                                    let restPart = String(child.title.dropFirst(prefix.count))
                                    HStack(spacing: 0) {
                                        Text(boldPart)
                                            .font(.system(size: 14, weight: .bold))
                                            .foregroundStyle(Color.accentColor)
                                        Text(restPart)
                                            .font(.system(size: 14, weight: .regular))
                                            .foregroundStyle(Color(nsColor: .labelColor))
                                    }
                                } else {
                                    Text(child.title)
                                        .font(.system(size: 14, weight: .regular))
                                        .foregroundStyle(Color(nsColor: .labelColor))
                                }
                                Spacer()
                                if let sc = child.shortcutDisplay, !sc.isEmpty {
                                    Text(sc)
                                        .font(.system(size: 11, weight: .medium))
                                        .foregroundStyle(.secondary.opacity(0.55))
                                        .padding(.horizontal, 5)
                                        .padding(.vertical, 2)
                                        .background(
                                            .regularMaterial,
                                            in: RoundedRectangle(cornerRadius: 4)
                                        )
                                }
                            }
                            .padding(.horizontal, 12)
                            .padding(.vertical, 8)
                            .background(
                                isActive
                                    ? Color(nsColor: .labelColor).opacity(0.07)
                                    : Color.clear,
                                in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                            )
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .onHover { h in
                            guard acceptsMouseDrivenDockInteraction else { return }
                            listViewHoveredIndex = h ? (10000 + idx) : nil
                        }
                        .padding(.horizontal, 6)
                        .id("submenu-drop-\(idx)")
                    }
                    .padding(.bottom, 8)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: 280)
            .background(.regularMaterial)
            .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .strokeBorder(.white.opacity(0.14), lineWidth: 0.5)
            )
            .shadow(color: .black.opacity(0.18), radius: 20, x: 0, y: 8)
            .onChange(of: l2.focusedPillIndex) { newIndex in
                guard let idx = newIndex else { return }
                withAnimation(.spring(response: 0.2, dampingFraction: 0.85)) {
                    proxy.scrollTo("submenu-drop-\(idx)", anchor: .center)
                }
            }
        }
        .transition(
            .asymmetric(
                insertion: .opacity.combined(
                    with: .scale(
                        scale: 0.95,
                        anchor: settings.effectiveDockAtBottom ? .bottom : .top)
                ),
                removal: .opacity.combined(
                    with: .scale(
                        scale: 0.95,
                        anchor: settings.effectiveDockAtBottom ? .bottom : .top)
                )
            ))
    }

    @ViewBuilder
    func findTokenChip(_ token: AppFindToken) -> some View {
        let selectedTitle =
            token.selectedMenu?.title.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let label = token.title
        HStack(spacing: 0) {
            Button {
                clearFindToken(preserveQuery: true)
            } label: {
                Text(label)
                    .font(.system(size: 13, weight: .semibold))
                    .foregroundStyle(Color(nsColor: .labelColor))
                    .lineLimit(1)
                    .padding(.leading, 10)
                    .padding(.trailing, token.hasChildMenu ? 6 : 10)
            }
            .buttonStyle(.plain)
            .help(selectedTitle.isEmpty ? "Remove Find mode" : selectedTitle)

            if token.hasChildMenu {
                Button {
                    withAnimation(.spring(response: 0.2, dampingFraction: 0.82)) {
                        showFindTokenMenu.toggle()
                        l2.focusedPillIndex = nil
                        listViewHoveredIndex = nil
                    }
                } label: {
                    ZStack {
                        Circle()
                            .fill(Color(nsColor: .labelColor).opacity(0.88))
                            .frame(width: 20, height: 20)
                        Image(systemName: "chevron.right")
                            .font(.system(size: 8, weight: .bold))
                            .foregroundStyle(Color(nsColor: .windowBackgroundColor))
                    }
                    .padding(.trailing, 4)
                }
                .buttonStyle(.plain)
                .help("Choose Find menu")
            }

            if !selectedTitle.isEmpty {
                Text(selectedTitle)
                    .font(.system(size: 12, weight: .medium))
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
                    .padding(.trailing, 9)
            }
        }
        .frame(height: 30)
        .background(.regularMaterial, in: Capsule())
        .overlay(
            Capsule()
                .strokeBorder(.white.opacity(showFindTokenMenu ? 0.32 : 0.18), lineWidth: 0.7)
        )
        .shadow(color: .black.opacity(0.12), radius: 4, x: 0, y: 2)
        .animation(.spring(response: 0.22, dampingFraction: 0.8), value: selectedTitle)
    }

    @ViewBuilder
    func findTokenDropdownView(_ token: AppFindToken) -> some View {
        let children = token.parentMenu.map(leafFindChildren(for:)) ?? []
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: 0) {
                Text("Find in \(token.targetAppName)")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 16)
                    .padding(.top, 12)
                    .padding(.bottom, 4)

                ForEach(Array(children.enumerated()), id: \.element.id) { idx, child in
                    let isHov = listViewHoveredIndex == (12000 + idx)
                    let selected = token.selectedMenu?.id == child.id
                    Button {
                        withAnimation(.spring(response: 0.2, dampingFraction: 0.82)) {
                            if var updatedToken = lockedFindToken {
                                updatedToken.selectedMenu = child
                                lockedFindToken = updatedToken
                            }
                            showFindTokenMenu = false
                            listViewHoveredIndex = nil
                        }
                        DispatchQueue.main.async { isSearchFieldFocused = true }
                    } label: {
                        HStack(spacing: 10) {
                            Image(
                                systemName: selected
                                    ? "checkmark.circle.fill" : menuSymbol(for: child)
                            )
                            .font(.system(size: 14, weight: .semibold))
                            .foregroundStyle(selected ? Color.accentColor : Color.secondary)
                            .frame(width: 20)
                            Text(child.title)
                                .font(.system(size: 14, weight: selected ? .semibold : .regular))
                                .foregroundStyle(Color(nsColor: .labelColor))
                                .lineLimit(1)
                            Spacer()
                            if let shortcut = child.shortcutDisplay, !shortcut.isEmpty {
                                Text(shortcut)
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundStyle(.secondary.opacity(0.55))
                                    .padding(.horizontal, 5)
                                    .padding(.vertical, 2)
                                    .background(
                                        .regularMaterial,
                                        in: RoundedRectangle(cornerRadius: 4)
                                    )
                            }
                        }
                        .padding(.horizontal, 12)
                        .padding(.vertical, 8)
                        .background(
                            (isHov || selected)
                                ? Color(nsColor: .labelColor).opacity(selected ? 0.10 : 0.07)
                                : Color.clear,
                            in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                        )
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .onHover { hovering in
                        guard acceptsMouseDrivenDockInteraction else { return }
                        listViewHoveredIndex = hovering ? (12000 + idx) : nil
                    }
                    .padding(.horizontal, 6)
                }
                .padding(.bottom, 8)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: 280)
        .background(.regularMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .strokeBorder(.white.opacity(0.14), lineWidth: 0.5)
        )
        .shadow(color: .black.opacity(0.18), radius: 20, x: 0, y: 8)
        .transition(
            .asymmetric(
                insertion: .opacity.combined(
                    with: .scale(
                        scale: 0.95,
                        anchor: settings.effectiveDockAtBottom ? .bottom : .top)
                ),
                removal: .opacity.combined(
                    with: .scale(
                        scale: 0.95,
                        anchor: settings.effectiveDockAtBottom ? .bottom : .top)
                )
            ))
    }

