    func l2ApprovalCardMeta(_ msg: AIChatMessage) -> (
        purpose: String, risk: String, isDockCommand: Bool
    ) {
        let sd = msg.structuredData ?? ""
        if sd.hasPrefix("dock_cmd|||") {
            return (String(sd.dropFirst("dock_cmd|||".count)), "Moderate", true)
        }
        let parts = sd.components(separatedBy: "|||/")
        return (parts.first ?? "", parts.count > 1 ? parts[1] : "Unknown", false)
    }

    @ViewBuilder
    func l2InlineApprovalCard(_ msg: AIChatMessage) -> some View {
        let (purpose, risk, isDockCommand) = l2ApprovalCardMeta(msg)
        let isHighRisk =
            risk.lowercased().contains("high") || risk.lowercased().contains("critical")
        let isHandled = l2.handledApprovalIds.contains(msg.id)
        let isPending = isDockCommand ? !isHandled : (terminalBridge.pendingApproval != nil)
        let termIconColor: SwiftUI.Color =
            isHandled ? .green : (isHighRisk ? .orange : .accentColor)

        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 6) {
                Image(systemName: "terminal.fill")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(termIconColor)
                Text(isHandled ? "Sent to terminal" : "Run command?")
                    .font(.system(size: 11, weight: .semibold))
                Spacer()
                if isHandled {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.system(size: 11))
                        .foregroundStyle(.green)
                } else if isHighRisk {
                    Text(risk)
                        .font(.system(size: 9, weight: .semibold))
                        .foregroundStyle(.orange)
                        .padding(.horizontal, 6).padding(.vertical, 2)
                        .background(Color.orange.opacity(0.15), in: Capsule())
                }
            }
            if !purpose.isEmpty {
                Text(purpose)
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
            }
            Text(msg.content)
                .font(.system(size: 11, design: .monospaced))
                .padding(.horizontal, 8).padding(.vertical, 5)
                .background(Color.black.opacity(0.35), in: RoundedRectangle(cornerRadius: 5))
                .frame(maxWidth: .infinity, alignment: .leading)
            if !isHandled {
                HStack(spacing: 8) {
                    Button("Deny") {
                        l2.handledApprovalIds.insert(msg.id)
                        if !isDockCommand { TerminalAIBridge.shared.denyCommand() }
                    }
                    .buttonStyle(.plain)
                    .font(.system(size: 11, weight: .medium))
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 12).padding(.vertical, 5)
                    .background(Color.primary.opacity(0.08), in: RoundedRectangle(cornerRadius: 6))
                    .disabled(!isPending)
                    Button {
                        if isDockCommand {
                            l2.handledApprovalIds.insert(msg.id)
                            // Ensure terminal is open and visible
                            if !livePanelVisible || livePanelMode != .terminal {
                                withAnimation(.spring(response: 0.28, dampingFraction: 0.85)) {
                                    livePanelMode = .terminal
                                    livePanelVisible = true
                                }
                            }
                            let consoleKey = activeConsoleKey
                            DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                                panelTerminal(for: consoleKey).sendCommand(msg.content)
                            }
                        } else {
                            TerminalAIBridge.shared.approveCommand(msg.content)
                        }
                    } label: {
                        HStack(spacing: 4) {
                            Image(systemName: "play.fill").font(.system(size: 9))
                            Text("Approve & Run")
                        }
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.white)
                        .padding(.horizontal, 14).padding(.vertical, 5)
                        .background(
                            isPending ? Color.accentColor : Color.gray,
                            in: RoundedRectangle(cornerRadius: 6))
                    }
                    .buttonStyle(.plain)
                    .disabled(!isPending)
                }
            }
        }
        .padding(12)
        .background(
            RoundedRectangle(cornerRadius: 10)
                .fill(cardBgFill(isHandled: isHandled, isHighRisk: isHighRisk))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 10)
                .strokeBorder(
                    cardBorderColor(isHandled: isHandled, isHighRisk: isHighRisk), lineWidth: 0.5)
        )
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    func cardBgFill(isHandled: Bool, isHighRisk: Bool) -> SwiftUI.Color {
        if isHandled { return SwiftUI.Color.green.opacity(0.06) }
        if isHighRisk { return SwiftUI.Color.orange.opacity(0.08) }
        return SwiftUI.Color.accentColor.opacity(0.07)
    }

    func cardBorderColor(isHandled: Bool, isHighRisk: Bool) -> SwiftUI.Color {
        if isHandled { return SwiftUI.Color.green.opacity(0.2) }
        if isHighRisk { return SwiftUI.Color.orange.opacity(0.25) }
        return SwiftUI.Color.accentColor.opacity(0.2)
    }

    // MARK: - Contextual Quick Actions (type-based)

    struct PanelAction: Identifiable {
        let id = UUID()
        let icon: String
        let label: String
        let action: () -> Void
    }

    func appScopeShortcuts(
        for appKey: String,
        placements: Set<AppShortcut.Placement>
    ) -> [AppShortcut] {
        let builtIns = AppShortcut.builtInDefaults.filter { shortcut in
            (shortcut.appKey == appKey || shortcut.targetAppKeys.contains(appKey))
                && placements.contains(shortcut.placement)
        }
        let custom: [AppShortcut] = {
            var shortcuts: [AppShortcut] = []
            if placements.contains(.quickActions) || placements.contains(.both) {
                shortcuts += settings.shortcuts(for: appKey)
            }
            if placements.contains(.contextDock) || placements.contains(.both) {
                shortcuts += settings.contextDockShortcuts(for: appKey)
            }
            return shortcuts
        }()
        var seen = Set<String>()
        return (builtIns + custom).filter { seen.insert($0.name).inserted }
    }

    func sortedAppScopeShortcuts(_ shortcuts: [AppShortcut], query: String) -> [AppShortcut]
    {
        let normalizedQuery = normalizedScopeIntentText(query)
        guard !normalizedQuery.isEmpty else { return shortcuts }
        let ranked = shortcuts.map { shortcut -> (AppShortcut, Double) in
            let score = scopeIntentScore(
                label: shortcut.name,
                keywords: shortcut.triggerKeywords,
                query: normalizedQuery
            )
            return (shortcut, score)
        }
        let hasPositiveMatch = ranked.contains { $0.1 > 0 }
        return
            ranked
            .filter { hasPositiveMatch ? $0.1 > 0 : true }
            .sorted { lhs, rhs in
                if lhs.1 == rhs.1 {
                    return lhs.0.name.localizedCaseInsensitiveCompare(rhs.0.name)
                        == .orderedAscending
                }
                return lhs.1 > rhs.1
            }
            .map(\.0)
    }

    func smartAppScopePanelActions(for appKey: String, query: String) -> [PanelAction] {
        guard appKey == "reminders" else { return [] }
        let normalizedQuery = normalizedScopeIntentText(query)
        guard !normalizedQuery.isEmpty else { return [] }

        let reminderTitle = reminderItemName(from: normalizedQuery)
        let listTitle = reminderListName(from: normalizedQuery)
        let wantsList = scopeIntentContainsAny(
            normalizedQuery,
            ["list", "shopping list", "todo list", "reminder list", "checklist"]
        )
        let wantsReminder = scopeIntentContainsAny(
            normalizedQuery,
            ["reminder", "remainder", "remind", "task", "todo", "to do"]
        )
        let createVerb = scopeIntentContainsAny(
            normalizedQuery,
            ["create", "new", "add", "make", "set"]
        )

        var ranked: [(PanelAction, Double)] = []
        if wantsReminder || createVerb {
            let score =
                (wantsReminder ? 80.0 : 30.0)
                + (createVerb ? 35.0 : 0.0)
                + (wantsList && !wantsReminder ? -18.0 : 0.0)
            ranked.append(
                (
                    PanelAction(
                        icon: "plus.circle",
                        label: reminderTitle.isEmpty ? "New Reminder" : "Add Reminder"
                    ) {
                        createReminderFromScopeQuery(reminderTitle)
                    },
                    score
                ))
        }

        if wantsList || normalizedQuery.contains("shopping") {
            let score =
                (wantsList ? 92.0 : 40.0)
                + (createVerb ? 30.0 : 0.0)
                + (normalizedQuery.contains("reminder list") ? 36.0 : 0.0)
            ranked.append(
                (
                    PanelAction(
                        icon: "list.bullet.rectangle",
                        label: listTitle.isEmpty ? "New List" : "Create List"
                    ) {
                        createReminderListFromScopeQuery(listTitle)
                    },
                    score
                ))
        }

        if normalizedQuery.contains("overdue") {
            ranked.append(
                (
                    PanelAction(icon: "exclamationmark.circle", label: "Overdue") {
                        searchState.query = "show overdue reminders"
                        handleRemPanelQuery()
                    },
                    120
                ))
        }

        if normalizedQuery.contains("today") {
            ranked.append(
                (
                    PanelAction(icon: "calendar", label: "Today") {
                        searchState.query = "show reminders due today"
                        handleRemPanelQuery()
                    },
                    112
                ))
        }

        return
            ranked
            .filter { $0.1 > 0 }
            .sorted { $0.1 > $1.1 }
            .map(\.0)
    }

    func createReminderFromScopeQuery(_ title: String) {
        let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            searchState.query = "create new reminder "
            return
        }
        let ok = AppleAppsAPI.shared.createReminder(title: trimmed)
        appendPanelMessage(
            AIChatMessage(
                role: .assistant,
                content: ok ? "Created reminder: \(trimmed)" : "Couldn't create that reminder.",
                isError: !ok
            )
        )
        if ok {
            searchState.query = ""
            reloadAppPanelData(for: "reminders")
        }
    }

    func createReminderListFromScopeQuery(_ title: String) {
        let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            searchState.query = "create new reminder list "
            return
        }
        let escaped = trimmed.replacingOccurrences(of: "\"", with: "\\\"")
        let script = """
            tell application "Reminders"
                activate
                make new list with properties {name:"\(escaped)"}
            end tell
            """
        var error: NSDictionary?
        NSAppleScript(source: script)?.executeAndReturnError(&error)
        let ok = error == nil
        appendPanelMessage(
            AIChatMessage(
                role: .assistant,
                content: ok ? "Created reminder list: \(trimmed)" : "Couldn't create that list.",
                isError: !ok
            )
        )
        if ok {
            searchState.query = ""
            reloadAppPanelData(for: "reminders")
        }
    }

    func reminderItemName(from normalizedQuery: String) -> String {
        cleanedReminderIntentName(
            from: normalizedQuery,
            removing: [
                "create", "new", "add", "make", "set", "a", "an", "reminder", "remainder", "remind",
                "task", "todo", "to", "do",
            ]
        )
    }

    func reminderListName(from normalizedQuery: String) -> String {
        cleanedReminderIntentName(
            from: normalizedQuery,
            removing: [
                "create", "new", "add", "make", "a", "an", "reminder", "remainder", "reminders",
                "list", "todo", "to", "do",
            ]
        )
    }

    func cleanedReminderIntentName(
        from normalizedQuery: String, removing stopWords: Set<String>
    ) -> String {
        normalizedQuery
            .split(separator: " ")
            .map(String.init)
            .filter { !stopWords.contains($0) }
            .joined(separator: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func scopeIntentScore(label: String, keywords: [String], query: String) -> Double {
        let normalizedLabel = normalizedScopeIntentText(label)
        var score = 0.0
        if normalizedLabel == query { score += 120 }
        if normalizedLabel.contains(query) || query.contains(normalizedLabel) { score += 80 }
        score += Double(scopeTokenOverlap(normalizedLabel, query)) * 22
        for keyword in keywords.map(normalizedScopeIntentText) where !keyword.isEmpty {
            if keyword == query { score += 120 }
            if keyword.contains(query) || query.contains(keyword) { score += 70 }
            score += Double(scopeTokenOverlap(keyword, query)) * 18
        }
        return score
    }

    func normalizedScopeIntentText(_ text: String) -> String {
        let lowered = text.lowercased()
        let scalars = lowered.unicodeScalars.map { scalar -> Character in
            CharacterSet.alphanumerics.contains(scalar) ? Character(scalar) : " "
        }
        return String(scalars).split(whereSeparator: \.isWhitespace).joined(separator: " ")
    }

    func scopeTokenOverlap(_ lhs: String, _ rhs: String) -> Int {
        let left = Set(lhs.split(separator: " ").map(String.init))
        let right = Set(rhs.split(separator: " ").map(String.init))
        return left.intersection(right).count
    }

    func scopeIntentContainsAny(_ query: String, _ needles: [String]) -> Bool {
        needles.contains { query.contains($0) }
    }

    /// Returns quick actions appropriate for the current context item.
    func contextPanelActions() -> [PanelAction] {
        let activeKey = searchState.activeSmartQueryKey ?? ""
        let scopedQuery = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
        if searchState.contextApp == nil {
            if !activeKey.isEmpty {
                var seen = Set<String>()
                let smartActions = smartAppScopePanelActions(for: activeKey, query: scopedQuery)
                let quick = appScopeShortcuts(for: activeKey, placements: [.quickActions, .both])
                let dock = appScopeShortcuts(for: activeKey, placements: [.contextDock, .both])
                let extActions = appPillScriptExtensions(for: activeKey, query: scopedQuery)
                    .map { ext in
                        PanelAction(
                            icon: ext.scriptLanguage?.systemImage ?? "terminal",
                            label: ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized
                        ) {
                            executeAppToolExtension(ext)
                        }
                    }
                for action in smartActions { seen.insert(action.label) }
                for s in quick { seen.insert(s.name) }
                let combined = quick + dock.filter { seen.insert($0.name).inserted }
                let sortedShortcuts = sortedAppScopeShortcuts(combined, query: scopedQuery)
                var actions =
                    smartActions
                    + sortedShortcuts.map { sc in
                        PanelAction(icon: sc.iconName, label: sc.name) { executeAppShortcut(sc) }
                    }
                for action in extActions where seen.insert(action.label).inserted {
                    actions.append(action)
                }
                if !actions.isEmpty {
                    return actions
                }
            }

            return []
        }
        guard let ctx = searchState.contextApp else { return [] }

        switch ctx.resultType {
        case .application:
            // Custom shortcuts first (combine quick-actions + context-dock placements), then standard
            let key = ctx.key ?? searchState.activeSmartQueryKey ?? ""
            let mergedShortcuts: [AppShortcut] = {
                var seen = Set<String>()
                let quick = appScopeShortcuts(for: key, placements: [.quickActions, .both])
                let dock = appScopeShortcuts(for: key, placements: [.contextDock, .both])
                for s in quick { seen.insert(s.name) }
                return quick + dock.filter { seen.insert($0.name).inserted }
            }()
            let smartActions = smartAppScopePanelActions(for: key, query: scopedQuery)
            let userShortcuts: [PanelAction] =
                smartActions
                + sortedAppScopeShortcuts(
                    mergedShortcuts, query: scopedQuery
                ).filter { shortcut in
                    !smartActions.contains(where: { $0.label == shortcut.name })
                }.map { sc in
                    PanelAction(icon: sc.iconName, label: sc.name) { executeAppShortcut(sc) }
                }
            let userExtensions: [PanelAction] = appPillScriptExtensions(
                for: key, query: scopedQuery
            )
            .map { ext in
                PanelAction(
                    icon: ext.scriptLanguage?.systemImage ?? "terminal",
                    label: ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized
                ) {
                    executeAppToolExtension(ext)
                }
            }
            let combinedUserActions =
                userShortcuts
                + userExtensions.filter { ext in
                    !userShortcuts.contains(where: { $0.label == ext.label })
                }
            if !combinedUserActions.isEmpty { return combinedUserActions }
            var actions: [PanelAction] = []
            if !ctx.appPath.isEmpty {
                actions.append(
                    PanelAction(icon: "arrow.up.forward.app", label: "Open") {
                        NSWorkspace.shared.openApplication(
                            at: URL(fileURLWithPath: ctx.appPath),
                            configuration: NSWorkspace.OpenConfiguration())
                    })
                actions.append(
                    PanelAction(icon: "magnifyingglass", label: "Reveal in Finder") {
                        NSWorkspace.shared.activateFileViewerSelecting([
                            URL(fileURLWithPath: ctx.appPath)
                        ])
                    })
            }
            return actions

        case .file, .document:
            guard let path = ctx.filePath else { return [] }
            return [
                PanelAction(icon: "doc", label: "Open") {
                    NSWorkspace.shared.open(URL(fileURLWithPath: path))
                },
                PanelAction(icon: "folder", label: "Reveal in Finder") {
                    NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: path)])
                },
                PanelAction(icon: "doc.on.doc", label: "Copy Path") {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(path, forType: .string)
                },
                PanelAction(icon: "eye", label: "Quick Look") {
                    quickLookDataSource = QuickLookDataSource(urls: [URL(fileURLWithPath: path)])
                },
                PanelAction(icon: "trash", label: "Move to Trash") {
                    try? FileManager.default.trashItem(
                        at: URL(fileURLWithPath: path), resultingItemURL: nil)
                },
            ]

        case .folder:
            let path = ctx.filePath ?? ctx.subtitle
            return [
                PanelAction(icon: "folder", label: "Open") {
                    NSWorkspace.shared.open(URL(fileURLWithPath: path))
                },
                PanelAction(icon: "doc.on.doc", label: "Copy Path") {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(path, forType: .string)
                },
                PanelAction(icon: "terminal", label: "Open in Terminal") {
                    let script =
                        "tell application \"Terminal\" to do script \"cd '\(path)'\" activate"
                    NSAppleScript(source: script)?.executeAndReturnError(nil)
                },
                PanelAction(icon: "eye", label: "Quick Look") {
                    quickLookDataSource = QuickLookDataSource(urls: [URL(fileURLWithPath: path)])
                },
            ]

        case .contact:
            var actions: [PanelAction] = []
            if let email = ctx.contactEmail, !email.isEmpty {
                actions.append(
                    PanelAction(icon: "envelope", label: "Send Email") {
                        if let url = URL(string: "mailto:\(email)") { NSWorkspace.shared.open(url) }
                    })
                actions.append(
                    PanelAction(icon: "message", label: "Send Message") {
                        if let url = URL(string: "imessage:\(email)") {
                            NSWorkspace.shared.open(url)
                        }
                    })
                actions.append(
                    PanelAction(icon: "doc.on.doc", label: "Copy Email") {
                        NSPasteboard.general.clearContents()
                        NSPasteboard.general.setString(email, forType: .string)
                    })
            }
            if let phone = ctx.contactPhone, !phone.isEmpty {
                actions.append(
                    PanelAction(icon: "phone", label: "Call") {
                        if let url = URL(string: "tel:\(phone)") { NSWorkspace.shared.open(url) }
                    })
            }
            actions.append(
                PanelAction(icon: "person.crop.circle", label: "Open in Contacts") {
                    NSWorkspace.shared.open(URL(string: "addressbook://")!)
                })
            return actions

        case .calendarEvent:
            return [
                PanelAction(icon: "calendar", label: "Open Calendar") {
                    NSWorkspace.shared.open(URL(string: "ical://")!)
                },
                PanelAction(icon: "doc.on.doc", label: "Copy Title") {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(ctx.name, forType: .string)
                },
            ]

        case .reminder:
            return [
                PanelAction(icon: "checkmark.circle", label: "Open Reminders") {
                    NSWorkspace.shared.open(URL(string: "x-apple-reminder://")!)
                },
                PanelAction(icon: "doc.on.doc", label: "Copy Title") {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(ctx.name, forType: .string)
                },
            ]

        case .note:
            return [
                PanelAction(icon: "note.text", label: "Open Notes") {
                    NSWorkspace.shared.open(URL(string: "notes://")!)
                },
                PanelAction(icon: "doc.on.doc", label: "Copy Title") {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(ctx.name, forType: .string)
                },
            ]

        case .cliTool:
            // Show subcommands as quick actions, plus a "Run in Terminal" button for TUI tools
            let toolCmd = ctx.name
            let pkg = TerminalPackageManager.shared.packages.first(where: {
                $0.name == ctx.name || $0.command == ctx.name
            })
            let isTUI = TerminalAIBridge.shared.isTUICommand(toolCmd)
            var actions: [PanelAction] = []

            func sendCLIQuery(_ msg: String) {
                searchState.query = msg
                handleRemPanelQuery()
                searchState.query = ""
            }

            if isTUI {
                actions.append(
                    PanelAction(icon: "play.fill", label: "Launch") {
                        // Direct spawn — bypasses AI so TUI starts instantly
                        if panelTerminalHost == nil {
                            panelTerminalHost = TerminalHostController()
                        }
                        showLivePanel(.terminal)
                        // Small delay so SwiftTerm shell is ready before we send the command
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                            panelTerminalHost?.sendCommand(toolCmd)
                            BackgroundWorkerPool.shared.registerPTYWorker(
                                command: toolCmd,
                                purpose: "Launched from panel",
                                intent: TerminalAIBridge.shared.detectWorkerIntent(for: toolCmd)
                            )
                        }
                    })
            }
            // First few subcommands as quick actions
            if let subs = pkg?.subcommands {
                for sub in subs.prefix(isTUI ? 3 : 4) {
                    actions.append(
                        PanelAction(icon: "arrow.right.circle", label: sub) {
                            sendCLIQuery("Run: \(toolCmd) \(sub)")
                        })
                }
            }
            actions.append(
                PanelAction(icon: "questionmark.circle", label: "Help") {
                    sendCLIQuery("Show \(toolCmd) --help")
                })
            actions.append(
                PanelAction(icon: "info.circle", label: "Version") {
                    sendCLIQuery("What version is \(toolCmd)?")
                })
            return actions

        default:
            return []
        }
    }

    // MARK: - Selected Result Preview

    /// Returns the action label shown next to a selected result (like Spotlight's "— Open")
    func selectedResultAction(_ result: SearchResult) -> String {
        switch result.type {
        case .application: return "Open"
        case .shortcut: return "Run"
        case .file, .document: return "Open"
        case .folder: return "Browse"
        case .contact: return "View"
        case .calendarEvent: return "View Event"
        case .reminder: return "View"
        case .note: return "Open"
        case .mail: return "Open"
        case .photo: return "View"
        case .message: return "Open"
        case .extensionCommand: return "Run"
        case .webSearch: return "Search"
        case .cliTool: return "Attach CLI"
        }
    }

    // MARK: - Spotlight-style App Context (Tab/→ on app result)

    /// Activates context panel for ANY result type (Spotlight-style Tab/→).
    /// Always opens the 2-column AI panel — chat + quick actions.
    func openCLIToolPanel(for package: TerminalPackage) {
        attachCLIToolToCurrentDock(command: package.command, package: package)
    }

    func activateSearchContext(for result: SearchResult) {
        if result.type == .cliTool {
            let package = terminalPackageManager.packages.first(where: {
                $0.command.caseInsensitiveCompare(result.title) == .orderedSame
                    || $0.name.caseInsensitiveCompare(result.title) == .orderedSame
                    || ($0.installedPath?.caseInsensitiveCompare(result.subtitle) == .orderedSame)
            })
            attachCLIToolToCurrentDock(
                command: package?.command ?? result.title,
                package: package
            )
            return
        }

        let appPath = result.type == .application ? result.subtitle : ""

        if result.type == .application {
            let resolvedBundleId =
                (!appPath.isEmpty ? Bundle(path: appPath)?.bundleIdentifier : nil)
                ?? NSWorkspace.shared.runningApplications.first(where: {
                    !$0.isTerminated
                        && $0.localizedName?.caseInsensitiveCompare(result.title) == .orderedSame
                })?.bundleIdentifier

            if let resolvedBundleId,
                activateInlineDockAppScope(
                    bundleIdentifier: resolvedBundleId,
                    appName: result.title,
                    queryOverride: result.title + " "
                )
            {
                isSearchFieldFocused = true
                return
            }
        }

        // Find matching customAppEntries key for apps (gives AI access to assigned CLI tools)
        let customEntry =
            result.type == .application
            ? settings.customAppEntries.first(where: {
                $0.label.lowercased() == result.title.lowercased() || $0.appPath == appPath
                    || $0.key == result.title.lowercased().replacingOccurrences(of: " ", with: "_")
            }) : nil

        // Built-in system panel keys for standard apps
        let builtInKey: String? = {
            guard result.type == .application else { return nil }
            let name = result.title.lowercased()
            if name == "reminders" { return "reminders" }
            if name == "calendar" { return "calendar" }
            if name == "notes" { return "notes" }
            if name == "mail" { return "mail" }
            if name == "photos" { return "photos" }
            if name == "messages" { return "messages" }
            if name == "contacts" { return "contacts" }
            if name == "amphetamine" { return "amphetamine" }
            if name == "homebrew" { return "homebrew" }
            if name == "system settings" || name == "system preferences" { return "systemsettings" }
            if name == "safari" { return "safari" }
            if name == "finder" { return "finder" }
            if name == "xcode" { return "xcode" }
            // Fallback: look up via bundle ID and name using AppSettings mapping
            if let appPath = result.filePath
                ?? (result.subtitle.hasSuffix(".app") ? result.subtitle : nil),
                let bundle = Bundle(path: appPath), let bid = bundle.bundleIdentifier
            {
                return AppSettings.shared.appKey(forBundleID: bid, appName: result.title)
            }
            return nil
        }()
        let contextKey = customEntry?.key ?? builtInKey

        withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
            searchState.contextApp = SearchContextApp(
                name: result.title,
                icon: result.icon,
                key: contextKey,
                appPath: appPath,
                resultType: result.type,
                filePath: result.filePath,
                subtitle: result.subtitle,
                contactEmail: result.contactData?.primaryEmail,
                contactPhone: result.contactData?.primaryPhone
            )
            searchState.query = ""
            searchState.results = []
            searchState.selectedIndex = nil
            isSearchBarExpanded = true
            // Load persisted chat for this panel (panelKey computed just below)
            let panelKeyForLoad =
                contextKey
                ?? result.title.lowercased()
                .replacingOccurrences(of: " ", with: "_")
                .components(
                    separatedBy: CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "_"))
                        .inverted
                )
                .joined()
            remPanelChatMessages = AppPanelChatStore.shared.load(for: panelKeyForLoad)

            // Set searchState.activeSmartQueryKey — used by handleRemPanelQuery and panel header
            let panelKey =
                contextKey
                ?? result.title.lowercased()
                .replacingOccurrences(of: " ", with: "_")
                .components(
                    separatedBy: CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "_"))
                        .inverted
                )
                .joined()
            searchState.activeSmartQueryKey = panelKey
            searchState.isInSmartMode = true
            searchState.appPanelAllItems = []
            // Only load data for built-in system types
            if let key = contextKey {
                reloadAppPanelData(for: key)
            }
            // Live panel only shows for meaningful results (terminal, music, file preview, or AI-returned lists)
            // Don't auto-open for plain context — file name/path already visible in chat header
            let isNonApp = result.type != .application
            if isNonApp {
                // Keep panel hidden until AI returns results
                livePanelVisible = false
            } else {
                // For apps, hide the live panel (they just use the AI chat)
                livePanelVisible = false
            }
        }
        isSearchFieldFocused = true
    }

    /// Exits the pinned L2 dock scope (l2.targetApp) without clearing other state.
    func exitL2DockScope() {
        let retainedQuery = searchState.query
        withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
            l2.targetApp = nil
            isHoveringL2ScopeChip = false
            focusedAppPillIndex = nil
            l2.focusedPillIndex = nil
            l2.pillNavViaKeyboard = false
        }
        scheduleDockPillRebuild(query: retainedQuery, delayNanoseconds: 0, refreshContext: false)
        if isGlobalContextActive {
            scheduleGlobalAppMatchRebuild(query: retainedQuery, delayNanoseconds: 0)
            scheduleGlobalGroupedListRebuild(query: retainedQuery, delayNanoseconds: 0)
        }
        syncL2DockSession(force: true)
    }

    /// Clears the app context and returns to normal search.
    func clearSearchContext(preserveQuery: Bool = false) {
        if let key = searchState.activeSmartQueryKey {
            AppPanelChatStore.shared.save(remPanelChatMessages, for: key)
        }
        let retainedQuery = searchState.query
        l2.terminalDismissed = false
        pendingAIMenuProposal = nil
        withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
            searchState.contextApp = nil
            searchState.activeSmartQueryKey = nil
            l2.targetApp = nil
            searchState.isInSmartMode = false
            searchState.appPanelAllItems = []
            remPanelChatMessages = []
            clearPinnedResults()
            searchState.results = []
            searchState.selectedIndex = nil
            livePanelVisible = false
            if !preserveQuery {
                searchState.query = ""
            }
        }
        if preserveQuery {
            searchState.query = retainedQuery
        }
        syncL2DockSession(force: true)
    }

    func reloadAppPanelData(for key: String) {
        switch key {
        case "clipboard":
            searchState.appPanelAllItems = clipboardSearchResults()
        case "notifications":
            searchState.appPanelAllItems = notificationSearchResults()
        case "reminders":
            loadSystemDataAsPinnedResults(
                query: "", types: [.reminder], title: "Reminders",
                perTypeLimit: 500, allowEmptyQuery: true, excludeTypes: [.reminder])
        case "calendar":
            loadSystemDataAsPinnedResults(
                query: "", types: [.calendarEvent], title: "Calendar",
                perTypeLimit: 500, allowEmptyQuery: true, excludeTypes: [.calendarEvent])
        case "notes":
            loadSystemDataAsPinnedResults(
                query: "", types: [.note], title: "Notes",
                perTypeLimit: 500, allowEmptyQuery: true, excludeTypes: [.note])
        case "mail":
            loadSystemDataAsPinnedResults(
                query: "", types: [.mail], title: "Mail",
                perTypeLimit: 200, allowEmptyQuery: true, excludeTypes: [.mail])
        case "photos":
            loadSystemDataAsPinnedResults(
                query: "", types: [.photo], title: "Photos",
                perTypeLimit: 200, allowEmptyQuery: true, excludeTypes: [.photo])
        case "messages":
            clearPinnedResults()
            searchState.appPanelAllItems = []
        case "contacts":
            loadAllContactsAsResults()
        case "safari":
            Task { await loadSafariTabs() }
        default: break
        }
    }

    @ViewBuilder
    var resultsSection: some View {
        // Show folder preview inline if active
        if showFolderPreview, let folderPath = folderPreviewPath {
            FolderPreviewView(
                folderPath: folderPath, isPresented: $showFolderPreview,
                selectedFilePath: $folderPreviewSelectedFile
            )
            .frame(minHeight: 400, maxHeight: 600)
            .transition(
                .opacity.combined(
                    with: .move(edge: settings.effectiveDockAtBottom ? .bottom : .top)))
        }
        // App panel: full-screen split view — hides normal search results entirely
        else if searchState.activeSmartQueryKey != nil && !isCompactSmartScope {
            appPanelView
        } else if !searchState.results.isEmpty {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(spacing: 0) {

                        // In dock mode, reverse order so first result is at bottom (closest to dock)
                        let sectionsToRender =
                            settings.effectiveDockAtBottom
                            ? Array(searchState.grouped.sections.reversed())
                            : searchState.grouped.sections

                        // O(1) index lookup — built once per render, used per row
                        let resultIndexMap = Dictionary(
                            uniqueKeysWithValues: searchState.results.enumerated().map {
                                ($1.id, $0)
                            }
                        )

                        // Render grouped sections with headers
                        ForEach(Array(sectionsToRender.enumerated()), id: \.offset) {
                            sectionIndex, section in
                            let (sectionName, sectionResults) = section

                            // In dock mode, also reverse items within each section
                            let itemsToRender =
                                settings.effectiveDockAtBottom
                                ? Array(sectionResults.reversed()) : sectionResults

                            // Section header
                            if searchState.grouped.sections.count > 1 || isCompactSmartScope {
                                HStack {
                                    Text(sectionName)
                                        .font(.system(size: 11, weight: .semibold))
                                        .foregroundStyle(.secondary)
                                        .textCase(.uppercase)
                                        .tracking(0.5)
                                    Spacer()
                                }
                                .padding(.horizontal, 16)
                                .padding(.top, settings.effectiveDockAtBottom ? 6 : 12)
                                .padding(.bottom, 4)
                            }

                            // Section items — ForEach by id, no Array(enumerated()) wrapper
                            ForEach(itemsToRender, id: \.id) { result in
                                let globalIndex = resultIndexMap[result.id] ?? 0

                                resultRowView(for: result, at: globalIndex)
                                    .id(result.id)

                                if result.id != itemsToRender.last?.id {
                                    Divider()
                                        .padding(.leading, 60)
                                }
                            }

                            // Divider between sections (but not after last section)
                            if sectionIndex < sectionsToRender.count - 1 {
                                Divider()
                                    .padding(.vertical, 4)
                            }
                        }
                    }
                    .padding(.top, settings.effectiveDockAtBottom ? 0 : 8)
                    .padding(.bottom, settings.effectiveDockAtBottom ? 4 : 8)
                }
                .scrollContentBackground(.hidden)
                .background(.clear)
                .frame(maxHeight: 400)
                .onChange(of: searchState.revision) { _, _ in
                    // When docked at bottom, keep the best match in view even if selection didn't change.
                    guard settings.effectiveDockAtBottom else { return }
                    guard let index = searchState.selectedIndex,
                        index >= 0,
                        index < searchState.results.count
                    else { return }
                    withAnimation(.easeInOut(duration: 0.2)) {
                        proxy.scrollTo(searchState.results[index].id, anchor: .bottom)
                    }
                }
                .onChange(of: searchState.selectedIndex) { _, newIndex in
                    // Auto-scroll to selected result ONLY when navigating with arrow keys
                    if isKeyboardNavigation || shouldAutoScroll,
                        let index = newIndex,
                        index >= 0 && index < searchState.results.count
                    {
                        withAnimation(.easeInOut(duration: 0.2)) {
                            let anchor: UnitPoint =
                                settings.effectiveDockAtBottom ? .bottom : .center
                            proxy.scrollTo(searchState.results[index].id, anchor: anchor)
                        }
                    }
                    if shouldAutoScroll { shouldAutoScroll = false }
                    // Update context extensions for the newly selected result
                    // so context-based dock pills reflect file type / app context immediately
                    updateL2ContextExtensions()
                    refreshQuickLookPreviewForCurrentFocusIfVisible()
                }
            }
        } else if searchState.isLoadingApps {
            loadingView
        }
    }

    // Helper to find global index for a result (for selection tracking)
    func getGlobalIndex(for result: SearchResult) -> Int {
        searchState.results.firstIndex(where: { $0.id == result.id }) ?? 0
    }

    func resultRowView(for result: SearchResult, at index: Int) -> some View {
        ResultRow(
            result: result,
            isSelected: searchState.selectedIndex == index,
            isPinned: result.type == .application && settings.isPinned(path: result.subtitle),
            usesDockCapsuleSelection: showContextInDock || isGlobalContextActive,
            selectionNamespace: compactScopeFocusNamespace,
            selectionEffectID: dockResultFocusEffectID
        )
        .equatable()
        .contentShape(Rectangle())
        .modifier(OptionalDragProviderModifier(provider: result.dragProvider))
        .onTapGesture {
            executeResult(result)
        }
        .onHover { hovering in
            guard acceptsMouseDrivenDockInteraction else { return }
            if hovering {
                if isSearchFieldFocused {
                    return
                }
                if isKeyboardNavigation {
                    // Switch back to mouse mode but don't steal selection immediately
                    isKeyboardNavigation = false
                    return
                }
                searchState.selectedIndex = index
            }
        }
        .contextMenu {
            resultContextMenu(for: result)
        }
    }

    @ViewBuilder
    func resultContextMenu(for result: SearchResult) -> some View {
        Group {
            if result.type == .contact {
                Button {
                    result.action()
                } label: {
                    Label("Open in Contacts", systemImage: "person.crop.circle")
                }
                Button {
                    let email = result.subtitle
                    guard !email.isEmpty else { return }
                    let pasteboard = NSPasteboard.general
                    pasteboard.clearContents()
                    pasteboard.setString(email, forType: .string)
                } label: {
                    Label("Copy Email", systemImage: "doc.on.doc")
                }
                Button {
                    let email = result.subtitle
                    guard !email.isEmpty, let url = URL(string: "mailto:\(email)") else { return }
                    NSWorkspace.shared.open(url)
                } label: {
                    Label("Send Email", systemImage: "envelope")
                }
                Button {
                    let email = result.subtitle
                    guard !email.isEmpty, let url = URL(string: "imessage:\(email)") else { return }
                    NSWorkspace.shared.open(url)
                } label: {
                    Label("Send Message", systemImage: "message")
                }
            } else if result.type == .application {
                if settings.isPinned(path: result.subtitle) {
                    Button {
                        if let pinnedApp = settings.pinnedApps.first(where: {
                            $0.path == result.subtitle
                        }) {
                            settings.unpinApp(pinnedApp)
                        }
                    } label: {
                        Label("Unpin from Launcher", systemImage: "pin.slash")
                    }
                } else {
                    Button {
                        settings.pinApp(name: result.title, path: result.subtitle)
                    } label: {
                        Label("Pin to Launcher", systemImage: "pin")
                    }
                }
            } else if result.type == .shortcut {
                let shortcutPath = result.subtitle.isEmpty ? result.title : result.subtitle
                if settings.pinnedApps.contains(where: { $0.path == shortcutPath }) {
                    Button {
                        if let pinnedItem = settings.pinnedApps.first(where: {
                            $0.path == shortcutPath
                        }) {
                            settings.unpinApp(pinnedItem)
                        }
                    } label: {
                        Label("Unpin from Launcher", systemImage: "pin.slash")
                    }
                } else {
                    Button {
                        settings.pinItem(name: result.title, path: shortcutPath, type: .shortcut)
                    } label: {
                        Label("Pin to Launcher", systemImage: "pin")
                    }
                }
            } else if let filePath = result.filePath,
                result.type == .file || result.type == .folder || result.type == .document
            {
                if settings.pinnedApps.contains(where: { $0.path == filePath }) {
                    Button {
                        if let pinnedItem = settings.pinnedApps.first(where: { $0.path == filePath }
                        ) {
                            settings.unpinApp(pinnedItem)
                        }
                    } label: {
                        Label("Unpin from Launcher", systemImage: "pin.slash")
                    }
                } else {
                    Button {
                        let itemType: PinnedApp.PinnedItemType =
                            result.type == .folder ? .folder : .file
                        settings.pinItem(name: result.title, path: filePath, type: itemType)
                    } label: {
                        Label("Pin to Launcher", systemImage: "pin")
                    }
                }
                Divider()
                Button {
                    NSWorkspace.shared.selectFile(filePath, inFileViewerRootedAtPath: "")
                } label: {
                    Label("Show in Finder", systemImage: "folder")
                }
                Button {
                    if let url = URL(string: "file://\(filePath)") {
                        NSWorkspace.shared.open(
                            [url],
                            withApplicationAt: URL(
                                fileURLWithPath: "/System/Library/CoreServices/Finder.app"),
                            configuration: NSWorkspace.OpenConfiguration())
                    }
                } label: {
                    Label("Get Info", systemImage: "info.circle")
                }
                Divider()
                Button {
                    let pasteboard = NSPasteboard.general
                    pasteboard.clearContents()
                    pasteboard.setString(filePath, forType: .string)
                } label: {
                    Label("Copy Path", systemImage: "doc.on.clipboard")
                }
            }
        }
    }

    var loadingView: some View {
        HStack {
            ProgressView()
                .scaleEffect(0.8)
            Text("Loading applications and shortcuts...")
                .font(.system(size: 12))
                .foregroundStyle(.secondary)
        }
        .padding()
    }

    var backgroundView: some View {
        Group {
            // Dark glassy blur is handled by NSVisualEffectView at window level
            // SwiftUI background should be clear to let the blur show through

            Color.clear
        }
    }

    // Determine if background should be shown
    var shouldShowBackground: Bool {
        // Results and chat now show inside expanding dock, so no separate background needed
        return false
    }

    func activateSearchField() {
        // Clear any existing text and results first
        searchState.query = ""
        searchState.results = []
        searchState.selectedIndex = nil

        // Immediately show and focus (no delay for better performance)
        isSearchFieldFocused = true
        isVisible = true

        // Expand search bar on launch
        expandSearchBar()

        // Make window key immediately
        if let window = NSApp.keyWindow ?? NSApp.windows.first(where: { $0.isVisible }) {
            window.makeKey()
        }
    }

    func loadUserProfilePicture() {
        Task(priority: .userInitiated) {
            // 1. AddressBook "me" card — Apple ID / account profile picture (macOS API)
            if let book = ABAddressBook.shared(),
                let me = book.me(),
                let data = me.imageData(),
                let image = NSImage(data: data)
            {
                await MainActor.run { userProfileImage = image }
                return
            }

            // 2. Fallback: known macOS local account picture paths
            let home = NSHomeDirectory()
            let localPaths = [
                home + "/Library/Application Support/AddressBook/Images/me.jpg",
                home + "/Library/Application Support/AddressBook/Thumbs/me.jpg",
            ]
            for path in localPaths {
                if let image = NSImage(contentsOfFile: path) {
                    await MainActor.run { userProfileImage = image }
                    return
                }
            }
            // No picture found — stays nil, shows person.circle.fill fallback
        }
    }

    // MARK: - Swipe Gesture Monitor Functions

    func setupSwipeGestureMonitor() {
        removeSwipeGestureMonitor()

        swipeGestureMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { event in
            // Pass scroll events through untouched when the settings window is front —
            // the user is scrolling inside settings, not trying to switch dock layers.
            if let settingsWindow = AppDelegate.shared?.settingsWindow,
                event.window === settingsWindow
            {
                return event
            }

            let dx = event.scrollingDeltaX
            let dy = event.scrollingDeltaY

            // ── Scroll over pill row → navigate pills (no scrolling, just index change) ──
            // Consumes the event so the ScrollView underneath never moves.
            if self.isHoveringPillRow
                && self.showContextInDock
                && !self.aiMode.isActive
                && !self.showShortcutSheet
                && abs(dx) > abs(dy)  // horizontal-dominant gesture
            {
                if event.phase == .began { self.pillScrollAccumulator = 0 }

                if event.phase == .changed || event.phase == .began || event.phase == .none {
                    self.pillScrollAccumulator += dx
                }

                let threshold: CGFloat = 22

                if self.isGlobalContextActive {
                    // Global context: scroll navigates app pills — same wrap behaviour as keyboard nav
                    let appPills = self.currentAppPillActions()
                    while self.pillScrollAccumulator >= threshold {
                        self.pillScrollAccumulator -= threshold
                        let cur = self.focusedAppPillIndex ?? 0
                        if cur <= 0 {
                            self.focusedAppPillIndex = nil
                        } else {
                            self.focusedAppPillIndex = cur - 1
                        }
                    }
                    while self.pillScrollAccumulator <= -threshold {
                        self.pillScrollAccumulator += threshold
                        let cur = self.focusedAppPillIndex ?? -1
                        let next = cur + 1
                        self.focusedAppPillIndex = next < appPills.count ? next : nil
                    }
                } else {
                    // Context dock: scroll navigates action pills (skip separators)
                    let pills = self.cachedDockPills
                    while self.pillScrollAccumulator >= threshold {
                        self.pillScrollAccumulator -= threshold
                        let cur = self.l2.focusedPillIndex ?? 0
                        if cur <= 0 {
                            self.l2.focusedPillIndex = nil
                            self.l2.pillNavViaKeyboard = false
                        } else {
                            var idx = cur - 1
                            while idx > 0 && pills[idx].isSeparator { idx -= 1 }
                            self.l2.pillNavViaKeyboard = true
                            self.l2.focusedPillIndex = idx
                        }
                    }
                    while self.pillScrollAccumulator <= -threshold {
                        self.pillScrollAccumulator += threshold
                        let cur = self.l2.focusedPillIndex ?? -1
                        if cur >= pills.count - 1 {
                            self.l2.focusedPillIndex = nil
                            self.l2.pillNavViaKeyboard = false
                        } else {
                            var idx = cur + 1
                            while idx < pills.count - 1 && pills[idx].isSeparator { idx += 1 }
                            self.l2.pillNavViaKeyboard = true
                            self.l2.focusedPillIndex = idx
                        }
                    }
                }

                if event.phase == .ended || event.phase == .cancelled {
                    self.pillScrollAccumulator = 0
                }
                return nil  // consume — pills stay visually stable
            }

            let deltaX = abs(event.scrollingDeltaX)
            let deltaY = abs(event.scrollingDeltaY)

            // Track both vertical and horizontal movement during the gesture
            if event.phase == .began {
                self.accumulatedSwipeDeltaY = 0
                self.accumulatedSwipeDeltaX = 0
            }

            if event.phase == .changed || event.phase == .began {
                // Accumulate both deltas
                self.accumulatedSwipeDeltaY += event.scrollingDeltaY
                self.accumulatedSwipeDeltaX += event.scrollingDeltaX
            }

            // When gesture ends, check if we have significant movement
            if event.phase == .ended {
                let totalVertical = abs(self.accumulatedSwipeDeltaY)
                let totalHorizontal = abs(self.accumulatedSwipeDeltaX)

                // Horizontal swipe over the input toggles AI Chat from any layer and back.
                if totalHorizontal > 40 && totalHorizontal > totalVertical * 1.8
                    && self.isHoveringInputField
                {
                    guard !self.isExplicitAppScopeLocked else { return event }
                    if self.aiMode.isActive || self.accumulatedSwipeDeltaX > 0 {
                        self.toggleAIModeViaSwipe()
                    }
                }
                // Vertical swipe — Context Dock is home: swipe down → Global, swipe up → Media.
                else if totalVertical > 30 && totalVertical > totalHorizontal * 0.8
                    && (self.isHoveringDockArea || self.isHoveringInputField)
                {
                    guard !self.isExplicitAppScopeLocked else { return event }
                    // Swipe UP (negative deltaY): Global → Context → Media
                    if self.accumulatedSwipeDeltaY < 0 {
                        if self.isGlobalContextActive {
                            // Global Context → Context Dock
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                self.dismissContextAndReturnToDock()
                            }
                        } else if !self.showMediaLayer && self.settings.enableLayer3 {
                            // Context Dock → Media Dock
                            Task {
                                await self.mediaObserver.refreshNowPlaying()
                                withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                    self.showContextInDock = true
                                    self.globalContextActivation = nil
                                    self.showMediaLayer = true
                                }
                                if self.searchState.query.isEmpty && !self.isSearchFieldFocused {
                                    self.startCollapseTimer()
                                }
                            }
                        }
                    }
                    // Swipe DOWN (positive deltaY): Media → Context → Global
                    else {
                        if self.aiMode.isActive {
                            // AI chat → previous layer
                            self.toggleAIModeViaSwipe()
                        } else if self.showMediaLayer {
                            // Media Dock → Context Dock
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                self.showMediaLayer = false
                                self.showContextInDock = true
                            }
                            if self.searchState.query.isEmpty && !self.isSearchFieldFocused {
                                self.startCollapseTimer()
                            }
                        } else if !self.isGlobalContextActive {
                            // Context Dock → Global Context (manual)
                            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                                self.showMediaLayer = false
                                self.globalContextActivation = GlobalContextActivation(
                                    autoActivated: false)
                            }
                            self.replaceCachedDockPills(
                                self.buildDockPills(query: self.lastPillQuery),
                                preserveFocus: true
                            )
                        }
                    }
                }
            }

            return event
        }
    }

    func removeSwipeGestureMonitor() {
        if let monitor = swipeGestureMonitor {
            NSEvent.removeMonitor(monitor)
            swipeGestureMonitor = nil
        }
    }

    func toggleAIModeViaSwipe() {
        toggleAIModePreservingLayer()
    }

    enum DockLayerDirection {
        case up
        case down
    }

    func switchDockLayer(_ direction: DockLayerDirection) {
        guard !isExplicitAppScopeLocked else { return }

        switch direction {
        case .up:
            if aiMode.isActive {
                toggleAIModeViaSwipe()
            } else if showMediaLayer {
                withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                    showMediaLayer = false
                    showContextInDock = true
                }
                if searchState.query.isEmpty && !isSearchFieldFocused {
                    startCollapseTimer()
                }
            } else if !isGlobalContextActive {
                withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                    showMediaLayer = false
                    globalContextActivation = GlobalContextActivation(autoActivated: false)
                }
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
            }
        case .down:
            if aiMode.isActive {
                toggleAIModeViaSwipe()
            } else if isGlobalContextActive {
                withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                    dismissContextAndReturnToDock()
                }
            } else if !showMediaLayer && settings.enableLayer3 {
                Task {
                    await mediaObserver.refreshNowPlaying()
                    withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                        showContextInDock = true
                        globalContextActivation = nil
                        showMediaLayer = true
                    }
                    if searchState.query.isEmpty && !isSearchFieldFocused {
                        startCollapseTimer()
                    }
                }
            }
        }
    }

    func toggleGlobalContextPreservingQuery() {
        guard !isExplicitAppScopeLocked else { return }
        guard showContextInDock, !aiMode.isActive else { return }

        withAnimation(.spring(response: 0.25, dampingFraction: 0.80)) {
            showMediaLayer = false
            showContextInDock = true
            globalContextActivation =
                globalContextActivation == nil
                ? GlobalContextActivation(autoActivated: false)
                : nil
            focusedAppPillIndex = nil
            l2.focusedPillIndex = nil
            l2.pillNavViaKeyboard = false
        }
        scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
        DispatchQueue.main.async {
            self.isSearchBarExpanded = true
            self.isSearchFieldFocused = true
        }
        updateWindowSize()
    }

    func handleCommandKeyContextScopeToggle() {
        guard settings.singleCommandTogglesContextScope else { return }
        guard !isCompactSmartScope else { return }
        guard showContextInDock, !aiMode.isActive else { return }
        guard Date() >= suppressCommandScopeToggleUntil else { return }

        if !isSearchBarExpanded {
            beginMouseDrivenInteractionGrace(0.55)
            expandSearchBar()
            return
        }

        toggleGlobalContextPreservingQuery()
    }

    func toggleAIModePreservingLayer() {
        guard settings.enableAIMode else { return }
        guard !isExplicitAppScopeLocked || aiMode.isActive else { return }

        searchState.results = []
        searchState.selectedIndex = nil
        searchState.query = ""
        aiMode.currentTask?.cancel()
        aiMode.isLoading = false

        if !aiMode.isActive {
            chatReturnContextInDock = showContextInDock
            chatReturnBrowserLayer = showMediaLayer
            chatReturnGlobalContext = globalContextActivation
            hasUserSentMessageInCurrentSession = false
        }

        withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
            aiMode.isActive.toggle()
            if aiMode.isActive {
                // Media hides the input field, so temporarily leave L3 while chat is active.
                showMediaLayer = false
            } else {
                showContextInDock = chatReturnContextInDock
                showMediaLayer = chatReturnBrowserLayer
                globalContextActivation = chatReturnGlobalContext
            }
        }

        if aiMode.isActive {
            collapseTimer?.cancel()
        } else {
            if searchState.query.isEmpty { startCollapseTimer() }
        }
    }

    // MARK: - Search Bar Collapse/Expand Functions

    func expandSearchBar() {
        // Blocked during layer transitions to prevent phantom expand on icon change
        guard !suppressHoverExpand else { return }

        collapseTimer?.cancel()

        withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
            isSearchBarExpanded = true
        }
        updateWindowSize()

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
            self.isSearchFieldFocused = true
        }

        startCollapseTimer()
    }

    func handlePersistentDockModifierExpansionChanged(_ notification: Notification) {
        guard AppDelegate.shared?.launcherWindow?.isVisible == true else { return }
        let isDown = notification.userInfo?["isDown"] as? Bool ?? false
        guard !isCompactSmartScope else {
            persistentDockCollapseTask?.cancel()
            persistentDockModifierExpansionActive = false
            return
        }
        persistentDockCollapseTask?.cancel()
        persistentDockModifierExpansionActive = isDown

        if isDown {
            let wasCollapsed = !isSearchBarExpanded
            if wasCollapsed {
                suppressCommandScopeToggleUntil = Date().addingTimeInterval(0.55)
            }
            withAnimation(.spring(response: 0.24, dampingFraction: 0.82)) {
                isSearchBarExpanded = true
            }
            updateWindowSize()
            if wasCollapsed {
                beginMouseDrivenInteractionGrace(0.55)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.04) {
                    AppDelegate.shared?.launcherWindow?.makeKeyAndOrderFront(nil)
                    self.isSearchFieldFocused = true
                }
            }
            return
        }

        persistentDockCollapseTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 220_000_000)
            collapsePersistentDockIfIdle()
        }
    }

    func collapsePersistentDockIfIdle(force: Bool = false) {
        guard AppDelegate.shared?.launcherWindow?.isVisible == true else { return }
        guard acceptsMouseDrivenDockInteraction else { return }

        if force {
            isSearchFieldFocused = false
        }

        guard !persistentDockModifierExpansionActive && !persistentDockHasExpandedWork else {
            return
        }

        withAnimation(.spring(response: 0.28, dampingFraction: 0.86)) {
            isSearchBarExpanded = false
        }
        updateWindowSize()
    }

    func startCollapseTimer() {
        // Auto-collapse disabled — bar only collapses when user clicks the search icon
        collapseTimer?.cancel()
    }

    func resetCollapseTimer() {
        // Cancel existing timer
        collapseTimer?.cancel()

        // Collapse timer is an L1 concept — skip entirely in L2 and AI mode
        if aiMode.isActive || isL2ContextActive {
            return
        }

        if !searchState.query.isEmpty {
            // Keep expanded while there's text
            return
        }

        // Restart timer if search is empty
        startCollapseTimer()
    }

    func updateL2ContextExtensions() {
        guard settings.enableContextAIExtensions else {
            l2.contextExtensions = []
            return
        }

        let query = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)

        // Frontmost app — from context or stored name
        let frontmostName: String? = {
            switch currentContext {
            case .appFocused(let name, _): return name
            default: return frontmost.name.isEmpty ? nil : frontmost.name
            }
        }()

        // Global Context always includes the live selection so file-type extensions fire.
        // Normal L2 app scope stays app-scoped (no reshuffle on every selection change).
        let includeSelectionContext =
            isGlobalContextActive
            || (!isL2ContextActive && AppDelegate.shared?.isDockContextMode != true)

        // Selected files — from context + Finder
        var contextFiles: [URL] = {
            guard includeSelectionContext else { return [] }
            switch currentContext {
            case .filesSelected(let urls): return urls
            default: return []
            }
        }()
        // Also pull live Finder selection
        if includeSelectionContext {
            let finderFiles = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            if !finderFiles.isEmpty { contextFiles = finderFiles }
        }

        // Selected text
        let selectedText: String? = {
            guard includeSelectionContext else { return nil }
            switch currentContext {
            case .textSelected(let t): return t.isEmpty ? nil : t
            default: return nil
            }
        }()

        // Show extensions whenever there's any meaningful context
        let hasAnyContext =
            frontmostName != nil
            || !contextFiles.isEmpty
            || selectedText != nil

        if !hasAnyContext {
            l2.contextExtensions = []
            return
        }

        // Discover with full context
        let results = LayeredExtensionManager.shared.discoverExtensions(
            for: query,
            selectedFiles: contextFiles,
            selectedText: selectedText,
            frontmostApp: frontmostName,
            layer: .l2_context
        )

        l2.contextExtensions = Array(results.prefix(6))
    }

    func updateContextSuggestions() {
        updateL2ContextExtensions()
        autoSwitchGlobalContextIfNeeded()
    }

    var shouldWarmFrontmostBrowserContext: Bool {
        let query = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
        return aiMode.isActive || aiMode.isLoading || l2.isLoading
            || (showContextInDock && !query.isEmpty)
    }

    func cancelBrowserContextWarmup() {
        browserWarmupTask?.cancel()
        browserWarmupTask = nil
    }

    func scheduleBrowserContextWarmup(reason: String, urlOverride: String? = nil) {
        cancelBrowserContextWarmup()

        guard shouldWarmFrontmostBrowserContext,
            let app = contextTargetApp(),
            !app.isTerminated,
            AXWebReader.shared.isBrowser(bundleId: app.bundleIdentifier ?? "")
        else { return }

        let resolvedURL =
            (urlOverride?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
                ? urlOverride?.trimmingCharacters(in: .whitespacesAndNewlines)
                : nil)
            ?? axContext.currentURL?.trimmingCharacters(in: .whitespacesAndNewlines)
            ?? AXContextReader.shared.current.currentURL?.trimmingCharacters(
                in: .whitespacesAndNewlines)

        guard let currentURL = resolvedURL, !currentURL.isEmpty else { return }

        let pid = app.processIdentifier
        let appName = app.localizedName ?? "Browser"

        browserWarmupTask = Task.detached(priority: .utility) {
            try? await Task.sleep(nanoseconds: 550_000_000)
            guard !Task.isCancelled else { return }
            AXWebReader.shared.refresh(pid: pid, currentURL: currentURL)
            print("🌐 [Browser Warmup] Refreshed \(appName) page context (\(reason))")
        }
    }

    func setFrontmostAppContextOnly(reason: String) {
        guard settings.enableContextAIExtensions else {
            clearFinderFollowUpTargets()
            currentContext = .none
            l2.contextExtensions = []
            return
        }

        guard let frontmostApp = contextTargetApp() else {
            currentContext = .none
            updateContextSuggestions()
            print("⚠️ [Context Detection] No frontmost app for L2 app-only context (\(reason))")
            return
        }

        let bundleID = frontmostApp.bundleIdentifier ?? ""
        let appName = frontmostApp.localizedName ?? "Unknown"
        if bundleID != "com.apple.finder" {
            clearFinderFollowUpTargets()
        }
        refreshCachedFinderCurrentDirectory(for: bundleID)
        frontmost.name = appName
        frontmost.bundleID = bundleID
        frontmost.icon =
            resolvedApplicationIcon(bundleIdentifier: bundleID, appName: appName)
            ?? preparedDockIcon(frontmostApp.icon)
        currentContext = .appFocused(name: appName, bundleID: bundleID)
        updateContextSuggestions()
        if AXWebReader.shared.isBrowser(bundleId: bundleID) {
            scheduleBrowserContextWarmup(reason: "frontmost browser context set")
        }
        print("🖥️ [Context Detection] L2 app-only context (\(reason)): \(appName) (\(bundleID))")
    }

    // MARK: - App Switch Observer

    @State var appSwitchObserver: NSObjectProtocol?
    @State var appLaunchObserver: NSObjectProtocol?
    @State var appTerminateObserver: NSObjectProtocol?

    func startObservingAppSwitches() {
        // ── Instant running-list refresh when any app launches ──
        appLaunchObserver = NSWorkspace.shared.notificationCenter.addObserver(
            forName: NSWorkspace.didLaunchApplicationNotification,
            object: nil, queue: .main
        ) { [self] notification in
            runningRegularApps = currentRegularRunningApps()
            if let app = notification.userInfo?[NSWorkspace.applicationUserInfoKey]
                as? NSRunningApplication,
                let bid = app.bundleIdentifier, app.activationPolicy == .regular
            {
                AppUsageLearner.shared.recordApp(bundleID: bid, appName: app.localizedName ?? "")
            }
        }

        // ── Instant running-list refresh when any app quits ──
        appTerminateObserver = NSWorkspace.shared.notificationCenter.addObserver(
            forName: NSWorkspace.didTerminateApplicationNotification,
            object: nil, queue: .main
        ) { [self] notification in
            if let app = notification.userInfo?[NSWorkspace.applicationUserInfoKey]
                as? NSRunningApplication
            {
                reconcileDockAfterTermination(of: app)
            } else {
                runningRegularApps = currentRegularRunningApps()
            }
        }

        // Observe when other apps become active (user switches windows)
        appSwitchObserver = NSWorkspace.shared.notificationCenter.addObserver(
            forName: NSWorkspace.didActivateApplicationNotification,
            object: nil,
            queue: .main
        ) { notification in
            // Only update if frontmost detection is enabled
            guard settings.enableFrontmostDetection else { return }

            // Get the activated app
            if let app = notification.userInfo?[NSWorkspace.applicationUserInfoKey]
                as? NSRunningApplication
            {
                let bundleID = app.bundleIdentifier ?? ""
                let appName = app.localizedName ?? "Unknown"

                // Skip if it's ILauncher itself or ChatGPT desktop app
                if bundleID == Bundle.main.bundleIdentifier || bundleID == "com.openai.chat" {
                    return
                }

                // Update frontmost app info
                frontmost.name = appName
                frontmost.bundleID = bundleID
                frontmost.icon =
                    resolvedApplicationIcon(bundleIdentifier: bundleID, appName: appName)
                    ?? preparedDockIcon(app.icon)

                // Record app activation in on-device learner
                AppUsageLearner.shared.recordApp(bundleID: bundleID, appName: appName)

                // Auto-map to an appKey so the AI knows context without manual panel selection
                settings.autoDetectedAppKey = settings.appKey(
                    forBundleID: bundleID, appName: appName)

                print(
                    "🔄 App switched to: \(appName) (\(bundleID)) → key: \(settings.autoDetectedAppKey ?? "none")"
                )

                // Re-detect context (selected text/files/browser tab/clipboard) and then refresh suggestions.
                // This ensures suggestions update based on actual user selection, not just the app name.
                if bundleID != "com.apple.finder" {
                    clearFinderFollowUpTargets()
                }

                // When Finder becomes active with no window (desktop mode), skip expensive
                // menu reloads — treat it as a neutral desktop state.
                let isFinderDesktop = bundleID == "com.apple.finder" && !finderHasActiveWindow()
                detectAndUpdateContext()

                if showContextInDock && !isFinderDesktop {
                    updateL2Results([])
                    reloadMenuForApp(app)
                }
            }
        }
    }

    func stopObservingAppSwitches() {
        for observer in [appSwitchObserver, appLaunchObserver, appTerminateObserver].compactMap({
            $0
        }) {
            NSWorkspace.shared.notificationCenter.removeObserver(observer)
        }
        appSwitchObserver = nil
        appLaunchObserver = nil
        appTerminateObserver = nil
    }

    // MARK: - Context Detection & Metadata

    func loadShortcutMetadata() {
        // Load shortcuts metadata from JSON file
        guard
            let metadataURL = Bundle.main.url(
                forResource: "shortcuts-metadata", withExtension: "json", subdirectory: ".claude")
        else {
            print("⚠️ Shortcuts metadata file not found")
            return
        }

        do {
            let data = try Data(contentsOf: metadataURL)
            let decoder = JSONDecoder()
            let metadata = try decoder.decode([String: ShortcutMetadataJSON].self, from: data)

            // Convert to our internal format
            for (name, meta) in metadata {
                shortcutMetadataCache[name] = ShortcutMetadata(
                    acceptsFiles: meta.acceptsFiles,
                    acceptsText: meta.acceptsText,
                    acceptsImages: meta.acceptsImages,
                    acceptsContacts: meta.acceptsContacts,
                    acceptsPDFs: meta.acceptsPDFs,
                    fileExtensions: meta.fileExtensions
                )
            }

            print("✅ Loaded metadata for \(shortcutMetadataCache.count) shortcuts")
        } catch {
            print("❌ Failed to load shortcuts metadata: \(error)")
        }
    }

    func detectAndUpdateContext() {
        // Skip context detection if context awareness is disabled
        guard settings.enableContextAIExtensions else {
            clearFinderFollowUpTargets()
            currentContext = .none
            print("⚠️ [Context Detection] Context awareness is DISABLED in settings")
            return
        }

        if isL2ContextActive {
            // While the dock is open, keep global context live:
            // if the user changed their Finder/AX file selection, update currentContext immediately
            // instead of stomping it with the generic app-scope context.
            if isGlobalContextActive {
                let livePaths = axContext.selectedFilePaths
                if !livePaths.isEmpty {
                    let urls = livePaths.map { URL(fileURLWithPath: $0) }
                    if case .filesSelected(let current) = currentContext,
                        current.map(\.path) == livePaths
                    {
                        // already correct — no-op
                    } else {
                        currentContext = .filesSelected(urls)
                    }
                    return
                }
                let liveText =
                    axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                if liveText.count > 3 {
                    currentContext = .textSelected(liveText)
                    return
                }
            }
            setFrontmostAppContextOnly(reason: "L2 context dock")
            return
        }

        print("🔍 [Context Detection] Starting automatic context detection...")

        // Priority 0: File selected in folder preview (highest priority!)
        if showFolderPreview, let selectedFile = folderPreviewSelectedFile, !selectedFile.isEmpty {
            let fileURL = URL(fileURLWithPath: selectedFile)
            rememberFinderFollowUpTargets(
                [fileURL],
                folderPath: fileURL.deletingLastPathComponent().path,
                sourceQuery: fileURL.lastPathComponent
            )
            currentContext = .filesSelected([fileURL])
            print("📁 Context: File selected in folder preview - \(fileURL.lastPathComponent)")
            updateContextSuggestions()
            return
        }

        // Priority 1: Files selected in search results (internal selection)
        if !selectedFiles.isEmpty {
            let selectedURLs =
                searchState.results
                .filter { selectedFiles.contains($0.id) }
                .compactMap { $0.filePath }
                .map { URL(fileURLWithPath: $0) }

            if !selectedURLs.isEmpty {
                rememberFinderFollowUpTargets(
                    selectedURLs,
                    folderPath: selectedURLs.first?.deletingLastPathComponent().path
                        ?? currentFinderFolderPath(),
                    sourceQuery: "search selection"
                )
                currentContext = .filesSelected(selectedURLs)
                print("📁 Context: \(selectedURLs.count) files selected in search results")
                updateContextSuggestions()
                return
            }
        }

        // Priority 2: Automatic context detection from frontmost app
        // This detects: Finder selections, browser tabs, selected text, etc.

        if let frontmostApp = contextTargetApp() {
            let bundleID = frontmostApp.bundleIdentifier ?? ""
            let appName = frontmostApp.localizedName ?? "Unknown"

            print("🔍 [Context Detection] Frontmost app: \(appName) (\(bundleID))")

            // CRITICAL: Skip Context-Dock itself - we never want to detect our own app
            if bundleID == Bundle.main.bundleIdentifier {
                print("⚠️ [Context Detection] Skipping Context-Dock itself")
            } else {
                frontmost.name = appName
                frontmost.bundleID = bundleID
                frontmost.icon =
                    resolvedApplicationIcon(bundleIdentifier: bundleID, appName: appName)
                    ?? preparedDockIcon(frontmostApp.icon)
                refreshCachedFinderCurrentDirectory(for: bundleID)
                if bundleID != "com.apple.finder" {
                    clearFinderFollowUpTargets()
                }

                print("🔍 [Context Detection] Calling ContextDetector.detectContext()...")
                if let detected = ContextDetector.shared.detectContext(frontmostApp: frontmostApp) {
                    print("✅ [Context Detection] Detected context type: \(detected.description)")

                    switch detected {
                    case .files(let urls):
                        rememberFinderFollowUpTargets(
                            urls,
                            folderPath: urls.first?.deletingLastPathComponent().path
                                ?? currentFinderFolderPath(),
                            sourceQuery: "finder selection"
                        )
                        currentContext = .filesSelected(urls)
                        print(
                            "📁 Context: \(urls.count) file(s) selected in Finder - \(urls.map { $0.lastPathComponent }.joined(separator: ", "))"
                        )

                    case .text(let text):
                        currentContext = .textSelected(text)
                        let words = text.components(separatedBy: .whitespacesAndNewlines).filter {
                            !$0.isEmpty
                        }
                        print(
                            "📝 ✅ Context: Selected text (\(words.count) words) - \"\(String(text.prefix(100)))...\""
                        )

                    case .browserTab(let url, let title):
                        currentContext = .url(url)
                        print("🌐 Context: Browser tab - \(title)")

                    case .browserTabs(let tabs):
                        if let firstTab = tabs.first {
                            currentContext = .url(firstTab.url)
                        }
                        print("🌐 Context: \(tabs.count) browser tabs")

                    case .clipboard(let content):
                        currentContext = .textSelected(content)
                        print("📋 Context: Clipboard content")

                    case .music(let title, let artist, _):
                        currentContext = .textSelected("\(title) by \(artist)")
                        print("🎵 Context: Playing \(title) by \(artist)")

                    case .podcast(let title, let show):
                        currentContext = .textSelected("\(title) - \(show)")
                        print("🎙️ Context: Podcast \(title)")

                    case .note(let content):
                        currentContext = .textSelected(content)
                        print("📝 Context: Note content detected")

                    case .email(let subject, _, _):
                        currentContext = .textSelected(subject)
                        print("📧 Context: Email - \(subject)")

                    case .app(_, let name):
                        if bundleID == "com.apple.finder",
                            let stickyURL = finderFollowUpTargetURLs(for: currentFinderFolderPath())
                                .first
                        {
                            currentContext = .filesSelected([stickyURL])
                            print(
                                "📁 Context: Finder follow-up target = \(stickyURL.lastPathComponent)"
                            )
                        } else {
                            currentContext = .appFocused(name: name, bundleID: bundleID)
                            print("🖥️ Context: Frontmost app = \(name)")
                        }
                    }

                    updateContextSuggestions()
                    return
                } else {
                    print("⚠️ [Context Detection] ContextDetector returned nil for \(appName)")
                }
            }
        } else {
            print("⚠️ [Context Detection] No target application found for context!")
        }

        // Priority 3: Fallback to clipboard
        // Check clipboard for files
        if let fileURLs = NSPasteboard.general.readObjects(forClasses: [NSURL.self], options: nil)
            as? [URL]
        {
            let validFileURLs = fileURLs.filter { $0.isFileURL }
            if !validFileURLs.isEmpty {
                clearFinderFollowUpTargets()
                currentContext = .filesSelected(validFileURLs)
                print("📁 Context: \(validFileURLs.count) file(s) in clipboard")
                updateContextSuggestions()
                return
            }
        }

        // Check clipboard for text
        if let clipboardText = NSPasteboard.general.string(forType: .string) {
            let trimmed = clipboardText.trimmingCharacters(in: .whitespacesAndNewlines)
            let words = trimmed.components(separatedBy: .whitespacesAndNewlines).filter {
                !$0.isEmpty
            }

            if words.count >= 2 || (words.count == 1 && trimmed.count >= 10) {
                clearFinderFollowUpTargets()
                currentContext = .textSelected(clipboardText)
                print("📝 Context: Text in clipboard (\(words.count) words)")
                updateContextSuggestions()
                return
            }
        }

        // Priority 4: No context
        clearFinderFollowUpTargets()
        currentContext = .none
        print("❌ No context detected")
        updateContextSuggestions()
    }

    func contextTargetApp() -> NSRunningApplication? {
        if !frontmost.bundleID.isEmpty,
            frontmost.bundleID != Bundle.main.bundleIdentifier,
            let resolvedApp = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == frontmost.bundleID && !$0.isTerminated
            })
        {
            return resolvedApp
        }

        // Fallback: NSWorkspace frontmost, but exclude ourselves
        if let frontmostApp = NSWorkspace.shared.frontmostApplication,
            frontmostApp.bundleIdentifier != Bundle.main.bundleIdentifier
        {
            return frontmostApp
        }

        // Fallback to the last captured pre-dock app only if we couldn't resolve
        // the live dock target from current frontmost state.
        if let prev = AppDelegate.shared?.previousFrontmostApp,
            prev.bundleIdentifier != Bundle.main.bundleIdentifier,
            !prev.isTerminated
        {
            return prev
        }

        return nil
    }

    func menuSourceApps() -> [NSRunningApplication] {
        var apps: [NSRunningApplication] = []
        var seen = Set<pid_t>()

        func append(_ app: NSRunningApplication?) {
            guard let app, !app.isTerminated else { return }
            guard app.bundleIdentifier != Bundle.main.bundleIdentifier else { return }
            guard seen.insert(app.processIdentifier).inserted else { return }
            apps.append(app)
        }

        append(contextTargetApp())
        append(AppDelegate.shared?.previousFrontmostApp)
        append(NSWorkspace.shared.frontmostApplication)

        if !frontmost.bundleID.isEmpty,
            let fallback = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == frontmost.bundleID
            })
        {
            append(fallback)
        }

        return apps
    }

    func menuInventory(for app: NSRunningApplication) -> [AXMenuItem] {
        let pid = app.processIdentifier
        var items = AXMenuReader.shared.peekCachedAllMenuItems(for: pid)
        if items.isEmpty {
            items = ContextDockEngine.shared.cachedMenuItems(for: app, maxResults: 120)
        }
        for i in items.indices {
            items[i].sourcePID = pid
            items[i].sourceAppName = app.localizedName ?? ""
        }
        return items
    }

    func filterMenuInventory(_ items: [AXMenuItem], query: String, maxResults: Int = 16)
        -> [AXMenuItem]
    {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let matches =
            q.isEmpty
            ? items
            : items.filter { item in
                item.title.lowercased().contains(q)
                    || item.path.contains { $0.lowercased().contains(q) }
            }
        return Array(
            matches.sorted {
                let aPrefix = q.isEmpty ? 1 : ($0.title.lowercased().hasPrefix(q) ? 0 : 1)
                let bPrefix = q.isEmpty ? 1 : ($1.title.lowercased().hasPrefix(q) ? 0 : 1)
                if aPrefix != bPrefix { return aPrefix < bPrefix }

                let aTitle = q.isEmpty ? 1 : ($0.title.lowercased().contains(q) ? 0 : 1)
                let bTitle = q.isEmpty ? 1 : ($1.title.lowercased().contains(q) ? 0 : 1)
                if aTitle != bTitle { return aTitle < bTitle }

                return $0.path.count < $1.path.count
            }.prefix(maxResults))
    }

    func currentFrontmostMenuCapabilityJSONBlock(maxItems: Int = 40) -> String {
        let items =
            liveMenuItems
            .filter {
                $0.isEnabled && !$0.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            }
            .prefix(maxItems)

        guard !items.isEmpty else { return "" }

        let payload: [[String: Any]] = items.map { item in
            [
                "title": item.title,
                "path": item.path,
                "shortcut": item.shortcutDisplay ?? "",
            ]
        }

        guard
            let data = try? JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys]),
            let json = String(data: data, encoding: .utf8)
        else { return "" }

        return """

            ## App Menu Capabilities JSON
            ```json
            \(json)
            ```
            Treat this JSON as executable app commands only. It describes what the app can do, not the app's live content.
            """
    }

    func acceptL2AppCompletion(_ completion: AppCompletion) {
        self.l2.appCompletion = nil
        if completion.bundleId == "scope://clipboard" {
            activateClipboardScope(queryOverride: completion.actionQuery)
            return
        }
        // Activate the scope immediately (explicit Tab action) and clear the app name
        // so the user can type their query into an empty field — Spotlight-style.
        let activated = activateInlineDockAppScope(
            bundleIdentifier: completion.bundleId,
            appName: completion.appName,
            queryOverride: completion.actionQuery,
            preserveGlobalContext: isGlobalContextActive
        )
        if !activated {
            let currentTokens = self.searchState.query.trimmingCharacters(in: .whitespaces)
                .split(separator: " ").map(String.init)
            let afterApp = currentTokens.dropFirst().joined(separator: " ")
            let fullName = (currentTokens.first ?? "") + completion.ghost
            self.searchState.query = afterApp.isEmpty ? fullName + " " : fullName + " " + afterApp
        }
    }

    @discardableResult
    func activateTypedAppScopeIfPossible(for query: String? = nil) -> Bool {
        guard isGlobalContextActive else { return false }

        let rawQuery = query ?? searchState.query
        let rawTrimmed = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard rawTrimmed.count >= 2 else { return false }

        let normalized =
            rawTrimmed.lowercased().hasSuffix(".app")
            ? String(rawTrimmed.dropLast(4)).trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            : rawTrimmed.lowercased()

        if let completion = l2.appCompletion, !completion.ghost.isEmpty {
            acceptL2AppCompletion(completion)
            return true
        }

        if normalized == "clipboard" {
            activateClipboardScope()
            return true
        }

        if let target = L2AppActionRouter.shared.appScopeTarget(for: normalized) {
            let activated = activateInlineDockAppScope(
                bundleIdentifier: target.bundleId,
                appName: target.appName,
                queryOverride: target.actionQuery,
                preserveGlobalContext: isGlobalContextActive
            )
            if !activated { searchState.query = target.appName + " " }
            return true
        }

        if let target = installedAppMenuTarget(
            for: normalized,
            runningOnly: false,
            includeAppsWithoutMenuSnapshot: true,
            allowPrefixAlias: true
        ) {
            let activated = activateInlineDockAppScope(
                bundleIdentifier: target.bundleId,
                appName: target.appName,
                queryOverride: target.actionQuery,
                preserveGlobalContext: isGlobalContextActive
            )
            if !activated { searchState.query = target.appName + " " }
            return true
        }

        if let completion = bestL2PartialAppCompletion(for: normalized, runningOnly: false),
            !completion.ghost.isEmpty
        {
            acceptL2AppCompletion(completion)
            return true
        }

        return false
    }

    func menuDebugSummary(query: String) -> String {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let matches =
            q.isEmpty
            ? liveMenuItems.count
            : liveMenuItems.filter {
                $0.title.lowercased().contains(q)
                    || $0.path.contains { part in part.lowercased().contains(q) }
            }.count
        return "\(menuDebugText), \(matches) matches"
    }

    func setupQuickLookEventMonitor() {
        // Remove any existing monitor first
        removeQuickLookEventMonitor()

        // Add a local event monitor to intercept Space key for Quick Look
        // This works even when the text field has focus
        quickLookEventMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) {
            [self] event in
            // Only handle Space key (keyCode 49)
            guard event.keyCode == 49 else { return event }

            if showFolderPreview {
                if let index = searchState.selectedIndex,
                    searchState.results.indices.contains(index),
                    let path = searchState.results[index].filePath,
                    searchState.results[index].type == .folder,
                    folderPreviewPath != path
                {
                    showFolderPreviewInline(path: path)
                } else {
                    withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                        showFolderPreview = false
                        folderPreviewPath = nil
                    }
                }
                return nil
            }

            // Don't intercept if in AI mode (allow typing spaces in AI queries)
            guard !aiMode.isActive else { return event }

            if let pill = currentFocusedDockPillForQuickLook(),
                quickLookDockPill(pill)
            {
                return nil
            }

            // Only intercept if we have a selected result
            guard let index = searchState.selectedIndex, index < searchState.results.count else {
                return event
            }

            let result = searchState.results[index]

            // Check if the result supports preview (file, folder, or contact)
            let supportsPreview = result.filePath != nil || result.type == .contact
            guard supportsPreview else { return event }

            // Only trigger Quick Look when query is literally empty (user pressed space with nothing typed)
            // or Shift+Space. Never consume space mid-query — user may be typing multi-word searches.
            let isShiftHeld = event.modifierFlags.contains(.shift)
            let searchIsEmpty = searchState.query.isEmpty

            if isShiftHeld || searchIsEmpty {
                DispatchQueue.main.async {
                    self.quickLookSelectedItem()
                }
                return nil  // Consume the event
            }

            return event
        }
    }

    func removeQuickLookEventMonitor() {
        if let monitor = quickLookEventMonitor {
            NSEvent.removeMonitor(monitor)
            quickLookEventMonitor = nil
        }
    }

    func quickLookPanelIsVisible() -> Bool {
        QLPreviewPanel.shared()?.isVisible ?? false
    }

    func showQuickLookURL(_ url: URL, toggleIfSame: Bool) -> Bool {
        guard FileManager.default.fileExists(atPath: url.path) else { return false }
        guard let panel = QLPreviewPanel.shared() else { return false }
        if panel.isVisible,
            let currentDataSource = quickLookDataSource,
            currentDataSource.urls.first == url,
            toggleIfSame
        {
            panel.orderOut(nil)
            quickLookDataSource = nil
            return true
        }

        let dataSource = QuickLookDataSource(urls: [url])
        quickLookDataSource = dataSource
        panel.dataSource = dataSource
        panel.delegate = dataSource
        panel.reloadData()
        if !panel.isVisible {
            panel.orderFront(nil)
        }
        if searchState.activeSmartQueryKey == "clipboard",
            let window = AppDelegate.shared?.launcherWindow
        {
            window.makeKeyAndOrderFront(nil)
            isSearchFieldFocused = true
        }
        return true
    }

    func refreshQuickLookPreviewForCurrentFocusIfVisible() {
        if showFolderPreview {
            if let index = searchState.selectedIndex,
                searchState.results.indices.contains(index),
                let path = searchState.results[index].filePath,
                path != folderPreviewPath
            {
                if searchState.results[index].type == .folder {
                    showFolderPreviewInline(path: path)
                } else {
                    showFolderPreview = false
                    folderPreviewPath = nil
                    _ = showQuickLookURL(URL(fileURLWithPath: path), toggleIfSame: false)
                }
            }
            return
        }

        guard quickLookPanelIsVisible() else { return }
        if let pill = currentFocusedDockPillForQuickLook(),
            let url = pill.quickLookURL
        {
            _ = showQuickLookURL(url, toggleIfSame: false)
            return
        }
        if searchState.activeSmartQueryKey == "clipboard",
            let index = focusedClipboardEntryIndex
        {
            let entries = filteredClipboardEntriesForScope()
            if entries.indices.contains(index), let url = quickLookURL(for: entries[index]) {
                _ = showQuickLookURL(url, toggleIfSame: false)
            }
            return
        }
        guard let index = searchState.selectedIndex,
            searchState.results.indices.contains(index),
            let path = searchState.results[index].filePath
        else { return }
        if searchState.results[index].type == .folder {
            QLPreviewPanel.shared()?.orderOut(nil)
            quickLookDataSource = nil
            showFolderPreviewInline(path: path)
            return
        }
        _ = showQuickLookURL(URL(fileURLWithPath: path), toggleIfSame: false)
    }

    // MARK: - Dock pill arrow-key navigation

    /// Flat list of app pills currently visible in the pinned/running or global-search row.
    /// Returns (action, destructiveAction, removeAction) per index for keyboard execution.
    func currentAppPillActions() -> [(
        execute: () -> Void, quit: (() -> Void)?, remove: (() -> Void)?
    )] {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        // Global context app search
        if shouldUsePureGlobalAppSearch && !q.isEmpty {
            return currentGlobalAppMatches(for: q)
                .map {
                    result -> (execute: () -> Void, quit: (() -> Void)?, remove: (() -> Void)?) in
                    let runningApp = runningApplication(forGlobalResult: result)
                    let quitAction: (() -> Void)? = runningApp.map { app in
                        { terminateRunningAppFromDock(app) }
                    }
                    let removeAction: (() -> Void)? = nil
                    return (
                        execute: {
                            executeGlobalAppSearchResult(result)
                        }, quit: quitAction, remove: removeAction
                    )
                }
        }
        // Pinned row
        var items: [(execute: () -> Void, quit: (() -> Void)?, remove: (() -> Void)?)] = []
        for app in settings.pinnedApps {
            let ri = runningApp(for: app)
            let captured = app
            items.append(
                (
                    execute: { launchPinnedApp(captured) },
                    quit: ri.map { r in { terminateRunningAppFromDock(r) } },
                    remove: { settings.unpinApp(captured) }
                ))
        }
        return items
    }

    /// Set up a key monitor that handles Left/Right arrow navigation and
    /// Enter-to-execute for dock pills when the L2 Context Dock is active.
    func searchInputHasHighlightedText() -> Bool {
        guard isSearchFieldFocused,
            let textView = NSApp.keyWindow?.firstResponder as? NSTextView
        else { return false }

        return textView.selectedRanges.contains { value in
            value.rangeValue.length > 0
        }
    }

    func searchInputCursorIsAtEnd() -> Bool {
        guard isSearchFieldFocused,
            let textView = NSApp.keyWindow?.firstResponder as? NSTextView
        else { return false }

        let range = textView.selectedRange()
        return range.length == 0 && range.location >= (textView.string as NSString).length
    }

    enum KeyRoutingMode {
        case shortcutSheet
        case shareSheet
        case ai
        case compactScope
        case hidden
        case globalContext
        case contextDock
    }

    var keyRoutingMode: KeyRoutingMode {
        if showShortcutSheet { return .shortcutSheet }
        if isSharingSheetActive { return .shareSheet }
        if aiMode.isActive { return .ai }
        if isCompactSmartScope { return .compactScope }
        if !showContextInDock { return .hidden }
        if isGlobalContextActive { return .globalContext }
        return .contextDock
    }

    func handleTopLevelKeyRouting(_ event: NSEvent, mode: KeyRoutingMode) -> NSEvent? {
        switch mode {
        case .shortcutSheet:
            return handleShortcutSheetKey(event)
        case .shareSheet, .ai, .compactScope, .hidden:
            return event
        case .globalContext, .contextDock:
            return nil
        }
    }

    func handleShortcutSheetKey(_ event: NSEvent) -> NSEvent? {
        guard showShortcutSheet else { return event }

        switch event.keyCode {
        case 53:  // Escape
            closeShortcutSheet()
            return nil
        case 125:  // Down
            let commands = shortcutSheetCommands
            guard !commands.isEmpty else { return nil }
            if let id = shortcutSheetFocusedCommandID,
                let index = commands.firstIndex(where: { $0.id == id })
            {
                shortcutSheetFocusedCommandID = commands[min(commands.count - 1, index + 1)].id
            } else {
                shortcutSheetFocusedCommandID = commands[0].id
            }
            return nil
        case 126:  // Up
            let commands = shortcutSheetCommands
            guard !commands.isEmpty else { return nil }
            guard let id = shortcutSheetFocusedCommandID,
                let index = commands.firstIndex(where: { $0.id == id })
            else { return nil }
            if index <= 0 {
                shortcutSheetFocusedCommandID = nil
            } else {
                shortcutSheetFocusedCommandID = commands[index - 1].id
            }
            return nil
        case 36:  // Return
            guard let id = shortcutSheetFocusedCommandID,
                let command = shortcutSheetCommands.first(where: { $0.id == id })
            else { return event }
            executeShortcutSheetCommand(command)
            return nil
        default:
            return event
        }
    }

    func setupDockPillKeyMonitor() {
        NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [self] event in
            let routingMode = self.keyRoutingMode
            if let routedEvent = self.handleTopLevelKeyRouting(event, mode: routingMode) {
                return routedEvent
            }

            // Only context/global dock modes can consume dock navigation keys.
            guard routingMode == .contextDock || routingMode == .globalContext else {
                return event
            }

            if event.keyCode == 48, self.isL2ContextActive, !self.isGlobalContextActive {
                return nil
            }

            if event.keyCode == 51,
                self.lockedFindToken != nil,
                self.searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            {
                self.clearFindToken(preserveQuery: false)
                return nil
            }

            // Right arrow: focus visible Global app result, otherwise accept app ghost text.
            if event.keyCode == 124 {
                if !self.searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                    self.focusTopGlobalAppResultIfPossible()
                {
                    return nil
                }
                if self.attachCurrentFinderFolderFromEmptyFieldIfNeeded() {
                    return nil
                }
                if let findToken = self.lockedFindToken,
                    findToken.hasChildMenu,
                    self.searchInputCursorIsAtEnd()
                {
                    withAnimation(.spring(response: 0.2, dampingFraction: 0.82)) {
                        self.showFindTokenMenu = true
                    }
                    return nil
                }
                if let completion = self.l2.appCompletion,
                    !completion.ghost.isEmpty,
                    self.searchInputCursorIsAtEnd()
                {
                    let full = completion.appName
                    if !full.isEmpty && self.searchState.query.lowercased() != full.lowercased() {
                        self.searchState.query = full
                        return nil
                    }
                }
            }
            // Tab in global context explicitly enters app scope.
            // Typing alone stays global so cross-app suggestions cannot steal the query.
            if event.keyCode == 48, self.isGlobalContextActive {
                if self.shouldUsePureGlobalAppSearch,
                    let result = self.focusedOrTopGlobalAppResult(),
                    let bundleId = self.bundleIdentifier(forApplicationResult: result)
                {
                    let appName = result.title.trimmingCharacters(in: .whitespacesAndNewlines)
                    let activated = self.activateInlineDockAppScope(
                        bundleIdentifier: bundleId,
                        appName: appName,
                        queryOverride: "",
                        preserveGlobalContext: true
                    )
                    if activated {
                        self.focusedAppPillIndex = nil
                        self.l2.focusedPillIndex = nil
                        return nil
                    }
                }

                // Pure global search mode: use globalInlineAppScope (lightweight, no L2 session switch).
                // Tab on "notes" → Notes scope, query="".
                // Tab on "new note" → Notes scope, query="new".
                // Pure global search: Tab on bare app name (e.g. "not", "notes") → lock into scope.
                // Cross-app queries like "new note" have a non-empty actionQuery → skip, no scope switch.
                if self.shouldUsePureGlobalAppSearch, self.globalInlineAppScope == nil {
                    let raw = self.searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
                    let isBareName =
                        self.installedAppMenuTarget(
                            for: raw,
                            includeAppsWithoutMenuSnapshot: true,
                            allowPrefixAlias: true
                        ).map {
                            $0.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        } ?? false
                    if isBareName, self.applyGlobalInlineAppScopeIfNeeded(for: raw + " ") {
                        self.focusedAppPillIndex = nil
                        self.l2.focusedPillIndex = nil
                        return nil
                    }
                }

                if self.activateTypedAppScopeIfPossible() {
                    self.focusedAppPillIndex = nil
                    self.l2.focusedPillIndex = nil
                    return nil
                }

            }
            // Tab: pill ghost completion (prefix match on current pill name)
            if event.keyCode == 48, !self.isGlobalContextActive,
                let ghost = self.ghostPillCompletion
            {
                self.searchState.query = ghost.name
                return nil
            }
            // Tab: app ghost completion (non-global L2 scope sub-scope entry).
            if let completion = self.l2.appCompletion, !completion.ghost.isEmpty,
                event.keyCode == 48
            {
                self.acceptL2AppCompletion(completion)
                return nil
            }
            // Tab: try scope activation — only in non-global context (global context uses inline scope)
            if event.keyCode == 48, !self.isGlobalContextActive,
                self.activateTypedAppScopeIfPossible()
            {
                return nil
            }

            let q = self.searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()

            if event.keyCode == 36, self.executeScopedRunningAppIfIdle() {
                return nil
            }

            if self.isGlobalContextActive,
                q.isEmpty,
                event.keyCode == 123 || event.keyCode == 124,
                self.focusedAppPillIndex == nil,
                self.l2.focusedPillIndex == nil
            {
                _ = self.cycleGlobalContextAppScope(direction: event.keyCode == 124 ? 1 : -1)
                self.focusedAppPillIndex = nil
                self.l2.focusedPillIndex = nil
                return nil
            }

            // Block 1: grouped navigation — fires when view shows globalAppSearchListView.
            // That view is shown when: app matches exist, OR frontmost has no matching menus
            // (cross-app or empty). When frontmost HAS menus (preferFrontmostMenuResults=true),
            // view shows dockPillListView instead — Block 3 handles it with full-pills indices.
            if self.shouldUsePureGlobalAppSearch && !q.isEmpty {
                let groupedState = self.globalGroupedListNavigationState(for: q)
                guard groupedState.totalCount > 0 else { return event }

                switch event.keyCode {
                case 125:  // Down — move through grouped app/menu rows
                    _ = self.moveGlobalGroupedListFocus(direction: 1)
                    return nil
                case 126:  // Up — move through grouped app/menu rows
                    _ = self.moveGlobalGroupedListFocus(direction: -1)
                    return nil
                case 36:  // Return — execute focused grouped row, or first row if none focused
                    return self.executeFocusedGlobalGroupedListRow() ? nil : event
                case 123:  // Left — exit result focus, return to input field
                    if self.focusedAppPillIndex != nil || self.l2.focusedPillIndex != nil {
                        self.focusedAppPillIndex = nil
                        self.l2.focusedPillIndex = nil
                        self.l2.pillNavViaKeyboard = false
                        DispatchQueue.main.async { self.reclaimSearchInputFocus() }
                        return nil
                    }
                    return event
                case 53:  // Escape — leave result focus first; keep query intact
                    if self.focusedAppPillIndex != nil || self.l2.focusedPillIndex != nil {
                        self.focusedAppPillIndex = nil
                        self.l2.focusedPillIndex = nil
                        self.l2.pillNavViaKeyboard = false
                        DispatchQueue.main.async { self.reclaimSearchInputFocus() }
                        return nil
                    }
                    return event
                case 48:  // Tab is handled above by explicit app-scope activation.
                    return nil
                case 51:  // Delete/Backspace — clear row focus and edit query normally
                    if self.currentGlobalGroupedFocusIndex(state: groupedState) != nil {
                        self.setGlobalGroupedFocus(nil, state: groupedState)
                        return nil
                    }
                    return event
                default:
                    return event
                }
            }

            // ── App-pill row navigation (pinned/running or global app search) ──────────
            let hasActiveContextSel = self.activeSelection != nil
            // Use the same cached pill list the List View renders. Do not rebuild here;
            // this key monitor runs on every keyDown.
            let pillQuery = self.shouldUseFinderSearchPopover(for: q) ? "" : q
            let actionPills =
                q.isEmpty
                ? self.selectionScopedDockPills(self.cachedDockPills)
                : self.currentVisibleDockPills(for: pillQuery)
            let showPinnedRow =
                q.isEmpty
                && self.l2.targetApp == nil
                && (actionPills.isEmpty || (self.isGlobalContextActive && !hasActiveContextSel))
            let hasGlobalAppMatches =
                self.isGlobalContextActive && !q.isEmpty
                && (!self.currentGlobalAppMatches(for: q).isEmpty
                    || self.pendingGlobalAppQuery == q)
            let showGlobalAppSearch =
                self.shouldUsePureGlobalAppSearch && !q.isEmpty && hasGlobalAppMatches
            let isAppPillRowActive = showPinnedRow || showGlobalAppSearch

            if isAppPillRowActive {
                let appPills = self.currentAppPillActions()
                guard !appPills.isEmpty else { return event }

                switch event.keyCode {
                case 48:  // Tab — enter/exit app pill navigation; never let macOS Full Keyboard Navigation take over
                    if self.focusedAppPillIndex == nil {
                        self.focusedAppPillIndex = 0
                        self.l2.pillNavViaKeyboard = true
                    } else {
                        self.focusedAppPillIndex = nil
                        self.expandSearchBar()
                    }
                    return nil
                case 123:  // Left — mirror context dock: wrap to input field at start
                    guard self.focusedAppPillIndex != nil else { return event }
                    if self.usesVerticalListDockLayout {
                        self.focusedAppPillIndex = nil
                        self.l2.pillNavViaKeyboard = false
                        DispatchQueue.main.async { self.reclaimSearchInputFocus() }
                        return nil
                    }
                    let curLeft = self.focusedAppPillIndex ?? 0
                    if curLeft <= 0 {
                        self.focusedAppPillIndex = nil
                        self.expandSearchBar()
                        return nil
                    }
                    self.focusedAppPillIndex = curLeft - 1
                    return nil
                case 124:  // Right — mirror context dock: wrap to input field at end
                    if self.searchInputHasHighlightedText() {
                        self.focusedAppPillIndex = nil
                        return event
                    }
                    guard self.focusedAppPillIndex != nil else { return event }
                    let curIdx = self.focusedAppPillIndex ?? -1
                    if curIdx >= appPills.count - 1 {
                        self.focusedAppPillIndex = nil
                        self.expandSearchBar()
                        return nil
                    }
                    self.focusedAppPillIndex = curIdx + 1
                    return nil
                case 125:  // Down — navigate app list in List View; otherwise Global → Context → Media
                    if self.usesVerticalListDockLayout {
                        _ = self.moveGlobalAppResultFocus(direction: 1)
                        return nil
                    }
                    guard q.isEmpty,
                        self.focusedAppPillIndex == nil,
                        self.l2.focusedPillIndex == nil
                    else { return event }
                    self.switchDockLayer(.down)
                    return nil
                case 126:  // Up — navigate app list in List View; otherwise Media → Context → Global
                    if self.usesVerticalListDockLayout {
                        _ = self.moveGlobalAppResultFocus(direction: -1)
                        return nil
                    }
                    guard q.isEmpty,
                        self.focusedAppPillIndex == nil,
                        self.l2.focusedPillIndex == nil
                    else { return event }
                    self.switchDockLayer(.up)
                    return nil
                case 36:  // Enter — launch/activate
                    if let idx = self.focusedAppPillIndex, idx < appPills.count {
                        appPills[idx].execute()
                        self.searchState.query = ""
                        self.focusedAppPillIndex = nil
                        self.collapseDockAfterResultExecution()
                        return nil
                    }
                    return event
                case 51:  // Delete/Backspace — clear app focus and return to input
                    if self.focusedAppPillIndex != nil {
                        self.focusedAppPillIndex = nil
                        self.l2.pillNavViaKeyboard = false
                        DispatchQueue.main.async { self.reclaimSearchInputFocus() }
                        return nil
                    }
                    return event
                case 53:  // Escape — mirror context dock: clear focus and re-expand input
                    if self.focusedAppPillIndex != nil {
                        self.focusedAppPillIndex = nil
                        self.expandSearchBar()
                        return nil
                    }
                    return event
                default:
                    return event
                }
            }

            let pills = actionPills
            guard !pills.isEmpty else { return event }

            switch event.keyCode {
            case 48:  // Tab — return focus to search field (prevents macOS Full Keyboard Navigation takeover)
                self.l2.focusedPillIndex = nil
                self.l2.pillNavViaKeyboard = false
                DispatchQueue.main.async { self.isSearchFieldFocused = true }
                return nil

            case 123:  // Left arrow — move focus left; wrap to input field at start
                guard self.l2.focusedPillIndex != nil else { return event }
                if self.usesVerticalListDockLayout {
                    self.l2.focusedPillIndex = nil
                    self.l2.pillNavViaKeyboard = false
                    DispatchQueue.main.async { self.reclaimSearchInputFocus() }
                    return nil
                }
                let curLeft = self.l2.focusedPillIndex ?? 0
                if curLeft <= 0 {
                    // Already at first pill — return focus to input field
                    self.l2.focusedPillIndex = nil
                    self.l2.pillNavViaKeyboard = false
                    DispatchQueue.main.async { self.isSearchFieldFocused = true }
                    return nil
                }
                self.l2.pillNavViaKeyboard = true
                var idx = max(0, curLeft - 1)
                while idx > 0 && pills[idx].isSeparator { idx -= 1 }
                self.l2.focusedPillIndex = idx
                return nil

            case 124:  // Right arrow — move focus right (skip separators); wrap to input at end
                if self.searchInputHasHighlightedText() {
                    self.l2.focusedPillIndex = nil
                    self.l2.pillNavViaKeyboard = false
                    return event
                }
                guard self.l2.focusedPillIndex != nil else { return event }
                let curIdx = self.l2.focusedPillIndex ?? -1
                if curIdx >= pills.count - 1 {
                    // Already at last pill — return focus to input field
                    self.l2.focusedPillIndex = nil
                    self.l2.pillNavViaKeyboard = false
                    DispatchQueue.main.async { self.isSearchFieldFocused = true }
                    return nil
                }
                self.l2.pillNavViaKeyboard = true
                var idx = min(pills.count - 1, curIdx + 1)
                while idx < pills.count - 1 && pills[idx].isSeparator { idx += 1 }
                self.l2.focusedPillIndex = idx
                return nil

            case 125:  // Down — navigate pills when focused, else pass through to SwiftUI
                if self.usesVerticalListDockLayout, !pills.isEmpty {
                    let curIdx = self.l2.focusedPillIndex ?? -1
                    var downIdx = curIdx + 1
                    while downIdx < pills.count && pills[downIdx].isSeparator { downIdx += 1 }
                    if downIdx < pills.count {
                        self.l2.pillNavViaKeyboard = true
                        self.l2.focusedPillIndex = downIdx
                        return nil
                    }
                }
                return event  // pass through → SwiftUI navigateResults(direction:1)

            case 126:  // Up — navigate pills when focused, else pass through to SwiftUI
                if q.isEmpty && self.showGlobalClipboardPill && !self.globalClipboardText.isEmpty
                    && !self.isSearchBarExpanded
                {
                    withAnimation(.spring(response: 0.25, dampingFraction: 0.78)) {
                        self.clipboardHistoryExpanded.toggle()
                    }
                    return nil
                }
                if self.usesVerticalListDockLayout, !pills.isEmpty {
                    if let cur = self.l2.focusedPillIndex, cur > 0 {
                        var upIdx = cur - 1
                        while upIdx > 0 && pills[upIdx].isSeparator { upIdx -= 1 }
                        self.l2.pillNavViaKeyboard = true
                        self.l2.focusedPillIndex = upIdx
                    } else {
                        self.l2.focusedPillIndex = nil
                        self.l2.pillNavViaKeyboard = false
                        DispatchQueue.main.async { self.isSearchFieldFocused = true }
                    }
                    return nil
                }
                return event  // pass through → SwiftUI navigateResults(direction:-1)

            case 36:  // Return / Enter
                if let findToken = self.lockedFindToken {
                    let payload = self.searchState.query.trimmingCharacters(
                        in: .whitespacesAndNewlines)
                    self.executeFindToken(findToken, userMessage: "find \(payload)")
                    return nil
                }
                // Submenu ghost: Enter executes the first matching child
                if let subCtx = self.submenuGhostContext, let firstChild = subCtx.children.first {
                    let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
                    let pid = firstChild.sourcePID != 0 ? firstChild.sourcePID : frontPID
                    self.searchState.query = ""
                    self.lockedSubmenuParent = nil
                    self.executeDockMenuAction(
                        sourcePID: pid, path: firstChild.path,
                        shortcutChar: firstChild.shortcutChar,
                        shortcutModifiers: firstChild.shortcutModifiers
                    )
                    return nil
                }
                if self.l2.focusedPillIndex != nil,
                    !self.showShortcutSheet,
                    self.executeFocusedOrDirectAppPillIfNeeded()
                {
                    return nil
                }

                if !self.showShortcutSheet,
                    self.executeFirstMatchingFinderFolderPillIfNeeded()
                {
                    return nil
                }

                if !self.showShortcutSheet,
                    self.executeFirstAttachedFinderFolderResultIfNeeded()
                {
                    return nil
                }

                if self.launchTypedAppMatchIfNeeded() {
                    return nil
                }

                if !self.showShortcutSheet, self.executeFocusedOrDirectAppPillIfNeeded() {
                    return nil
                }

                return event

            case 53:  // Escape — clear pill focus and return to input field
                if self.lockedFindToken != nil {
                    self.clearFindToken(preserveQuery: true)
                    return nil
                }
                if self.l2.focusedPillIndex != nil {
                    self.l2.focusedPillIndex = nil
                    self.l2.pillNavViaKeyboard = false
                    DispatchQueue.main.async { self.isSearchFieldFocused = true }
                    return nil
                }
                return event

            case 51:  // Delete/Backspace — deselect focused action pill and return to input field
                if self.l2.focusedPillIndex != nil {
                    self.l2.focusedPillIndex = nil
                    self.l2.pillNavViaKeyboard = false
                    DispatchQueue.main.async { self.isSearchFieldFocused = true }
                    return nil
                }
                return event

            default:
                return event
            }
        }
    }

    // MARK: - Cmd long-press → shortcut sheet

    /// Holds Cmd ≥ 1.5 s without pressing any other key → shows the shortcut sheet.
    func setupCmdHoldMonitor() {
        if let m = cmdHoldMonitor {
            NSEvent.removeMonitor(m)
            cmdHoldMonitor = nil
        }
        if let m = cmdHoldGlobalMonitor {
            NSEvent.removeMonitor(m)
            cmdHoldGlobalMonitor = nil
        }

        cmdHoldMonitor = NSEvent.addLocalMonitorForEvents(matching: [.flagsChanged, .keyDown]) {
            [self] event in
            if event.type == .keyDown {
                // Any keyDown while Cmd held → cancel the long-press timer
                cmdHoldTask?.cancel()
                cmdHoldTask = nil
                if event.modifierFlags.contains(.command) {
                    cmdChordUsed = true
                }

                // Shortcut passthrough: when L2 context dock is open, forward Cmd+key combos
                // to the frontmost app using liveMenuItems shortcut index — no focus switch needed.
                let routingMode = keyRoutingMode
                if routingMode == .contextDock || routingMode == .globalContext,
                    event.modifierFlags.contains(.command),
                    let ch = event.charactersIgnoringModifiers?.lowercased(), !ch.isEmpty,
                    let targetApp = AppDelegate.shared?.previousFrontmostApp
                {
                    let pid = targetApp.processIdentifier
                    let shift = event.modifierFlags.contains(.shift) ? 1 : 0
                    let option = event.modifierFlags.contains(.option) ? 2 : 0
                    let control = event.modifierFlags.contains(.control) ? 4 : 0
                    let mods = shift | option | control
                    // Look up the matching menu item shortcut in the live cache
                    let match = liveMenuItems.first { item in
                        item.shortcutChar?.lowercased() == ch && item.shortcutModifiers == mods
                    }
                    if let item = match, item.isEnabled {
                        self.executeDockMenuAction(
                            sourcePID: pid,
                            path: item.path,
                            shortcutChar: item.shortcutChar,
                            shortcutModifiers: item.shortcutModifiers
                        )
                        return nil  // consume — don't pass to dock's text field
                    }
                }

                return event
            }

            // flagsChanged
            let cmdDown =
                event.modifierFlags.contains(.command)
                && !event.modifierFlags.contains(.shift)
                && !event.modifierFlags.contains(.option)
                && !event.modifierFlags.contains(.control)

            if cmdDown {
                if !cmdTapArmed {
                    cmdTapArmed = true
                    cmdChordUsed = false
                    cmdHoldTriggered = false
                }
                guard cmdHoldTask == nil else { return event }  // already counting
                let targetApp =
                    AppDelegate.shared?.previousFrontmostApp
                    ?? NSWorkspace.shared.frontmostApplication
                cmdHoldTask = Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 800_000_000)  // 0.8 s
                    guard !Task.isCancelled else { return }
                    guard !self.aiMode.isActive, !self.isCompactSmartScope else { return }
                    self.cmdHoldTriggered = true
                    self.presentGlobalShortcutSheet(for: targetApp)
                    self.cmdHoldTask = nil
                }
            } else {
                // Cmd released — bare tap toggles Context Dock ↔ Global Context.
                let shouldToggleScope =
                    cmdTapArmed
                    && !cmdChordUsed
                    && !cmdHoldTriggered
                    && !showShortcutSheet

                cmdHoldTask?.cancel()
                cmdHoldTask = nil
                cmdTapArmed = false
                cmdChordUsed = false
                cmdHoldTriggered = false

                if shouldToggleScope {
                    handleCommandKeyContextScopeToggle()
                    return nil
                }
            }
            return event
        }

        cmdHoldGlobalMonitor = NSEvent.addGlobalMonitorForEvents(matching: [
            .flagsChanged, .keyDown,
        ]) {
            [self] event in
            guard !NSApp.isActive else { return }

            if event.type == .keyDown {
                cmdHoldTask?.cancel()
                cmdHoldTask = nil
                if event.modifierFlags.contains(.command) {
                    cmdChordUsed = true
                }
                return
            }

            let cmdDown =
                event.modifierFlags.contains(.command)
                && !event.modifierFlags.contains(.shift)
                && !event.modifierFlags.contains(.option)
                && !event.modifierFlags.contains(.control)

            if cmdDown {
                if !cmdTapArmed {
                    cmdTapArmed = true
                    cmdChordUsed = false
                    cmdHoldTriggered = false
                }
                guard cmdHoldTask == nil else { return }
                let targetApp = NSWorkspace.shared.frontmostApplication
                cmdHoldTask = Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 800_000_000)
                    guard !Task.isCancelled, !cmdChordUsed else { return }
                    guard !self.aiMode.isActive, !self.isCompactSmartScope else { return }
                    self.cmdHoldTriggered = true
                    self.presentGlobalShortcutSheet(for: targetApp)
                    self.cmdHoldTask = nil
                }
            } else {
                cmdHoldTask?.cancel()
                cmdHoldTask = nil
                cmdTapArmed = false
                cmdChordUsed = false
                cmdHoldTriggered = false
            }
        }
    }

    func presentGlobalShortcutSheet(for app: NSRunningApplication?) {
        guard let app,
            !app.isTerminated,
            app.bundleIdentifier != Bundle.main.bundleIdentifier
        else { return }

        AppDelegate.shared?.recordFrontmostApp(app)
        ContextDockEnvironment.shared.frontmostAppDidChange(
            name: app.localizedName ?? "",
            bundleID: app.bundleIdentifier ?? ""
        )

        globalContextActivation = nil
        aiMode.isActive = false
        shortcutSheetSearchQuery = ""
        shortcutSheetFocusedCommandID = nil
        shortcutSheetSourcePID = app.processIdentifier
        shortcutSheetAppName = app.localizedName ?? "App"

        let cachedItems = MenuWarmCacheService.shared.cachedMenuItems(for: app, maxResults: 180)
        if !cachedItems.isEmpty {
            liveMenuItems = cachedItems
        } else {
            liveMenuItems = []
        }
        showStandaloneShortcutSheetPanel(appName: shortcutSheetAppName)

        Task { @MainActor in
            await MenuWarmCacheService.shared.warm(app: app, force: true)
            let warmedItems = MenuWarmCacheService.shared.cachedMenuItems(for: app, maxResults: 180)
            if !warmedItems.isEmpty {
                self.liveMenuItems = warmedItems
            }
            for _ in 0..<6 {
                if !self.liveMenuItems.isEmpty { break }
                try? await Task.sleep(nanoseconds: 120_000_000)
            }
            guard !self.isCompactSmartScope else { return }
            self.shortcutSheetFocusedCommandID = nil
            self.showShortcutSheet = true
            ShortcutSheetPanelPresenter.shared.update(
                rootView: self.shortcutSheetPanelRootView(appName: self.shortcutSheetAppName)
            )
        }
    }

    func showStandaloneShortcutSheetPanel(appName: String) {
        closeShortcutSheet(resetSearch: false)
        AppDelegate.shared?.launcherWindow?.orderOut(nil)
        showShortcutSheet = true
        ShortcutSheetPanelPresenter.shared.show(
            rootView: shortcutSheetPanelRootView(appName: appName),
            onKeyDown: handleShortcutSheetPanelKey
        )
    }

    func shortcutSheetPanelRootView(appName: String) -> some View {
        ShortcutSheetView(
            commands: shortcutSheetAllCommands,
            appName: appName,
            onSelect: executeShortcutSheetCommand,
            focusedCommandID: $shortcutSheetFocusedCommandID,
            searchQuery: $shortcutSheetSearchQuery
        )
        .padding(10)
        .background {
            RoundedRectangle(cornerRadius: 22, style: .continuous)
                .fill(.ultraThinMaterial)
            RoundedRectangle(cornerRadius: 22, style: .continuous)
                .strokeBorder(
                    LinearGradient(
                        colors: [.white.opacity(0.36), .white.opacity(0.08)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    ),
                    lineWidth: 1
                )
        }
    }

    func handleShortcutSheetPanelKey(_ event: NSEvent) -> Bool {
        handleShortcutSheetKey(event) == nil
    }

    func closeShortcutSheet(resetSearch: Bool = true) {
        showShortcutSheet = false
        shortcutSheetFocusedCommandID = nil
        if resetSearch {
            shortcutSheetSearchQuery = ""
        }
        ShortcutSheetPanelPresenter.shared.close()
    }

    func updateWindowSize() {
        // Cancel any previously scheduled resize — coalesce rapid calls (e.g. every result update)
        windowResizeTask?.cancel()
        windowResizeTask = Task { @MainActor in
            // One-frame delay breaks out of the current layout pass (prevents constraint crash)
            try? await Task.sleep(nanoseconds: 16_000_000)  // 16 ms — one frame; keeps window in sync with content
            guard !Task.isCancelled else { return }
            guard !self.suppressOpenResize else { return }

            guard let window = AppDelegate.shared?.launcherWindow
            else {
                return
            }
            guard window.isVisible else { return }

            let newHeight = self.calculatedHeight
            let newWidth = self.calculatedWidth
            let currentFrame = window.frame
            let screen = window.screen ?? NSScreen.main
            let visibleFrame = screen?.visibleFrame ?? CGRect(x: 0, y: 0, width: 1440, height: 900)

            // Only update if size actually changed
            guard abs(currentFrame.height - newHeight) > 1 || abs(currentFrame.width - newWidth) > 1
            else {
                return
            }

            // Smart vertical positioning — keep anchor point stable so window doesn't jump
            let spaceBelow = currentFrame.minY - visibleFrame.minY
            let spaceAbove = visibleFrame.maxY - currentFrame.maxY

            let resizeAnchorX: CGFloat
            if let keyableWindow = window as? KeyableWindow {
                resizeAnchorX = keyableWindow.horizontalResizeAnchorX ?? currentFrame.midX
                keyableWindow.horizontalResizeAnchorX = resizeAnchorX
            } else {
                resizeAnchorX = currentFrame.midX
            }
            let newX = resizeAnchorX - (newWidth / 2)

            let newY: CGFloat
            if settings.effectiveDockAtBottom {
                // Bottom-anchored: grow upward, keep bottom edge fixed
                newY = currentFrame.minY
            } else if spaceBelow >= newHeight || spaceBelow >= spaceAbove {
                // Anchor top edge, grow downward
                newY = currentFrame.maxY - newHeight
            } else {
                // Anchor bottom edge, grow upward
                newY = currentFrame.minY
            }

            let newFrame = NSRect(x: newX, y: newY, width: newWidth, height: newHeight)

            // Animate resize with a short spring so the panel grows out rather than snapping.
            // NSAnimationContext (not animate:true) avoids cascading jumps when calls overlap.
            NSAnimationContext.beginGrouping()
            NSAnimationContext.current.duration = 0.22
            NSAnimationContext.current.timingFunction = CAMediaTimingFunction(
                controlPoints: 0.2, 0.9, 0.4, 1.0)
            window.animator().setFrame(newFrame, display: true)
            NSAnimationContext.endGrouping()

            // SwiftUI's @FocusState reconciliation fires asynchronously after setFrame and
            // calls becomeFirstResponder → selectAll on the NSTextField.
            // Two DispatchQueue.main.async ticks puts us after that reconciliation pass so
            // we can collapse any unwanted selection to an insertion point at the end.
            DispatchQueue.main.async {
                DispatchQueue.main.async {
                    guard let fe = window.fieldEditor(false, for: nil) as? NSTextView else {
                        return
                    }
                    let len = (fe.string as NSString).length
                    if fe.selectedRange().length > 0, len > 0 {
                        fe.setSelectedRange(NSRange(location: len, length: 0))
                    }
                }
            }
        }
    }

    func loadApplicationsInBackground() {
        searchState.isLoadingApps = true
        Task.detached(priority: .userInitiated) {
            let apps = findAllApplications()
            await MainActor.run {
                withAnimation(.easeInOut(duration: 0.2)) {
                    allApplications = apps
                    searchState.isLoadingApps = false
                }
                if !searchState.query.trimmingCharacters(in: .whitespaces).isEmpty {
                    DispatchQueue.main.async { performSearch() }
                }
            }
        }
    }

    func findAllApplications() -> [SearchResult] {
        let fileManager = FileManager.default
        let appDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]

        var apps: [SearchResult] = []
        var foundPaths = Set<String>()  // Track to avoid duplicates

        print("📂 Searching for applications in directories:")
        for directory in appDirectories {
            print("  - \(directory)")

            // Check if directory exists
            guard fileManager.fileExists(atPath: directory) else {
                print("    ⚠️ Directory does not exist")
                continue
            }

            guard
                let enumerator = fileManager.enumerator(
                    at: URL(fileURLWithPath: directory),
                    includingPropertiesForKeys: [.isDirectoryKey],
                    options: [.skipsHiddenFiles]
                )
            else {
                print("    ⚠️ Could not enumerate directory")
                continue
            }

            var dirCount = 0
            for case let fileURL as URL in enumerator {
                if fileURL.pathExtension == "app" {
                    // Resolve symlinks to get the real path
                    let resolvedURL = fileURL.resolvingSymlinksInPath()

                    // Use the original path for display but resolved for deduplication
                    let displayPath = fileURL.path
                    let realPath = resolvedURL.path

                    // Skip if we've already found this app (by real path)
                    guard !foundPaths.contains(realPath) else {
                        continue
                    }
                    foundPaths.insert(realPath)

                    let appName = fileURL.deletingPathExtension().lastPathComponent
                    let bundleId = Bundle(url: fileURL)?.bundleIdentifier
                    guard
                        !shouldIgnoreApplicationFromAppSearch(
                            appName: appName,
                            bundleIdentifier: bundleId,
                            path: displayPath
                        )
                    else {
                        enumerator.skipDescendants()
                        continue
                    }
                    let icon = NSWorkspace.shared.icon(forFile: fileURL.path)

                    apps.append(
                        SearchResult(
                            title: appName,
                            subtitle: displayPath,
                            icon: icon,
                            action: {
                                NSWorkspace.shared.open(fileURL)
                            },
                            type: .application,
                            filePath: displayPath,
                            contactData: nil
                        ))
                    dirCount += 1

                    if appName == "Safari" {
                        print("    ✅ Found Safari: display=\(displayPath), real=\(realPath)")
                    }

                    // Skip descending into .app bundles to avoid finding nested apps
                    enumerator.skipDescendants()
                }
            }
            print("    ✓ Found \(dirCount) apps")
        }

        // Fallback: Ensure Safari is found using NSWorkspace
        if !foundPaths.contains(where: { $0.contains("Safari.app") }) {
            print("🔍 Safari not found in directories, trying NSWorkspace...")
            if let safariURL = NSWorkspace.shared.urlForApplication(
                withBundleIdentifier: "com.apple.Safari")
            {
                print("  ✅ Found Safari at: \(safariURL.path)")
                foundPaths.insert(safariURL.path)

                let appName = safariURL.deletingPathExtension().lastPathComponent
                let icon = NSWorkspace.shared.icon(forFile: safariURL.path)

                apps.append(
                    SearchResult(
                        title: appName,
                        subtitle: safariURL.path,
                        icon: icon,
                        action: {
                            NSWorkspace.shared.open(safariURL)
                        },
                        type: .application,
                        filePath: safariURL.path,
                        contactData: nil
                    ))
            }
        }

        print("🎯 Total applications found: \(apps.count)")
        let sorted = apps.sorted { $0.title.lowercased() < $1.title.lowercased() }
        if sorted.count > 0 {
            print("📝 First few apps: \(sorted.prefix(5).map { $0.title }.joined(separator: ", "))")
        }
        return sorted
    }

    func findAllShortcuts() -> [SearchResult] {
        var shortcuts: [SearchResult] = []

        print("🔗 Searching for shortcuts using AppIntents framework...")

        // Get the Shortcuts app icon once
        let shortcutsAppIcon: NSImage = {
            if let appURL = NSWorkspace.shared.urlForApplication(
                withBundleIdentifier: "com.apple.shortcuts")
            {
                let icon = NSWorkspace.shared.icon(forFile: appURL.path)
                print("    ✅ Found Shortcuts app icon")
                return icon
            } else {
                print("    ⚠️ Shortcuts app not found, using fallback icon")
                return NSWorkspace.shared.icon(forFileType: "shortcut")
            }
        }()

        // Use ShortcutsLink to query available shortcuts
        // Note: This requires macOS 13+ and proper entitlements
        do {
            // Query all available shortcuts
            let query = ShortcutsLinkQuery()

            // This is a synchronous call that fetches shortcuts
            let results = try query.shortcuts()

            print("    ✅ Found \(results.count) shortcuts via AppIntents")

            for shortcut in results {
                let shortcutName = shortcut.name
                print("    📝 Shortcut: \(shortcutName)")

                shortcuts.append(
                    SearchResult(
                        title: shortcutName,
                        subtitle: "Shortcut",
                        icon: shortcutsAppIcon,
                        action: {
                            // Run the shortcut using the shortcuts:// URL scheme
                            if let encodedName = shortcutName.addingPercentEncoding(
                                withAllowedCharacters: .urlPathAllowed),
                                let url = URL(
                                    string: "shortcuts://run-shortcut?name=\(encodedName)")
                            {
                                print("🚀 Running shortcut: \(shortcutName)")
                                NSWorkspace.shared.open(url)
                            }
                        },
                        type: .shortcut,
                        filePath: nil,
                        contactData: nil
                    ))
            }
        } catch {
            print("    ⚠️ Error querying shortcuts: \(error)")
            print(
                "    💡 Make sure com.apple.security.automation.apple-events entitlement is enabled")
        }

        print("🎯 Total shortcuts found: \(shortcuts.count)")

        let sorted = shortcuts.sorted { $0.title.lowercased() < $1.title.lowercased() }
        if sorted.count > 0 {
            print("📝 Shortcuts: \(sorted.map { $0.title }.joined(separator: ", "))")
        } else {
            print("⚠️ No shortcuts found")
        }
        return sorted
    }

    func findSystemFolders() -> [SearchResult] {
        var folders: [SearchResult] = []
        let fileManager = FileManager.default

        // Get user's home directory
        let homeURL = fileManager.homeDirectoryForCurrentUser

        // Common system folders with their names and icons
        let systemFolders: [(name: String, path: String, icon: String)] = [
            ("Desktop", "\(homeURL.path)/Desktop", "desktop"),
            ("Documents", "\(homeURL.path)/Documents", "doc.text.fill"),
            ("Downloads", "\(homeURL.path)/Downloads", "arrow.down.circle.fill"),
            ("Pictures", "\(homeURL.path)/Pictures", "photo.fill"),
            ("Music", "\(homeURL.path)/Music", "music.note"),
            ("Movies", "\(homeURL.path)/Movies", "film.fill"),
            ("Applications", "/Applications", "app.fill"),
            ("Library", "\(homeURL.path)/Library", "books.vertical.fill"),
            ("Public", "\(homeURL.path)/Public", "person.2.fill"),
            (
                "iCloud Drive", "\(homeURL.path)/Library/Mobile Documents/com~apple~CloudDocs",
                "icloud.fill"
            ),
        ]

        // Scan home directory for user-created folders (like MEGA, Projects, etc.)
        do {
            let homeContents = try fileManager.contentsOfDirectory(
                at: homeURL,
                includingPropertiesForKeys: [.isDirectoryKey, .isHiddenKey],
                options: [.skipsHiddenFiles, .skipsPackageDescendants]
            )

            // Get list of system folder names to exclude duplicates
            let systemFolderNames = Set(systemFolders.map { $0.name.lowercased() })

            for url in homeContents {
                // Check if it's a directory
                guard let resourceValues = try? url.resourceValues(forKeys: [.isDirectoryKey]),
                    resourceValues.isDirectory == true
                else {
                    continue
                }

                let folderName = url.lastPathComponent

                // Skip if it's already in system folders
                guard !systemFolderNames.contains(folderName.lowercased()) else {
                    continue
                }

                // Skip hidden folders (like .ssh, .config, etc.)
                guard !folderName.hasPrefix(".") else {
                    continue
                }

                // Skip known non-interesting folders
                let skipFolders = ["Applications (Parallels)", "Parallels", "VirtualBox VMs"]
                guard !skipFolders.contains(folderName) else {
                    continue
                }

                // Add user folder with inline preview
                let folderPath = url.path
                folders.append(
                    SearchResult(
                        title: folderName,
                        subtitle: url.path,
                        icon: NSWorkspace.shared.icon(forFile: url.path),
                        action: {
                            self.showFolderPreviewInline(path: folderPath)
                        },
                        type: .folder,
                        filePath: url.path,
                        contactData: nil
                    ))

                print("📁 Added user folder: \(folderName)")
            }
        } catch {
            print("⚠️ Error scanning home directory for user folders: \(error)")
        }

        // Add predefined system folders
        for folder in systemFolders {
            let folderURL = URL(fileURLWithPath: folder.path)

            // Check if folder exists
            var isDirectory: ObjCBool = false
            if fileManager.fileExists(atPath: folder.path, isDirectory: &isDirectory),
                isDirectory.boolValue
            {
                folders.append(
                    SearchResult(
                        title: folder.name,
                        subtitle: folder.path,
                        icon: NSImage(
                            systemSymbolName: folder.icon, accessibilityDescription: folder.name),
                        action: {
                            // Folder opening is handled in executeResult
                        },
                        type: .folder,
                        filePath: folder.path,
                        contactData: nil
                    ))
            }
        }

        print("📁 Found \(folders.count) system + user folders")
        return folders
    }

    func findAllContacts() async -> [SearchResult] {
        var contacts: [SearchResult] = []

        // Check if contacts search is enabled in settings
        if !settings.allowContacts {
            print("ℹ️ Contacts search is disabled in settings")
            return []
        }

        // Check permission first
        if !contactManager.hasContactsPermission {
            let granted = await contactManager.requestPermission()
            if !granted {
                print("⚠️ Contacts permission denied")
                return []
            }
        }

        // Get all contacts for searching
        let contactResults = await contactManager.getAllContacts()

        for contactResult in contactResults {
            contacts.append(
                SearchResult(
                    title: contactResult.fullName,
                    subtitle: contactResult.subtitle,
                    icon: contactResult.image,
                    action: { [contactResult] in
                        // Default action: open in Contacts app
                        contactResult.openInContacts()
                    },
                    type: .contact,
                    filePath: nil,
                    contactData: SearchResult.ContactData(
                        primaryEmail: contactResult.primaryEmail,
                        allEmails: contactResult.allEmails,
                        primaryPhone: contactResult.primaryPhone,
                        allPhones: contactResult.allPhones,
                        identifier: contactResult.identifier
                    )
                ))
        }

        print("📇 Loaded \(contacts.count) contacts")
        return contacts
    }

    func initializeFileIndex() {
        Task {
            await fileIndexManager.initialize()
        }
    }

    func searchIndexedFiles(for query: String) {
        guard settings.enableSpotlightSearch,
            settings.enableL1DocumentSearch || settings.enableL1FileSearch
        else {
            indexedFileResults = []
            return
        }

        guard !query.isEmpty else {
            indexedFileResults = []
            return
        }

        guard fileIndexManager.isReady else {
            print("⚠️ File index not ready yet")
            indexedFileResults = []
            return
        }

        // Use the pre-built index for instant search
        let results = fileIndexManager.search(query: query, limit: 20)
            .filter(includeIndexedSearchResult)

        indexedFileResults = results
    }

    func includeIndexedSearchResult(_ result: SearchResult) -> Bool {
        switch result.type {
        case .document:
            return settings.enableL1DocumentSearch
        case .file, .folder:
            return settings.enableL1FileSearch
        default:
            return true
        }
    }

    func searchSystemData(for query: String) async {
        // System data (calendar, reminders, notes, mail) only appears in the
        // dedicated app panel (searchState.activeSmartQueryKey), never in normal search results.
        // This prevents clutter like "call mom" showing under CALENDAR & NOTES when
        // the user types "cal" looking for Calendar.app.
        guard !query.isEmpty else {
            await MainActor.run {
                systemDataResults = []
            }
            return
        }
        // Skip entirely when not in app panel mode
        guard
            await MainActor.run(
                resultType: Bool.self, body: { searchState.activeSmartQueryKey != nil })
        else {
            return
        }

        print("🔍 [SystemSearch] Starting search for: '\(query)'")

        // Search all system data types
        let systemResults = await systemDataManager.searchAll(
            query: query,
            types: [.calendarEvent, .reminder, .note, .mail, .photo, .voiceRecording],
            perTypeLimit: 5
        )

        print("✅ [SystemSearch] Found \(systemResults.count) system data results")
        if systemResults.isEmpty {
            print(
                "⚠️ [SystemSearch] No results found - this might indicate permission issues or no matching data"
            )
        } else {
            print(
                "📊 [SystemSearch] Result types: \(systemResults.map { "\($0.type)" }.joined(separator: ", "))"
            )
        }

        // Convert SystemSearchResult to SearchResult
        let convertedSearchResults = systemResults.map { systemResult -> SearchResult in
            // Map SystemDataType to ResultType
            let resultType: SearchResult.ResultType
            switch systemResult.type {
            case .calendarEvent:
                resultType = .calendarEvent
            case .reminder:
                resultType = .reminder
            case .note:
                resultType = .note
            case .mail:
                resultType = .mail
            case .photo:
                resultType = .photo
            case .message:
                resultType = .message
            case .voiceRecording, .contact:
                // Map voiceRecording to file type and contact is already handled separately
                resultType = .file
            }

            return SearchResult(
                title: systemResult.title,
                subtitle: systemResult.subtitle,
                icon: systemResult.icon,
                action: { systemResult.open() },
                score: 0.0,
                type: resultType,
                filePath: nil,
                contactData: nil
            )
        }

        print("✅ [SystemSearch] Converted to \(convertedSearchResults.count) SearchResults")

        await MainActor.run {
            print("📝 [SystemSearch] Updating systemDataResults on main thread")
            systemDataResults = convertedSearchResults
            print("📝 [SystemSearch] Current systemDataResults count: \(systemDataResults.count)")
            print("📝 [SystemSearch] Current allItems count: \(allItems.count)")
            // Trigger re-search on next run loop to avoid state changes during view updates
            DispatchQueue.main.async {
                performSearchWithoutSpotlight()
            }
        }
    }

    func navigateResults(direction: Int) {
        let results = searchState.results  // Capture current snapshot
        guard !results.isEmpty else {
            searchState.selectedIndex = nil
            return
        }

        // Mark as keyboard navigation for auto-scroll
        isKeyboardNavigation = true

        let movementDirection = direction

        if let currentIndex = searchState.selectedIndex {
            // Validate current index is still valid
            guard currentIndex >= 0 && currentIndex < results.count else {
                searchState.selectedIndex = 0
                return
            }

            let newIndex = currentIndex + movementDirection
            if newIndex >= 0 && newIndex < results.count {
                searchState.selectedIndex = newIndex
            } else if movementDirection < 0 {
                // At the top, stay at top
                searchState.selectedIndex = 0
            } else {
                // At the bottom, stay at bottom
                searchState.selectedIndex = results.count - 1
            }
        } else {
            searchState.selectedIndex = direction > 0 ? 0 : max(results.count - 1, 0)
        }
    }

    func executeSelectedResult() {
        // Cancel any in-flight background search task so its stale result batch
        // cannot overwrite searchState.results after the action has already fired.
        debounceTask?.cancel()
        debounceTask = nil

        // In AI mode, submit to AI provider instead
        if aiMode.isActive {
            if launchTypedAppMatchIfNeeded() {
                return
            }
            let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
            if q.count > 3 {
                submitAIQuery()
            }
            return
        }

        // Validate index bounds before accessing
        if let index = searchState.selectedIndex, index >= 0 && index < searchState.results.count {
            executeResult(searchState.results[index])
        } else if !searchState.results.isEmpty {
            executeResult(searchState.results[0])
        } else {
            // Try to open as URL or perform web search
            handleDirectInput()
        }
    }

    func collapseDockAfterResultExecution() {
        guard settings.autoCollapseToIconAfterAction else { return }
        let shouldKeepGlobalIcon = isGlobalContextActive
        suppressAutomaticGlobalContextUntil = Date().addingTimeInterval(1.6)
        suppressedAutomaticFinderSelectionSignature = nil
        dismissedFinderSelectionSignature = nil

        withAnimation(.spring(response: 0.24, dampingFraction: 0.86)) {
            globalContextActivation =
                shouldKeepGlobalIcon
                ? GlobalContextActivation(autoActivated: false)
                : nil
            aiMode.isActive = false
            showMediaLayer = false
            showFolderPreview = false
            showContextInDock = true
            searchState.query = ""
            searchState.results = []
            searchState.selectedIndex = nil
            searchState.activeSmartQueryKey = nil
            searchState.contextApp = nil
            searchState.isInSmartMode = false
            l2.targetApp = nil
            globalInlineAppScope = nil
            additionalGlobalInlineAppScopes = []
            dismissedGlobalInlineAppScopes = [:]
            l2.focusedPillIndex = nil
            focusedAppPillIndex = nil
            l2.pillNavViaKeyboard = false
            isSearchFieldFocused = false
            isSearchBarExpanded = false
        }

        beginMouseDrivenInteractionGrace(0.55)
        updateWindowSize()
        AppDelegate.shared?.launcherWindow?.resignKey()
    }

    func collapseDockToIconAfterFinderAction() {
        guard showContextInDock else { return }
        guard
            frontmost.bundleID == "com.apple.finder"
                || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
                || axContext.bundleId == "com.apple.finder"
        else { return }

        collapseDockAfterResultExecution()
    }

    func executeResult(_ result: SearchResult) {
        // Track usage for frecency ranking
        UsageTracker.shared.recordAccess(for: result.trackingIdentifier)

        // Contacts → open context panel (contact card)
        if result.type == .contact {
            activateSearchContext(for: result)
            return
        }

        // Files, documents, and folders → Enter always opens them directly
        // (Use Tab or → to open the context panel instead)
        if result.type == .file || result.type == .document || result.type == .folder {
            result.action()
            collapseDockAfterResultExecution()
            return
        }

        if result.type == .application {
            let bundleId =
                Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
            _ = launchApplication(
                bundleIdentifier: bundleId,
                appName: result.title,
                path: result.subtitle
            )
            collapseDockAfterResultExecution()
            return
        }

        // Special handling for shortcuts with context
        if result.type == .shortcut {
            executeShortcutWithContext(result)
        } else {
            result.action()
        }

        collapseDockAfterResultExecution()
    }

    func executeL2Extension(_ ext: ILExtension, context: UserContext) async {
        await MainActor.run {
            l2.isLoading = true
            updateWindowSize()
        }

        defer {
            Task { @MainActor in
                l2.isLoading = false
                updateWindowSize()
            }
        }

        let inputFiles: [URL]
        if case .filesSelected(let urls) = context {
            inputFiles = urls
        } else {
            inputFiles = []
        }

        do {
            if ext.name == "Summarize Webpage",
                frontmost.name.lowercased().contains("safari"),
                let pageText = fetchSafariPageText(),
                !pageText.isEmpty
            {
                let prompt = "Summarize this webpage:\n\n\(pageText)"
                let response = try await sendToAIProvider(query: prompt)
                await MainActor.run {
                    updateL2Results(buildL2OutputResults(title: ext.name, output: response))
                }
                return
            }

            let output = try await LayeredExtensionManager.shared.execute(
                extension: ext, with: inputFiles)
            await MainActor.run {
                updateL2Results(buildL2OutputResults(title: ext.name, output: output))
            }
        } catch {
            print("❌ [L2 Extension] Failed to run \(ext.name): \(error.localizedDescription)")
        }
    }

    func fetchSafariPageText() -> String? {
        let script = """
            tell application "Safari"
                if (count of windows) = 0 then return ""
                set currentTab to current tab of front window
                set js to "document.body ? document.body.innerText : ''"
                return do JavaScript js in currentTab
            end tell
            """

        var error: NSDictionary?
        guard let scriptObject = NSAppleScript(source: script) else {
            return nil
        }

        let output = scriptObject.executeAndReturnError(&error)
        if error != nil {
            return nil
        }

        let text = output.stringValue ?? ""
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            return nil
        }
        return String(trimmed.prefix(6000))
    }

    func fetchSafariPageLinks() -> [String] {
        let script = """
            tell application "Safari"
                if (count of windows) = 0 then return ""
                set currentTab to current tab of front window
                set js to "Array.from(document.links).map(a => a.href).filter(Boolean).join('\\\\n')"
                return do JavaScript js in currentTab
            end tell
            """

        var error: NSDictionary?
        guard let scriptObject = NSAppleScript(source: script) else {
            return []
        }

        let output = scriptObject.executeAndReturnError(&error)
        if error != nil {
            return []
        }

        let text = output.stringValue ?? ""
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            return []
        }

        let links =
            trimmed
            .split(separator: "\n")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        return Array(NSOrderedSet(array: links)) as? [String] ?? links
    }

    func fetchSafariPageImages() -> [String] {
        let script = """
            tell application "Safari"
                if (count of windows) = 0 then return ""
                set currentTab to current tab of front window
                set js to "Array.from(document.images).map(i => i.src).filter(Boolean).join('\\\\n')"
                return do JavaScript js in currentTab
            end tell
            """

        var error: NSDictionary?
        guard let scriptObject = NSAppleScript(source: script) else {
            return []
        }

        let output = scriptObject.executeAndReturnError(&error)
        if error != nil {
            return []
        }

        let text = output.stringValue ?? ""
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            return []
        }

        let images =
            trimmed
            .split(separator: "\n")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        return Array(NSOrderedSet(array: images)) as? [String] ?? images
    }

    func shouldAutoRunL2Extension(query: String, ext: ILExtension) -> Bool {
        let normalized = query.lowercased()
        let name = ext.name.lowercased()

        if normalized.contains(name) {
            return true
        }

        if ext.matchesKeyword(query) {
            return true
        }

        for intent in ext.intents {
            if normalized.contains(intent.action.lowercased()) {
                return true
            }
            if let target = intent.target?.lowercased(), normalized.contains(target) {
                return true
            }
        }

        return false
    }

    func buildL2OutputResults(title: String, output: String) -> [SearchResult] {
        let trimmed = output.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return [] }

        let lines =
            trimmed
            .split(separator: "\n")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        let maxItems = 20
        let items = lines.isEmpty ? [trimmed] : Array(lines.prefix(maxItems))

        return items.map { line in
            let url = URL(string: line)
            return SearchResult(
                title: line,
                subtitle: title,
                icon: NSImage(systemSymbolName: "doc.text", accessibilityDescription: title),
                action: {
                    if let url, url.scheme != nil {
                        NSWorkspace.shared.open(url)
                    } else {
                        NSPasteboard.general.clearContents()
                        NSPasteboard.general.setString(line, forType: .string)
                    }
                },
                score: 0.0,
                type: .extensionCommand,
                filePath: nil,
                contactData: nil
            )
        }
    }

    /// Returns a stable string identifying WHAT the context is about (file path, text hash, URL, app bundle).
    /// Used to detect when the user switches to a different subject so stale chat can be cleared.
    func contextIdentityKey(_ context: UserContext) -> String {
        switch context {
        case .filesSelected(let urls):
            // Use all paths so selecting a different file in same folder is caught
            return "files:" + urls.map(\.path).sorted().joined(separator: "|")
        case .textSelected(let text):
            return "text:" + String(text.prefix(200))
        case .url(let urlString):
            return "url:" + urlString
        case .appFocused(_, let bundleID):
            return "app:" + bundleID
        case .contactSelected(let name):
            return "contact:" + name
        case .none:
            return "none"
        }
    }

    func updateL2Results(_ results: [SearchResult]) {
        l2.extensionResults = results
        if showContextInDock && !showMediaLayer {
            if !isSearchBarExpanded && !results.isEmpty {
                withAnimation(.spring(response: 0.3, dampingFraction: 0.8)) {
                    isSearchBarExpanded = true
                }
            }
            searchState.results = results
            searchState.grouped = {
                var grouped = GroupedResults()
                results.forEach { grouped.add($0) }
                return grouped
            }()
            // Never auto-select in L2 — keeps the search bar as a plain text field
            // so the user can immediately type a follow-up query.
            searchState.selectedIndex = nil
        }
    }

    // MARK: - Intelligent L2 Query Handling

    // Compact prompt for on-device AI (4096 token limit)
    func buildCompactL2Prompt(query: String, context: UserContext, frontmostApp: String?)
        -> String
    {
        var prompt =
            "You are a macOS assistant. Answer the user's question based on the context provided.\n\n"
        prompt += currentDateTimeContextBlock() + "\n\n"
        let queryLower = query.lowercased()
        let isExtensionRequest =
            queryLower.contains("extension") || queryLower.contains("automation")
            || queryLower.contains("script")

        // Add only essential context based on what's selected
        switch context {
        case .filesSelected(let urls):
            let fileAnalysis = ContextDetector.shared.analyzeFiles(urls)
            prompt += "SELECTED FILES (\(fileAnalysis.count)):\n"
            for (index, file) in fileAnalysis.prefix(3).enumerated() {
                prompt += "\n\(index + 1). \(file.url.lastPathComponent)\n"
                prompt += "Type: \(file.type), Size: \(file.size)\n"

                if let content = file.content {
                    // For PDFs and text, limit to 1500 chars
                    let preview = String(content.prefix(1500))
                    prompt += "Content:\n```\n\(preview)\n```\n"
                    if content.count > 1500 {
                        prompt += "(truncated)\n"
                    }
                }
            }
            if fileAnalysis.count > 3 {
                prompt += "\n... and \(fileAnalysis.count - 3) more files\n"
            }
            if frontmostApp?.lowercased() == "finder",
                let currentDir = ContextDetector.shared.getCurrentFinderDirectory()
            {
                prompt += "\nCURRENT DIRECTORY:\n\(currentDir)\n"
            }

        case .textSelected(let text):
            let preview = String(text.prefix(2000))
            prompt += "SELECTED TEXT:\n```\n\(preview)\n```\n"
            if text.count > 2000 {
                prompt += "(truncated)\n"
            }

        case .appFocused(let appName, _):
            if appName.lowercased() == "finder" {
                if let currentDir = ContextDetector.shared.getCurrentFinderDirectory() {
                    prompt += "CURRENT DIRECTORY:\n\(currentDir)\n"
                }
                let selectedFiles = ContextDetector.shared.getFinderSelectedFiles()
                if !selectedFiles.isEmpty {
                    let fileAnalysis = ContextDetector.shared.analyzeFiles(selectedFiles)
                    prompt += "FINDER - SELECTED FILES (\(fileAnalysis.count)):\n"
                    for (index, file) in fileAnalysis.prefix(3).enumerated() {
                        prompt += "\n\(index + 1). \(file.url.lastPathComponent)\n"
                        prompt += "Type: \(file.type), Size: \(file.size)\n"

                        if let content = file.content {
                            let preview = String(content.prefix(1500))
                            prompt += "Content:\n```\n\(preview)\n```\n"
                            if content.count > 1500 {
                                prompt += "(truncated)\n"
                            }
                        }
                    }
                }
            } else {
                prompt += "User is in: \(appName)\n"
            }

        default:
            break
        }

        if frontmostApp?.lowercased().contains("safari") == true {
            if let safariContext = ContextDetector.shared.getSafariContext() {
                prompt += "\nCURRENT SAFARI TAB:\n"
                prompt += "Title: \(safariContext.title)\n"
                prompt += "URL: \(safariContext.url)\n"
            }

            if let pageText = fetchSafariPageText(), !pageText.isEmpty {
                let preview = pageText.prefix(1200)
                prompt += "\nPAGE CONTENT (excerpt):\n```\n\(preview)\n```\n"
                if pageText.count > 1200 {
                    prompt += "(truncated)\n"
                }
            }

            if queryLower.contains("link") || queryLower.contains("social")
                || queryLower.contains("url")
            {
                let links = fetchSafariPageLinks()
                if !links.isEmpty {
                    prompt += "\nPAGE LINKS:\n"
                    for link in links.prefix(30) {
                        prompt += "- \(link)\n"
                    }

                    if queryLower.contains("social") {
                        let socialDomains = [
                            "twitter.com", "x.com", "facebook.com", "instagram.com",
                            "linkedin.com", "youtube.com", "tiktok.com", "github.com", "reddit.com",
                        ]
                        let socialLinks = links.filter { link in
                            socialDomains.contains { link.lowercased().contains($0) }
                        }
                        if !socialLinks.isEmpty {
                            prompt += "\nSOCIAL LINKS:\n"
                            for link in socialLinks.prefix(20) {
                                prompt += "- \(link)\n"
                            }
                        }
                    }
                }
            }

            prompt += SafariDeepContextReader.shared.contextBlock(
                query: query,
                maxRecentHistory: 35,
                maxMatchedHistory: 25,
                maxBookmarks: 25,
                maxCharacters: 4_000
            )
        }

        if isExtensionRequest {
            prompt +=
                "\nUser explicitly requested an extension. You MUST respond with [SUGGEST_EXTENSION] and include working code.\n"
        }

        // Inject tools for every app mentioned in the query (cross-app task support)
        let crossAppSnippet = buildCrossAppToolsSnippet(query: query, frontmostApp: frontmostApp)
        if !crossAppSnippet.isEmpty {
            prompt += crossAppSnippet
        }

        // Proactively suggest missing tools based on query intent
        // e.g. user asks "compress this video" but has no video tool → suggest ffmpeg
        let missingTools = FileTypeToolRegistry.shared.suggestMissingTools(for: query, maxCount: 2)
        if !missingTools.isEmpty {
            let suggestions = missingTools.map {
                "  - \($0.toolName): \($0.description) (brew install \($0.toolName))"
            }.joined(separator: "\n")
            prompt += """

                TOOL SUGGESTION: No installed tool matches this request. Tell the user:
                \(suggestions)
                Provide the exact brew install command so they can tap the install button.

                """
        }

        prompt += "\nUser question: \(query)\n"
        return prompt
    }

    /// Detects which apps are mentioned in the query (beyond the frontmost app),
    /// pulls the user's installed CLI tools for each, and returns a prompt snippet
    /// so the AI can chain tools across apps without any hardcoded AppleScript.
    func buildCrossAppToolsSnippet(query: String, frontmostApp: String?) -> String {
        let q = query.lowercased()
        let frontmostKey =
            searchState.activeSmartQueryKey ?? settings.autoDetectedAppKey
            ?? frontmostApp.flatMap {
                settings.appKey(forBundleID: frontmost.bundleID, appName: $0)
            }

        // Build app mention map from two sources:
        // 1. Built-in well-known app keys with common aliases
        // 2. All user-registered custom apps and tool extensions (dynamic — no hardcoded limit)
        var appMentionMap: [(words: [String], key: String)] = [
            (["notes", "note"], "notes"),
            (["reminders", "reminder", "todo"], "reminders"),
            (["calendar", "event", "meeting"], "calendar"),
            (["mail", "email"], "mail"),
            (["messages", "imessage", "sms"], "messages"),
            (
                [
                    "safari", "browser", "webpage",
                    "page", "link", "url", "tab",
                ], "safari"
            ),
            (["finder", "files", "folder"], "finder"),
            (
                [
                    "spotify", "music", "song",
                    "playlist", "track",
                ], "spotify"
            ),
            (["xcode", "project", "build"], "xcode"),
            (["vscode", "code", "editor"], "vscode"),
        ]
        // Append every user-registered custom app (e.g. "obsidian", "notion", "slack")
        // Words = [key, label.lowercased()] so both "obsidian" and "Obsidian" match
        for entry in settings.customAppEntries {
            let key = entry.key.lowercased()
            guard !appMentionMap.contains(where: { $0.key == key }) else { continue }
            var words: [String] = [key]
            let labelLower = entry.label.lowercased()
            if labelLower != key { words.append(labelLower) }
            appMentionMap.append((words: words, key: key))
        }
        // Also add any appKey that has tool extensions but isn't a custom entry or built-in
        let knownKeys = Set(appMentionMap.map { $0.key })
        for ext in settings.appToolExtensions {
            let key = ext.appKey.lowercased()
            guard !knownKeys.contains(key) else { continue }
            appMentionMap.append((words: [key], key: key))
        }

        // Collect keys of all apps mentioned in the query (excluding frontmost — already injected)
        var mentionedKeys: [String] = []
        for entry in appMentionMap {
            guard entry.key != frontmostKey else { continue }
            if entry.words.contains(where: { q.contains($0) }) {
                mentionedKeys.append(entry.key)
            }
        }
        guard !mentionedKeys.isEmpty else { return "" }

        // For each mentioned app, pull its installed tools (scored against query)
        let pkgs = TerminalPackageManager.shared.packages
        var sections: [String] = []

        for key in mentionedKeys {
            let tools = settings.topExtensions(for: key, query: query, maxCount: 3)
            guard !tools.isEmpty else { continue }

            let appLabel =
                settings.customAppEntries.first(where: { $0.key == key })?.label
                ?? key.capitalized

            let toolLines = tools.map { ext -> String in
                let pkg = pkgs.first(where: { $0.command == ext.toolName })
                var line = "  - \(ext.toolName)"
                if let path = pkg?.installedPath ?? (ext.toolPath.isEmpty ? nil : ext.toolPath) {
                    line += " (\(path))"
                }
                let hint = ext.effectiveHint
                if !hint.isEmpty {
                    line += ": \(String(hint.prefix(200)))"
                } else if let ht = pkg?.helpText, !ht.isEmpty {
                    line += ": \(String(ht.prefix(200)))"
                }
                if !ext.profile.exampleCommands.isEmpty {
                    line +=
                        " | e.g. \(ext.profile.exampleCommands.prefix(2).joined(separator: " / "))"
                }
                return line
            }.joined(separator: "\n")

            sections.append("\(appLabel) tools:\n\(toolLines)")
        }

        guard !sections.isEmpty else { return "" }

        return """

            ADDITIONAL APP TOOLS FOR THIS TASK:
            \(sections.joined(separator: "\n\n"))

            RULES:
            - Use these tools (via run_command) to complete the cross-app task.
            - Chain run_command calls: first get data from the current app, then pass it to the target app's tool.
            - After completing, respond with a single clean confirmation line (e.g. "Saved." or "Done — note created in Notes.").
            - Do NOT use AppleScript unless no CLI tool is available for an app.

            """
    }

    func buildIntelligentL2Prompt(
        query: String, context: UserContext, frontmostApp: String?
    ) -> String {
        // Check if using on-device AI (has 4096 token limit) - need MUCH shorter prompt
        let isOnDeviceAI = settings.selectedAIProvider == .onDevice
        let queryLower = query.lowercased()
        let isExtensionRequest =
            queryLower.contains("extension") || queryLower.contains("automation")
            || queryLower.contains("script")

        if isOnDeviceAI {
            // COMPACT PROMPT for on-device AI (4096 token limit)
            return buildCompactL2Prompt(query: query, context: context, frontmostApp: frontmostApp)
        }

        // FULL PROMPT for cloud AI providers (larger context windows)
        // Get current date and time
        let now = Date()
        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .full
        dateFormatter.timeStyle = .medium
        let currentDateTime = dateFormatter.string(from: now)

        let calendar = Calendar.current
        let weekday = calendar.component(.weekday, from: now)
        let weekdayName = dateFormatter.weekdaySymbols[weekday - 1]

        var prompt = """
            You are an intelligent assistant integrated into macOS. You have access to system information and can help users with file operations, app context, and more.

            CURRENT DATE & TIME:
            📅 \(currentDateTime) (\(weekdayName))

            IMPORTANT: Use this current date/time to:
            - Filter calendar events correctly (today, tomorrow, this week, this month)
            - Understand relative time queries ("today", "tomorrow", "next Monday")
            - Provide accurate time-based responses

            """

        // Add system capabilities
        prompt += """

            CAPABILITIES:
            - Access to user's file system (read directories, find files, get file info)
            - Context awareness (knows which app is active and what's selected)
            - Can execute shell commands for file operations
            - Can use installed extensions/tools
            - macOS system knowledge
            - Can directly analyze and explain files (images, documents, code, etc.)
            - Access to REAL Calendar events, Reminders, Contacts (ALWAYS available regardless of frontmost app)
            - Full Safari control: search, navigate, bookmark, manage tabs
            - AI-powered intelligent understanding of user intent

            INSTALLED TERMINAL TOOLS:
            \(TerminalToolDiscovery.installedToolsSummary())

            SAFARI CONTROL & ANALYSIS:
            - Search/open URL: [EXECUTE_COMMAND: open -a Safari "https://youtube.com"]
            - Google search: [EXECUTE_COMMAND: open -a Safari "https://google.com/search?q=your+query"]
            - Access ALL open tabs and their URLs (provided in context when in Safari)
            - Analyze tab content by titles and URLs
            - Answer questions about tabs ("which tabs are about X?", "how many tabs?")
            - Summarize research across multiple tabs
            - Can execute AppleScript for Safari operations (bookmarks, navigation, tab management)

            IMPORTANT RULES:
            - For simple file questions, answer directly without extensions
            - For Calendar/Reminders/Contacts questions, use the ACTUAL data provided below
            - For Safari PDF save, use File > Export as PDF from the menu bar
            - For Safari search/navigate, use [EXECUTE_COMMAND] with appropriate URLs
            - For Safari tab analysis, use the tab data provided in context to answer intelligently
            - Only suggest extensions for complex automation that can't be done with existing APIs
            - When suggesting extensions, provide COMPLETE, WORKING code ready to save and use
            - You are INTELLIGENT - understand user intent and provide the most helpful response

            EXTENSION SUGGESTION CRITERIA:
            - Task requires automation not available via existing APIs
            - Task would be reused frequently (not one-time)
            - Task involves file format conversion, image processing, or complex workflows
            - For PDF save in Safari: Tell user to use File > Export as PDF
            - For tab management/analysis: Answer directly with provided data, DON'T suggest extension
            - For recurring workflows: SUGGEST extension with complete code

            """

        if isExtensionRequest {
            prompt += """

                USER EXPLICITLY REQUESTED AN EXTENSION.
                You MUST respond with [SUGGEST_EXTENSION] and include complete, working code.

                """
        }

        // Add available extensions catalog
        let availableExtensions = getAvailableExtensionsForContext(
            frontmostApp: frontmostApp, context: context)

        if !availableExtensions.isEmpty {
            prompt += """

                AVAILABLE EXTENSIONS/TOOLS:
                You have access to these pre-built extensions that can help complete tasks:

                """

            for (index, ext) in availableExtensions.prefix(10).enumerated() {
                let keywordsList =
                    ext.keywords.isEmpty ? "N/A" : ext.keywords.prefix(5).joined(separator: ", ")
                prompt += """
                    \(index + 1). \(ext.name)
                       - Description: \(ext.description)
                       - Keywords: \(keywordsList)
                       - Can do: \(ext.capabilities)
                       - Category: \(ext.category)

                    """
            }

            if availableExtensions.count > 10 {
                prompt += "... and \(availableExtensions.count - 10) more extensions available\n"
            }

            prompt += """

                HOW TO USE EXTENSIONS:
                - If the user's request matches an extension, respond with:
                  [USE_EXTENSION: extension_name]
                - Example: If user asks "compress these files" and you have an "Archive Tool" extension, respond with:
                  "I'll compress your files using the Archive Tool.
                  [USE_EXTENSION: Archive Tool]"
                - You can explain what you're doing AND trigger the extension in the same response

                """
        } else {
            // No extensions available, suggest creating one if applicable
            prompt += """

                NOTE: No extensions are currently available for this context.
                You can still help the user by:
                1. Answering their question directly
                2. Suggesting they create an extension if this is a recurring task

                """
        }

        // Add selected text context FIRST (most important for user queries)
        if case .textSelected(let text) = context, !text.isEmpty {
            let preview = text.prefix(2000)  // Show more text for better context
            prompt += """

                📝 SELECTED TEXT (User has this text selected/visible):
                ```
                \(preview)
                ```
                """
            if text.count > 2000 {
                prompt += "\n... (truncated, total \(text.count) characters)\n"
            }
            prompt += "\n"
        }

        // UNIVERSAL APP CONTEXT - AI automatically understands any app
        if let appName = frontmostApp, !appName.isEmpty {
            // Get comprehensive context for current app
            // IMPORTANT: Use the app from the context, NOT the current frontmost app (which is ILauncher)
            var targetApp: NSRunningApplication?

            // Extract bundle ID from context
            switch context {
            case .appFocused(_, let bundleID):
                // Find the running app by bundle ID
                targetApp = NSWorkspace.shared.runningApplications.first {
                    $0.bundleIdentifier == bundleID
                }
            default:
                // Fallback: try to find by name
                targetApp = NSWorkspace.shared.runningApplications.first {
                    $0.localizedName == appName
                }
            }

            // If we found the target app, get its context
            if let app = targetApp {
                let comprehensiveContext = ContextDetector.shared.getComprehensiveContext(
                    frontmostApp: app)

                prompt += """

                    ========================================
                    FRONTMOST APP: \(appName)
                    ========================================

                    You are helping the user with \(appName).
                    ALL user queries are in the context of \(appName) unless explicitly stated otherwise.

                    AUTOMATICALLY AVAILABLE CONTEXT:
                    """

                // Add all detected context
                for ctx in comprehensiveContext {
                    switch ctx {
                    case .browserTabs(let tabs):
                        prompt += "\n\n🌐 ALL BROWSER TABS (\(tabs.count) tabs):\n"
                        var currentWindow = 0
                        for (index, tab) in tabs.prefix(50).enumerated() {
                            if tab.windowIndex != currentWindow {
                                currentWindow = tab.windowIndex
                                prompt += "\n--- Window \(currentWindow) ---\n"
                            }
                            prompt += "\(tab.tabIndex). \(tab.title)\n   \(tab.url)\n"
                        }
                        if tabs.count > 50 {
                            prompt += "... and \(tabs.count - 50) more tabs\n"
                        }

                    case .clipboard(let content):
                        let preview = content.prefix(500)
                        prompt += "\n\n📋 CLIPBOARD:\n\(preview)"
                        if content.count > 500 {
                            prompt += "...\n(total: \(content.count) chars)"
                        }

                    case .music(let title, let artist, let album):
                        prompt += "\n\n🎵 CURRENTLY PLAYING:\n"
                        prompt += "Song: \(title)\n"
                        prompt += "Artist: \(artist)\n"
                        prompt += "Album: \(album)\n"

                    case .podcast(let title, let show):
                        prompt += "\n\n🎙️ CURRENTLY PLAYING PODCAST:\n"
                        prompt += "Episode: \(title)\n"
                        prompt += "Show: \(show)\n"

                    case .files(let urls):
                        prompt += "\n\n📁 SELECTED FILES (\(urls.count)):\n"
                        for url in urls.prefix(20) {
                            prompt += "- \(url.lastPathComponent)\n"
                        }

                    case .text(let text):
                        let preview = text.prefix(1000)
                        prompt += "\n\n📝 SELECTED TEXT:\n\(preview)"
                        if text.count > 1000 {
                            prompt += "...\n"
                        }

                    case .browserTab(let url, let title):
                        prompt += "\n\n🌐 CURRENT TAB:\n"
                        prompt += "Title: \(title)\n"
                        prompt += "URL: \(url)\n"

                        // Fetch actual page content for Safari
                        if appName.lowercased() == "safari" {
                            if let pageText = fetchSafariPageText(), !pageText.isEmpty {
                                let preview = pageText.prefix(3000)
                                prompt += "\n📄 PAGE CONTENT:\n```\n\(preview)\n```\n"
                                if pageText.count > 3000 {
                                    prompt += "... (total: \(pageText.count) characters)\n"
                                }
                                prompt +=
                                    "\n✅ Use this ACTUAL page content to answer questions about what's on the page!\n"
                            }
                        }

                    case .note(let content):
                        let preview = content.prefix(1000)
                        prompt += "\n\n📝 CURRENT NOTE:\n\(preview)"
                        if content.count > 1000 {
                            prompt += "...\n"
                        }

                    case .email(let subject, let from, let content):
                        prompt += "\n\n📧 SELECTED EMAIL:\n"
                        prompt += "Subject: \(subject)\n"
                        prompt += "From: \(from)\n"

                        if !content.isEmpty {
                            let preview = content.prefix(2000)
                            prompt += "\nEmail Content:\n```\n\(preview)\n```\n"
                            if content.count > 2000 {
                                prompt += "... (total: \(content.count) characters)\n"
                            }
                            prompt += "\n✅ Use this ACTUAL email content to answer questions!\n"
                        }

                    case .app:
                        break  // Already shown above
                    }
                }
            }

            prompt += "\n\n"

            // Add app-specific capabilities
            switch appName.lowercased() {
            case "finder":
                prompt += """
                    - User is in Finder (file manager)
                    - User has full access to their file system
                    - Can perform: find files, check sizes, list directories, organize files
                    - Downloads folder: ~/Downloads
                    - Desktop folder: ~/Desktop
                    - Documents folder: ~/Documents

                    """

                // Get current Finder directory (ALWAYS include this for context)
                if let currentDir = ContextDetector.shared.getCurrentFinderDirectory() {
                    prompt += "\n📂 CURRENT DIRECTORY:\n"
                    prompt += "Path: \(currentDir)\n"
                    prompt += "Folder: \(URL(fileURLWithPath: currentDir).lastPathComponent)\n"
                }

                // Get selected files/folders and analyze them
                let selectedFiles = ContextDetector.shared.getFinderSelectedFiles()
                if !selectedFiles.isEmpty {
                    let fileAnalysis = ContextDetector.shared.analyzeFiles(selectedFiles)

                    prompt += "\n"
                    prompt += "========================================\n"
                    prompt += "📁 SELECTED FILES (\(fileAnalysis.count))\n"
                    prompt += "========================================\n"

                    for (index, file) in fileAnalysis.enumerated() {
                        let fileName = file.url.lastPathComponent
                        prompt += "\n\(index + 1). \(fileName)\n"
                        prompt += "   Type: \(file.type)\n"
                        prompt += "   Size: \(file.size)\n"
                        prompt += "   Path: \(file.url.path)\n"

                        // If it's a text/code file with content, include it
                        if let content = file.content {
                            prompt += "\n   📄 FILE CONTENT:\n"
                            prompt += "   ```\n"
                            let lines = content.components(separatedBy: "\n").prefix(50)
                            prompt += lines.joined(separator: "\n")
                            prompt += "\n   ```\n"

                            // Special note for PDFs
                            if file.type == "pdf" {
                                prompt +=
                                    "\n   ✅ THIS IS THE ACTUAL PDF CONTENT ABOVE - Use it to answer user questions!\n"
                            }
                        } else {
                            // No content extracted
                            if file.type == "pdf" {
                                prompt +=
                                    "\n   ⚠️ Could not extract text from this PDF (might be image-based/scanned)\n"
                            }
                        }

                        // Special handling for images
                        if file.isImage {
                            prompt += "\n   📷 This is an image file - you can analyze it visually\n"
                        }
                    }

                    prompt += "\n========================================\n"
                } else {
                    prompt += "\n(No files selected)\n"
                }

                // ALWAYS include instructions for file operations
                prompt += """

                    IMPORTANT INSTRUCTIONS FOR FILE OPERATIONS:

                    CONTEXT AVAILABLE:
                    - Current directory path (where the user is in Finder)
                    - Selected files/folders with full paths, types, sizes, and content (if any)
                    - For PDFs: Text content has been automatically extracted from the PDF
                    - For text/code files: Full content is provided
                    - You can reference these paths in your responses and extension scripts

                    1. ANALYSIS QUERIES: For questions like "what is this file?", "explain this code", "summarize this PDF", "what is this PDF about?" → Analyze and answer directly using the provided content
                    2. ACTION QUERIES: For tasks like "move to Downloads", "copy to folder X", "send via iMessage", "add to Notes" → Suggest creating an extension
                    3. DIRECTORY QUERIES: User can ask about current directory, list files, find files, organize files, etc.

                    IMPORTANT: When user asks "what is this PDF about?" or similar questions about PDFs, you MUST use the PDF text content provided above to answer. DO NOT say you cannot read PDFs - the content is already extracted and provided!
                    IMPORTANT: Do NOT suggest an extension if you can answer directly from this content.

                    WHEN TO SUGGEST EXTENSIONS:
                    - ONLY when the task cannot be completed directly with the provided context
                    - Examples: batch processing, file format conversion, multi-step automation

                    HOW TO SUGGEST EXTENSIONS:
                    Use this format:
                    [SUGGEST_EXTENSION]
                    {
                        "name": "Task Name",
                        "description": "What it does",
                        "app": "Finder",
                        "code": "#!/bin/bash\\n# Your working script here\\n# You have access to: SELECTED_FILES (if any) and CURRENT_DIR"
                    }
                    [/SUGGEST_EXTENSION]

                    The extension will be automatically:
                    - Added to the Extensions directory
                    - Grouped under "Finder" app
                    - Immediately executed to complete the user's request

                    """

            case "safari":
                prompt += """
                    - User is browsing in Safari
                    - You can answer questions about the current page and user intent
                    - You can reference the current URL/title below

                    """

                if let safariContext = ContextDetector.shared.getSafariContext() {
                    prompt += "\n🌐 CURRENT TAB:\n"
                    prompt += "Title: \(safariContext.title)\n"
                    prompt += "URL: \(safariContext.url)\n"
                }

                if let pageText = fetchSafariPageText(), !pageText.isEmpty {
                    let preview = pageText.prefix(2000)
                    prompt += "\n📄 PAGE CONTENT (excerpt):\n"
                    prompt += "```\n\(preview)\n```\n"
                    if pageText.count > 2000 {
                        prompt += "... (truncated, total \(pageText.count) characters)\n"
                    }
                }

                if queryLower.contains("link") || queryLower.contains("social")
                    || queryLower.contains("url")
                {
                    let links = fetchSafariPageLinks()
                    if !links.isEmpty {
                        prompt += "\n🔗 PAGE LINKS:\n"
                        for link in links.prefix(50) {
                            prompt += "- \(link)\n"
                        }

                        if queryLower.contains("social") {
                            let socialDomains = [
                                "twitter.com", "x.com", "facebook.com", "instagram.com",
                                "linkedin.com", "youtube.com", "tiktok.com", "github.com",
                                "reddit.com",
                            ]
                            let socialLinks = links.filter { link in
                                socialDomains.contains { link.lowercased().contains($0) }
                            }
                            if !socialLinks.isEmpty {
                                prompt += "\n🔗 SOCIAL LINKS:\n"
                                for link in socialLinks.prefix(30) {
                                    prompt += "- \(link)\n"
                                }
                            }
                        }
                    }
                }

            case "calendar":
                prompt += """
                    - User is in Calendar app
                    - Can help with: event analysis, scheduling, finding free time

                    """

                // Detect if query is simple (viewing) or complex (needs extension)
                let isSimpleCalendarQuery =
                    queryLower.contains("show") || queryLower.contains("list")
                    || queryLower.contains("what") || queryLower.contains("today")
                    || queryLower.contains("this week") || queryLower.contains("this month")

                let isComplexCalendarQuery =
                    queryLower.contains("create") || queryLower.contains("add event")
                    || queryLower.contains("schedule") || queryLower.contains("export")
                    || queryLower.contains("sync") || queryLower.contains("free time")
                    || queryLower.contains("available")

                if isComplexCalendarQuery {
                    prompt += """

                        USER QUERY REQUIRES COMPLEX CALENDAR OPERATIONS.
                        Suggest creating a custom extension for this task.

                        Examples needing extensions:
                        - Creating/modifying events
                        - Finding free time slots
                        - Exporting calendar data
                        - Syncing calendars
                        - Complex filtering by date ranges

                        Use [SUGGEST_EXTENSION] tag with working code.

                        """
                } else if isSimpleCalendarQuery {
                    // Fetch REAL calendar events for viewing
                    let calendarEvents = AppleAppsAPI.shared.getCalendarEvents(limit: 50)
                    if !calendarEvents.isEmpty {
                        prompt += "\n📅 ACTUAL CALENDAR EVENTS (Current Month):\n"

                        let dateFormatter = DateFormatter()
                        dateFormatter.dateFormat = "MMM d, yyyy h:mm a"

                        for event in calendarEvents {
                            if let title = event["title"] as? String,
                                let startDateStr = event["startDate"] as? String,
                                let startDate = ISO8601DateFormatter().date(from: startDateStr)
                            {
                                let formattedDate = dateFormatter.string(from: startDate)
                                let isAllDay = event["isAllDay"] as? Bool ?? false
                                let location = event["location"] as? String ?? ""

                                prompt += "- \(title)"
                                prompt += " on \(formattedDate)"
                                if isAllDay { prompt += " (All Day)" }
                                if !location.isEmpty { prompt += " at \(location)" }
                                prompt += "\n"
                            }
                        }
                        prompt +=
                            "\nIMPORTANT: Use this ACTUAL calendar data to answer questions. Don't make up generic holidays.\n"
                    } else {
                        prompt += "\nNo upcoming calendar events found.\n"
                    }
                }

            case "notes":
                prompt += """
                    - User is in Notes app
                    - Can help with: note content, summarization, organization

                    """

            case "mail":
                prompt += """
                    - User is in Mail app
                    - Can help with: email analysis, drafting replies, organizing
                    - Menu pills are for Mail commands; attached Mail context is for mailbox questions

                    """

                if isCurrentMailContextAttached() {
                    if let block = buildAttachedMailContextBlock(for: query) {
                        prompt += block
                    }
                } else {
                    prompt += """

                        MAILBOX DATA: Not attached.
                        If the user wants mailbox questions answered from real Mail data, tell them to press the + button in the dock while Mail is frontmost.

                        """
                }

            case "safari", "chrome", "arc":
                prompt += """
                    - User is in \(appName) browser
                    - FULL BROWSER CONTROL available

                    """

                // Detect user intent for Safari operations
                let queryLower = query.lowercased()

                // Check if user wants to search/navigate
                let isSearchQuery =
                    queryLower.contains("search") || queryLower.contains("youtube")
                    || queryLower.contains("google") || queryLower.contains("open")
                    || queryLower.contains("go to") || queryLower.contains("navigate")

                let isBookmarkQuery = queryLower.contains("bookmark")

                // Detect PDF save requests (should use API, not extension)
                let isPDFSaveQuery =
                    (queryLower.contains("save") || queryLower.contains("export"))
                    && (queryLower.contains("pdf") || queryLower.contains("page"))

                // Detect tab queries (should answer with data, not extension)
                let isTabQuery =
                    queryLower.contains("tab")
                    && (queryLower.contains("list") || queryLower.contains("show")
                        || queryLower.contains("how many") || queryLower.contains("which")
                        || queryLower.contains("what") || queryLower.contains("find")
                        || queryLower.contains("about") || queryLower.contains("opened")
                        || queryLower.contains("open") || queryLower.contains("count"))

                let isComplexBrowserQuery =
                    !isPDFSaveQuery && !isTabQuery
                    && (queryLower.contains("save") || queryLower.contains("export")
                        || queryLower.contains("close") || queryLower.contains("organize")
                        || queryLower.contains("group") || queryLower.contains("screenshot"))

                if isTabQuery {
                    prompt += """

                        TAB QUERY DETECTED:
                        The user is asking about Safari tabs. ALL tab data is provided below.
                        Analyze the tabs and answer intelligently:
                        - Count tabs if asked "how many tabs"
                        - List specific tabs if asked "show tabs about X"
                        - Summarize research if asked about topics across tabs
                        - Find tabs matching criteria

                        DO NOT suggest creating an extension - ANSWER WITH THE DATA PROVIDED!

                        """
                } else if isSearchQuery {
                    prompt += """

                        SAFARI SEARCH/NAVIGATION COMMANDS:
                        - To open YouTube: [EXECUTE_COMMAND: open -a Safari "https://youtube.com"]
                        - To search on Google: [EXECUTE_COMMAND: open -a Safari "https://google.com/search?q=SEARCH_TERM"]
                        - To search YouTube: [EXECUTE_COMMAND: open -a Safari "https://youtube.com/results?search_query=SEARCH_TERM"]
                        - To open any URL: [EXECUTE_COMMAND: open -a Safari "https://example.com"]

                        IMPORTANT: Understand user intent intelligently:
                        - "youtube" → open YouTube homepage
                        - "search for cats on youtube" → open YouTube search for cats
                        - "google python tutorial" → Google search for python tutorial
                        - Replace spaces in search terms with + symbols

                        """
                } else if isBookmarkQuery {
                    prompt += """

                        BOOKMARK OPERATIONS:
                        Create an extension using AppleScript to add current tab to bookmarks:
                        tell application "Safari"
                            add current tab of front window to bookmarks
                        end tell

                        Use [SUGGEST_EXTENSION] tag with complete code.

                        """
                } else if isComplexBrowserQuery {
                    prompt += """

                        COMPLEX BROWSER OPERATIONS - Suggest Extension:
                        - Save/export tabs to files
                        - Close tabs matching criteria
                        - Take screenshots of pages
                        - Organize tabs into groups

                        Use [SUGGEST_EXTENSION] tag with working AppleScript code.

                        """
                } else {
                    // For viewing tabs or general browser queries, provide actual URLs from ALL windows
                    if let frontmostApp = NSWorkspace.shared.frontmostApplication {
                        let comprehensiveContext = ContextDetector.shared.getComprehensiveContext(
                            frontmostApp: frontmostApp)

                        // Look for browserTabs or clipboard in comprehensive context
                        for ctx in comprehensiveContext {
                            if case .browserTabs(let tabs) = ctx {
                                prompt += "\n🌐 ALL BROWSER TABS (All Windows):\n"
                                prompt += "Total: \(tabs.count) tabs across multiple windows\n\n"

                                var currentWindow = 0
                                for tab in tabs.prefix(50) {  // Limit to 50 tabs to avoid huge prompts
                                    if tab.windowIndex != currentWindow {
                                        currentWindow = tab.windowIndex
                                        prompt += "\n--- Window \(currentWindow) ---\n"
                                    }
                                    prompt += "\(tab.tabIndex). \(tab.title)\n   URL: \(tab.url)\n"
                                }

                                if tabs.count > 50 {
                                    prompt += "\n... and \(tabs.count - 50) more tabs\n"
                                }

                                prompt += "\nYou can:\n"
                                prompt += "- List specific tabs\n"
                                prompt += "- Search for tabs by title or URL\n"
                                prompt += "- Answer questions about tab content\n"
                                prompt += "- Summarize research across tabs\n"
                                break
                            }
                        }

                        // Also include clipboard if available
                        for ctx in comprehensiveContext {
                            if case .clipboard(let content) = ctx {
                                prompt += "\n\n📋 CLIPBOARD CONTENT:\n"
                                let preview = content.prefix(500)
                                prompt += "\(preview)\n"
                                if content.count > 500 {
                                    prompt +=
                                        "... (clipboard has \(content.count) total characters)\n"
                                }
                                prompt +=
                                    "\nYou can reference clipboard content in your response.\n"
                                break
                            }
                        }
                    }
                }

            default:
                prompt += "- User is currently in: \(appName)\n"
            }
        }

        // ALWAYS include clipboard if available (for ALL apps, not just browsers)
        if let frontmostApp = NSWorkspace.shared.frontmostApplication {
            if let clipboard = ContextDetector.shared.getClipboardContent() {
                prompt += "\n📋 CLIPBOARD CONTENT (Always Available):\n"
                let preview = clipboard.prefix(1000)
                prompt += "\(preview)\n"
                if clipboard.count > 1000 {
                    prompt += "... (clipboard has \(clipboard.count) total characters)\n"
                }
                prompt += "\nYou can reference or use clipboard content in your response.\n"
            }

            // Include currently playing music/podcast if available
            if let musicInfo = ContextDetector.shared.getMusicInfo() {
                prompt += "\n🎵 CURRENTLY PLAYING:\n"
                prompt += "Track: \(musicInfo.title)\n"
                prompt += "Artist: \(musicInfo.artist)\n"
                prompt += "Album: \(musicInfo.album)\n"
                prompt +=
                    "\nYou can reference this music in your response or help with music-related queries.\n"
            } else if let podcastInfo = ContextDetector.shared.getPodcastInfo() {
                prompt += "\n🎙️ CURRENTLY PLAYING PODCAST:\n"
                prompt += "Episode: \(podcastInfo.title)\n"
                prompt += "Show: \(podcastInfo.show)\n"
                prompt += "\nYou can reference this podcast in your response.\n"
            }
        }

        // ALWAYS provide system data (Calendar, Reminders, Contacts) - AI can use when relevant
        prompt += "\n=== SYSTEM DATA (Always Available) ===\n"

        // Calendar Events - always fetch
        let calendarEvents = AppleAppsAPI.shared.getCalendarEvents(limit: 30)
        if !calendarEvents.isEmpty {
            prompt += "\n📅 CALENDAR EVENTS (Next 30 days from NOW):\n"
            let eventDateFormatter = DateFormatter()
            eventDateFormatter.dateFormat = "MMM d, yyyy h:mm a"

            let relativeDateFormatter = RelativeDateTimeFormatter()
            relativeDateFormatter.unitsStyle = .full

            for event in calendarEvents.prefix(15) {
                if let title = event["title"] as? String,
                    let startDateStr = event["startDate"] as? String,
                    let startDate = ISO8601DateFormatter().date(from: startDateStr)
                {
                    let formattedDate = eventDateFormatter.string(from: startDate)
                    let isAllDay = event["isAllDay"] as? Bool ?? false

                    // Calculate relative time
                    let timeInterval = startDate.timeIntervalSince(now)
                    let relativeTime = relativeDateFormatter.localizedString(
                        for: startDate, relativeTo: now)

                    prompt += "- \(title)\n"
                    prompt += "  Date: \(formattedDate)"
                    if isAllDay { prompt += " (All Day)" }
                    prompt += "\n  Time from now: \(relativeTime)\n"
                }
            }
        } else {
            prompt += "\n📅 CALENDAR: No upcoming events\n"
        }

        // Reminders - always fetch
        let reminders = AppleAppsAPI.shared.getReminders(limit: 15)
        if !reminders.isEmpty {
            prompt += "\n📝 REMINDERS:\n"
            let reminderDateFormatter = DateFormatter()
            reminderDateFormatter.dateStyle = .medium
            reminderDateFormatter.timeStyle = .short

            let relativeDateFormatter = RelativeDateTimeFormatter()
            relativeDateFormatter.unitsStyle = .full

            for reminder in reminders.prefix(10) {
                if let title = reminder["title"] as? String {
                    prompt += "- \(title)"
                    if let dueDateStr = reminder["dueDate"] as? String,
                        let dueDate = ISO8601DateFormatter().date(from: dueDateStr)
                    {
                        let formattedDate = reminderDateFormatter.string(from: dueDate)
                        let relativeTime = relativeDateFormatter.localizedString(
                            for: dueDate, relativeTo: now)

                        // Check if overdue
                        let isOverdue = dueDate < now
                        if isOverdue {
                            prompt += " ⚠️ OVERDUE"
                        }
                        prompt += "\n  Due: \(formattedDate) (\(relativeTime))"
                    }
                    prompt += "\n"
                }
            }
        } else {
            prompt += "\n📝 REMINDERS: No active reminders\n"
        }

        // Contacts - provide count, AI can ask for specific searches
        prompt += "\n👥 CONTACTS: Available (you can search by name if user asks)\n"

        prompt +=
            "\nIMPORTANT: This system data is ALWAYS available. Use it intelligently when relevant to user's query.\n"
        prompt += "========================================\n"

        // Add selected files context
        if case .filesSelected(let urls) = context, !urls.isEmpty {
            prompt += "\nSELECTED FILES:\n"
            for url in urls.prefix(10) {
                prompt += "- \(url.lastPathComponent) (\(url.pathExtension))\n"
            }
            if urls.count > 10 {
                prompt += "... and \(urls.count - 10) more files\n"
            }

            let fileAnalysis = ContextDetector.shared.analyzeFiles(urls)
            if !fileAnalysis.isEmpty {
                prompt += "\nSELECTED FILE DETAILS:\n"
                for (index, file) in fileAnalysis.prefix(3).enumerated() {
                    prompt += "\n\(index + 1). \(file.url.lastPathComponent)\n"
                    prompt += "Type: \(file.type)\n"
                    prompt += "Size: \(file.size)\n"
                    if let content = file.content, !content.isEmpty {
                        let preview = content.prefix(3000)
                        prompt += "Content:\n```\n\(preview)\n```\n"
                        if content.count > 3000 {
                            prompt += "... (truncated)\n"
                        }
                        if file.type == "pdf" {
                            prompt += "✅ PDF text extracted above. Use it to summarize.\n"
                        }
                    } else if file.type == "pdf" {
                        prompt += "⚠️ PDF text could not be extracted (image-based PDF).\n"
                    }
                }
            }
        }

        prompt += """

            USER REQUEST:
            \(query)

            ========================================
            INTELLIGENCE RULES - READ CAREFULLY
            ========================================

            YOU ARE CONTEXT-AWARE:
            - The user is in \(frontmostApp ?? "an app")
            - ALL their questions relate to this app unless explicitly stated
            - ALL context provided above is AUTOMATICALLY AVAILABLE to you
            - You DON'T need to ask for context - it's already provided

            AUTOMATIC UNDERSTANDING:
            - SELECTED TEXT (ANY APP): If user has text selected → Use SELECTED TEXT provided above
            - Safari/Browser: Questions about page content → Use PAGE CONTENT provided above
            - Safari/Browser: Questions about tabs → Use tab data provided above
            - Finder: Questions about files → Use the file/directory data provided
            - Mail: Questions about emails → Use email context if provided
            - Calendar: Questions about events → Use calendar data provided
            - ANY APP: Answer based on automatically detected context

            FOR SELECTED TEXT QUESTIONS (HIGHEST PRIORITY):
            - If SELECTED TEXT is provided, user's questions are about THAT TEXT
            - "summarize this" → Summarize the SELECTED TEXT
            - "explain this" → Explain the SELECTED TEXT
            - "translate this" → Translate the SELECTED TEXT
            - "what does this mean" → Explain the SELECTED TEXT meaning
            - The SELECTED TEXT section is shown at the TOP - it's the most important context!
            - Works in Safari, TextEdit, Notes, Mail, or ANY app where text is selected

            FOR MAIL APP QUESTIONS:
            - "summarize this email" → Summarize the EMAIL CONTENT provided
            - "what is this about" → Explain based on EMAIL CONTENT
            - "reply to this" → Draft reply based on EMAIL CONTENT
            - "who sent this" → Use the From field provided
            - The EMAIL CONTENT section contains the ACTUAL email text
            - DON'T say "I can't see the email" - the content is RIGHT THERE!

            FOR SAFARI PAGE CONTENT QUESTIONS:
            - "explain about X on this page" → Read and analyze the PAGE CONTENT provided
            - "what apps are shown" → Look in PAGE CONTENT for app names
            - "summarize this page" → Summarize the PAGE CONTENT provided
            - The PAGE CONTENT section contains the ACTUAL text from the webpage
            - DON'T say "I can't see the page" - the content is RIGHT THERE in the context!

            FOR TAB QUESTIONS IN SAFARI:
            - Answer using the tab data already provided above
            - Count tabs, filter tabs, summarize tabs
            - DON'T suggest creating extension
            - JUST ANSWER with the data!

            FOR FILE QUESTIONS IN FINDER:
            - Answer using the file/directory data provided above
            - List files, find files, analyze files
            - DON'T suggest extension for simple queries
            - JUST ANSWER with the data!

            RESPONSE GUIDELINES:
            1. If you can answer with the provided context → Answer directly (no extension)
            2. If an extension is required to complete the task → Use it with [USE_EXTENSION: name]
            3. If the task cannot be completed by AI or existing APIs → Suggest a custom extension

            WHEN TO SUGGEST EXTENSIONS:
            - ONLY when the task cannot be completed with the provided context or built-in APIs
            - Examples: batch automation, file transformations, app automation not already supported

            HOW TO SUGGEST EXTENSIONS:
            - Add [SUGGEST_EXTENSION] tag in your response
            - Provide complete, working extension code
            - Use this format:

            ```bash
            #!/bin/bash
            # Extension: [Name]
            # Description: [What it does]
            # Trigger: keyword
            # Layer: l2_context

            [Your working code here]
            ```

            - Make code simple, well-commented, and copy-paste ready
            - Include example usage
            - Explain where to save the file

            IMPORTANT:
            - For file operations: Provide ACTUAL RESULTS (run commands if needed)
            - For simple questions (like "what is X?"): Give direct, comprehensive answers
            - Do NOT suggest extensions when you can answer directly
            - Only include code blocks when using [SUGGEST_EXTENSION]
            - Always be actionable and helpful
            """

        // For Finder queries, actually execute and add results to prompt
        if let appName = frontmostApp, appName.lowercased() == "finder" {
            if let fileResults = executeFinderQuery(query) {
                prompt += """

                    ACTUAL FILE SYSTEM RESULTS:
                    \(fileResults)

                    Now provide a helpful summary of these results to the user.
                    """
            }
        }

        // Inject user-configured app-specific tool extensions into L2 prompt
        let l2AppKey =
            searchState.activeSmartQueryKey ?? settings.autoDetectedAppKey
            ?? frontmostApp.flatMap {
                settings.appKey(forBundleID: frontmost.bundleID, appName: $0)
            }
        if let key = l2AppKey {
            let relevantTools = settings.topExtensions(for: key, query: query, maxCount: 4)
            if !relevantTools.isEmpty {
                let pkgs = TerminalPackageManager.shared.packages
                let toolSnippet = relevantTools.map { ext -> String in
                    let pkg = pkgs.first(where: { $0.command == ext.toolName })
                    var line = "- \(ext.toolName)"
                    if let path = pkg?.installedPath ?? (ext.toolPath.isEmpty ? nil : ext.toolPath)
                    {
                        line += " (\(path))"
                    }
                    let hint = ext.effectiveHint
                    if !hint.isEmpty {
                        line += ": " + String(hint.prefix(300))
                    } else if let ht = pkg?.helpText, !ht.isEmpty {
                        line += ": " + String(ht.prefix(300))
                    }
                    return line
                }.joined(separator: "\n")
                prompt += """

                    APP CONTEXT [\(key)] — USER-CONFIGURED TOOLS:
                    \(toolSnippet)
                    Use these tools via run_command when they match the user's request.
                    """
            }
        }

        // ── Cross-app shortcut catalog ──────────────────────────────────────────
        // Inject ALL user-defined scriptable shortcuts across ALL app panels so the
        // AI can chain tools from different apps (e.g. Safari URL → Notes → Mail).
        let crossAppSection = buildCrossAppShortcutsSection()
        if !crossAppSection.isEmpty {
            prompt += crossAppSection
        }

        return prompt
    }

    /// Builds a cross-app tool catalog from all user-defined scriptable shortcuts.
    /// Writes multi-line JXA/AppleScript scripts to /tmp/ilauncher_tools/ so the AI
    /// can call them via run_command. Single-line scripts are inlined.
    func buildCrossAppShortcutsSection() -> String {
        // Gather all scriptable shortcuts grouped by appKey
        let scriptable = settings.appShortcuts.filter {
            $0.actionType == .jxa || $0.actionType == .appleScript || $0.actionType == .shellCommand
        }
        guard !scriptable.isEmpty else { return "" }

        // Create temp tools directory
        let toolsDir = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(
            "ilauncher_tools")
        try? FileManager.default.createDirectory(at: toolsDir, withIntermediateDirectories: true)

        // Group by appKey
        var byApp: [String: [AppShortcut]] = [:]
        for sc in scriptable {
            byApp[sc.appKey, default: []].append(sc)
        }

        var section = "\n=== CROSS-APP TOOLS (User-Defined) ===\n"
        section += "You can chain these tools across apps to complete multi-step tasks.\n"
        section += "Use run_command to execute them. See instructions per tool below.\n\n"

        for (appKey, shortcuts) in byApp.sorted(by: { $0.key < $1.key }) {
            let appDisplay = appKey.capitalized
            section += "── \(appDisplay) ──\n"

            for sc in shortcuts {
                let safeName = sc.name.lowercased()
                    .replacingOccurrences(of: " ", with: "_")
                    .filter { $0.isLetter || $0.isNumber || $0 == "_" }
                let toolID = "\(appKey)_\(safeName)"

                switch sc.actionType {
                case .jxa:
                    let code = sc.actionValue
                    let isMultiLine = code.contains("\n") || code.count > 120
                    if isMultiLine {
                        let filePath = toolsDir.appendingPathComponent("\(toolID).js").path
                        try? code.write(toFile: filePath, atomically: true, encoding: .utf8)
                        section +=
                            "  • \(sc.name) → run_command: osascript -l JavaScript \"\(filePath)\"\n"
                    } else {
                        let escaped = code.replacingOccurrences(of: "\"", with: "\\\"")
                        section +=
                            "  • \(sc.name) → run_command: osascript -l JavaScript -e \"\(escaped)\"\n"
                    }

                case .appleScript:
                    let code = sc.actionValue
                    let isMultiLine = code.contains("\n") || code.count > 120
                    if isMultiLine {
                        let filePath = toolsDir.appendingPathComponent("\(toolID).scpt").path
                        try? code.write(toFile: filePath, atomically: true, encoding: .utf8)
                        section += "  • \(sc.name) → run_command: osascript \"\(filePath)\"\n"
                    } else {
                        let escaped = code.replacingOccurrences(of: "\"", with: "\\\"")
                        section += "  • \(sc.name) → run_command: osascript -e \"\(escaped)\"\n"
                    }

                case .shellCommand:
                    // Pass $CURRENT_FILE and $SELECTED_TEXT as env vars if needed
                    let cmd = sc.actionValue
                    section += "  • \(sc.name) → run_command: \(cmd)\n"

                default:
                    break
                }
            }
            section += "\n"
        }

        section += """
            CROSS-APP CHAINING RULES:
            - To do multi-step tasks (e.g. "save Safari URL to Notes"), chain run_command calls:
              1. First run_command to get data from app A (e.g. Safari URL via osascript)
              2. Use the output in the next run_command to write to app B (e.g. Notes)
            - Variables: capture stdout from step N, pass as arg to step N+1
            - For AppleScript output: wrap with 'result=$(osascript -e ...)' then use $result
            ===================================\n
            """

        return section
    }

    func executeFinderQuery(_ query: String) -> String? {
        let lowerQuery = query.lowercased()

        // Detect what user wants to find
        let targetPath: String
        if lowerQuery.contains("downloads") {
            targetPath = NSHomeDirectory() + "/Downloads"
        } else if lowerQuery.contains("desktop") {
            targetPath = NSHomeDirectory() + "/Desktop"
        } else if lowerQuery.contains("documents") {
            targetPath = NSHomeDirectory() + "/Documents"
        } else {
            return nil
        }

        // Detect file size criteria
        let sizeCriteria: String
        if lowerQuery.contains("large") || lowerQuery.contains("big") {
            sizeCriteria = "+10M"  // Files larger than 10MB
        } else if lowerQuery.contains("huge") || lowerQuery.contains("largest") {
            sizeCriteria = "+100M"  // Files larger than 100MB
        } else {
            return nil
        }

        // Execute find command
        let findCommand =
            "find \"\(targetPath)\" -type f -size \(sizeCriteria) -exec ls -lh {} \\; 2>/dev/null | head -20"
        print("🔍 [L2] Executing: \(findCommand)")

        let task = Process()
        let pipe = Pipe()
        task.standardOutput = pipe
        task.standardError = Pipe()
        task.launchPath = "/bin/bash"
        task.arguments = ["-c", findCommand]

        do {
            try task.run()
            task.waitUntilExit()

            let data = pipe.fileHandleForReading.readDataToEndOfFile()
            if let output = String(data: data, encoding: .utf8), !output.isEmpty {
                // Parse ls output to extract file names and sizes
                let lines = output.components(separatedBy: "\n")
                    .filter { !$0.isEmpty }
                    .prefix(20)

                var results = "Found \(lines.count) large files in \(targetPath):\n\n"
                for line in lines {
                    // Parse ls -lh output: extract size and filename
                    let components = line.components(separatedBy: .whitespaces).filter {
                        !$0.isEmpty
                    }
                    if components.count >= 9 {
                        let size = components[4]
                        let filename = components[8...].joined(separator: " ")
                        results += "• \(filename) (\(size))\n"
                    }
                }
                return results
            }
        } catch {
            print("❌ [L2] Failed to execute find command: \(error)")
        }

        return nil
    }

    // MARK: - AI Response Parsing & Execution

    enum L2Action {
        case useExtension(String)
        case executeCommand(String)
        case terminalCommand(command: String, purpose: String)  // AI terminal automation
        case suggestExtension(code: String, explanation: String)
        case createAndExecuteExtension(name: String, description: String, app: String, code: String)
        case safariCommand(SafariCommand)
        case directAnswer(String)
    }

    func parseL2AIResponse(_ response: String) -> L2Action {
        print("🔍 [L2] Parsing AI response...")

        // Check for Safari browser control tags
        if let safariCmd = SafariCommandBridge.shared.parseTag(from: response) {
            print("🌐 [L2] Safari command tag detected")
            return .safariCommand(safariCmd)
        }

        // Check if AI wants to use an extension
        if let range = response.range(
            of: #"\[USE_EXTENSION:\s*([^\]]+)\]"#, options: .regularExpression)
        {
            let matched = String(response[range])
            // Extract extension name between brackets
            let extensionName =
                matched
                .replacingOccurrences(of: "[USE_EXTENSION:", with: "")
                .replacingOccurrences(of: "]", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)

            print("✅ [L2] AI wants to use extension: \(extensionName)")
            return .useExtension(extensionName)
        }

        // Check if AI is suggesting extension creation (explicit tag)
        if response.contains("[SUGGEST_EXTENSION]") {
            print("💡 [L2] AI is suggesting an extension (explicit tag)")

            // Try to parse JSON format first
            if let jsonStart = response.range(of: "\\{[\\s\\S]*?\\}", options: .regularExpression) {
                let jsonString = String(response[jsonStart])
                if let jsonData = jsonString.data(using: .utf8),
                    let json = try? JSONSerialization.jsonObject(with: jsonData)
                        as? [String: String],
                    let name = json["name"],
                    let description = json["description"],
                    let app = json["app"],
                    let code = json["code"]
                {
                    print("✅ [L2] Parsed JSON extension suggestion")
                    return .createAndExecuteExtension(
                        name: name, description: description, app: app, code: code)
                }
            }

            // Fallback to old code block parsing
            let codePattern = "```(?:bash|python|javascript|applescript)?\\n([\\s\\S]*?)```"
            if let codeRange = response.range(of: codePattern, options: .regularExpression) {
                let codeBlock = String(response[codeRange])
                // Remove markdown code fence
                let code =
                    codeBlock
                    .replacingOccurrences(of: "```bash\n", with: "")
                    .replacingOccurrences(of: "```python\n", with: "")
                    .replacingOccurrences(of: "```javascript\n", with: "")
                    .replacingOccurrences(of: "```applescript\n", with: "")
                    .replacingOccurrences(of: "```sh\n", with: "")
                    .replacingOccurrences(of: "```\n", with: "")
                    .replacingOccurrences(of: "\n```", with: "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)

                // Extract explanation (everything before code block)
                let explanation = response.components(separatedBy: "```").first ?? response

                return .suggestExtension(code: code, explanation: explanation)
            }
        }

        // Check if AI wants to run a terminal command (new format with purpose)
        if let commandRange = response.range(
            of: #"\[TERMINAL_COMMAND:\s*([^\]]+)\]"#, options: .regularExpression)
        {
            let commandMatched = String(response[commandRange])
            let command =
                commandMatched
                .replacingOccurrences(of: "[TERMINAL_COMMAND:", with: "")
                .replacingOccurrences(of: "]", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)

            // Extract purpose if available
            var purpose = "Execute terminal command"
            if let purposeRange = response.range(
                of: #"\[COMMAND_PURPOSE:\s*([^\]]+)\]"#, options: .regularExpression)
            {
                let purposeMatched = String(response[purposeRange])
                purpose =
                    purposeMatched
                    .replacingOccurrences(of: "[COMMAND_PURPOSE:", with: "")
                    .replacingOccurrences(of: "]", with: "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }

            print("✅ [L2] AI wants to run terminal command: \(command)")
            print("   Purpose: \(purpose)")
            return .terminalCommand(command: command, purpose: purpose)
        }

        // Check if AI wants to execute a command (legacy format)
        if let range = response.range(
            of: #"\[EXECUTE_COMMAND:\s*([^\]]+)\]"#, options: .regularExpression)
        {
            let matched = String(response[range])
            let command =
                matched
                .replacingOccurrences(of: "[EXECUTE_COMMAND:", with: "")
                .replacingOccurrences(of: "]", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)

            print("✅ [L2] AI wants to execute command: \(command)")
            return .executeCommand(command)
        }

        // Otherwise, it's a direct answer
        print("💬 [L2] Direct answer from AI")
        return .directAnswer(response)
    }

    // Store suggested extension code for easy copying
    @State var suggestedExtensionCode: String? = nil
    @State var originalUserQuery: String? = nil  // Store original query to re-execute

    func copySuggestedExtension() {
        guard let code = suggestedExtensionCode else { return }
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(code, forType: .string)

        // Show confirmation
        let confirmMessage = AIChatMessage(
            role: .assistant,
            content:
                "✅ Extension code copied to clipboard! Save it to ExtensionLibrary/ and make it executable."
        )
        l2.chatMessages.append(confirmMessage)
    }

    func installSuggestedExtension() {
        guard let code = suggestedExtensionCode else { return }

        Task {
            do {
                // Extract extension metadata from code comments
                let extensionName = extractExtensionName(from: code)
                let description = extractExtensionDescription(from: code)
                let layer = extractExtensionLayer(from: code)
                await MainActor.run {
                    let scriptType = determineExtensionScriptType(from: code)
                    let category = inferExtensionCategory(layer: layer, appName: frontmost.name)
                    let triggers = buildExtensionTriggers(layer: layer, appName: frontmost.name)
                    let ext = ILExtension(
                        name: extensionName,
                        description: description,
                        icon: "sparkles",
                        layer: layer.contains("l1")
                            ? .l1_search : (layer.contains("l3") ? .l3_browser : .l2_context),
                        tags: [.automation],
                        category: category,
                        triggers: triggers,
                        scriptPath: "",
                        scriptContent: code,
                        scriptType: scriptType,
                        isBuiltIn: false
                    )

                    LayeredExtensionManager.shared.addExtension(ext)
                    updateL2ContextExtensions()

                    let successMessage = """
                        ✅ Extension installed successfully!

                        📦 **\(extensionName)**
                        📝 \(description)
                        📂 Saved to: Documents/ILauncher/Extensions

                        The extension has been added and is now available in your Extensions library!
                        """

                    let confirmMessage = AIChatMessage(role: .assistant, content: successMessage)
                    l2.chatMessages.append(confirmMessage)
                }

            } catch {
                await MainActor.run {
                    let errorMessage = AIChatMessage(
                        role: .assistant,
                        content: "❌ Failed to install extension: \(error.localizedDescription)",
                        isError: true
                    )
                    l2.chatMessages.append(errorMessage)
                }
            }
        }
    }

    // MARK: - Extension Proposal Helpers

    /// Build the system-prompt appendix that asks the AI to emit an extension proposal block
    /// when it can automate the user's action with AppleScript or bash.
    func extensionProposalPromptAppendix(appName: String, query: String) -> String {
        let q = query.lowercased()
        let isQuestion =
            q.hasSuffix("?") || q.hasPrefix("what") || q.hasPrefix("how")
            || q.hasPrefix("why") || q.hasPrefix("explain") || q.hasPrefix("tell")
            || q.hasPrefix("describe") || q.hasPrefix("who") || q.hasPrefix("when")
        guard !isQuestion else { return "" }
        return """

            ══ AUTOMATION ASSISTANT MODE ══
            When the user's request is an ACTION you can automate with AppleScript or bash:
            1. Answer in one plain-English sentence.
            2. Immediately follow with a working script wrapped in these exact markers:

            <<EXTENSION_PROPOSAL>>
            {
              "type": "extension_proposal",
              "name": "<short verb-noun name, e.g. Save Page as PDF>",
              "description": "<one-line description>",
              "scriptType": "<applescript or bash>",
              "script": "<complete, runnable script — NO placeholders, NO TODOs>",
              "layer": "contextDock",
              "triggers": [{"type": "appContext", "value": "\(appName)"}],
              "icon": "<SF Symbol name>"
            }
            <<END_PROPOSAL>>

            RULES:
            - Prefer AppleScript for macOS app automation (\(appName), Finder, System Events, Notes).
            - Prefer bash for file ops, network calls, or multi-step shell workflows.
            - Use $CD_URL for the current page URL; $CD_TEXT for selected text; $CD_FILE for selected file path.
            - For tasks needing user input, use `osascript -e 'display dialog...'` or `choose from list`.
            - The script must be 100% complete and run as-is — no stubs, no comments asking to fill in.
            - If you cannot write a fully working script, omit the proposal block entirely.
            """
    }

    /// After an AI response arrives, extract any embedded proposal, strip the markers from the
    /// displayed text, and return an updated message tagged for the extension card UI.
    func tagMessageWithProposal(_ msg: AIChatMessage) -> AIChatMessage {
        guard let proposal = ExtensionProposalData.parse(from: msg.content),
            let json = proposal.asJSON()
        else { return msg }
        let cleaned = ExtensionProposalData.cleanResponse(msg.content)
        return AIChatMessage(
            id: msg.id, role: msg.role, content: cleaned,
            structuredData: json, hasInstallButton: true
        )
    }

    /// Execute a proposal's script immediately without saving.
    func runOnceFromProposal(_ json: String) {
        guard let data = json.data(using: .utf8),
            let proposal = try? JSONDecoder().decode(ExtensionProposalData.self, from: data)
        else { return }
        let ctx = AXContextReader.shared.current
        let envVars: [String: String] = [
            "CD_URL": ctx.currentURL ?? SafariBrowserBridge.shared.currentContext()?.url ?? "",
            "CD_TEXT": ctx.selectedText ?? "",
            "CD_FILE": ctx.selectedFilePaths.first ?? "",
            "CD_APP": ctx.appName,
            "CD_TITLE": ctx.windowTitle ?? "",
        ]
        AppToast.show(
            "Running \(proposal.name)…", icon: "bolt.fill", tint: .blue.opacity(0.9), duration: 2.0,
            centered: true)
        switch proposal.scriptType.lowercased() {
        case "applescript":
            AXTriggerRuleEngine.shared.run(
                type: .appleScript, value: proposal.script, envVars: envVars)
        default:
            let tmp = FileManager.default.temporaryDirectory
                .appendingPathComponent("proposal_\(UUID().uuidString).sh")
            try? proposal.script.write(to: tmp, atomically: true, encoding: .utf8)
            try? FileManager.default.setAttributes(
                [.posixPermissions: 0o755], ofItemAtPath: tmp.path)
            AXTriggerRuleEngine.shared.run(type: .scriptFile, value: tmp.path, envVars: envVars)
        }
    }

    /// Save a proposal as a persistent Context Trigger rule.
    func installFromProposal(_ json: String) {
        guard let data = json.data(using: .utf8),
            let proposal = try? JSONDecoder().decode(ExtensionProposalData.self, from: data)
        else { return }
        let lang: AppScriptLanguage = {
            switch proposal.scriptType.lowercased() {
            case "applescript": return .applescript
            case "jxa": return .jxa
            default: return .bash
            }
        }()
        let savedPath =
            AppSettings.shared.saveScript(
                appKey: "context-dock", name: proposal.name, language: lang, code: proposal.script
            ) ?? ""
        let actionType: AppShortcut.ActionType = savedPath.isEmpty ? .appleScript : .scriptFile
        let actionValue = savedPath.isEmpty ? proposal.script : savedPath
        let conditions: [AXTriggerCondition] = proposal.triggers.compactMap { t in
            switch t.type {
            case "appContext":
                return AXTriggerCondition(field: .appName, op: .contains, value: t.value)
            case "urlPattern":
                return AXTriggerCondition(field: .currentURL, op: .contains, value: t.value)
            case "fileType":
                return AXTriggerCondition(field: .filePath, op: .endsWith, value: ".\(t.value)")
            default: return nil
            }
        }
        let pill = AXRulePill(
            label: proposal.name,
            icon: proposal.icon ?? "sparkles",
            accentColor: "blue",
            actionType: actionType,
            actionValue: actionValue
        )
        // Rules with no conditions are always-on global — use a non-empty conditions list.
        let finalConditions: [AXTriggerCondition] =
            conditions.isEmpty
            ? [AXTriggerCondition(field: .appName, op: .isNotEmpty, value: "")]
            : conditions
        let rule = AXTriggerRule(
            name: proposal.name, isEnabled: true,
            conditions: finalConditions, conditionLogic: .any, pills: [pill], priority: 10
        )
        AppSettings.shared.addAXRule(rule)
        l2.chatMessages.append(
            AIChatMessage(
                role: .assistant,
                content:
                    "**\(proposal.name)** saved as a Context Trigger. Type \"\(proposal.name.lowercased())\" anytime to run it instantly."
            ))
    }

    func extractExtensionName(from code: String) -> String {
        // Look for "# Extension: Name" in comments
        let lines = code.components(separatedBy: "\n")
        for line in lines {
            if line.hasPrefix("# Extension:") {
                return line.replacingOccurrences(of: "# Extension:", with: "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }
        return "Custom Extension"
    }

    func extractExtensionDescription(from code: String) -> String {
        // Look for "# Description: ..." in comments
        let lines = code.components(separatedBy: "\n")
        for line in lines {
            if line.hasPrefix("# Description:") {
                return line.replacingOccurrences(of: "# Description:", with: "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }
        return "No description provided"
    }

    func extractExtensionLayer(from code: String) -> String {
        // Look for "# Layer: ..." in comments
        let lines = code.components(separatedBy: "\n")
        for line in lines {
            if line.hasPrefix("# Layer:") {
                return line.replacingOccurrences(of: "# Layer:", with: "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }
        return "l2_context"  // Default to L2
    }

    func determineExtensionScriptType(from code: String, language: String? = nil)
        -> ILExtension.ScriptType
    {
        if code.hasPrefix("#!/bin/bash") || code.hasPrefix("#!/usr/bin/env bash")
            || code.hasPrefix("#!/bin/sh") || language == "bash" || language == "sh"
        {
            return .bash
        }
        if code.hasPrefix("#!/usr/bin/env python") || code.hasPrefix("#!/usr/bin/python")
            || language == "python"
        {
            return .python
        }
        if code.hasPrefix("#!/usr/bin/osascript") || language == "applescript" {
            return .applescript
        }
        return .bash
    }

    func inferExtensionCategory(layer: String, appName: String) -> String {
        let normalized = appName.lowercased()
        if layer.contains("l2") {
            if normalized.contains("safari") || normalized.contains("chrome")
                || normalized.contains("arc")
            {
                return "browser"
            }
            if normalized.contains("finder") {
                return "finder"
            }
            if normalized.contains("mail") {
                return "mail"
            }
            if normalized.contains("notes") || normalized.contains("textedit") {
                return "text-editor"
            }
            if normalized.contains("xcode") || normalized.contains("vscode") {
                return "code-editor"
            }
        }
        if layer.contains("l3") {
            return "page-enhancers"
        }
        return "custom"
    }

    func buildExtensionTriggers(layer: String, appName: String) -> [ExtensionTrigger] {
        if layer.contains("l2"), !appName.isEmpty {
            return [.appContext(appName)]
        }
        return [.always]
    }

    func runAppleScript(_ script: String) -> String? {
        var error: NSDictionary?
        guard let scriptObject = NSAppleScript(source: script) else {
            print("❌ Failed to create AppleScript")
            return nil
        }

        let output = scriptObject.executeAndReturnError(&error)

        if let error = error {
            print("❌ AppleScript error: \(error)")
            return nil
        }

        return output.stringValue
    }

    func executeShellCommandSafely(_ command: String) async -> String {
        // Check if this is an ilauncher-api command - handle it directly
        if command.trimmingCharacters(in: .whitespacesAndNewlines).hasPrefix("ilauncher-api ") {
            print("🔧 [Shell] Detected ilauncher-api command, routing to APICommandHandler")

            // Extract args from command
            let cleanCommand = command.trimmingCharacters(in: .whitespacesAndNewlines)
            let components = cleanCommand.components(separatedBy: .whitespaces)
                .filter { !$0.isEmpty }

            // Remove "ilauncher-api" prefix
            let args = Array(components.dropFirst())

            print("🔧 [Shell] API args: \(args)")

            // Route to API handler
            let result = APICommandHandler.shared.handleCommand(args)
            print("✅ [Shell] API result: \(result)")

            return result
        }

        // Otherwise execute as normal shell command
        let task = Process()
        let pipe = Pipe()

        task.standardOutput = pipe
        task.standardError = pipe
        task.launchPath = "/bin/bash"
        task.arguments = ["-c", command]

        do {
            try task.run()
            task.waitUntilExit()

            let data = pipe.fileHandleForReading.readDataToEndOfFile()
            if let output = String(data: data, encoding: .utf8), !output.isEmpty {
                return output.trimmingCharacters(in: .whitespacesAndNewlines)
            } else {
                return "✅ Command executed successfully"
            }
        } catch {
            return "❌ Error: \(error.localizedDescription)"
        }
    }

